INSERT INTO public.spaces VALUES ('ac174fe3-2406-4940-a82b-7f71030cac27', NULL, '00000000-0000-0000-0000-000000000064', 'Aarhus School of Architecture', 'aarhus-school-of-architecture', NULL, '{"title": "Aarhus School of Architecture", "extract": "The Aarhus School of Architecture was founded in 1965 in Aarhus, Denmark. Along with the Royal Danish Academy of Fine Arts, School of Architecture in Copenhagen, it is responsible for the education of architects in Denmark. The school has approximately 750 students.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/7b/Arkitektskolen_Aarhus_%28ny_bygning%29.jpg/330px-Arkitektskolen_Aarhus_%28ny_bygning%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Aarhus_School_of_Architecture", "description": "Architecture school in Aarhus, Denmark"}', NULL, NULL, 'DK', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.353781+01', '2026-08-07 12:47:33.353781+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('19db9a7f-9ca5-4ca4-90c2-344d7d2d0815', NULL, '00000000-0000-0000-0000-000000000064', 'American University of Afghanistan', 'american-university-of-afghanistan', NULL, '{"title": "American University of Afghanistan", "extract": "The American University of Afghanistan is an online private university. After the fall of Kabul in 2021, many former students of AUAF live abroad and, as of 2022, there were plans to create a new AUAF campus in Qatar. AUAF was the country''s first private, not-for-profit institution of higher education.", "content_url": "https://en.wikipedia.org/wiki/American_University_of_Afghanistan", "description": "Former university in Kabul, Afghanistan"}', NULL, NULL, 'AF', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.262718+01', '2026-08-07 12:47:33.262718+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('d9fb400b-b6bb-4436-a16a-b0597cdf3560', NULL, '00000000-0000-0000-0000-000000000064', 'Aaniiih Nakoda College', 'aaniiih-nakoda-college', NULL, '{"title": "Aaniiih Nakoda College", "extract": "Aaniiih Nakoda College is a public tribal land-grant community college on the Fort Belknap Indian Reservation in Harlem, Montana. The institution incorporates native culture into the curriculum and promotes cultural identity; however, the school is open to both tribal and non-tribal members. Aaniiih Nakoda College is a member of the American Indian Higher Education Consortium (AIHEC), which is a community of tribally and federally chartered institutions working to strengthen tribal nations and make a lasting difference in the lives of American Indians and Alaska Natives. ANC was created in response to the higher education needs of American Indians. ANC generally serves geographically isolated populations that have no other means accessing education beyond the high school level.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/a/a6/Fort_Belknap_College.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Aaniiih_Nakoda_College", "description": "Tribal community college in Harlem, Montana, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-07 12:47:33.702225+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('15d14188-9446-471f-9f3b-983fcfba9c20', NULL, '00000000-0000-0000-0000-000000000064', 'Dohto University', 'dohto-university', NULL, '{"name": "Seisa Dohto University", "image": "http://commons.wikimedia.org/wiki/Special:FilePath/Dohto%20daigaku%202005.jpg", "country": "Japan", "founded": "1964-01-01T00:00:00Z", "website": "http://www.dohto.ac.jp/", "description": "university in Japan", "wikidata_id": "http://www.wikidata.org/entity/Q5288576", "wikipedia_url": "https://en.wikipedia.org/wiki/Q5288576"}', NULL, NULL, 'JP', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.465646+01', '2026-08-07 12:47:33.465646+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('39537f1a-1eea-45dd-a659-8317dcce684e', NULL, '00000000-0000-0000-0000-000000000064', 'Abant Izzet Baysal University', 'abant-izzet-baysal-university', NULL, '{"title": "Bolu Abant İzzet Baysal University", "extract": "Bolu Abant İzzet Baysal University is a public university in Bolu, Turkey. It was founded on 3 July 1992 by İzzet Baysal. It has campuses in the city center and three districts of Bolu. The main campus of the university, namely the İzzet Baysal Campus, is located in Gölköy, which is 8 km from the city center. The university comprises 16 faculties, 1 institute, 1 school, 8 vocational schools, and 20 research centers. 1.539 faculty members and 1.176 administrative staff.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/54/BA%C4%B0B%C3%9C_logo.png/330px-BA%C4%B0B%C3%9C_logo.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Bolu_Abant_%C4%B0zzet_Baysal_University", "description": "Public university in Bolu, Turkey"}', NULL, NULL, 'TR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.65283+01', '2026-08-07 12:47:33.65283+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('bbfb111e-3a40-4fed-8140-d051db382ae8', NULL, '00000000-0000-0000-0000-000000000064', 'Abdullah Gul University', 'abdullah-gul-university', NULL, '{"title": "Abdullah Gül University", "extract": "Abdullah Gül University (AGU) is a public university located in Kayseri, Turkey. Established in 2010, the university began admitting students in the 2013–2014 academic year. AGU offers twelve undergraduate and eleven graduate programs across five schools. The university’s primary language of instruction is English, a characteristic shared with a limited number of other public universities in Turkey, including Middle East Technical University, Boğaziçi University and İzmir Institute of Technology. The main campus, known as the Sümer Campus, functions as the center for academic and student activities.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/a9/Abdullah_G%C3%BCl_University_logo.svg/330px-Abdullah_G%C3%BCl_University_logo.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Abdullah_G%C3%BCl_University", "description": "Public university in Kayseri, Turkey"}', NULL, NULL, 'TR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.679268+01', '2026-08-07 12:47:33.679268+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
