INSERT INTO public.spaces VALUES ('1080b24c-8c90-4e49-8396-d959c8aa60b5', NULL, '00000000-0000-0000-0000-000000000064', 'American University of Beirut', 'american-university-of-beirut', NULL, '{"title": "American University of Beirut", "extract": "The American University of Beirut is a private, non-sectarian, and independent university chartered in New York with its main campus in Beirut, Lebanon. AUB is governed by a private, autonomous board of trustees and offers programs leading to bachelor''s, master''s, MD, and PhD degrees.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/4/40/New_logo_of_the_American_University_of_Beirut.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/American_University_of_Beirut", "description": "Private university in Lebanon"}', NULL, NULL, 'LB', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.5184+01', '2026-08-07 12:47:33.5184+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('2697bceb-8fe6-41f0-afe2-6ebcf2e4525b', NULL, '00000000-0000-0000-0000-000000000064', 'American University of Paris', 'american-university-of-paris', NULL, '{"title": "American University of Paris", "extract": "The American University of Paris (AUP) is a private university in Paris, France. Founded in 1962, the university is one of the oldest American institutions of higher education in Europe, and the first to be established in France. The university campus consists of seven buildings, centrally located in the 7th arrondissement of Paris, on the Left Bank near the Eiffel Tower, Les Invalides, and the Seine.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/ff/AUP_Learning_Commons.jpg/330px-AUP_Learning_Commons.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/American_University_of_Paris", "description": "Private university college in France"}', NULL, NULL, 'FR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.384776+01', '2026-08-07 12:47:33.384776+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('6d01da4a-c754-4f68-9b87-3b8a89a64f00', NULL, '00000000-0000-0000-0000-000000000064', 'American University of Central Asia', 'american-university-of-central-asia', NULL, '{"title": "American University of Central Asia", "extract": "The American University of Central Asia (AUCA), formerly the Kyrgyz-American School and the American University in Kyrgyzstan, is a liberal arts university located in Bishkek, the capital of the Kyrgyz Republic.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/1/1b/American_University_of_Central_Asia_%28crest%29.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/American_University_of_Central_Asia", "description": "University in Bishkek, Kyrgyzstan"}', NULL, NULL, 'KG', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.5184+01', '2026-08-07 12:47:33.5184+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
