INSERT INTO public.spaces VALUES ('4a06c3e7-27ea-4ef6-a541-e3e50132dfd5', NULL, '00000000-0000-0000-0000-000000000064', 'St. Joseph''s College of Commerce', 'st-joseph-s-college-of-commerce', NULL, '{"title": "St. Joseph''s College of Commerce", "extract": "St. Joseph''s College of Commerce (SJCC) is a Bengaluru City University-affiliated college operated by the Jesuits. It is autonomous and has an independent examination and recognition system. It is situated in central Bangalore at Brigade Road. The college is ranked 55th among colleges in India by the National Institutional Ranking Framework (NIRF) in 2024.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/3/3e/St._Joseph%27s_College_of_Commerce_logo.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/St._Joseph''s_College_of_Commerce", "description": "Jesuit college in Bangalore, India"}', 'baa11a40-1adc-4f66-aa5f-f7d8509949c9', NULL, 'IN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.753691+01', '2026-08-09 02:14:06.529408+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
