INSERT INTO public.spaces VALUES ('c4e6b78a-9a20-42f9-a8f3-a418dbbe8afa', NULL, '00000000-0000-0000-0000-000000000060', 'Colombia', 'colombia', 'It is set in South America, sharing borders with Venezuela, Brazil, Peru, and Ecuador. Whether you''re still in South America or building a life elsewhere, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Colombia", "extract": "Colombia, officially the Republic of Colombia, is a country located in South America, with insular regions in North America. Colombia''s mainland is bordered by the Caribbean Sea to the north, Venezuela to the east, Brazil to the southeast, Peru and Ecuador to the south and southwest, the Pacific Ocean to the west, and Panama to the northwest. Colombia is divided into 32 departments. The Capital District of Bogotá is the country''s largest city hosting the main financial and cultural hub. Other urban areas include Medellín, Cali, Barranquilla, Cartagena, Bucaramanga, Pereira, Santa Marta, Cúcuta, Ibagué, Villavicencio and Manizales. It covers an area of 1,141,748 square kilometers and has a population of around 52 million. Its rich cultural heritage—including language, religion, cuisine, and art—reflects its history as a colony, fusing cultural elements brought by immigration from Europe and the Middle East, with those brought by the African diaspora, as well as with those of Indigenous civilizations that predate colonization. Spanish is the official language, although Creole, English and 64 other languages are recognized regionally.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/21/Flag_of_Colombia.svg/330px-Flag_of_Colombia.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Colombia", "description": "Country in South America"}', '6a475efa-fc9c-4efe-a520-a1ec00812d82', NULL, 'CO', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:22.49704+01', NULL, NULL, '{colombia,co,"south america",community,diaspora}', NULL, 'Americas', 'South America', NULL);
