INSERT INTO public.spaces VALUES ('770516c2-270e-40b6-9a3a-eba42e3a3c27', NULL, '00000000-0000-0000-0000-000000000064', 'California State University, Monterey Bay', 'california-state-university-monterey-bay', NULL, '{"title": "California State University, Monterey Bay", "extract": "California State University, Monterey Bay is a public university located in Monterey County, California, United States. The main campus is situated on the site of the former military base Fort Ord, spanning the cities of Seaside and Marina, approximately one mile inland from Monterey Bay along the Central Coast of California. CSUMB also maintains locations in the cities of Monterey and Salinas. Founded in 1994, CSUMB is part of the California State University system and is accredited by the WASC Senior College and University Commission. The university is designated as a Hispanic-Serving Institution.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/1/13/CSU_Monterey_Bay_seal.svg/330px-CSU_Monterey_Bay_seal.svg.png", "content_url": "https://en.wikipedia.org/wiki/California_State_University%2C_Monterey_Bay", "description": "Public university in California, U.S."}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.188857+01', '2026-08-07 12:47:33.188857+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
