INSERT INTO public.spaces VALUES ('0d61c0fd-e4aa-40e7-b85c-f6159a795703', NULL, '00000000-0000-0000-0000-000000000064', 'Aims Community College', 'aims-community-college', NULL, '{"title": "Aims Community College", "extract": "Aims Community College is a public community college serving northern Colorado with locations in Greeley, Windsor, Fort Lupton, and Loveland. Aims has more than 200 degree and certificate programs and provides day and night classes. Aims was founded in Greeley in 1967 and graduated its first class in 1969. The school established a second campus in Fort Lupton in 1984, and a third in Loveland in 1987. The Aims Automotive and Technology Center, located in Windsor, opened in January 2010.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d0/Aims_Community_College%2C_Fort_Lupton_Campus.JPG/330px-Aims_Community_College%2C_Fort_Lupton_Campus.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Aims_Community_College", "description": "Public college in Northern Colorado, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.679268+01', '2026-08-07 12:47:33.679268+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
