INSERT INTO public.spaces VALUES ('db2785a8-2597-4438-a239-59cb354779ab', NULL, '00000000-0000-0000-0000-000000000064', 'Adirondack Community College', 'adirondack-community-college', NULL, '{"title": "SUNY Adirondack", "extract": "SUNY Adirondack is a public community college in Queensbury, New York. It serves residents in Warren, Washington and northern Saratoga counties in New York State with over 30 academic programs of study. It was founded in 1961 as Adirondack Community College (ACC). Bachelor''s and master''s degree programs became available with the opening of the SUNY at Plattsburgh Queensbury Branch on the SUNY Adirondack campus. It adopted its present name on March 1, 2010.", "content_url": "https://en.wikipedia.org/wiki/SUNY_Adirondack", "description": "Community college in Queensbury, New York, U.S."}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-07 12:47:33.702225+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('7c4030c2-494b-4c01-88d8-54c0ff1a9807', NULL, '00000000-0000-0000-0000-000000000064', 'Adrian College', 'adrian-college', NULL, '{"title": "Adrian College", "extract": "Adrian College is a private United Methodist liberal arts college in Adrian, Michigan. The college offers bachelor''s degrees in 92 academic majors and programs. The 100 acre (0.40 km2) campus contains newly constructed facilities along with historic buildings. Adrian College is affiliated with the United Methodist Church and is accredited by the Higher Learning Commission. The spring 2020–21 enrollment was 1,677 students.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/0/0f/Adrian_College_seal.svg/330px-Adrian_College_seal.svg.png", "content_url": "https://en.wikipedia.org/wiki/Adrian_College", "description": "Private liberal arts college in Michigan, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.753691+01', '2026-08-07 12:47:33.753691+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
