INSERT INTO public.spaces VALUES ('b738a1ef-d3cb-4dd0-af6f-7f900b57f231', NULL, '00000000-0000-0000-0000-000000000064', 'Aiken Technical College', 'aiken-technical-college', NULL, '{"title": "Aiken Technical College", "extract": "Aiken Technical College (ATC) is a public community college in Graniteville, South Carolina. It is part of the South Carolina Technical College System. More than 3,400 students enroll in credit courses annually and 10,000 people enroll in non-credit courses and programs.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/0/0f/Aiken_Tech_emblem.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Aiken_Technical_College", "description": "College in Graniteville, South Carolina, U.S."}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.188857+01', '2026-08-07 12:47:33.188857+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('099890dc-69a1-4d73-a99a-0830120247c8', NULL, '00000000-0000-0000-0000-000000000064', 'Aichi Gakuin University', 'aichi-gakuin-university', NULL, '{"title": "Aichi Gakuin University", "extract": "Aichi Gakuin University  is a private university in Aichi Prefecture, Japan. It has campuses at the city of Nisshin, Aichi, Chikusa-ku, Nagoya and Meijō Park in Nagoya.\nThe predecessor of the university, a Soto Zen college, was founded in 1876, and it was chartered as a university in 1953.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/10/Aichi_Gakuin_Univ_Bldg1.jpg/330px-Aichi_Gakuin_Univ_Bldg1.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Aichi_Gakuin_University", "description": "Private university in Japan"}', NULL, NULL, 'JP', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.465646+01', '2026-08-07 12:47:33.465646+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
