INSERT INTO public.spaces VALUES ('3a2088a9-1f56-45e9-b6e4-068ff7583d22', NULL, '00000000-0000-0000-0000-000000000064', 'The University of Texas at San Antonio', 'the-university-of-texas-at-san-antonio', NULL, '{"title": "University of Texas at San Antonio", "extract": "The University of Texas at San Antonio is a public research university in San Antonio, Texas. Established in 1969, UTSA is the largest university in San Antonio and the third-largest public research university in Texas by annual research expenditures, enrolling approximately 38,200 students across six campuses spanning about 1,200 acres.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/8/8b/University_of_Texas_at_San_Antonio_seal.svg/330px-University_of_Texas_at_San_Antonio_seal.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/University_of_Texas_at_San_Antonio", "description": "Public university in San Antonio, Texas, US"}', 'c47ad47b-935d-40d8-ade8-cc94ffcf9362', NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.262718+01', '2026-08-11 00:20:20.494423+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
