INSERT INTO public.spaces VALUES ('29a22ca7-e527-4282-b9bc-df23d28d0569', NULL, '00000000-0000-0000-0000-000000000064', 'University of Michigan - Dearborn', 'university-of-michigan-dearborn', NULL, '{"title": "University of Michigan–Dearborn", "extract": "The University of Michigan–Dearborn (UM-Dearborn) is a public university in Dearborn, Michigan, United States. Founded in 1959 with a gift from the Ford Motor Company, it was initially known as the Dearborn Center, operating as a remote branch of the University of Michigan. Upon receiving its own accreditation in 1970, the branch became a fully-fledged university and subsequently changed its name to the University of Michigan–Dearborn. It continues to adhere to the policies of the University of Michigan Board of Regents without having a separate governing board.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/6/6e/University_of_Michigan-Dearborn_seal.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/University_of_Michigan%E2%80%93Dearborn", "description": "Public university in Dearborn, Michigan, U.S."}', '690c4272-246a-48e4-8587-5fe52a72e912', NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.262718+01', '2026-08-11 00:21:17.312672+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('20dbc1bc-f961-4825-a034-98c9be95fedc', NULL, '00000000-0000-0000-0000-000000000064', 'Islamic University Kushtia', 'islamic-university-kushtia', NULL, '{"title": "Islamic University, Bangladesh", "extract": "Islamic University, Bangladesh, commonly referred to as Islamic University, Kushtia, is a public PhD granting research university in Kushtia-Jhenaidah, Bangladesh and the largest seat of higher education in the southwestern part of the country.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/7/7b/Islamic_University%2C_Bangladesh_logo.svg/330px-Islamic_University%2C_Bangladesh_logo.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Islamic_University%2C_Bangladesh", "description": "Public University in Bangladesh"}', '8dedf1c9-0212-4703-96c2-1e18376aab09', NULL, 'BD', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.296289+01', '2026-08-11 00:29:16.898326+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
