INSERT INTO public.spaces VALUES ('3f3a574a-cf18-4a6d-9a57-5f58f7fcb169', NULL, '00000000-0000-0000-0000-000000000064', 'Odessa National Academy of Food Technologies', 'odessa-national-academy-of-food-technologies', NULL, '{"title": "Odesa National Academy of Food Technologies", "extract": "The Odesa National University of Technology (ONTU) is a public university with the highest level of accreditation established in 1902. ONTU is a multi-profile higher education institution which includes 4 scientific-educational institutions and 11 faculties and research institutes with 15 scientific schools. ONTU has about 6500 students in 21 areas of training, 42 training programs, 10 doctorate and 3 post-doctorate programs, and 4 specialized scientific councils for doctorate and post-doctorate theses defenses. Educational and research activities of ONTU provides 104 doctors/professors and 388 PhD/associate professors.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/c1/%D0%A3%D0%BB.%D0%9A%D0%B0%D0%BD%D0%B0%D1%82%D0%BD%D0%B0%D1%8F_-_panoramio.jpg/330px-%D0%A3%D0%BB.%D0%9A%D0%B0%D0%BD%D0%B0%D1%82%D0%BD%D0%B0%D1%8F_-_panoramio.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Odesa_National_Academy_of_Food_Technologies", "description": "Public university in Odesa, Ukraine"}', '0ca828d9-8260-4c91-b519-dcd5dbf7fbec', NULL, 'UA', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.65283+01', '2026-08-11 01:09:20.159081+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
