INSERT INTO public.spaces VALUES ('35ad93c0-eaad-4f4b-9a40-1b16f5b755a8', NULL, '00000000-0000-0000-0000-000000000064', 'Yamanashi University', 'yamanashi-university', NULL, '{"title": "University of Yamanashi", "extract": "The University of Yamanashi , abbreviated to Nashidai (梨大)Note, is a national university that has campuses in Kofu and Chūō, Japan. The University of Yamanashi has its origin in “Kitenkan” (徽典館) which was founded in 1795 as a branch school of “Shoheizaka-School” of Tokugawa Government and was reformed into the Normal School of Yamanashi after the Meiji Restoration. In 1921 the Normal School of Yamanashi for Junior and in 1924 the Yamanashi High School of Engineering were established. After the World War II these three schools were integrated to the University of Yamanashi according to the new school system of Japan. In 1978 the Yamanashi Medical University was opened which was only a Medical University in Prefecture of Yamanashi. Today’s University of Yamanashi was founded in 2002 by a merger between (former) University of Yamanashi and Yamanashi Medical University. It is formally referred to as the National University Corporation University of Yamanashi. In 2012 the Faculty of Education and Human science and the Faculty of Engineering were reorganized and the Faculty of Life and Environmental Science was newly established. In 2016 the lifelong studies course in the Faculty of Education and Human science was abolished, and the faculty was renamed to the Faculty of Education.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/9a/Yamanashiuni.jpg/330px-Yamanashiuni.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/University_of_Yamanashi", "description": "University in Yamanashi Prefecture, Japan"}', 'a1dabd9f-0150-45ca-9c1d-390b5f4460e0', NULL, 'JP', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.493186+01', '2026-08-09 18:59:20.523342+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('5c8f797c-db38-4064-b79b-c89d4d440059', NULL, '00000000-0000-0000-0000-000000000064', 'National Institute of Technology Trichy', 'national-institute-of-technology-trichy', NULL, '{"title": "National Institute of Technology, Tiruchirappalli", "extract": "The National Institute of Technology Tiruchirappalli is a national research deemed university near the city of Tiruchirappalli in Tamil Nadu, India. It was founded as Regional Engineering College Tiruchirappalli in 1964 by the governments of India and Tamil Nadu under the affiliation of the University of Madras. The college was granted deemed university status in 2003 with the approval of the University Grants Commission (UGC), the All India Council for Technical Education (AICTE), and the Government of India and renamed the National Institute of Technology Tiruchirappalli.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/4/4f/National_Institute_of_Technology%2C_Tiruchirappalli.svg/330px-National_Institute_of_Technology%2C_Tiruchirappalli.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/National_Institute_of_Technology%2C_Tiruchirappalli", "description": "Public engineering institution in Tamil Nadu, India"}', '82c25f61-3317-4433-b882-de71c69dc618', NULL, 'IN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.436788+01', '2026-08-10 07:27:26.662962+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
