INSERT INTO public.spaces VALUES ('26377b13-55b7-411b-8762-c57fe1f051c3', NULL, '00000000-0000-0000-0000-000000000064', 'University of South Carolina, Beaufort', 'university-of-south-carolina-beaufort', NULL, '{"title": "University of South Carolina Beaufort", "extract": "The University of South Carolina Beaufort is a public college with three campuses in the Lowcountry region of South Carolina. It is part of the University of South Carolina System, enrolls about 2,000 students, and offers over 50 areas of study. The main campus is in Bluffton. The institution''s campus in Beaufort houses the school''s honor programs and the Department of Visual Arts & Design. The campus location on Hilton Head Island is home to the institution''s program for hospitality management.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/93/Hargray_Building.jpg/330px-Hargray_Building.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/University_of_South_Carolina_Beaufort", "description": "Public university with three locations in South Carolina, U.S."}', '42e50c95-2075-43e6-b505-a8c440f0aed1', NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.753691+01', '2026-08-09 17:31:16.678726+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
