INSERT INTO public.spaces VALUES ('5bcac939-dc5b-42f5-9f67-bbf099701173', NULL, '00000000-0000-0000-0000-000000000064', 'Islamic Azad University, Central Tehran Branch', 'islamic-azad-university-central-tehran-branch', NULL, '{"title": "Islamic Azad University, Central Tehran Branch", "extract": "The Islamic Azad University, Central Tehran Branch is a private research university located in Tehran, Iran. Founded in 1982, Central Tehran is the flagship institution of the universities affiliated with Islamic Azad University system. The university is the oldest, the largest and the top university among all branches of Islamic Azad University academic organization, established in 1982, originally as the Islamic Azad University of Tehran.\nThe university campuses rest on 297,904 m2 (3,206,610 sq ft) of various districts of Tehran.\nIt offers approximately 500 undergraduate and graduate degree programs in a wide range of disciplines such as sciences, engineering, art, architecture, humanities and social sciences.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/f/ff/IAU_CTB_logo.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Islamic_Azad_University%2C_Central_Tehran_Branch", "description": "Iranian university"}', 'b61f833a-a093-40c7-8a03-b1fb98ede2aa', NULL, 'IR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.465646+01', '2026-08-10 07:37:40.497076+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
