INSERT INTO public.spaces VALUES ('5dda534a-3bcb-423a-befc-e2ce44946d36', NULL, '00000000-0000-0000-0000-000000000064', 'Kuala Lumpur Infrastructure University College', 'kuala-lumpur-infrastructure-university-college', NULL, '{"title": "Kuala Lumpur University of Science & Technology", "extract": " Kuala Lumpur University of Science and Technology (KLUST) formerly known as Infrastructure University Kuala Lumpur (IUKL); Malay: (Universiti Infrastruktur Kuala Lumpur) and Kuala Lumpur Infrastructure University College (KLIUC), is a university in Kajang, Hulu Langat District, Selangor, Malaysia. It is the first infrastructure university in Malaysia. It was established in 1998 following the privatisation of the Research and Training Institute of Public Works Department of Malaysia (IKRAM).", "content_url": "https://en.wikipedia.org/wiki/Kuala_Lumpur_University_of_Science_%26_Technology", "description": "Private university in Malaysia"}', NULL, NULL, 'MY', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.5184+01', '2026-08-09 19:09:27.934758+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
