INSERT INTO public.spaces VALUES ('de832853-d398-4010-a8fd-3817181beed9', NULL, '00000000-0000-0000-0000-000000000064', 'Texas A&M University - Kingsville', 'texas-a-m-university-kingsville', NULL, '{"title": "Texas A&M University–Kingsville", "extract": "Texas A&M University–Kingsville is a public research university in Kingsville, Texas, United States. It is the southernmost campus of the Texas A&M University System. The university developed the nation''s first doctoral degree in bilingual education. It is classified among \"R2: Doctoral Universities – High research activity\" and accredited by the Southern Association of Colleges and Schools (SACS).", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/0/0a/Texas_A%26M_University%E2%80%93Kingsville_seal.svg/330px-Texas_A%26M_University%E2%80%93Kingsville_seal.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Texas_A%26M_University%E2%80%93Kingsville", "description": "Public university in Kingsville, Texas"}', '537f2412-0fec-4358-8426-4f65efa0baf6', NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.233464+01', '2026-08-09 17:47:17.226211+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
