INSERT INTO public.spaces VALUES ('48cc03b8-0d80-4883-b8ce-b5efb2f2f5e1', NULL, '00000000-0000-0000-0000-000000000064', 'Islamic University of Medinah', 'islamic-university-of-medinah', NULL, '{"title": "Islamic University of Madinah", "extract": "The Islamic University of Madinah is a public Islamic university in Medina, Saudi Arabia. Established by King Saud bin Abdulaziz in 1961, This institution is associated with Salafism, while claiming to have exported Salafi-inclined theologians around the world. Others disagree and state that the institution is objective and scientific, being detached to any singular ideology. It received institutional academic accreditation without exceptions from the National Commission for Academic Accreditation and Assessment in April 2017. Renowned Islamic scholar Maududi was involved in the establishment and management of the university.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/4/48/Islamic_University_of_Madinah_Logo.svg/330px-Islamic_University_of_Madinah_Logo.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Islamic_University_of_Madinah", "description": "University in Madinah, Saudi Arabia"}', '7a7220d7-0b4a-474f-902b-f9cd2f8f9ca7', NULL, 'SA', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.625787+01', '2026-08-09 19:29:19.455438+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
