INSERT INTO public.spaces VALUES ('d90be491-d081-472f-960d-b979da49569d', NULL, '00000000-0000-0000-0000-000000000064', 'University of Minnesota - Crookston', 'university-of-minnesota-crookston', NULL, '{"title": "University of Minnesota Crookston", "extract": "The University of Minnesota Crookston (UMN–Crookston) is a public college in Crookston, Minnesota, United States. One of five campuses in the University of Minnesota system, UMN Crookston had a fall 2022 enrollment of 1,489 undergraduate students. Students come from 20 countries and 40 states.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/86/Seal_of_the_University_of_Minnesota.svg/330px-Seal_of_the_University_of_Minnesota.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/University_of_Minnesota_Crookston", "description": "Public university in Crookston, Minnesota, US"}', 'b267b391-237c-4865-be2b-546ff469ffe1', NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.262718+01', '2026-08-09 20:41:07.402412+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
