INSERT INTO public.spaces VALUES ('085a1841-4844-4a52-8e82-89b5af0c925a', NULL, '00000000-0000-0000-0000-000000000064', 'Washington University, Saint Louis', 'washington-university-saint-louis', NULL, '{"title": "Washington University in St. Louis", "extract": "Washington University in St. Louis (WashU) is a private research university in the St. Louis metropolitan area, Missouri, United States. Founded in 1853 by a group of civic leaders and named for the first U.S. president George Washington, the university spans 355 acres across its Danforth and Medical campuses. It comprises 10 schools and offers more than 150 undergraduate, 80 master''s and professional, and 50 doctoral degree programs. As of 2024, Washington University enrolled 16,399 students representing all 50 U.S. states and more than 110 countries.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/d/d7/WashU_St._Louis_seal.svg/330px-WashU_St._Louis_seal.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Washington_University_in_St._Louis", "description": "Private research university in Missouri, US"}', '3bf09662-a572-42b7-9e79-c13b9b23d8ff', NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.262718+01', '2026-08-09 20:43:12.046588+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
