INSERT INTO public.spaces VALUES ('8ddcbbda-f159-4e47-9669-a3984f077c69', NULL, '00000000-0000-0000-0000-000000000064', 'Tokyo Institute of Polytechnics', 'tokyo-institute-of-polytechnics', NULL, '{"title": "Tokyo Polytechnic University", "extract": "Tokyo Polytechnic University  is a private university in Honchō, Nakano, Tokyo. Its nickname is Shadai (写大). It was formerly known as Tokyo College of Photography.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/89/Tokyo_Polytechnic_University_%28school_gate%29.jpg/330px-Tokyo_Polytechnic_University_%28school_gate%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Tokyo_Polytechnic_University", "description": "Private university in Honchō, Nakano, Tokyo"}', 'bad48fb5-9141-4bb7-b112-a76937661f69', NULL, 'JP', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.493186+01', '2026-08-09 23:15:11.122721+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('fd023403-44d9-42c5-8db8-34263e06a55c', NULL, '00000000-0000-0000-0000-000000000064', 'University of Malawi', 'university-of-malawi', NULL, '{"title": "University of Malawi", "extract": "The University of Malawi is a public university established in 1965 and until 4 May 2021, when the university underwent a delinking, was composed of four constituent colleges located in Zomba, Blantyre, and Lilongwe. Of the four colleges, the largest is Chancellor College in Zomba. It is part of the Malawian government educational system. The last Vice-Chancellor was Professor John Kalenga Saka.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/a/aa/Universityofmalawishield.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/University_of_Malawi", "description": "University in Zomba, Malawi"}', '8c1512be-c493-4b5c-9d0a-1fbe7f46d5b7', NULL, 'MW', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.5184+01', '2026-08-09 23:15:22.668627+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
