INSERT INTO public.spaces VALUES ('3db21e55-8db4-4d35-be28-75cc90934e64', NULL, '00000000-0000-0000-0000-000000000064', 'Kookmin University', 'kookmin-university', NULL, '{"title": "Kookmin University", "extract": "Kookmin University is a private research university established in 1946 in Seongbuk-gu, Seoul, South Korea. It has historic significance, as it was founded by the Provisional Government of the Republic of Korea and is the first private university founded after the liberation of the Republic of Korea from Japan.", "content_url": "https://en.wikipedia.org/wiki/Kookmin_University", "description": "Private university in Seoul, South Korea"}', NULL, NULL, 'KR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.5184+01', '2026-08-09 23:16:12.921309+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
