INSERT INTO public.spaces VALUES ('464fa52d-9803-4dcc-b54a-168380c5eac1', NULL, '00000000-0000-0000-0000-000000000064', 'Omar Al-Mukhtar University', 'omar-al-mukhtar-university', NULL, '{"title": "Omar Al-Mukhtar University", "extract": "Omar Al-Mukhtar University Is a public university in Bayda, Libya. it is the third largest university in Libya after the University of Tripoli and the University of Benghazi. It was founded in 1961 and grew to be a moderately religious institute that taught practice regarding scripture reading and interpretation. However, after Muammar Gaddafi''s 1969 coup d''état, educational reforms were implemented that caused the shutdown of the Islamic departments, replacing them with scientific departments.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/4/43/Omar_Al-Mukhtar_University.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Omar_Al-Mukhtar_University", "description": "University in Bayda, Libya"}', '15485651-abc1-47f0-b35e-0eed64f0bd9e', NULL, 'LY', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.5184+01', '2026-08-09 23:15:38.962308+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('2460aa37-757c-41f2-b193-fac6505f317a', NULL, '00000000-0000-0000-0000-000000000064', 'Vilnius Pedagogical University', 'vilnius-pedagogical-university', NULL, '{"title": "Vytautas Magnus University Education Academy", "extract": "Vytautas Magnus University Education Academy is an academical unit of Vytautas Magnus University, which specialized in preparing school teachers and other educators. Located in Vilnius and Kaunas, Lithuania.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/9c/Pedagaske_by_Augustas_Didzgalvis.jpg/330px-Pedagaske_by_Augustas_Didzgalvis.jpg", "content_url": "https://en.wikipedia.org/wiki/Vytautas_Magnus_University_Education_Academy", "description": "Academical unit of Vytautas Magnus University"}', '1315202b-9f41-4728-a98e-ce39dce63a1a', NULL, 'LT', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.5184+01', '2026-08-09 23:16:08.66414+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('cec7b331-7d23-416e-930a-10131ac4e63b', NULL, '00000000-0000-0000-0000-000000000064', 'National Defence Academy of Latvia', 'national-defence-academy-of-latvia', NULL, '{"title": "National Defence Academy of Latvia", "extract": "The National Defence Academy of Latvia is a defense academy of higher education and scientific research in Riga, Latvia. It was established on February 13, 1992, as the Academy of the Ministry of Defense of the Republic of Latvia. It builds on the historic traditions of the pre-WWII Latvian School of War. It is the only military academy in Latvia. The Latvian Armed Forces also contribute to and utilize the Baltic Defence College in Tartu.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/1/14/National_Defence_Academy_of_Latvia_logo.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/National_Defence_Academy_of_Latvia", "description": "Military academy in Riga, Latvia"}', 'e91217e7-b226-433f-8dd4-c769e753e5af', NULL, 'LV', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.5184+01', '2026-08-09 23:16:10.891398+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
