INSERT INTO public.spaces VALUES ('e007f7b8-2725-45e7-bf9f-ad8123216790', NULL, '00000000-0000-0000-0000-000000000064', 'Olympia College', 'olympia-college', NULL, '{"title": "Everest College", "extract": "Everest College was a system of colleges in the United States, and in conjunction with Wyotech made up Zenith Education. It was until 2015 a system of for-profit colleges in the United States and the Canadian province of Ontario, owned and operated by Corinthian Colleges, Inc.. On July 19, 2017, Zenith Education announced that it would rebrand its Everest campuses as Altierus Career College.", "content_url": "https://en.wikipedia.org/wiki/Everest_College", "description": "American system of colleges"}', NULL, NULL, 'MY', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.5184+01', '2026-08-09 23:17:28.982486+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('1134f5e8-d24f-4990-9633-6ca716a809ed', NULL, '00000000-0000-0000-0000-000000000064', 'Université d''Antananarivo', 'universit-d-antananarivo', NULL, '{"title": "University of Antananarivo", "extract": "University of Antananarivo is the primary public university of Madagascar, located in the capital Antananarivo.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/0a/University_of_Antananarivo_Madagascar.JPG/330px-University_of_Antananarivo_Madagascar.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/University_of_Antananarivo", "description": "Public university in Madagascar"}', 'baeb15a7-e928-4bf1-b8bb-315499aa714b', NULL, 'MG', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.5184+01', '2026-08-09 23:16:14.974055+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('527e7698-5823-4d7c-961b-010d97a0cc9d', NULL, '00000000-0000-0000-0000-000000000064', 'Pusan National University', 'pusan-national-university', NULL, '{"title": "Pusan National University", "extract": "Pusan National University is one of ten Flagship Korean National Universities in South Korea. It is the first national university established after the National Liberation Day of Korea.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/5/50/Pusan_National_University_logo.svg/330px-Pusan_National_University_logo.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Pusan_National_University", "description": "National University of Busan and Gyeongsangnam-do, Republic of Korea"}', '602fe52d-b1e0-4128-9fb5-a71fd4ec5fdb', NULL, 'KR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.5184+01', '2026-08-09 23:17:36.700494+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('2ed34e84-046a-444f-844a-89b330978ac2', NULL, '00000000-0000-0000-0000-000000000064', 'Mongolian State University of Agriculture', 'mongolian-state-university-of-agriculture', NULL, '{"title": "Mongolian University of Life Sciences", "extract": "The Mongolian University of Life Sciences is a national university of Mongolia, with the main branch situated in the capital of Ulaanbaatar. It lies in the southern part of the city in the Khoroo 11 district on the southern side of the Tuul River, just to the northwest of the Zaisan Memorial and the American School of Ulan Bator.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/02/Mongolian_University_of_Life_Sciences_Darkhan_Campus.jpg/330px-Mongolian_University_of_Life_Sciences_Darkhan_Campus.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Mongolian_University_of_Life_Sciences", "description": "University in Ulaanbaatar, Mongolia"}', '7720bcf6-bdb3-4e67-b976-898b2f6d2742', NULL, 'MN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.543021+01', '2026-08-09 23:18:17.740838+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('d17bbe9a-3925-4a39-bad0-882009268026', NULL, '00000000-0000-0000-0000-000000000064', 'Gwangju Institute of Science and Technology', 'gwangju-institute-of-science-and-technology', NULL, '{"title": "Gwangju Institute of Science and Technology", "extract": "The Gwangju Institute of Science and Technology (GIST) is a public research university and institute of technology that was established in 1993 by a legislative act of the National Assembly of the Republic of Korea with its primary purpose to advance national science and technology through education, research, and international and industrial cooperation.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/d/d4/Gwangju_Institute_of_Science_and_Technology_%28logo%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Gwangju_Institute_of_Science_and_Technology", "description": "University in South Korea"}', '2a2b7256-ce09-4585-a263-06a418b9c0ea', NULL, 'KR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.5184+01', '2026-08-09 23:18:19.508722+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('0a8ec756-f1a0-41e6-8fd0-c64fda20b6b5', NULL, '00000000-0000-0000-0000-000000000064', 'Instituto Tecnologico de Durango', 'instituto-tecnologico-de-durango', NULL, '{"title": "Durango Institute of Technology", "extract": "The Durango Institute of Technology is a Mexican public university located in the state of Durango.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/1f/Instituto_Tecnologico_de_Durango.jpg/330px-Instituto_Tecnologico_de_Durango.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Durango_Institute_of_Technology", "description": ""}', '255e15f2-b064-4cee-a3ed-0d04359ad4f7', NULL, 'MX', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.543021+01', '2026-08-09 23:18:21.055697+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('b23611ee-8ba5-4f6e-b2b5-05477a617b51', NULL, '00000000-0000-0000-0000-000000000064', 'Palestine Technical University - Kadoorie', 'palestine-technical-university-kadoorie', NULL, '{"title": "Palestine Technical University – Kadoorie", "extract": "Palestine Technical University – Kadoorie  is an agricultural college located in Tulkarm, in the northern West Bank, Palestine. The college was inaugurated in 1930 after the British Government had received a bequest from the Iraqi-born Jewish philanthropist Sir Ellis Kadoorie. The college was named in his honour and still bears his name.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/c1/Ptuk.jpg/330px-Ptuk.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Palestine_Technical_University_%E2%80%93_Kadoorie", "description": "Agricultural school in Tulkarm, Palestine"}', 'd46b9905-0b36-4325-bd17-5542841519c9', NULL, 'PS', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.573335+01', '2026-08-10 09:34:05.170703+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
