INSERT INTO public.spaces VALUES ('d97d91d3-cc3b-4674-99f7-5a0b22e41db9', NULL, '00000000-0000-0000-0000-000000000064', 'Mary Washington College', 'mary-washington-college', NULL, '{"logo": "http://commons.wikimedia.org/wiki/Special:FilePath/Univ%20mary%20wash%20logonew.png", "name": "University of Mary Washington", "image": "http://commons.wikimedia.org/wiki/Special:FilePath/Monroe%20Hall%20UMW.jpg", "country": "Q30", "founded": "+1908-00-00T00:00:00Z", "website": "https://www.umw.edu/", "students": "+4293", "description": "public liberal arts university in Fredericksburg, Virginia, United States", "wikidata_id": "Q657374", "wikipedia_url": "https://en.wikipedia.org/wiki/Q657374"}', 'aac852d8-11fa-4540-920b-7344dff7e175', NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.233464+01', '2026-08-08 05:48:16.874246+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('df47e317-7a08-4ad2-bc39-5103e99f1aae', NULL, '00000000-0000-0000-0000-000000000064', 'Universiti Malaya', 'universiti-malaya', NULL, '{"title": "University of Malaya", "extract": "The University of Malaya is a public research university located in Kuala Lumpur, Malaysia. It is the oldest Malaysian institution of higher education, and was the only university in newly independent Malaya.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/8/8f/University_of_Malaya_logo.svg/330px-University_of_Malaya_logo.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/University_of_Malaya", "description": ""}', '6ced9eb5-3764-4f9e-abd2-8b8d05df5b56', NULL, 'MY', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.543021+01', '2026-08-09 23:17:10.94934+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('508e5cb0-30c8-446e-88d6-d80d80a8e139', NULL, '00000000-0000-0000-0000-000000000064', 'Hankuk University of Foreign Studies', 'hankuk-university-of-foreign-studies', NULL, '{"title": "Hankuk University of Foreign Studies", "extract": "Hankuk University of Foreign Studies is a private research university in Seoul, South Korea. The university currently teaches 45 foreign languages. In addition, it contains studies in humanities, law, political science, social sciences, business, medical science, natural sciences, and engineering.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/d/d4/Hankuk_University_of_Foreign_Studies_emblem.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Hankuk_University_of_Foreign_Studies", "description": "Private university in South Korea"}', 'b68bed1d-33b9-41f4-abb9-adc4562ac2cf', NULL, 'KR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.5184+01', '2026-08-09 23:17:14.68051+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('8374125a-c6bc-40c7-b67a-7e2696129600', NULL, '00000000-0000-0000-0000-000000000064', 'Sangmyung University', 'sangmyung-university', NULL, '{"title": "Sangmyung University", "extract": "Sangmyung University (Korean: 상명대학교) is a private university in South Korea with the main campus in Jongno, Seoul, and an auxiliary campus in Cheonan, Chungcheongnam-do. It was established in 1937, with the Sangmyung Women''s College being founded in 1965, and the Sangmyung Women''s College in Cheonan in 1985. In 1987, the college was promoted to a university and changed its name to Sangmyung Women''s University. In 1996, it changed into coeducation and changed its name to Sangmyung University.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/03/Sangmyung_University.jpg/330px-Sangmyung_University.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Sangmyung_University", "description": "University in Seoul, South Korea"}', 'f7dde97c-644c-4092-b5b0-b9a05512b4b3', NULL, 'KR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.5184+01', '2026-08-09 23:17:21.065561+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('8cc4afe3-129a-46c4-b1d3-298cd00c7bb5', NULL, '00000000-0000-0000-0000-000000000064', 'Vytautas Magnus University', 'vytautas-magnus-university', NULL, '{"title": "Vytautas Magnus University", "extract": "Vytautas Magnus University (VMU) is a public university in Kaunas, Lithuania. The university was founded in 1922 during the interwar period as an alternate national university.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/11/VDU_Didydis_antspaudas.svg/330px-VDU_Didydis_antspaudas.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Vytautas_Magnus_University", "description": "Public university in Kaunas, Lithuania"}', '66e432c8-2aad-4df4-83b0-164878e15967', NULL, 'LT', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.5184+01', '2026-08-09 23:17:24.674924+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('9afc8dff-f563-4d6b-b0d4-7e6260b8ab4d', NULL, '00000000-0000-0000-0000-000000000064', 'Hoseo University', 'hoseo-university', NULL, '{"title": "Hoseo University", "extract": "Hoseo University is a private Christian university with four campuses; Main Campus in Asan, South Korea, other campuses in Cheonan, South Korea, known for its large size, 3.471074 km, Dangjin, South Korea and Seoul, South Korea. It was the first school to establish a graduate school for venture business in South Korea.\nThe university''s \"World Class 2030\" project promotes research in the area of unexplored fields such as the interface of five senses, the expression of the sense of smell, or defense mechanism of invertebrate animals within 20 years.[3]", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/2/21/Hoseo_University_%28Highteen_TV%29_46s.jpg/330px-Hoseo_University_%28Highteen_TV%29_46s.jpg", "content_url": "https://en.wikipedia.org/wiki/Hoseo_University", "description": "Private Christian university in South Korea"}', '77bf9796-cb7b-454d-bcfd-dec67e141c80', NULL, 'KR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.5184+01', '2026-08-09 23:18:32.688409+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('650d37ec-e832-4476-9e19-ca406610a964', NULL, '00000000-0000-0000-0000-000000000064', 'American University College of Technology', 'american-university-college-of-technology', NULL, '{"title": "American University of Technology", "extract": "American University of Technology (AUT), is a private university established in Lebanon. It was founded in 1998 by Ghada Hinain near Byblos. The university is directed by an appointed Board of Trustees.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/83/University.png/330px-University.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/American_University_of_Technology", "description": "Private university in Byblos, Lebanon"}', '3f45d53f-28ff-4c04-b2dd-9f1e91c9c829', NULL, 'LB', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.5184+01', '2026-08-09 23:18:35.354396+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
