INSERT INTO public.spaces VALUES ('9bb20bc5-20ab-4f86-bb9f-6f1319e34afd', NULL, '00000000-0000-0000-0000-000000000064', 'Université Paris-Saclay', 'universit-paris-saclay', NULL, '{"logo": "http://commons.wikimedia.org/wiki/Special:FilePath/Logo%20Universit%C3%A9%20Paris-Saclay%20%28ComUE%29.svg", "name": "Paris-Saclay University", "image": "http://commons.wikimedia.org/wiki/Special:FilePath/All%C3%A9e%20des%20sciences%20Paris-Saclay.jpg", "country": "Q142", "founded": "+2019-11-05T00:00:00Z", "website": "https://www.universite-paris-saclay.fr", "students": "+47007", "description": "university consortium in the South of Paris", "wikidata_id": "Q109409389", "wikipedia_url": "https://en.wikipedia.org/wiki/Q109409389"}', NULL, NULL, 'FR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.726322+01', '2026-08-10 00:23:20.251389+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('d643b6bc-970e-40f1-9830-456c15cb790c', NULL, '00000000-0000-0000-0000-000000000064', 'Chonnam National University', 'chonnam-national-university', NULL, '{"title": "Chonnam National University", "extract": "Chonnam National University is a national university located in Gwangju and South Jeolla Province, Republic of Korea. The University was founded in 1952, under the motto “Truth, Creativity and Service”, by merging five provincial colleges in South Jeolla Province and is now widely recognized as one of the Korea’s ten Flagship Korean National Universities. Following its second merger with Yosu National University in 2006, CNU has operated a specialized multi-campus system across Gwangju, Yeosu and Hwasun.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/7/7f/Chonnam_National_University_logo.svg/330px-Chonnam_National_University_logo.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Chonnam_National_University", "description": "National university in Gwangju, South Korea"}', 'd10c985f-da17-439f-9e08-152d6a3c1f02', NULL, 'KR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.5184+01', '2026-08-09 23:15:09.535906+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('c027d321-1e56-4337-8618-2a5f51c7159b', NULL, '00000000-0000-0000-0000-000000000064', 'University of Livingstonia', 'university-of-livingstonia', NULL, '{"title": "University of Livingstonia", "extract": "The University of Livingstonia (UNILIA) is a university located in Livingstonia, Malawi. It was founded in 2003 and has grown to over 2,000 students located in three campuses. It offers undergraduate and graduate degrees. It is accredited by the National Council of Higher Education.\nThe main campus is the Laws Campus in Livingstonia; a smaller campuses is the Ekwendeni Campusn in Mzimba District.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/8/86/University_of_Livingstonia_arms.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/University_of_Livingstonia", "description": "Private university in Malawi"}', '8b66aa5d-c19e-46e4-ba39-d71eeaed5f6d', NULL, 'MW', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.5184+01', '2026-08-09 23:18:23.172872+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('bd520038-4f81-448a-aba1-e6956d09f33c', NULL, '00000000-0000-0000-0000-000000000064', 'Lithuania Christian College', 'lithuania-christian-college', NULL, '{"title": "LCC International University", "extract": "LCC International University, formerly Lithuania Christian College (LCC), is a liberal arts institution in the city of Klaipėda, Lithuania, established in 1991 by a joint venture of Lithuanian, Canadian and American foundations.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/1/1a/Main_campus_of_LCC_International_University_in_Klaip%C4%97da%2C_Lithuania.jpg/330px-Main_campus_of_LCC_International_University_in_Klaip%C4%97da%2C_Lithuania.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/LCC_International_University", "description": "Liberal arts institution in Klaipėda, Lithuania"}', '149293d2-3eba-4934-bd20-911d4c6c6ddc', NULL, 'LT', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.5184+01', '2026-08-09 23:19:09.375612+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('8af09a92-7b55-4898-af47-6721bf14bb55', NULL, '00000000-0000-0000-0000-000000000064', 'Bahauddin Zakariya University, Multan', 'bahauddin-zakariya-university-multan', NULL, '{"title": "Bahauddin Zakariya University", "extract": "Bahauddin Zakariya University (BZU) (Urdu: جامعۂ بہاءالدین زکریا) is a public university with its main campus located in Multan, Punjab, Pakistan. Bahauddin Zakariya University was founded in 1975 as Multan University, and is today the second largest university in Punjab following University of the Punjab. It was renamed in 1979 in honour of the Punjabi Sufi saint Baha-ud-din Zakariya.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/9c/BZU-Multan.png/330px-BZU-Multan.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Bahauddin_Zakariya_University", "description": "Pakistani public university"}', 'bdc31fa3-2571-4622-ac85-da32b18e2536', NULL, 'PK', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.573335+01', '2026-08-09 23:29:25.175805+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
