INSERT INTO public.spaces VALUES ('b1a5850d-cc84-48eb-89ef-55c5e59c41a8', NULL, '00000000-0000-0000-0000-000000000064', 'Handong Global University', 'handong-global-university', NULL, '{"title": "Handong Global University", "extract": "Handong Global University is a private evangelical four-year university located in Pohang, North Gyeongsang, South Korea, with a campus of approximately 200 acres (0.81 km2).", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/c/c8/HGUseal.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Handong_Global_University", "description": "University in South Korea"}', 'c64aba5c-bdd6-44d5-8435-bdaeb7fee67b', NULL, 'KR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.5184+01', '2026-08-09 23:15:36.845603+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('9684ec0e-de77-4b2f-85cd-e946a120ac8c', NULL, '00000000-0000-0000-0000-000000000064', 'University of Eldoret', 'university-of-eldoret', NULL, '{"title": "University of Eldoret", "extract": "University of Eldoret is one of the 22 public universities in Kenya and situated approximately 9 km along the Eldoret-Ziwa road in Eldoret town, Uasin Gishu County. It was founded in 1946 by the white settlers as a Large Scale Farmers Training Centre. In 1984, it was converted to a teachers’ training college and renamed Moi Teachers’ Training College to offer Diploma Science Teachers Training. \nDue to the double intake crisis, the college was taken over by Moi University as a campus in 1990, renaming it Chepkoilel Campus. From 1990, the university made it a campus of Natural, Basic and Applied Science programmes.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/0/0a/University_of_Eldoret_Administration_Block.jpeg/330px-University_of_Eldoret_Administration_Block.jpeg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/University_of_Eldoret", "description": "University in Kenya"}', '14f7d2c5-735a-4a28-8a4d-82b3ca2c2d73', NULL, 'KE', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.5184+01', '2026-08-09 23:16:25.354674+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('d5607e95-6dbb-49e4-bbda-f1decdd15c07', NULL, '00000000-0000-0000-0000-000000000064', 'Sogang University', 'sogang-university', NULL, '{"title": "Sogang University", "extract": "Sogang University is a private Jesuit research university in Mapo, Seoul, South Korea. Sogang University was established on April 18, 1960 by the Society of Jesus, with the school being the oldest and only Jesuit institution of higher education in the country. It is widely regarded as one of South Korea''s most prestigious universities. It was founded at the initiative of the Catholic Hierarchy of Korea, after Pope Pius XII gave assurance that a Catholic institution of higher learning would be established on the territory of Korea.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/9/99/Sogang_University_emblem.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Sogang_University", "description": "University in Seoul, South Korea"}', 'c8cf96d6-0617-44c3-8d3f-5d55ad24780b', NULL, 'KR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.5184+01', '2026-08-09 23:17:01.632576+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('468f7d4b-a085-4ffc-a4b2-0fce0382c311', NULL, '00000000-0000-0000-0000-000000000064', 'University of Prishtina', 'university-of-prishtina', NULL, '{"title": "University of Pristina", "extract": "The University of Pristina is a public university located in Pristina, Kosovo. It is the institution that emerged after the disestablishment of the University of Pristina (1969–1999) as a result of the Kosovo War. The inauguration of the university was a historical occurrence not only for the people of Kosovo, but for the whole Albanian nation. On 15 February, the solemn Parliament session took place, which is also proclaimed as The University of Pristina''s Day. In the composition of the newly established University of Pristina were faculties with their headquarters in Pristina: the Faculty of Philosophy, Faculty of Law and Economics, Faculty of Engineering and Faculty of Medicine. Now the University of Pristina has 17 faculties, of which 14 are academic faculties and 3 are faculties of applied sciences. \nContained within the emblem is a translation of the name into Latin, Universitas Studiorum Prishtiniensis.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/e1/University_of_Prishtina_logo.svg/330px-University_of_Prishtina_logo.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/University_of_Pristina", "description": "Public university in Kosovo"}', 'ba7a85ca-c30b-439f-aaa5-2db132ad569f', NULL, 'XK', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.5184+01', '2026-08-09 23:17:04.955953+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('dce0d8ca-e1cc-49eb-b06c-bad55cde16ed', NULL, '00000000-0000-0000-0000-000000000064', 'Pyeongtaek University', 'pyeongtaek-university', NULL, '{"title": "Pyeongtaek University", "extract": "Pyeongtaek University is a private research university located in Pyeongtaek, South Korea. Originating at Pierson Memorial Union Bible Institute in 1912, Pyeongtaek University is one of the oldest universities in South Korea.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/67/%ED%8F%89%ED%83%9D%EB%8C%80%ED%95%99%EA%B5%90%28%E5%B9%B3%E6%BE%A4%E5%A4%A7%E5%AD%B8%E6%A0%A1%2C_Pyeongtaek_University%29.jpg/330px-%ED%8F%89%ED%83%9D%EB%8C%80%ED%95%99%EA%B5%90%28%E5%B9%B3%E6%BE%A4%E5%A4%A7%E5%AD%B8%E6%A0%A1%2C_Pyeongtaek_University%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Pyeongtaek_University", "description": "Private university in South Korea"}', '5b3058d0-0375-48ab-99c9-a923acb6a02e', NULL, 'KR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.5184+01', '2026-08-09 23:16:39.436649+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
