INSERT INTO public.spaces VALUES ('fa706aee-03fe-4f9f-ad11-5ca953002b28', NULL, '00000000-0000-0000-0000-000000000064', 'Technical University of Timisoara', 'technical-university-of-timisoara', NULL, '{"title": "Politehnica University of Timișoara", "extract": "Politehnica University of Timișoara is a public university in Timișoara. Founded in 1920, it is one of the largest technical universities in Central and Eastern Europe. The 10 faculties of the university provide study programs for about 13,000 students. In 2011, Politehnica University of Timișoara was classified as an advanced research and education university by the Ministry of Education. The university is a founding member of the Romanian Alliance of Technical Universities (ARUT).", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/49/Universitatea_Politehnica_Timisoara_-_Rectorat.jpg/330px-Universitatea_Politehnica_Timisoara_-_Rectorat.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Politehnica_University_of_Timi%C8%99oara", "description": "University in Romania"}', '68c45fa5-3911-4a03-8370-4fcca7a9d33f', NULL, 'RO', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.60068+01', '2026-08-09 23:37:17.762041+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
