INSERT INTO public.spaces VALUES ('252f10ee-b098-4a7e-98af-119ae5341a4a', NULL, '00000000-0000-0000-0000-000000000064', 'University College of Skövde', 'university-college-of-sk-vde', NULL, '{"title": "University of Skövde", "extract": "The University of Skövde is a Swedish state university in Skövde municipality, Sweden.. The higher education institution was founded in 1977 and was granted official university status in 1983.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/d/d9/HIS_EN_LOGO_WEB.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/University_of_Sk%C3%B6vde", "description": "Public University in Sweden"}', 'eff05cd2-8026-4de8-a0c9-c11219caa2dd', NULL, 'SE', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.625787+01', '2026-08-09 23:48:18.544996+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('1fd8283c-efc3-4080-ad04-c5d733c6ce62', NULL, '00000000-0000-0000-0000-000000000064', 'CUNY Lehman College', 'cuny-lehman-college', NULL, '{"title": "Lehman College", "extract": "Lehman College is a public college in New York City, United States. Founded in 1931 as the Bronx campus of Hunter College, it became an independent college in 1967. The college is named after Herbert H. Lehman, a former New York governor, United States senator, and philanthropist. It is a senior college of the City University of New York (CUNY) and offers more than 90 undergraduate and graduate degree programs and specializations.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/1/16/Lehman_College_seal.svg/330px-Lehman_College_seal.svg.png", "content_url": "https://en.wikipedia.org/wiki/Lehman_College", "description": "Public college in the Bronx, New York, US"}', 'b5def44f-1128-4c70-8873-13f10a8b92fa', NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.726322+01', '2026-08-10 00:20:18.505744+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
