INSERT INTO public.spaces VALUES ('a705d08b-989e-4e79-aea5-6bd3c13642db', NULL, '00000000-0000-0000-0000-000000000064', 'University of Texas - Pan American', 'university-of-texas-pan-american', NULL, '{"title": "University of Texas–Pan American", "extract": "The University of Texas–Pan American (UTPA) was a public university in Edinburg, Texas, United States from 1927 until 2015. Founded as Edinburg College, it was a component institution of the University of Texas System. The university served the Rio Grande Valley and South Texas with baccalaureate, master''s, and doctoral degrees. The Carnegie Foundation classified UTPA as a \"doctoral research university\". From the institution''s founding until it was merged into the University of Texas Rio Grande Valley (UTRGV), it grew from 200 students to over 20,000, making UTPA the 10th-largest university in Texas. The majority of these students were natives of the Rio Grande Valley. UTPA also operated an Upper Level Studies Center in Rio Grande City, Starr County, Texas. On August 15, 2014, Dr. Havidan Rodriguez was appointed interim President of UTPA, the institution''s final leader.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/a/ad/Texas%E2%80%93Pan_American_seal.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/University_of_Texas%E2%80%93Pan_American", "description": "Public University in Edinburg, Texas"}', '0b800f30-0558-44c8-9b81-f0636918d56f', NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.262718+01', '2026-08-10 00:47:07.29098+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
