INSERT INTO public.spaces VALUES ('c52e7d62-9aae-4765-a7fb-130cb24187ce', NULL, '00000000-0000-0000-0000-000000000064', 'Bangabandhu Sheikh Mujibur Rahman Medical University', 'bangabandhu-sheikh-mujibur-rahman-medical-university', NULL, '{"title": "Bangladesh Medical University", "extract": "Bangladesh Medical University (BMU) is a postgraduate medical university in Dhaka, Bangladesh. It was established in 1965 as Institute of Postgraduate Medicine and Research (IPGMR). The university offers postgraduate degrees in various medical specialties including MPhil, MPH, MD, MS, PhD, and diploma degrees.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/6/6b/Bangladesh_Medical_University_Logo.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Bangladesh_Medical_University", "description": "Public medical university in Dhaka, Bangladesh"}', '1e9d3204-b39c-4266-926e-a2edbc8e4812', NULL, 'BD', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.296289+01', '2026-08-10 00:51:14.679049+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
