INSERT INTO public.spaces VALUES ('06fe0e96-d55e-4356-8025-4e16aa285595', NULL, '00000000-0000-0000-0000-000000000064', 'DAV Institute of Engineering & Technology', 'dav-institute-of-engineering-technology', NULL, '{"title": "DAV Institute of Engineering and Technology", "extract": "DAV Institute of Engineering and Technology (DAVIET) is a private engineering institute in Jalandhar city of Punjab, India. It is established by the Dayanand Anglo-Vedic College Trust and Management Society offering undergraduate and post-graduate programmes. The DAV College Trust and Management Society is the largest non-government educational organization in India, managing a chain of about 700 institutions in India and abroad. The institute is located in the heart of city adjacent to DAV College, Jalandhar, on the left side of the Jalandhar-Amritsar National Highway.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/f/f4/DAVIET_logo.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/DAV_Institute_of_Engineering_and_Technology", "description": "Private engineering institute in Jalandhar, Punjab, India"}', '998358ec-4e59-498e-803e-2c1162a76a78', NULL, 'IN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.188857+01', '2026-08-10 00:53:24.250722+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
