INSERT INTO public.spaces VALUES ('db6c33b8-0c8c-418f-bacf-b0815bb85028', NULL, '00000000-0000-0000-0000-000000000064', 'University of Science & Technology Chittagong', 'university-of-science-technology-chittagong', NULL, '{"title": "University of Science and Technology Chittagong", "extract": "University of Science & Technology Chittagong (USTC) is the first private Research university in Chattogram, Bangladesh along with the first certified private university by University Grants Commission in Bangladesh. At first, it was established with the sponsorship of a private charity on 13 May 1989. Later, it was upgraded to USTC as a full-phased university under the Private University Act of 1992.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/7/72/University_of_Science_and_Technology%2C_Chittagong_%28crest%29.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/University_of_Science_and_Technology_Chittagong", "description": "Science and Technology University in Bangladesh"}', '10e4b1ad-567e-46fb-8b33-8b23a1c5244c', NULL, 'BD', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.296289+01', '2026-08-10 00:56:21.228272+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
