INSERT INTO public.spaces VALUES ('8fdb7c5b-6a93-478f-99de-aff53a4b80fd', NULL, '00000000-0000-0000-0000-000000000064', 'B. S. Abdur Rahman University', 'b-s-abdur-rahman-university', NULL, '{"title": "B. S. Abdur Rahman Crescent Institute of Science and Technology", "extract": "B.S. Abdur Rahman Crescent Institute of Science and Technology is a private deemed university located in Tamil Nadu, India. Founded in 1984, Crescent was one of the first self-financing engineering institutions in the Indian State of Tamil Nadu. After being affiliated to University of Madras and Anna University for 25 years, Crescent was Deemed to be University by Indian Government and was known as B.S. Abdur Rahman Crescent University. Since 2017, Crescent is known as B.S. Abdur Rahman Crescent Institute of Science and Technology.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/c/c7/B.S._Abdur_Rahman_Crescent_Institute_of_Science_and_Technology_logo.png", "content_url": "https://en.wikipedia.org/wiki/B._S._Abdur_Rahman_Crescent_Institute_of_Science_and_Technology", "description": "Private university in Chennai, Tamil Nadu, India"}', 'f4a8f6ea-761e-4f4d-8b9d-ee04f19f57fe', NULL, 'IN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.411195+01', '2026-08-10 01:28:17.713035+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('c8c0db4a-fcf2-4d4e-a4ce-0ed2fa5f219e', NULL, '00000000-0000-0000-0000-000000000064', 'Trinity College Bristol', 'trinity-college-bristol', NULL, '{"title": "Trinity College, Bristol", "extract": "Trinity College, Bristol is an evangelical Anglican theological college located in Stoke Bishop, Bristol, England. It offers a range of full-time and part-time taught undergraduate and postgraduate courses which are validated by the University of Durham through the Common Awards Scheme, though the college sets its own curriculum. Many of its students are training for ordination in the Church of England; and hence there is a strong vocational aspect to the courses it provides. It also has students of other Christian denominations, as well as students who are intending to serve within various forms of lay ministry. The college also has a significant number of students studying for research degrees at masters and doctoral levels. All of Trinity''s postgraduate research courses are validated by the University of Aberdeen.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/fa/Trinitycollegebristol.jpg/330px-Trinitycollegebristol.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Trinity_College%2C_Bristol", "description": "Evangelical Anglican theological college in Bristol, England"}', '3c7e4c4e-475c-483b-a9bc-cdd0b380dbfb', NULL, 'GB', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.753691+01', '2026-08-10 10:22:40.734093+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
