INSERT INTO public.spaces VALUES ('74ad7e26-9b82-4478-b396-a65f84b1248a', NULL, '00000000-0000-0000-0000-000000000064', 'National Institute of Technology Srinagar', 'national-institute-of-technology-srinagar', NULL, '{"title": "National Institute of Technology, Srinagar", "extract": "National Institute of Technology Srinagar is a public technical university located in Srinagar, Jammu and Kashmir, India. It is one of the 31 National Institutes of Technology (NITs) and, as such, is directly under the control of the Ministry of Education (MoE). It was established in 1960 as one of several Regional Engineering Colleges established as part of the Second Five-Year Plan (1956–61) by the Government of India. It is governed by the National Institutes of Technology Act, 2007, which has declared it an Institute of National Importance.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/2/24/National_Institute_of_Technology%2C_Srinagar_Logo.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/National_Institute_of_Technology%2C_Srinagar", "description": "Institute in Srinagar, Jammu and Kashmir"}', '480bc1db-0a5f-44bf-8e36-950d6812a270', NULL, 'IN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.436788+01', '2026-08-10 01:33:26.582523+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
