INSERT INTO public.spaces VALUES ('576dc359-58e6-49eb-8206-8d13512b66de', NULL, '00000000-0000-0000-0000-000000000064', 'Pusan University of Foreign Studies', 'pusan-university-of-foreign-studies', NULL, '{"title": "Busan University of Foreign Studies", "extract": "Busan University of Foreign Studies (Korean: 부산외국어대학교), often shortened to 부산외대 and BUFS, romanized as Pusan University of Foreign Studies before 2011, is a private university in Busan, South Korea, which specializes in foreign languages. \nIn 2014, following the completion of a new campus on the slope of Mount Geumjeongsan, the university moved to Namsan-dong.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/08/BUFS.jpg/330px-BUFS.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Busan_University_of_Foreign_Studies", "description": "University in Busan, South Korea"}', '7ef6b66d-fd7a-4101-ad4a-ef838acd57b0', NULL, 'KR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.5184+01', '2026-08-10 03:24:30.889371+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
