INSERT INTO public.spaces VALUES ('7336f2a0-ffeb-4327-866a-f5763ca83060', NULL, '00000000-0000-0000-0000-000000000064', 'UC Hastings College of the Law', 'uc-hastings-college-of-the-law', NULL, '{"title": "University of California College of the Law, San Francisco", "extract": "The University of California College of the Law, San Francisco is a public law school in San Francisco. Formerly known as the University of California, Hastings College of the Law, the school was founded in 1878 by Serranus Clinton Hastings, the first chief justice of the Supreme Court of California. It was the first law school of the University of California and one of the first law schools established in California. Although part of the University of California, UC Law SF is not directly governed by the Regents of the University of California.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/5/53/UC_Law_San_Francisco_Seal.svg/330px-UC_Law_San_Francisco_Seal.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/University_of_California_College_of_the_Law%2C_San_Francisco", "description": "Public law school in San Francisco, California"}', '32ff7d6b-63aa-4573-872c-b5e36f6b49fa', NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.262718+01', '2026-08-11 00:23:19.279563+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
