INSERT INTO public.spaces VALUES ('0c9ad405-ffc7-4e9f-a80c-6f4b8ca54f83', NULL, '00000000-0000-0000-0000-000000000064', 'Kiev National University of Construction and Architecture', 'kiev-national-university-of-construction-and-architecture', NULL, '{"title": "Kyiv National University of Construction and Architecture", "extract": "The Kyiv National University of Construction and Architecture – better known under its former name abbr.  KISI or KIBI for rendering of Kyiv Civil Engineering Institute – is the largest and most important civil engineering, construction and architectural university of Ukraine located in the nation''s capital, Kyiv.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/0/04/LogoKNUBA3.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Kyiv_National_University_of_Construction_and_Architecture", "description": "Public university in Kyiv, Ukraine"}', '4b239be4-b616-4400-9d3a-39b0c4d34d7f', NULL, 'UA', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.65283+01', '2026-08-10 04:08:20.241561+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('797b6af6-2b4f-4429-83aa-a1f4b5661575', NULL, '00000000-0000-0000-0000-000000000064', 'Luhansk Taras Shevchenko National Pedagogical University', 'luhansk-taras-shevchenko-national-pedagogical-university', NULL, '{"title": "Luhansk University", "extract": "Luhansk University is a higher education institution located in the Donbas region of Ukraine. Founded in the Ukrainian SSR in 1921, it is the oldest university in the region. Since the outbreak of the Russo-Ukrainian War in 2014, the institution has de facto operated as two competing entities:The Ukraine-aligned Luhansk Taras Shevchenko National University, which maintains campuses in Poltava, Myrhorod, and Lubny.\nThe Russian Federation-aligned Luhansk State Pedagogical University, which remains based at the original campus in Luhansk.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/8/8f/Luhansk_University_%28Luhansk_campus%29_logo.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Luhansk_University", "description": "University in Luhansk"}', '3feb640e-86fa-4f1c-a8b9-0115695e54ff', NULL, 'UA', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.65283+01', '2026-08-10 04:03:06.671477+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
