INSERT INTO public.spaces VALUES ('30afa5a5-ef89-4799-95f8-5938c5c09cf5', NULL, '00000000-0000-0000-0000-000000000064', 'Cedarville College', 'cedarville-college', NULL, '{"title": "Cedarville University", "extract": "Cedarville University is a private university in Cedarville, Ohio, United States. Established in 1887, the school was originally affiliated with the conservative Reformed Presbyterian Church in North America, General Synod. In 1953, the college became affiliated with the General Association of Regular Baptist Churches until 2006. Since 2003, Cedarville is affiliated with the State Convention of Baptists in Ohio. It is chartered by the state of Ohio, approved by the Ohio Board of Regents, and accredited by the Higher Learning Commission.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/f/f6/Cedarville_univ_seal.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Cedarville_University", "description": "Baptist university in Cedarville, Ohio, US"}', '3a72de8b-0a59-482e-9b5f-f8764d28d2ae', NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.188857+01', '2026-08-10 06:20:39.113335+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
