INSERT INTO public.spaces VALUES ('05f8ca37-6727-4826-a5e0-773d3fcf14e1', NULL, '00000000-0000-0000-0000-000000000064', 'University of Nebraska, Omaha', 'university-of-nebraska-omaha', NULL, '{"title": "University of Nebraska Omaha", "extract": "The University of Nebraska at Omaha (UNO) is a public research university in Omaha, Nebraska, United States. Founded in 1908 by faculty from the Omaha Presbyterian Theological Seminary as a private non-sectarian college, the university was originally known as the University of Omaha. Originally meant to provide a Christian-based education free from ecclesiastical control, the university served as a strong alternative to the city''s many successful religiously-affiliated institutions.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/a2/Seal_of_the_University_of_Nebraska.svg/330px-Seal_of_the_University_of_Nebraska.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/University_of_Nebraska_Omaha", "description": "Public university in Omaha, Nebraska, US"}', 'a0d7ac54-f302-4981-92da-df2daa169df3', NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.262718+01', '2026-08-10 06:41:09.641916+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
