INSERT INTO public.spaces VALUES ('b86c1b52-c269-4180-abbe-b7e55a8656ae', NULL, '00000000-0000-0000-0000-000000000064', 'Dongduk Women''s University', 'dongduk-women-s-university', NULL, '{"title": "Dongduk Women''s University", "extract": "Dongduk Women''s University is a private university in Seoul, South Korea. Dongduk Women''s University is originated from Dongwon Girls School, founded in 1950. DWU is composed of eight colleges, six departments, 18 majors, 16 departments of majors, and seven graduate schools. Facilities include its Design Research Center in Chungdam, Performing Art Center in Daehangno, and Dongduk Art Gallery in Insadong.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/1/18/Dongduk_Women%27s_University_logo.svg/330px-Dongduk_Women%27s_University_logo.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Dongduk_Women''s_University", "description": "Private university in Seoul, South Korea"}', NULL, NULL, 'KR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.5184+01', '2026-08-07 12:47:33.5184+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
