INSERT INTO public.spaces VALUES ('2f03082d-ee70-416b-8989-394ff8ba7a79', NULL, '00000000-0000-0000-0000-000000000064', 'Annamalai University', 'annamalai-university', NULL, '{"title": "Annamalai University", "extract": "The Annamalai University (AU) is a public state university in Chidambaram, Tamil Nadu, India. The 1,500-acre (6.1 km2) sprawling campus offers courses of higher education in arts, science, engineering, management, humanities, agriculture, and physical education. With over 32,480 students residing on campus, it is one of the largest teaching, and residential universities in Asia,", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/2/2a/Annamalai_University_logo.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Annamalai_University", "description": "Public university in Tamil Nadu, India"}', NULL, NULL, 'IN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.411195+01', '2026-08-07 12:47:33.411195+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('12d81c42-7e66-4b37-ad9d-83d5fc57d9ef', NULL, '00000000-0000-0000-0000-000000000064', 'Anhui University of Traditional Chinese Medicine', 'anhui-university-of-traditional-chinese-medicine', NULL, '{"title": "Anhui University of Chinese Medicine", "extract": "Anhui University of Chinese Medicine is a comprehensive public university based in Hefei, Anhui province, China. The university provides programmes in traditional Chinese medicine as well as in the fields of technology, engineering, management and economics.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/5/58/Anhui_University_of_Chinese_Medicine_logo.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Anhui_University_of_Chinese_Medicine", "description": "University in Hefei, Anhui, China"}', NULL, NULL, 'CN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.326239+01', '2026-08-07 12:47:33.326239+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('58f1a25c-c445-4bd5-b869-76cc6e6d5244', NULL, '00000000-0000-0000-0000-000000000064', 'Ankara Haci Bayram Veli University', 'ankara-haci-bayram-veli-university', NULL, '{"title": "Ankara Hacı Bayram Veli University", "extract": "Ankara Hacı Bayram Veli University, shortened HBV, is a public university in Turkey which was formed on 18 May 2018 by the separation from Gazi University. Some faculties which have been separated from Gazi University in accordance with the law no 7141 such as Gazi University Faculty of Law, Faculty of Economics and Administrative Sciences, Faculty of Letters have been become a part of newly established Ankara Hacı Bayram Veli University. The Besevler Campus is located in the city center of Ankara, the capital city of Turkey. Besevler Campus, which has the Faculty of Law and Faculty of Economics and Administrative Sciences, has graduated many famous people who are active in Turkish politics. Kemal Kılıçdaroğlu of the Republican People''s Party, the leader of the main opposition party in the Turkish Grand National Assembly, and Devlet Bahçeli, the leader of the Nationalist Movement Party, have graduated from the aforementioned Faculty of Economics and Administrative Sciences.", "content_url": "https://en.wikipedia.org/wiki/Ankara_Hac%C4%B1_Bayram_Veli_University", "description": "Turkish public university located in Ankara"}', NULL, NULL, 'TR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.65283+01', '2026-08-07 12:47:33.65283+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
