INSERT INTO public.spaces VALUES ('d5faf135-07bc-421d-86f5-ad513af2d72a', NULL, '00000000-0000-0000-0000-000000000064', 'Arkansas Baptist College', 'arkansas-baptist-college', NULL, '{"title": "Arkansas Baptist College", "extract": "Arkansas Baptist College (ABC) is a private Baptist-affiliated historically black college in Little Rock, Arkansas. Founded in 1884 as the Minister''s Institute, while later renaming it to its current name in April 1885, ABC was initially funded by the Colored Baptists of the State of Arkansas. It is the only historically black Baptist school west of the Mississippi River. The Main Building on its campus, built in 1893, is one of the oldest surviving academic buildings in the state, and was listed on the National Register of Historic Places in 1976.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/0/0e/Arkansas_Baptist_College_seal.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Arkansas_Baptist_College", "description": "Private college in Little Rock, Arkansas, U.S."}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.726322+01', '2026-08-07 12:47:33.726322+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
