INSERT INTO public.spaces VALUES ('45107419-ac56-4ea7-9540-69e1d9fdc6bb', NULL, '00000000-0000-0000-0000-000000000064', 'Armstrong State College', 'armstrong-state-college', NULL, '{"title": "Georgia Southern University–Armstrong Campus", "extract": "Georgia Southern University–Armstrong Campus, formerly Armstrong State University, is one of four campuses of Georgia Southern University, a public university in the U.S. state of Georgia. Occupying a 268-acre (1.08 km2) area on the residential southside of Savannah, Georgia, the school became one of three campuses of Georgia Southern University in 2018. The university''s flagship campus is in Statesboro, 50 miles (80 km) west of Savannah. The Armstrong campus is located approximately 15 miles (24 km) from downtown Savannah and 25 miles (40 km) from Tybee Island. Armstrong offers undergraduate and graduate degrees; it has a total student enrollment of approximately 5,000 students.", "content_url": "https://en.wikipedia.org/wiki/Georgia_Southern_University%E2%80%93Armstrong_Campus", "description": "Public university in Savannah, Georgia, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.188857+01', '2026-08-07 12:47:33.188857+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
