INSERT INTO public.spaces VALUES ('6d94d685-aab0-4723-8957-235fc2218a36', NULL, '00000000-0000-0000-0000-000000000060', 'Tuvalu', 'tuvalu', 'It is set in Oceania, an island nation. Whether you''re still in Oceania or building a life elsewhere, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Tuvalu", "extract": "Tuvalu is an archipelagic country in the Polynesian sub-region of Oceania in the Pacific Ocean, about midway between Hawaii and Australia. It lies east-northeast of the Santa Cruz Islands, northeast of Vanuatu, southeast of Nauru, south of Kiribati, west of Tokelau, northwest of Samoa and Wallis and Futuna, and north of Fiji.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/38/Flag_of_Tuvalu.svg/330px-Flag_of_Tuvalu.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Tuvalu", "description": "Island country in Oceania"}', '92469f28-573b-4e10-8d75-91c4977a2ff9', NULL, 'TV', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:54.774915+01', NULL, NULL, '{tuvalu,tv,oceania,island,community,diaspora}', NULL, 'Oceania', 'Polynesia', NULL);
