INSERT INTO public.spaces VALUES ('e5d3b8e4-faf0-4ecb-adbd-56e00d728e0f', NULL, '00000000-0000-0000-0000-000000000064', 'Assam University', 'assam-university', NULL, '{"title": "Assam University", "extract": "Assam University is a central public university located at Silchar, Assam, India. It was founded in the year 1994 by the provisions of an act enacted by the Parliament of India. Former Air Chief Marshal Arup Raha is the Chancellor, the Governor of Assam is the Chief Rector and the President of India is acting as the Visitor of the university. Professor Rajive Mohan Pant succeeded Professor Dilip Chandra Nath as the vice chancellor of the university. The university has sixteen schools which offer Humanities, Languages, Environmental Sciences, Information Sciences, Life Sciences, Physical Sciences, Social Sciences, Law, Technology and Management Studies. There are 42 departments under these sixteen schools. The five districts under the jurisdiction of Assam University have 73 undergraduate colleges as of 31 March 2020. Assam University is an institutional signatory to the Global Universities Network for Innovation (GUNI), Barcelona and United Nations Global Compact (UNGC) for its commitment to educational social responsibilities.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/6/6e/Assam_University_Logo.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Assam_University", "description": "Indian university in Silchar, Assam"}', NULL, NULL, 'IN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.411195+01', '2026-08-07 12:47:33.411195+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
