INSERT INTO public.spaces VALUES ('7b729752-e0c9-4f29-918b-f4382bd84eeb', NULL, '00000000-0000-0000-0000-000000000064', 'Assumption College for Sisters', 'assumption-college-for-sisters', NULL, '{"title": "Assumption College for Sisters", "extract": "The Assumption College for Sisters is a private two-year Catholic women''s college formerly located in Mendham Borough, New Jersey, United States. Founded in 1953 through an affiliation with nearby Seton Hall University, Assumption is run by the Sisters of Christian Charity. It is the last remaining sisters'' college, or college primarily designed to educate religious sisters, in the US. Since 2014, Assumption has shared a campus with Morris Catholic High School in Denville Township, New Jersey.", "content_url": "https://en.wikipedia.org/wiki/Assumption_College_for_Sisters", "description": "Private Roman Catholic women''s college in Mendham Borough, New Jersey"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-07 12:47:33.702225+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
