INSERT INTO public.spaces VALUES ('780d5d0d-3a45-44c0-896f-12183ed4c269', NULL, '00000000-0000-0000-0000-000000000064', 'Aston University', 'aston-university', NULL, '{"title": "Aston University", "extract": "Aston University is a public university situated in the city centre of Birmingham, England. Aston began as the Birmingham Municipal Technical School in 1895, evolving into the UK''s first college of advanced technology in 1956. Aston University received its royal charter from Queen Elizabeth II on 22 April 1966.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/07/Shield_of_Aston_University.svg/330px-Shield_of_Aston_University.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Aston_University", "description": "University in Birmingham, England"}', NULL, NULL, 'GB', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.65283+01', '2026-08-07 12:47:33.65283+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('577938b4-60d4-4ceb-8d78-70d878b73250', NULL, '00000000-0000-0000-0000-000000000064', 'Ateneo de Davao University', 'ateneo-de-davao-university', NULL, '{"title": "Ateneo de Davao University", "extract": "The Ateneo de Davao University is a private Catholic basic and higher education institution in Davao City, Davao del Sur, Philippines. It is run by the Philippine Jesuit Province.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/6/64/Ateneo_de_Davao_University_logo.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Ateneo_de_Davao_University", "description": "Roman Catholic university in Davao City, Philippines"}', NULL, NULL, 'PH', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.573335+01', '2026-08-07 12:47:33.573335+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('0c32cb11-0da5-4a00-bdc5-44dfb3f3ae3f', NULL, '00000000-0000-0000-0000-000000000064', 'Atatürk University', 'atat-rk-university', NULL, '{"title": "Atatürk University", "extract": "Atatürk University is a public land-grant research university established in 1957 in Erzurum, Turkey, in collaboration with the University of Nebraska. The university comprises 23 faculties, 18 colleges, 8 institutes, and 30 research centers. The university''s main campus is located in Erzurum, one of the largest cities in Eastern Anatolia, and is considered one of the city''s most prominent assets. Since its founding, the university has been a center of educational and cultural development for the eastern region of Turkey.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/3a/Atat%C3%BCrk_%C3%9Cniversitesi%2C_2012.jpg/330px-Atat%C3%BCrk_%C3%9Cniversitesi%2C_2012.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Atat%C3%BCrk_University", "description": "Public university located in Erzurum, Turkey"}', NULL, NULL, 'TR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.65283+01', '2026-08-07 12:47:33.65283+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('90975998-e630-4c30-8a96-a1e17f6453c8', NULL, '00000000-0000-0000-0000-000000000064', 'Donetsk National Technical University', 'donetsk-national-technical-university', NULL, '{"title": "Donetsk National Technical University", "extract": "The Donetsk National Technical University is the largest and oldest higher education institution established in Donbas, founded in 1921. Since 2024, a Ukrainian-controlled campus has been operating in Drohobych, Lviv Oblast, due to the Russo-Ukrainian war. The Russian-controlled campus in Donetsk continues to function, leaving the university effectively split between the two governments.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/3a/Logo_DNTU.png/330px-Logo_DNTU.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Donetsk_National_Technical_University", "description": "University in Donetsk, Ukraine"}', NULL, NULL, 'UA', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.65283+01', '2026-08-07 12:47:33.65283+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('20663bbd-be3e-471a-8218-52368e63d2bb', NULL, '00000000-0000-0000-0000-000000000064', 'Donetsk State Medical University', 'donetsk-state-medical-university', NULL, '{"title": "Donetsk National Medical University", "extract": "The Donetsk National Medical University is one of the largest medical state-sponsored universities in Ukraine and the former USSR. The university is considered one of the best medical schools in Ukraine. Originally located in Donetsk, it was relocated to Kropyvnytskyi and Mariupol in 2014 due to the War in Donbas.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/a0/%D0%94%D0%BE%D0%BD%D0%9D%D0%9C%D0%A3.jpg/330px-%D0%94%D0%BE%D0%BD%D0%9D%D0%9C%D0%A3.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Donetsk_National_Medical_University", "description": "Public university in Kropyvnytskyi and Mariupol, Ukraine"}', NULL, NULL, 'UA', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.65283+01', '2026-08-07 12:47:33.65283+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
