INSERT INTO public.spaces VALUES ('a086e516-4f81-41d8-97d9-cadac436aae1', NULL, '00000000-0000-0000-0000-000000000064', 'Australian Maritime College', 'australian-maritime-college', NULL, '{"title": "Australian Maritime College", "extract": "The Australian Maritime College (AMC) is a tertiary education institution based in Launceston, Tasmania, established by the Maritime College Act 1978 (Cth). Tertiary education is provided and organised by the University of Tasmania (UTAS) as the Australian Maritime College at the University of Tasmania (AMC@UTAS). The college''s educational curriculum is governed by the independent AMC Board. The AMC is Australia''s national centre for maritime education, training and research. It has two campuses located within 50 kilometres (31 mi) of each other in Northern Tasmania, each with different facilities and residence. The AMC''s two national centres are the National Centre for Maritime Engineering and Hydrodynamics and the National Centre for Ports and Shipping. AMC also has a commercial arm, AMC Search Ltd, that provides maritime related training and consultancy for a wide range of international and Australian organisations and individuals including the Federal Government Pacific Patrol Boat Program.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d9/Australian_Maritime_College_Logo.png/330px-Australian_Maritime_College_Logo.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Australian_Maritime_College", "description": "Maritime college in Tasmania, Australia"}', NULL, NULL, 'AU', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.296289+01', '2026-08-07 12:47:33.296289+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('ed7c17be-f170-4284-9da0-8ee65be98f81', NULL, '00000000-0000-0000-0000-000000000064', 'Dundalk Institute of Technology', 'dundalk-institute-of-technology', NULL, '{"title": "Dundalk Institute of Technology", "extract": "Dundalk Institute of Technology is an institute of technology, located in Dundalk, Ireland. Established as the Dundalk Regional Technical College, students were first enrolled in the college in 1971 and it was later re-defined as an institute of technology in January 1998.", "content_url": "https://en.wikipedia.org/wiki/Dundalk_Institute_of_Technology", "description": "Irish institute of technology"}', NULL, NULL, 'IE', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.726322+01', '2026-08-07 12:47:33.726322+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('bf290fc7-0eec-48cd-a7f4-7e5afd2ab45d', NULL, '00000000-0000-0000-0000-000000000064', 'Australian International School', 'australian-international-school', NULL, '{"title": "Australian International School", "extract": "Australian International School may refer to:Australian International School Beijing\nAustralian International School Hong Kong\nAustralian Independent School, Indonesia, formerly Australian International School, Indonesia. Name change was a government requirement.\nAustralian International School, Malaysia\nAustralian International School Singapore", "content_url": "https://en.wikipedia.org/wiki/Australian_International_School", "description": "Topics referred to by the same term"}', NULL, NULL, 'SG', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.726322+01', '2026-08-07 12:47:33.726322+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('0fb03d19-3da6-475b-af86-9bbbc17f8d5d', NULL, '00000000-0000-0000-0000-000000000064', 'Avicenna International College', 'avicenna-international-college', NULL, '{"title": "Avicenna International College", "extract": "Avicenna International College (AIC) was founded in 1995 by Shahrokh Mirza Hosseini and has been in operation as a preparatory college for higher education since 2000. It offers foundation programs in medicine, business, technical studies, and English, as well as preparatory programs for Masters and PhD studies.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/9e/Avicenna_International_College2.jpg/330px-Avicenna_International_College2.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Avicenna_International_College", "description": "Preparatory college in Hungary"}', NULL, NULL, 'HU', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.411195+01', '2026-08-07 12:47:33.411195+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
