INSERT INTO public.spaces VALUES ('32bf6870-87ab-412f-8058-a6f83c990cdb', NULL, '00000000-0000-0000-0000-000000000064', 'Australian National University', 'australian-national-university', NULL, '{"title": "Australian National University", "extract": "The Australian National University (ANU) is a public research university and member of the Group of Eight, located in Canberra, the capital of Australia. Its main campus in Acton encompasses seven teaching and research colleges, in addition to several national academies and institutes.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/5/5f/Australian_National_University_coat_of_arms.svg/330px-Australian_National_University_coat_of_arms.svg.png", "content_url": "https://en.wikipedia.org/wiki/Australian_National_University", "description": "National research university in Canberra, Australian Capital Territory"}', NULL, NULL, 'AU', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.296289+01', '2026-08-07 12:47:33.296289+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('742be468-515c-4572-a214-69361d3f5f33', NULL, '00000000-0000-0000-0000-000000000064', 'Avrasya University', 'avrasya-university', NULL, '{"title": "Avrasya University", "extract": "Avrasya University is a foundation (private) university located in Trabzon, Turkey. It was established on November 25, 2010, by the Maçka İmar, Eğitim, Kültür ve Sosyal Hizmet Vakfı and began academic activities in the 2011–2012 academic year.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/e/ee/Avrasya_%C3%9Cniversitesi.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Avrasya_University", "description": "Private university in Trabzon, Turkey"}', NULL, NULL, 'TR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.679268+01', '2026-08-07 12:47:33.679268+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
