INSERT INTO public.spaces VALUES ('fc07c8f5-533c-46b3-a848-bac01e15a8af', NULL, '00000000-0000-0000-0000-000000000064', 'Averett College', 'averett-college', NULL, '{"title": "Averett University", "extract": "Averett University (AU) is a private university in Danville, Virginia, United States. Founded in 1859 as a women''s college, Averett became a four-year, coeducational institution in 1969. In 2011, the university restored its Baptist affiliation, renewing a relationship that had existed from Averett''s founding until 2005.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/b/bc/Averett_stacked_logo.png/330px-Averett_stacked_logo.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Averett_University", "description": "Baptist college in Danville, Virginia, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.188857+01', '2026-08-07 12:47:33.188857+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
