INSERT INTO public.spaces VALUES ('1b6ac99f-c121-4555-86e8-7301012c02d8', NULL, '00000000-0000-0000-0000-000000000064', 'Baker University', 'baker-university', NULL, '{"title": "Baker University", "extract": "Baker University is a private university in Baldwin City, Kansas, United States. Founded in 1858, it was the first four-year university in Kansas and is affiliated with the United Methodist Church. Baker University is made up of four schools. The College of Arts and Sciences and the undergraduate courses in the School of Education (SOE) are located on the campus in Baldwin City. The School of Professional and Graduate Studies (SPGS) and the graduate branch of the SOE serve nontraditional students on campuses in Overland Park, Kansas, and online. The School of Nursing, which is operated in partnership with Stormont Vail Health in Topeka, offers a Bachelor of Science in nursing (BSN) and an online Master of Science in nursing (MSN). Enrollment in all four schools has grown to a student population of more than 3,000, with about 900 students on the Baldwin City campus.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/4/4e/Baker_University_crest.png", "content_url": "https://en.wikipedia.org/wiki/Baker_University", "description": "Private university in Baldwin City, Kansas, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.188857+01', '2026-08-07 12:47:33.188857+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('925cb6b2-5a74-4aa9-8c55-bd6cf2820170', NULL, '00000000-0000-0000-0000-000000000064', 'Bakhtar University', 'bakhtar-university', NULL, '{"title": "Bakhtar Institute of Higher Education", "extract": "Bakhtar University is an established private university in Afghanistan. It is in the capital city, Kabul. The university has developed a research and development cell and will issue its first journal, Bakhtar Journal of Advance Research, soon.", "content_url": "https://en.wikipedia.org/wiki/Bakhtar_Institute_of_Higher_Education", "description": "Private university in Kabul, Afghanistan"}', NULL, NULL, 'AF', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.262718+01', '2026-08-07 12:47:33.262718+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
