INSERT INTO public.spaces VALUES ('a717fa67-cad0-4d9a-b72d-b44279b96d3a', NULL, '00000000-0000-0000-0000-000000000064', 'Baldwin Wallace University', 'baldwin-wallace-university', NULL, '{"title": "Baldwin Wallace University", "extract": "Baldwin Wallace University (BW) is a private university in Berea, Ohio, United States. Established in 1845 as Baldwin Institute by Methodist businessman and former founder of a utopian community at Berea, Ohio John Baldwin, it merged with nearby German Wallace College in 1913 to become Baldwin-Wallace College. There are two campus sites: Berea, which serves as the main campus, and Corporate College East in Warrensville Heights, Ohio. The university enrolls approximately 3,300 full-time undergraduate and graduate students as of fall 2024. Baldwin Wallace''s athletic teams compete as members of NCAA Division III athletics in the Ohio Athletic Conference.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/c/c1/Baldwin_Wallace_University_seal.svg/330px-Baldwin_Wallace_University_seal.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Baldwin_Wallace_University", "description": "Private university in Berea, Ohio, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.188857+01', '2026-08-07 12:47:33.188857+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
