INSERT INTO public.spaces VALUES ('a1fc7029-9205-4613-8e67-219632c2524a', NULL, '00000000-0000-0000-0000-000000000064', 'Bakersfield College', 'bakersfield-college', NULL, '{"title": "Bakersfield College", "extract": "Bakersfield College (BC) is a public community college in Bakersfield, California, United States. BC serves about 31,000 students each semester or 46,500 annually, and offers associate degrees, certificate programs, and is one of fifteen California Community Colleges offering a baccalaureate degree. It is part of the Kern Community College District (KCCD), which is itself part of the California Community Colleges system.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/7/70/Bakersfield_college_seal.png", "content_url": "https://en.wikipedia.org/wiki/Bakersfield_College", "description": "Community college in Bakersfield, California, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.679268+01', '2026-08-07 12:47:33.679268+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
