INSERT INTO public.spaces VALUES ('17bd9614-193f-4a98-bce2-c8c342d64778', NULL, '00000000-0000-0000-0000-000000000064', 'Beijing Foreign Studies University', 'beijing-foreign-studies-university', NULL, '{"title": "Beijing Foreign Studies University", "extract": "Beijing Foreign Studies University is a public university in Haidian, Beijing, China. It is affiliated with the Ministry of Education. The university is part of Project 211 and the Double First-Class Construction.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/07/%E5%8C%97%E4%BA%AC%E5%A4%96%E5%9B%BD%E8%AF%AD%E5%A4%A7%E5%AD%A6.jpeg/330px-%E5%8C%97%E4%BA%AC%E5%A4%96%E5%9B%BD%E8%AF%AD%E5%A4%A7%E5%AD%A6.jpeg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Beijing_Foreign_Studies_University", "description": "Public university in Beijing, China"}', NULL, NULL, 'CN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.326239+01', '2026-08-07 12:47:33.326239+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('8ed2c771-d100-441c-aa09-4efd565a7507', NULL, '00000000-0000-0000-0000-000000000064', 'Beijing Information Science and Technology University', 'beijing-information-science-and-technology-university', NULL, '{"title": "Beijing Information Science and Technology University", "extract": "Beijing Information Science and Technology University (BISTU) is a school of higher education and a merger in founding process of Beijing Institute of Machinery and Beijing Information Technology Institute. The university takes engineering as its main faculty combined with management, liberal and science programs. It is a member of the Plan 111.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/8c/Beijing_Information_Science_and_Technology_University_%2820210608145706%29.jpg/330px-Beijing_Information_Science_and_Technology_University_%2820210608145706%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Beijing_Information_Science_and_Technology_University", "description": "University in China"}', NULL, NULL, 'CN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.326239+01', '2026-08-07 12:47:33.326239+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
