INSERT INTO public.spaces VALUES ('1b3cd331-f2c3-4156-9873-933b8519222e', NULL, '00000000-0000-0000-0000-000000000064', 'Barani Institute of Information Technology', 'barani-institute-of-information-technology', NULL, '{"title": "Barani Institute of Information Technology", "extract": "Barani Institute of Information Technology (BIIT) was established at the Pir Mehr Ali Shah Arid Agriculture University and is located in Rawalpindi, Punjab, Pakistan. The institute is a self-financed/ self-funded project and was established as a partnership venture between the Pir Mehr Ali Shah Arid Agriculture University and Resource Organizers and Software Engineers (ROSE) International.", "content_url": "https://en.wikipedia.org/wiki/Barani_Institute_of_Information_Technology", "description": ""}', NULL, NULL, 'PK', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.573335+01', '2026-08-07 12:47:33.573335+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('ff012bf9-51d4-4e40-b47f-88c8b8bccff8', NULL, '00000000-0000-0000-0000-000000000064', 'Barcelona Graduate School of Economics', 'barcelona-graduate-school-of-economics', NULL, '{"title": "Barcelona School of Economics", "extract": "The Barcelona School of Economics (BSE) is an institute for research and graduate education in economics, finance, data science, and the social sciences located in Barcelona, Spain. It was founded as a partnership among four academic units: Universitat Pompeu Fabra (UPF) and Universitat Autònoma de Barcelona (UAB), together with the Center for Research in International Economics (CREI) and Institute for Economic Analysis (IAE-CSIC). In research-based rankings, BSE is widely recognized as one of the world''s leading economics institutions, while UPF is ranked among the top departments in Europe in Economics & Econometrics. BSE was founded in 2006 by economist and microeconomic theorist Andreu Mas-Colell.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/be/Barcelona_School_of_Economics_logo.svg/330px-Barcelona_School_of_Economics_logo.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Barcelona_School_of_Economics", "description": "Research institution in Barcelona"}', NULL, NULL, 'ES', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.625787+01', '2026-08-07 12:47:33.625787+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('709dcf5f-b45c-4e58-92b0-e7fec1baf11b', NULL, '00000000-0000-0000-0000-000000000064', 'Barber-Scotia College', 'barber-scotia-college', NULL, '{"title": "Barber–Scotia College", "extract": "Barber–Scotia College is a private unaccredited historically black college in Concord, North Carolina. It began as a seminary in 1867 before becoming a college in 1916. It is affiliated with the Presbyterian Church (USA).", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/25/BSC-Seal-blue.jpg/330px-BSC-Seal-blue.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Barber%E2%80%93Scotia_College", "description": "Historically black college in Concord, North Carolina, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.726322+01', '2026-08-07 12:47:33.726322+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('18a5d8f1-da5f-4dff-a914-5728299d0b43', NULL, '00000000-0000-0000-0000-000000000064', 'Bard College', 'bard-college', NULL, '{"title": "Bard College", "extract": "Bard College is a private liberal arts college in Annandale-on-Hudson, New York, United States. The campus overlooks the Hudson River and Catskill Mountains within the Hudson River Historic District and is a National Historic Landmark.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/2/2f/Bard_College_Seal.svg/330px-Bard_College_Seal.svg.png", "content_url": "https://en.wikipedia.org/wiki/Bard_College", "description": "Private college in Annandale-on-Hudson, New York, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.188857+01', '2026-08-07 12:47:33.188857+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('369f6e17-70a3-49fb-ad4f-ab91d7286acc', NULL, '00000000-0000-0000-0000-000000000064', 'Bar-Ilan University', 'bar-ilan-university', NULL, '{"title": "Bar-Ilan University", "extract": "Bar-Ilan University is a public research university in the Tel Aviv District city of Ramat Gan, Israel. Established in 1955, Bar Ilan is Israel''s second-largest academic university institution. It has 20,000 students and 1,350 faculty members.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/9e/Biu_Aerial_photograph_of_Bar-Ilan_University_%2821004322376%29.jpg/330px-Biu_Aerial_photograph_of_Bar-Ilan_University_%2821004322376%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Bar-Ilan_University", "description": "Public research university in Ramat Gan, Israel"}', NULL, NULL, 'IL', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.465646+01', '2026-08-07 12:47:33.465646+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
