INSERT INTO public.spaces VALUES ('b4d8f409-a523-4f60-950b-ba547c368d41', NULL, '00000000-0000-0000-0000-000000000064', 'Barkatullah University', 'barkatullah-university', NULL, '{"title": "Barkatullah University", "extract": "Barkatullah University is a public university in Bhopal, Madhya Pradesh, India. formally known as University of Bhopal, and informally known as Bhopal University. It was named after Barkatullah, one of the freedom fighters in Bhopal.\nBarkatullah University has been accredited as a A category university by the National Assessment and Accreditation Council (NAAC).", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/0/05/Barkatullah_University_logo.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Barkatullah_University", "description": "State University in Madhya Pradesh"}', NULL, NULL, 'IN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.411195+01', '2026-08-07 12:47:33.411195+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('092d9074-f75c-4120-bdc4-e1e0a04fe16e', NULL, '00000000-0000-0000-0000-000000000064', 'Barnard College', 'barnard-college', NULL, '{"title": "Barnard College", "extract": "Barnard College is a private women''s liberal arts college in New York City, New York, United States. It is affiliated with Columbia University and was founded in 1889 by a group of women led by young student activist Annie Nathan Meyer, who petitioned Columbia University''s trustees to create an affiliated college named after university president Frederick A. P. Barnard. The college is one of the original Seven Sisters—seven liberal arts colleges in the Northeastern United States that were historically women''s colleges.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/0/07/Formal_Seal_of_Barnard_College%2C_New_York_City%2C_USA.svg/330px-Formal_Seal_of_Barnard_College%2C_New_York_City%2C_USA.svg.png", "content_url": "https://en.wikipedia.org/wiki/Barnard_College", "description": "Private women''s college in New York City"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.188857+01', '2026-08-07 12:47:33.188857+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('83197cb0-767e-495b-9bf8-72b49924874a', NULL, '00000000-0000-0000-0000-000000000060', 'Montenegro', 'montenegro', 'Every journey out of Southeast Europe carries a story — of ambition, of longing, of roots that stretch but never break. From the capital, Podgorica, to the cities where the diaspora now lives, the connection to home runs deep. Discover local businesses, share news from home, find events near you, and build a network that spans borders — all on JapaConnect.', '{"title": "Montenegro", "extract": "Montenegro is a country in Southeast Europe, on the Balkan Peninsula. Its 25 municipalities have a total population of 633,158 people in an area of 13,883 km2. It is bordered by Serbia to the northeast, Bosnia and Herzegovina to the northwest, Kosovo to the east, Albania to the southeast, and Croatia to the west, and has a coastline along the Adriatic Sea to the southwest. The capital and largest city is Podgorica, while Cetinje is the Old Royal Capital and cultural centre.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/64/Flag_of_Montenegro.svg/330px-Flag_of_Montenegro.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Montenegro", "description": "Country in Southeast Europe"}', 'b5025dc3-ed21-4a3c-b60f-0fb7e38c9adb', NULL, 'ME', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:11.419743+01', NULL, 'EUR', '{montenegro,me,europe,community,diaspora}', NULL, 'Europe', 'Southern Europe', NULL);
INSERT INTO public.spaces VALUES ('80e77845-59c7-434c-a24d-74056a32c27d', NULL, '00000000-0000-0000-0000-000000000064', 'Barton County Community College', 'barton-county-community-college', NULL, '{"title": "Barton Community College", "extract": "Barton Community College, previously Barton County Community College, is a public community college in Great Bend, Kansas. Its service area includes Barton, Ellsworth, Pawnee, Rush and Russell Counties, Stafford County north of US Highway 50, and northwestern Rice County.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/7/71/Barton_Community_College_seal.svg/330px-Barton_Community_College_seal.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Barton_Community_College", "description": "Public college in Great Bend, Kansas, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-07 12:47:33.702225+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
