INSERT INTO public.spaces VALUES ('054f621e-accc-4e9a-bc46-26314b4da4d6', NULL, '00000000-0000-0000-0000-000000000064', 'Benguet State University', 'benguet-state-university', NULL, '{"title": "Benguet State University", "extract": "Benguet State University (BSU) is a state university in the province of Benguet, Philippines. Its main campus is in La Trinidad.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/b/b1/Benguet_State_University_logo.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Benguet_State_University", "description": "Public university in Benguet, Philippines"}', NULL, NULL, 'PH', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.573335+01', '2026-08-07 12:47:33.573335+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('37f8f315-2e5d-46e7-89c9-3f86d6f6afe7', NULL, '00000000-0000-0000-0000-000000000064', 'Catholic Kwandong University', 'catholic-kwandong-university', NULL, '{"title": "Catholic Kwandong University", "extract": "Catholic Kwandong University (Korean: 가톨릭관동대학교) is a private Roman Catholic University located in Gangneung, Gangwon-do, South Korea.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/a9/Korea_Special_Olympics_27_%288382984068%29.jpg/330px-Korea_Special_Olympics_27_%288382984068%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Catholic_Kwandong_University", "description": "University in Gangneung, South Korea"}', NULL, NULL, 'KR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.5184+01', '2026-08-07 12:47:33.5184+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('c90558b4-339d-40a3-a909-52c3ca468da2', NULL, '00000000-0000-0000-0000-000000000064', 'Catawba College', 'catawba-college', NULL, '{"title": "Catawba College", "extract": "Catawba College is a private college in Salisbury, North Carolina. Founded in 1851 by the North Carolina Classis of the Reformed Church in Newton, the college adopted its name from its county of origin, Catawba County, before moving to its current home of Salisbury in 1925. Catawba College still holds loose ties with the successor to the Reformed Church, the United Church of Christ. It offers over 70 undergraduate degrees. As of August 2024, Catawba has an endowment over $580 million.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/8/80/CatawbaCollege-Seal-Blue.jpg", "content_url": "https://en.wikipedia.org/wiki/Catawba_College", "description": "Private college in Salisbury, North Carolina, U.S."}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.726322+01', '2026-08-07 12:47:33.726322+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('a5b9ef61-fd8d-4d4d-91eb-d412a67b85e0', NULL, '00000000-0000-0000-0000-000000000064', 'Carson-Newman College', 'carson-newman-college', NULL, '{"title": "Carson–Newman University", "extract": "Carson-Newman University is a private university in Jefferson City, Tennessee, United States. Carson-Newman is affiliated with the Tennessee Baptist Mission Board. Founded in 1851, the university enrolls about 2,500 students. Studies are offered in approximately 90 different academic programs.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/d/d3/Carson%E2%80%93Newman_seal.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Carson%E2%80%93Newman_University", "description": "Baptist university in Jefferson City, Tennessee, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.188857+01', '2026-08-07 12:47:33.188857+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('5c387967-94d5-4d9f-a4fa-c00dd90397de', NULL, '00000000-0000-0000-0000-000000000064', 'Carver College', 'carver-college', NULL, '{"title": "Carver College", "extract": "\n\nCarver College is a private Bible college located in Atlanta, Georgia, United States.", "content_url": "https://en.wikipedia.org/wiki/Carver_College", "description": "Private college in Atlanta, Georgia, United States"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.726322+01', '2026-08-07 12:47:33.726322+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('33408870-f7d8-495b-86f8-83ba39bb88b1', NULL, '00000000-0000-0000-0000-000000000064', 'Case Western Reserve University', 'case-western-reserve-university', NULL, '{"title": "Case Western Reserve University", "extract": "Case Western Reserve University (CWRU) is a private research university in Cleveland, Ohio, United States. It was federated in 1967 by a merger between Western Reserve University, founded in 1826 by the Presbyterian Church, and the Case Institute of Technology, founded in 1880. In 2024, the university enrolled 12,475 students from all 50 U.S. states and 106 countries, and employed more than 1,182 full-time faculty members.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/0/08/Case_Western_Reserve_University_seal.svg/330px-Case_Western_Reserve_University_seal.svg.png", "content_url": "https://en.wikipedia.org/wiki/Case_Western_Reserve_University", "description": "Private university in Cleveland, Ohio, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.188857+01', '2026-08-07 12:47:33.188857+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('a720fce9-6b3e-4419-a6e5-84ed21a72018', NULL, '00000000-0000-0000-0000-000000000064', 'Elizabethtown College', 'elizabethtown-college', NULL, '{"title": "Elizabethtown College", "extract": "Elizabethtown College is a private college in Elizabethtown, Pennsylvania.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/3/35/Elizabethtown_seal.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Elizabethtown_College", "description": "Private college in Elizabethtown, Pennsylvania, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.188857+01', '2026-08-07 12:47:33.188857+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
