INSERT INTO public.spaces VALUES ('2e38f875-b3bd-402f-bd80-2e1341650814', NULL, '00000000-0000-0000-0000-000000000064', 'Ben-Gurion University of the Negev', 'ben-gurion-university-of-the-negev', NULL, '{"title": "Ben-Gurion University of the Negev", "extract": "Ben-Gurion University of the Negev is a public research university in Beersheba, Israel. Named after Israeli national founder David Ben-Gurion, the university was founded in 1969 and currently has five campuses; three in Beersheba, one in Sede Boqer and one in Eilat.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/2/29/Ben-Gurion_University_of_the_Negev.svg/330px-Ben-Gurion_University_of_the_Negev.svg.png", "content_url": "https://en.wikipedia.org/wiki/Ben-Gurion_University_of_the_Negev", "description": "Public research university in Beersheba, Israel"}', NULL, NULL, 'IL', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.465646+01', '2026-08-07 12:47:33.465646+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('f95e0276-c7e5-41ff-91d8-12355b45348c', NULL, '00000000-0000-0000-0000-000000000064', 'Benedictine College', 'benedictine-college', NULL, '{"title": "Benedictine College", "extract": "Benedictine College is a private Benedictine liberal arts college in Atchison, Kansas, United States. It was established in 1971 by the merger of St. Benedict''s College for men and Mount St. Scholastica College for women.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/f/fe/Benedictine_College_seal.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Benedictine_College", "description": "Catholic college in Atchison, Kansas, U.S."}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.188857+01', '2026-08-07 12:47:33.188857+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
