INSERT INTO public.spaces VALUES ('670b300c-dc8e-4099-9bd9-19f3fc6388d6', NULL, '00000000-0000-0000-0000-000000000064', 'Beni Suef University', 'beni-suef-university', NULL, '{"title": "Beni Suef University", "extract": "Beni Suef University is an institution of higher education located in Beni Suef, Egypt.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/3/39/Beni-Suef_University_logo.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Beni_Suef_University", "description": "University in Egypt"}', NULL, NULL, 'EG', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.384776+01', '2026-08-07 12:47:33.384776+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('efa8782a-1300-4d30-a89e-0b8ed868d22a', NULL, '00000000-0000-0000-0000-000000000064', 'Bergen Community College', 'bergen-community-college', NULL, '{"title": "Bergen Community College", "extract": "Bergen Community College is a public community college in Bergen County, New Jersey. It was founded in 1965 and opened in 1968. As of November 2021, it is the largest community college in the state, with campuses in Paramus, Hackensack, and Lyndhurst and 13,352 students enrolled in degree programs, as well as approximately 5,800 in continuing and adult education programs. Federal data rank Bergen graduates first in earning the highest salaries among their peers from the state''s 19 two-year institutions, and even out-earning peers from some four-year colleges. Bergen has graduated more than half a million students with associate degrees and certificates since its founding in 1968.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/4/43/Bergen_Community_College_Logo.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Bergen_Community_College", "description": "Public college in Bergen County, New Jersey, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-07 12:47:33.702225+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('c97bd8c3-2502-4f82-9d14-eff28d045fa8', NULL, '00000000-0000-0000-0000-000000000064', 'Bergen University College', 'bergen-university-college', NULL, '{"title": "Western Norway University of Applied Sciences", "extract": "Western Norway University of Applied Sciences, or HVL, is a Norwegian public institution of higher education, established in January 2017 through the merging of formerly independent colleges across five campuses: Bergen, Førde, Haugesund, Sogndalsfjøra and Stord. Its oldest programs – teacher education in Stord – can be traced to 1839. The total number of students at HVL is about 16000, and there are 1800 academic and administrative staff. Its main campus is in the Kronstad neighborhood of Bergen, Norway.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/0b/StudiestedBergen.jpg/330px-StudiestedBergen.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Western_Norway_University_of_Applied_Sciences", "description": "Norwegian public institution of higher learning"}', NULL, NULL, 'NO', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.543021+01', '2026-08-07 12:47:33.543021+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
