INSERT INTO public.spaces VALUES ('5ff90151-bc1f-47a7-899b-d3a9209cb5e2', NULL, '00000000-0000-0000-0000-000000000064', 'Boğaziçi University', 'bo-azi-i-university', NULL, '{"title": "Boğaziçi University", "extract": "Boğaziçi University is a public research university in Istanbul, Turkey. Its main campus in Bebek is located just west of the Bosphorus, from which the institution takes its name. It is historically linked to Robert College, the first American college founded outside the United States.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/7/76/Bo%C4%9Fazi%C3%A7i_University_logo.svg/330px-Bo%C4%9Fazi%C3%A7i_University_logo.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Bo%C4%9Fazi%C3%A7i_University", "description": "Public research university in Turkey"}', NULL, NULL, 'TR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.65283+01', '2026-08-07 12:47:33.65283+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('ca6b9931-c7bd-499d-9296-3ca864179552', NULL, '00000000-0000-0000-0000-000000000064', 'Bogor Agricultural University', 'bogor-agricultural-university', NULL, '{"title": "IPB University", "extract": "IPB University in the City of Bogor is a state-run agricultural university based in the regency of Bogor, Indonesia. IPB has long been considered one of the \"Big 5\" universities in Indonesia, along with University of Indonesia, Bandung Institute of Technology, Gadjah Mada University and Airlangga University.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/6/6b/Institut_Pertanian_Bogor_logo.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/IPB_University", "description": "University in Bogor, Indonesia"}', NULL, NULL, 'ID', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.436788+01', '2026-08-07 12:47:33.436788+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
