INSERT INTO public.spaces VALUES ('11a80e02-5486-48af-bfb6-4f1b31b680dc', NULL, '00000000-0000-0000-0000-000000000064', 'Biola University', 'biola-university', NULL, '{"title": "Biola University", "extract": "Biola University is a private, nondenominational, evangelical Christian university in La Mirada, California, United States. It was founded in 1908 as the Bible Institute of Los Angeles as a center for biblical and missionary training. Its campus in downtown Los Angeles featured iconic \"Jesus Saves\" signs and a 3,500-seat auditorium. In 1949, it became Biola College and later adopted the name Biola University in 1981. The school relocated to La Mirada, California, in 1959 and has maintained a strong evangelical identity rooted in traditional theology, as reflected in its association with The Fundamentals: A Testimony to the Truth.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/6/65/Biola_Seal.png", "content_url": "https://en.wikipedia.org/wiki/Biola_University", "description": "Christian university in La Mirada, California, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.188857+01', '2026-08-07 12:47:33.188857+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
