INSERT INTO public.spaces VALUES ('ca6522ea-fc8d-416d-8ff8-6229e61a615a', NULL, '00000000-0000-0000-0000-000000000064', 'Birkbeck College, University of London', 'birkbeck-college-university-of-london', NULL, '{"title": "Birkbeck, University of London", "extract": "Birkbeck College, University of London is a public research university located in London, England, and a member institution of the University of London. Established in 1823 as the London Mechanics'' Institute by its founder Joseph Clinton Robertson and its supporters George Birkbeck, Jeremy Bentham, J. C. Hobhouse and Henry Brougham, Birkbeck is one of the few universities to specialise in evening higher education in the United Kingdom.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/c2/Birkbeck_College_London_Achievement.png/330px-Birkbeck_College_London_Achievement.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Birkbeck%2C_University_of_London", "description": "Public university in England"}', NULL, NULL, 'GB', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.65283+01', '2026-08-07 12:47:33.65283+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('7905b54d-c5d1-4894-9a57-cc671d61c421', NULL, '00000000-0000-0000-0000-000000000064', 'Birla Institute of Technology and Science', 'birla-institute-of-technology-and-science', NULL, '{"title": "BITS Pilani", "extract": "The Birla Institute of Technology and Science, Pilani is a private deemed university in Pilani, Rajasthan, India. It focuses primarily on higher education and research in engineering and sciences. BITS Pilani was one of the first six institutes in India to be declared Institution of Eminence. According to 2012 data, BITS Pilani has an acceptance rate (on-campus) of 1.47%, making it one of the most exclusive technical universities in the world.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/d/d3/BITS_Pilani-Logo.svg/330px-BITS_Pilani-Logo.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/BITS_Pilani", "description": "Deemed university in Pilani, Rajasthan, India"}', NULL, NULL, 'IN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.411195+01', '2026-08-07 12:47:33.411195+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('7c200ccd-db2b-47ab-8662-2b07db4cc1d1', NULL, '00000000-0000-0000-0000-000000000064', 'Bingol University', 'bingol-university', NULL, '{"title": "Bingöl University", "extract": "Bingöl University is a university located in Bingöl, Turkey. It was established in 2007. The University is led by Prof. Dr. İbrahim Çapak. Bingol University, Web of Science database, according to 2019 data, 108 state universities in terms of number of publications per faculty member in Turkey has a performance ranking #6 ranking.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/3/32/Bing%C3%B6lUniversityLogo.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Bing%C3%B6l_University", "description": "Public university in Bingöl, Turkey"}', NULL, NULL, 'TR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.679268+01', '2026-08-07 12:47:33.679268+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('a7abdb1b-b7a8-41e5-a40e-40da043f12d7', NULL, '00000000-0000-0000-0000-000000000064', 'Birmingham-Southern College', 'birmingham-southern-college', NULL, '{"title": "Birmingham–Southern College", "extract": "Birmingham–Southern College (BSC) was a private liberal arts college in Birmingham, Alabama. Founded in 1856, the college was affiliated with the United Methodist Church and was accredited by the Southern Association of Colleges and Schools (SACS). The college''s student body was approximately 975 students when it closed at the end of the 2023–24 school year after years of financial trouble.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/c/c8/BSC_seal.svg/330px-BSC_seal.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Birmingham%E2%80%93Southern_College", "description": "Methodist university in Birmingham, Alabama, US (1856–2024)"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.188857+01', '2026-08-07 12:47:33.188857+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
