INSERT INTO public.spaces VALUES ('bda9dad2-b158-4e13-b9ef-2e6f12c5cc89', NULL, '00000000-0000-0000-0000-000000000064', 'Bossier Parish Community College', 'bossier-parish-community-college', NULL, '{"title": "Bossier Parish Community College", "extract": "Bossier Parish Community College (BPCC) is a public community college located in Bossier City, Louisiana, United States. Established in 1967, BPCC was established by the Louisiana legislature in 1966 and began classes in 1967. Their current main campus, located on HWY 80, was built in 2004.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/45/Bossier_Parish_Community_College_Administration_Building_IMG_0382.JPG/330px-Bossier_Parish_Community_College_Administration_Building_IMG_0382.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Bossier_Parish_Community_College", "description": "Public college in Bossier City, Louisiana, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-07 12:47:33.702225+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
