INSERT INTO public.spaces VALUES ('220664ee-84b1-4af6-ab1b-68cc8afe4d37', NULL, '00000000-0000-0000-0000-000000000064', 'Botswana International University of Science & Technology', 'botswana-international-university-of-science-technology', NULL, '{"title": "Botswana International University of Science and Technology", "extract": "The Botswana International University of Science & Technology, or BIUST, is an international university located in the town of Palapye, Botswana. It is the nation''s second university, after the university of Botswana in the country''s capital, Gaborone. The location is a 2,500-hectare (9.7 sq mi) site of gently sloping land on the outskirts of Palapye.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/1f/BIUST_Botswana_3.jpg/330px-BIUST_Botswana_3.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Botswana_International_University_of_Science_and_Technology", "description": "University in Palapye, Botswana"}', NULL, NULL, 'BW', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.296289+01', '2026-08-07 12:47:33.296289+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
