INSERT INTO public.spaces VALUES ('c11fd18e-1a47-4834-9724-1cd339a3f513', NULL, '00000000-0000-0000-0000-000000000064', 'Boston University', 'boston-university', NULL, '{"title": "Boston University", "extract": "Boston University (BU) is a private research university in Boston, Massachusetts, United States. BU was founded in 1839 by a group of Boston Methodists with its original campus in Newbury, Vermont. It was chartered in Boston in 1869. The university is a member of the Association of American Universities and the Boston Consortium for Higher Education.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/f5/Boston_University_seal.svg/330px-Boston_University_seal.svg.png", "content_url": "https://en.wikipedia.org/wiki/Boston_University", "description": "Private university in Boston, Massachusetts, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.188857+01', '2026-08-07 12:47:33.188857+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('83b8e9e0-4ec7-4e63-8094-f30cd94d0b2b', NULL, '00000000-0000-0000-0000-000000000064', 'Botho University', 'botho-university', NULL, '{"title": "Botho University", "extract": "Botho University is Botswana''s largest private tertiary educational provider, founded in 1997. The college offers certificates, diplomas and graduate degrees in accountancy and computer science. It is the first private tertiary institution in the country to be accredited by the Tertiary Education Council (TEC). All of its programs are also accredited by the Botswana Qualification Authority (BQA). It has trained 16,000 graduates, and enrolls 4,000 students, supported by 150 academic staff.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/36/Campus_Pictures_064.jpg/330px-Campus_Pictures_064.jpg", "content_url": "https://en.wikipedia.org/wiki/Botho_University", "description": "Private university in Botswana"}', NULL, NULL, 'BW', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.296289+01', '2026-08-07 12:47:33.296289+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
