INSERT INTO public.spaces VALUES ('114f44db-5155-4df3-a624-6ccc9793ff5f', NULL, '00000000-0000-0000-0000-000000000064', 'Bridgemont Community and Technical College', 'bridgemont-community-and-technical-college', NULL, '{"title": "BridgeValley Community and Technical College", "extract": "BridgeValley Community and Technical College (BVCTC) is a public community college with multiple campuses in West Virginia. It was formed in 2014 by the merger of Bridgemont Community and Technical College of Montgomery, West Virginia and Kanawha Valley Community and Technical College of South Charleston, West Virginia. The college is part of the West Virginia Community and Technical College System.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/7/74/BridgeValley_CTC_logo.png/330px-BridgeValley_CTC_logo.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/BridgeValley_Community_and_Technical_College", "description": "Multi-campus college in West Virginia, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.726322+01', '2026-08-07 12:47:33.726322+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('17f9c1dd-1bfc-4840-ba8c-b2f94c969932', NULL, '00000000-0000-0000-0000-000000000064', 'Brest State University', 'brest-state-university', NULL, '{"title": "A.S. Pushkin Brest State University", "extract": "A.S. Pushkin Brest State University is an institution of higher education in Brest, Belarus. Founded in 1945 as the Brest State Teachers'' Training Institute, it was reorganised into Brest State Pedagogical Institute in 1950, and eventually into a university in 1995. It was named after Alexander Pushkin.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/1c/Brest1.JPG/330px-Brest1.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/A.S._Pushkin_Brest_State_University", "description": "Public university in Brest, Belarus"}', NULL, NULL, 'BY', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.296289+01', '2026-08-07 12:47:33.296289+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('2cf1fbac-cdf1-4bbe-968f-af8441fb23a5', NULL, '00000000-0000-0000-0000-000000000064', 'Bridgewater College', 'bridgewater-college', NULL, '{"title": "Bridgewater College", "extract": "Bridgewater College is a private liberal-arts college in Bridgewater, Virginia. Established in 1880, Bridgewater College admitted both men and women from the time of its founding and was the first four-year liberal arts college in Virginia to do so. Approximately 1,800 students are enrolled.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/7/70/Bridgewater_college_seal.png", "content_url": "https://en.wikipedia.org/wiki/Bridgewater_College", "description": "Private college in Bridgewater, Virginia, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.188857+01', '2026-08-07 12:47:33.188857+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('dbb058e0-bff5-4028-932f-d72c3e9b28c8', NULL, '00000000-0000-0000-0000-000000000064', 'Bridgewater State University', 'bridgewater-state-university', NULL, '{"title": "Bridgewater State University", "extract": "Bridgewater State University is a public university with its main campus in Bridgewater, Massachusetts, United States. It is the largest of nine state universities in Massachusetts. Including its off-campus sites in New Bedford, Attleboro, and Cape Cod, BSU has the fourth-largest campus of the 29 institutions in the Massachusetts Public Higher Education System. BSU''s sports teams are called the Bears. Its school colors are crimson, white, and black.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/7/74/Bridgewater_State_University_seal.jpg", "content_url": "https://en.wikipedia.org/wiki/Bridgewater_State_University", "description": "Public university in Bridgewater, Massachusetts, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.726322+01', '2026-08-07 12:47:33.726322+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('02acf5bd-f7b6-4d68-8d67-9892acadce24', NULL, '00000000-0000-0000-0000-000000000064', 'Bristol Community College', 'bristol-community-college', NULL, '{"title": "Bristol Community College", "extract": "Bristol Community College (Bristol) is a public community college with four campuses in Southeastern Massachusetts.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/cd/Bristol_Community_College_%282018%29_logo.png/330px-Bristol_Community_College_%282018%29_logo.png", "content_url": "https://en.wikipedia.org/wiki/Bristol_Community_College", "description": "College in Fall River, Massachusetts, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-07 12:47:33.702225+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
