INSERT INTO public.spaces VALUES ('2872fa1a-5e20-44ba-a8d5-f2abcefbc310', NULL, '00000000-0000-0000-0000-000000000064', 'Budapest Business School', 'budapest-business-school', NULL, '{"title": "Budapest University of Economics and Business", "extract": "Budapest University of Economics and Business (BUEB) is a public business school specializing in business studies and social sciences, located in Budapest, Hungary. It was founded in 1857 by the merchants and bankers of Austria-Hungary. It is the oldest public business school in the world, and the second oldest among all business schools, after the ESCP Business School in Paris.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/b9/Iskola%C3%A9p%C3%BClet_%28527._sz%C3%A1m%C3%BA_m%C5%B1eml%C3%A9k%29.jpg/330px-Iskola%C3%A9p%C3%BClet_%28527._sz%C3%A1m%C3%BA_m%C5%B1eml%C3%A9k%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Budapest_University_of_Economics_and_Business", "description": "Business University in Budapest, Hungary"}', NULL, NULL, 'HU', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.726322+01', '2026-08-07 12:47:33.726322+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('a8c080e6-dfa2-4551-be9c-c7818192e6ab', NULL, '00000000-0000-0000-0000-000000000064', 'Bukkyo University', 'bukkyo-university', NULL, '{"title": "Bukkyo University", "extract": "Bukkyo University  is a private university in Kita-ku, Kyoto in Kyoto Prefecture, Japan. The university began as an organization within the Chion-in Temple for the lecturing and study of Buddhism in 1868. The school''s official predecessor was founded in 1912, and it was chartered as a junior college in 1949. Bukkyo means Buddhism in Japanese, and the university''s philosophy is based on Jōdo-shū Buddhism.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/27/Bukkyo_University140524NI1.JPG/330px-Bukkyo_University140524NI1.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Bukkyo_University", "description": "Private University in Japan"}', NULL, NULL, 'JP', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.465646+01', '2026-08-07 12:47:33.465646+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('5d007e73-7b1b-46cb-86d7-8b7d99cd26e6', NULL, '00000000-0000-0000-0000-000000000064', 'Bunkyo University', 'bunkyo-university', NULL, '{"title": "Bunkyo University", "extract": "Bunkyo University  is a private university located in Shinagawa, Tokyo, Japan, with campuses in Saitama and Kanagawa Prefecture.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/49/Bunkyo_University_Koshigaya_Campus.JPG/330px-Bunkyo_University_Koshigaya_Campus.JPG", "content_url": "https://en.wikipedia.org/wiki/Bunkyo_University", "description": "Private university in Shinagawa, Tokyo, Japan"}', NULL, NULL, 'JP', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.465646+01', '2026-08-07 12:47:33.465646+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
