INSERT INTO public.spaces VALUES ('0ae286e8-7ee3-4b2e-8a50-a04d077f570b', NULL, '00000000-0000-0000-0000-000000000064', 'Bulent Ecevit University', 'bulent-ecevit-university', NULL, '{"title": "Zonguldak Bülent Ecevit University", "extract": "Zonguldak Bülent Ecevit University is a state university located in Zonguldak, Turkey. The university was founded in 1992 with a primary focus on education in Mining and Engineering.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/9/96/Zonguldak_B%C3%BClent_Ecevit_University_Logo.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Zonguldak_B%C3%BClent_Ecevit_University", "description": "Public university in Zonguldak, Turkey"}', NULL, NULL, 'TR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.679268+01', '2026-08-07 12:47:33.679268+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('d1116414-3f6f-4d6c-b465-d1970df85be7', NULL, '00000000-0000-0000-0000-000000000064', 'Budapest University of Technology and Economics', 'budapest-university-of-technology-and-economics', NULL, '{"title": "Budapest University of Technology and Economics", "extract": "The Budapest University of Technology and Economics, official abbreviation BME, is a public research university located in Budapest, Hungary. It is the most significant university of technology in the country and is considered the world''s oldest institute of technology with university rank and structure, founded in 1782.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/f3/BME_K_building.png/330px-BME_K_building.png", "content_url": "https://en.wikipedia.org/wiki/Budapest_University_of_Technology_and_Economics", "description": "University in Hungary"}', NULL, NULL, 'HU', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.411195+01', '2026-08-07 12:47:33.411195+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
