INSERT INTO public.spaces VALUES ('21fb20c5-4250-4a71-8895-ef15ff07371d', NULL, '00000000-0000-0000-0000-000000000060', 'Jersey', 'jersey', 'It is set in English Channel, an island nation. Whether you''re still in English Channel or building a life elsewhere, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Jersey", "extract": "Jersey, officially the Bailiwick of Jersey, is an autonomous and self-governing British Crown Dependency in Northwestern Europe 14 miles (23 km) off the Cotentin Peninsula of north-west France. At 45 square miles (120 km2), the main island, Jersey, is the largest of the Channel Islands. Although not a sovereign state, Jersey has its own legal, fiscal and governmental systems; on that basis, it is regarded as a small nation or island country. Jersey''s territory also includes some surrounding uninhabited islands and rocks. As of 2021, the island had a population of 103,267.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/1c/Flag_of_Jersey.svg/330px-Flag_of_Jersey.svg.png", "content_url": "https://en.wikipedia.org/wiki/Jersey", "description": "Crown Dependency in the English Channel"}', 'bb155a21-4972-4027-ba69-913fafde7a90', NULL, 'JE', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:53.764316+01', NULL, 'GBP', '{jersey,je,island,community,diaspora}', NULL, 'Europe', 'Northern Europe', NULL);
