INSERT INTO public.spaces VALUES ('50585a02-5f42-47d2-9361-3b5ad3d596f7', NULL, '00000000-0000-0000-0000-000000000064', 'Bunka Women''s University', 'bunka-women-s-university', NULL, '{"title": "Bunka Gakuen University", "extract": "Bunka Gakuen University  is a private university in Shinjuku, Tokyo, Japan. The predecessor of the school, a women''s vocational school, was founded 1923. In 1952 it was chartered as a junior women''s college. In 1964 it became a four-year college and it was named Bunka Women''s University . In 2011 it changed its name \"Bunka Gakuen University\".", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/6b/Bunka_Gakuen_Univ._Shintoshin_Campus_Green_Plaza.jpg/330px-Bunka_Gakuen_Univ._Shintoshin_Campus_Green_Plaza.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Bunka_Gakuen_University", "description": "Private university in Shinjuku, Tokyo, Japan"}', NULL, NULL, 'JP', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.465646+01', '2026-08-07 12:47:33.465646+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
