INSERT INTO public.spaces VALUES ('a119b362-7b67-4dff-8cc1-0bb51b43b8e1', NULL, '00000000-0000-0000-0000-000000000064', 'Busan National University of Education', 'busan-national-university-of-education', NULL, '{"title": "Busan National University of Education", "extract": "The Busan National University of Education is a government-supported institution which provides training for future public-school teachers in South Korea. The campus is located in the Yeonje-gu district of Busan Metropolitan City. The university offers graduate and undergraduate programs, and enrolls 1,762 undergraduate and 565 graduate students. A primary-level lab school with an enrollment of 768 students is located on the campus. The university''s current president, its third, is Sung-Taek Park.", "content_url": "https://en.wikipedia.org/wiki/Busan_National_University_of_Education", "description": "University"}', NULL, NULL, 'KR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.5184+01', '2026-08-07 12:47:33.5184+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('61e3386e-8c60-4499-bf69-79b164ce76f7', NULL, '00000000-0000-0000-0000-000000000064', 'Bunker Hill Community College', 'bunker-hill-community-college', NULL, '{"title": "Bunker Hill Community College", "extract": "Bunker Hill Community College (BHCC) is a public community college with multiple campuses in the Greater Boston area. Founded in 1973 in the Charlestown neighborhood of Boston, Massachusetts, United States, BHCC provides higher education and job training services at two campuses and three satellite locations.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/f7/Bunker_Hill_Community_College_%28BHCC%29.jpg/330px-Bunker_Hill_Community_College_%28BHCC%29.jpg", "content_url": "https://en.wikipedia.org/wiki/Bunker_Hill_Community_College", "description": "Community college in Boston, Massachusetts, U.S."}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-07 12:47:33.702225+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
