INSERT INTO public.spaces VALUES ('38d48d44-cb93-43aa-a22d-18591b40d22a', NULL, '00000000-0000-0000-0000-000000000064', 'Eichi University', 'eichi-university', NULL, '{"title": "St. Thomas University, Japan", "extract": "St.Thomas University, Japan , formerly known as Sapientia University or Eichi University , was a Christian private university in Amagasaki, Hyogo, Japan. The school was founded in 1962 as a junior college and became a four-year college in the following year. The name \"St. Thomas University\" was adopted in 2007. The university stopped enrolling new students in 2010 and, after its last remaining student graduated in 2014, announced its closure and revealed its intention to donate its facilities to the city of Amagasaki.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/da/St_Thomas_Univ_of_Osaka.jpg/330px-St_Thomas_Univ_of_Osaka.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/St._Thomas_University%2C_Japan", "description": "Christian private university in Amagasaki, Hyoko, Japan"}', NULL, NULL, 'JP', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.465646+01', '2026-08-07 12:47:33.465646+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
