INSERT INTO public.spaces VALUES ('bd4bf517-9053-4602-aa08-54ed8c4b4325', NULL, '00000000-0000-0000-0000-000000000064', 'State University of New York College at Potsdam', 'state-university-of-new-york-college-at-potsdam', NULL, '{"title": "State University of New York at Potsdam", "extract": "The State University of New York at Potsdam is a public college in Potsdam, New York, United States. Founded in 1816, it is the northernmost member of the State University of New York (SUNY) system. It is composed of the College of Arts & Sciences, the School of Education and Professional Studies, and the Crane School of Music.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/9/99/SUNY_Potsdam_seal.svg/330px-SUNY_Potsdam_seal.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/State_University_of_New_York_at_Potsdam", "description": "Public college in Potsdam, New York, US"}', '71db22f0-ceb6-4073-97c1-b4d77dd852fd', NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.233464+01', '2026-08-09 02:32:19.260937+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
