INSERT INTO public.spaces VALUES ('6a098fde-3358-4863-becc-eb7620972738', NULL, '00000000-0000-0000-0000-000000000060', 'Saint-Martin (French part)', 'saint-martin-french-part', 'Your digital anchor — wherever the diaspora has settled, this is home base. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "Collectivity of Saint Martin", "extract": "The Collectivity of Saint Martin, commonly known as simply Saint Martin, is an overseas collectivity of France in the West Indies in the Caribbean, on the northern half of the island of Saint Martin, as well as some smaller adjacent islands. Saint Martin is separated from the island of Anguilla by the Anguilla Channel. Its capital is Marigot.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/ad/Saint_Martin_in_France.svg/330px-Saint_Martin_in_France.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Collectivity_of_Saint_Martin", "description": "Overseas collectivity of France"}', '978e2589-71f4-465a-bf09-4b0d680bd578', NULL, 'MF', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:32.60712+01', NULL, 'EUR', '{"saint-martin (french part)",saint-martin-french-part,mf,island,community,diaspora}', NULL, 'Americas', 'Caribbean', NULL);
