INSERT INTO public.spaces VALUES ('19062242-1d0e-426f-b245-c548f80927d5', NULL, '00000000-0000-0000-0000-000000000064', 'Elgin Community College', 'elgin-community-college', NULL, '{"title": "Elgin Community College", "extract": "Elgin Community College (ECC) is a public community college in Elgin, Illinois. It was founded in 1949 as part of Elgin Area School District U46. Community College District 509 was formed 17 years later in 1966, a year after Illinois legislators created the Illinois Community College System. Most of the District is in Kane County with portions in DeKalb, Cook, McHenry, and DuPage. The 360-square-mile (930 km2) District serves 300,000 people, 11,000 businesses, four public school districts, and 15 high schools.", "content_url": "https://en.wikipedia.org/wiki/Elgin_Community_College", "description": "Community college in Elgin, Illinois, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-07 12:47:33.702225+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
