INSERT INTO public.spaces VALUES ('66529e17-e8fb-4c86-b24a-6c1856e20f28', NULL, '00000000-0000-0000-0000-000000000064', 'California State University, Northridge', 'california-state-university-northridge', NULL, '{"title": "California State University, Northridge", "extract": "California State University, Northridge, is a public university in the Northridge neighborhood of Los Angeles, California, United States. With a total enrollment of 36,960 students, it has the fourth largest total student body in the California State University system. The size of CSUN also has a major impact on the California economy, with an estimated $1.9 billion in economic output generated by CSUN on a yearly basis. As of Fall 2025, the university has 2,085 faculty members, of which around 37% are tenured or on the tenure-track.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/8/8c/CSUNS.svg/330px-CSUNS.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/California_State_University%2C_Northridge", "description": "Public university in Los Angeles, California, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.188857+01', '2026-08-07 12:47:33.188857+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('5b20d337-bfac-424e-9e16-7e487d9f91c8', NULL, '00000000-0000-0000-0000-000000000064', 'California State University, Chico', 'california-state-university-chico', NULL, '{"title": "California State University, Chico", "extract": "California State University, Chico is a public university in Chico, California, United States. It was founded in 1887 as one of about 180 \"normal schools\" founded by state governments in the 19th century to train teachers for the rapidly growing public common schools. Some closed but most steadily expanded their role and became state colleges in the early 20th century and state universities in the late 20th century. It is the second oldest campus in the California State University system. As of the fall 2020 semester, the university had a total enrollment of 16,630 students. The university offers 126 bachelor''s degree programs, 35 master''s degree programs, and four types of teaching credentials. Chico is a Hispanic-Serving Institution (HSI).", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/1/10/Caifornia_stat_univ_chico_seal.svg/330px-Caifornia_stat_univ_chico_seal.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/California_State_University%2C_Chico", "description": "Public university in Chico, California"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.188857+01', '2026-08-07 12:47:33.188857+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
