INSERT INTO public.spaces VALUES ('add0c9f3-95d3-4c40-8a01-1d08d45dcd3e', NULL, '00000000-0000-0000-0000-000000000064', 'California State University System', 'california-state-university-system', NULL, '{"title": "California State University", "extract": "The California State University is a public university system in California, and the largest public university system in the United States. It consists of 22 campuses and seven off-campus centers, which together enroll 461,612 students and employ 63,375 faculty and staff members. In California, it is one of the three public higher education systems, along with the University of California and the California Community Colleges systems. The CSU system is officially incorporated as The Trustees of the California State University, and is headquartered in Long Beach, California.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/c/cc/Seal_of_the_California_State_University.svg/330px-Seal_of_the_California_State_University.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/California_State_University", "description": "Public university system"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.188857+01', '2026-08-07 12:47:33.188857+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
