INSERT INTO public.spaces VALUES ('a9992eeb-acfd-4dca-9ffd-634a40494306', NULL, '00000000-0000-0000-0000-000000000064', 'California University of Science and Medicine', 'california-university-of-science-and-medicine', NULL, '{"title": "California University of Science and Medicine", "extract": "The California University of Science and Medicine (CUSM) is a non-profit private accredited medical school located in Colton, San Bernardino County, United States. CUSM received full LCME accreditation in February 2026.", "content_url": "https://en.wikipedia.org/wiki/California_University_of_Science_and_Medicine", "description": "Private medical school in California, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.753691+01', '2026-08-07 12:47:33.753691+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('0b102b47-fd13-473c-96ec-96681a88dd6b', NULL, '00000000-0000-0000-0000-000000000064', 'Central New Mexico Community College', 'central-new-mexico-community-college', NULL, '{"title": "Central New Mexico Community College", "extract": "Central New Mexico Community College (CNM), formerly Technical Vocational Institute (TVI), is a public community college based in Albuquerque, New Mexico. Founded in 1964, CNM offers associate degrees, professional certificates, and training options.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/d/de/Central_New_Mexico_Community_College.svg/330px-Central_New_Mexico_Community_College.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Central_New_Mexico_Community_College", "description": "College in Albuquerque, New Mexico, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-07 12:47:33.702225+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('8065d6ad-1aec-4ad6-a128-a8838d6aad1b', NULL, '00000000-0000-0000-0000-000000000064', 'Central Institute of Higher Tibetan Studies', 'central-institute-of-higher-tibetan-studies', NULL, '{"title": "Central Institute of Higher Tibetan Studies", "extract": "\nThe Central University for Tibetan Studies (CUTS), formerly called the Central Institute of Higher Tibetan Studies, is a Deemed University founded in Sarnath, Varanasi, India, in 1967. It is an autonomous university under India''s Ministry of Culture. \nThe CUTS was founded by Prime Minister Jawahar Lal Nehru and the 14th Dalai Lama Tenzin Gyatso with the aims of educating exiled Tibetan youths and other Himalayan border students, and re-translating original Indo-Buddhist Sanskrit texts, that in 1959 existed only in Tibetan, into Sanskrit, Hindi, and other modern Indian languages.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/5/5f/Central_University_for_Tibetan_Studies_logo.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Central_Institute_of_Higher_Tibetan_Studies", "description": "Deemed university in Varanasi, India"}', NULL, NULL, 'IN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.411195+01', '2026-08-07 12:47:33.411195+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('d512d667-dce6-45a4-ac7a-739f38d888c6', NULL, '00000000-0000-0000-0000-000000000064', 'Central Police University', 'central-police-university', NULL, '{"name": "Central Police University", "image": "http://commons.wikimedia.org/wiki/Special:FilePath/Taoyuan%20Central%20Police%20University%20%2CTaiwan.jpg", "country": "Taiwan", "founded": "1936-09-01T00:00:00Z", "website": "http://www.cpu.edu.tw/", "description": "police academy in Taiwan", "wikidata_id": "http://www.wikidata.org/entity/Q10875117", "wikipedia_url": "https://en.wikipedia.org/wiki/Q10875117"}', NULL, NULL, 'TW', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.625787+01', '2026-08-07 12:47:33.625787+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('c7188186-450e-4abf-9107-2e6438ed3380', NULL, '00000000-0000-0000-0000-000000000064', 'Duksung Women''s University', 'duksung-women-s-university', NULL, '{"title": "Duksung Women''s University", "extract": "Duksung Women''s University is a private university in Seoul, South Korea, founded in 1920. Its campus is located in Dobong District, Seoul Metropolitan Government, and a lifelong graduate school and a corporation are located in Jongno District. Duksung Women''s University is the first female school founded by a female independence activist. In particular, Duksung Women''s University stands out in early childhood education. The English abbreviations of the university are Duksung, DSU, and DSWU. Located around Deokseong Women''s University on a transportation route, the subway station has the April 19th National Cemetery station on Seoul LRT Ui-Sinseol Line.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/c/cc/Duksung_Women%27s_University_logo.svg/330px-Duksung_Women%27s_University_logo.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Duksung_Women''s_University", "description": "Private university in Seoul, South Korea"}', NULL, NULL, 'KR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.5184+01', '2026-08-07 12:47:33.5184+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
