INSERT INTO public.spaces VALUES ('0942310f-8b53-4ac5-a33e-5111712fc237', NULL, '00000000-0000-0000-0000-000000000064', 'Eastern Iowa Community College District', 'eastern-iowa-community-college-district', NULL, '{"title": "Eastern Iowa Community Colleges", "extract": "The Eastern Iowa Community Colleges (EICC) includes three community colleges stretched along the Mississippi River in the U.S. state of Iowa. Eastern Iowa Community Colleges consists of the Iowa counties of Clinton, Muscatine, and Scott. The EICC administrative offices are in Davenport.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/9/90/EICC_vertical_200px.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Eastern_Iowa_Community_Colleges", "description": ""}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-07 12:47:33.702225+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
