INSERT INTO public.spaces VALUES ('a58e2040-1183-429c-9df8-169e02241f86', NULL, '00000000-0000-0000-0000-000000000064', 'Camberwell College of Arts', 'camberwell-college-of-arts', NULL, '{"title": "Camberwell College of Arts", "extract": "Camberwell College of Arts is a constituent college of the University of the Arts London, a public art and design university in London, England. The college offers further and higher education programmes, including postgraduate and PhD awards. The college has retained single degree options within Fine Art, offering specialist Bachelor of Arts courses in painting, sculpture, photography and drawing. It also runs graduate and postgraduate courses in fine art as well as design courses such as graphic design, illustration and 3D design. It has been ranked as the top British art school by The Times.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/2f/Camberwell_Art_School.jpg/330px-Camberwell_Art_School.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Camberwell_College_of_Arts", "description": "Art school at the University of the Arts London"}', NULL, NULL, 'GB', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.65283+01', '2026-08-07 12:47:33.65283+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('e76cc9b4-70da-47b4-95d8-805dc22f3c61', NULL, '00000000-0000-0000-0000-000000000064', 'Cambodian Mekong University', 'cambodian-mekong-university', NULL, '{"title": "Cambodian Mekong University", "extract": "Cambodian Mekong University (CMU) is a private university located in Phnom Penh, Cambodia. It is registered as a private higher education institution with the Ministry of Education, Youth and Sports. The university was established in 2003. The current chancellor is Mr.Ban Thero, a graduate of Southern Cross University and the University of Adelaide.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/1/15/Logo-mekong-cambodia-univ.jpg/330px-Logo-mekong-cambodia-univ.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Cambodian_Mekong_University", "description": "Private university in Phnom Penh, Cambodia"}', NULL, NULL, 'KH', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.326239+01', '2026-08-07 12:47:33.326239+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('0047005d-0e9b-4363-a903-ba2489a88894', NULL, '00000000-0000-0000-0000-000000000064', 'Camosun College', 'camosun-college', NULL, '{"title": "Camosun College", "extract": "Camosun College is a public college located in Saanich, British Columbia, Canada. The college has two campuses, Lansdowne and Interurban, with a total student head count of 15,540 in 2023/24. Camosun College also provides contract training for local business; research, innovation and prototyping services for industry; and trained co-op students for employers.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d6/Camosun_College.jpg/330px-Camosun_College.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Camosun_College", "description": "Public college in British Columbia, Canada"}', NULL, NULL, 'CA', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.326239+01', '2026-08-07 12:47:33.326239+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
