INSERT INTO public.spaces VALUES ('b75cc957-a78c-4157-9356-8275ad4fe482', NULL, '00000000-0000-0000-0000-000000000064', 'Central Community College', 'central-community-college', NULL, '{"title": "Central Community College", "extract": "Central Community College is a public community college located in Nebraska. The college has three campuses, in Columbus, Grand Island, and Hastings. In addition, the college has learning centers in Holdrege, Kearney, and Lexington. The college''s athletic nickname is the CCC Raiders. As of 2025, the college enrolls 3,200 students. The college was created by the Nebraska State Legislature in 1973.", "content_url": "https://en.wikipedia.org/wiki/Central_Community_College", "description": "Public community college in Central Nebraska"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-07 12:47:33.702225+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('d75895c4-616a-4bce-ae53-73394ca44a6b', NULL, '00000000-0000-0000-0000-000000000064', 'Central Institute of Fisheries Education', 'central-institute-of-fisheries-education', NULL, '{"title": "Central Institute of Fisheries Education", "extract": "The Central Institute of Fisheries Education (CIFE) is a Deemed to be a University and institution of higher learning for fisheries science in Mumbai, India. It was ranked 9th in India by the National Institutional Ranking Framework in the agriculture and allied sectors ranking for 2024.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/2/28/Central_Institute_of_Fisheries_Education.svg/330px-Central_Institute_of_Fisheries_Education.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Central_Institute_of_Fisheries_Education", "description": "ICAR-CIFE, a research institute in Mumbai, India"}', NULL, NULL, 'IN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.411195+01', '2026-08-07 12:47:33.411195+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
