INSERT INTO public.spaces VALUES ('443e0a5d-8598-4cb4-8697-bf392df81778', NULL, '00000000-0000-0000-0000-000000000064', 'Catholic University in Ruzomberok', 'catholic-university-in-ruzomberok', NULL, '{"title": "Catholic University in Ružomberok", "extract": "Catholic University in Ružomberok (CU) is a public university with religious character. The Conference of Slovak Bishops and National Council of the Slovak Republic took part in its foundation in 2000. \nCU performs its activities especially in the areas of the humanities, historical, pedagogical, and social and health sciences, as well as in the areas of art, economics, management, and law. Catholic University has been the associate since 2004 and in 2010, it became the member of International Federation of Catholic Universities. University has also been the member of Fédération des Universités Catholiques Européennes (FUCE) since 2007. Since 2016 vice-rector prof. František Trstenský is member of Board of FUCE.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/2/2a/Logo_CU.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Catholic_University_in_Ru%C5%BEomberok", "description": "University in Slovakia"}', NULL, NULL, 'SK', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.625787+01', '2026-08-07 12:47:33.625787+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('e9da7763-c80d-4523-b1e7-987d4f605fc7', NULL, '00000000-0000-0000-0000-000000000064', 'Catawba Valley Community College', 'catawba-valley-community-college', NULL, '{"title": "Catawba Valley Community College", "extract": "Catawba Valley Community College (CVCC) is a public community college in Hickory, North Carolina. The college, established April 3, 1958, is part of the North Carolina Community College System. The main campus covers 162 acres (0.66 km2) and includes 16 buildings. The college also operates a Cosmetology Center in downtown Newton, the CVCC Alexander Center for Education in Taylorsville, and East Campus, where continuing education and business & industry services are provided. Specialty programs include the Manufacturing Solutions Center, where US manufacturers are provided assistance to increase sales, improve quality and improve efficiency. A 28,000-square-foot (2,600 m2) Regional Simulated Hospital, ValleySim Hospital, opened in 2011. CVCC now has two furniture academies, one in Newton, North Carolina, and one in Taylorsville, North Carolina.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/7/71/Catawba_Valley_Community_College_Logo.jpg/330px-Catawba_Valley_Community_College_Logo.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Catawba_Valley_Community_College", "description": "Public college in Hickory, North Carolina, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-07 12:47:33.702225+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
