INSERT INTO public.spaces VALUES ('917f73d6-487e-4194-b7c4-481f4ede0f44', NULL, '00000000-0000-0000-0000-000000000064', 'Catholic University of Lublin', 'catholic-university-of-lublin', NULL, '{"title": "John Paul II Catholic University of Lublin", "extract": "John Paul II Catholic University of Lublin is a university in Lublin, Poland, established in 1918.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/9/99/LogoKUL.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/John_Paul_II_Catholic_University_of_Lublin", "description": "Catholic university in Lublin, Poland"}', NULL, NULL, 'PL', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.573335+01', '2026-08-07 12:47:33.573335+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('19c21823-b1aa-4583-bdc8-a1bda236923a', NULL, '00000000-0000-0000-0000-000000000064', 'Catholic University of Pusan', 'catholic-university-of-pusan', NULL, '{"title": "Catholic University of Pusan", "extract": "The Catholic University of Pusan is situated in the southeastern South Korean port city of Busan. The current president is Son Sam-seok. The university is traditionally focused on nursing and health sciences, but in addition to these fields it includes schools of environmental science, business administration, computer information engineering, and social welfare. It enrolls about 1,200 students.", "content_url": "https://en.wikipedia.org/wiki/Catholic_University_of_Pusan", "description": "University in South Korea"}', NULL, NULL, 'KR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.5184+01', '2026-08-07 12:47:33.5184+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('13ec5865-71f5-4d86-a787-572583403636', NULL, '00000000-0000-0000-0000-000000000064', 'Central Piedmont Community College', 'central-piedmont-community-college', NULL, '{"title": "Central Piedmont Community College", "extract": "Central Piedmont Community College is a public community college in Charlotte, North Carolina. With an enrollment of more than 40,000 students annually, Central Piedmont is the second-largest community college in the North Carolina Community College System and the largest in the Charlotte metropolitan area. The college has six campuses and three centers and offers nearly 300 degree, diploma and certificate programs.", "content_url": "https://en.wikipedia.org/wiki/Central_Piedmont_Community_College", "description": "Public college in Charlotte, North Carolina, U.S."}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-07 12:47:33.702225+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
