INSERT INTO public.spaces VALUES ('44ddd595-5fc4-4c0d-bb90-d76fdf8cba9c', NULL, '00000000-0000-0000-0000-000000000064', 'Eastern Arizona College', 'eastern-arizona-college', NULL, '{"title": "Eastern Arizona College", "extract": "Eastern Arizona College (EAC), is a community college in Graham County, Arizona, United States. The main campus is in Thatcher, with satellite locations in Gila County and Greenlee County. It is the oldest community college in Arizona and the only one in the state with a marching band.", "content_url": "https://en.wikipedia.org/wiki/Eastern_Arizona_College", "description": "Community college in Graham County, Arizona"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.679268+01', '2026-08-07 12:47:33.679268+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('a4eb474a-7b7e-4a1e-9ee3-e2cad91110b5', NULL, '00000000-0000-0000-0000-000000000064', 'Eastern Connecticut State University', 'eastern-connecticut-state-university', NULL, '{"title": "Eastern Connecticut State University", "extract": "Eastern Connecticut State University is a public university in Willimantic, Connecticut, United States. Founded in 1889, it is the second-oldest campus in the Connecticut State University System and third-oldest public university in the state.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/8/84/Seal_1_of_Eastern_Connecticut_State_University.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Eastern_Connecticut_State_University", "description": "Public university in Willimantic, Connecticut, U.S."}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.188857+01', '2026-08-07 12:47:33.188857+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
