INSERT INTO public.spaces VALUES ('050b0a44-f163-4053-8e93-648345f01d96', NULL, '00000000-0000-0000-0000-000000000064', 'American University of Antigua', 'american-university-of-antigua', NULL, '{"title": "American University of Antigua", "extract": "American University of Antigua (AUA) is a private for-profit international medical school located in Antigua and Barbuda.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/d/de/AUA_COM_Seal_200x200.png", "content_url": "https://en.wikipedia.org/wiki/American_University_of_Antigua", "description": "Medical school located in Antigua and Barbuda"}', NULL, NULL, 'AG', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.262718+01', '2026-08-07 12:47:33.262718+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('d6035f98-1e84-482d-ad72-691f11f17c79', NULL, '00000000-0000-0000-0000-000000000064', 'Eastern Florida State College', 'eastern-florida-state-college', NULL, '{"title": "Eastern Florida State College", "extract": "Eastern Florida State College (EFSC) is a public college based in Cocoa, Florida. It is a member of the Florida College System and has additional campuses in Melbourne, Palm Bay, and Titusville, as well as a virtual campus.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/6/62/Seal-of-Eastern-Florida-State-College.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Eastern_Florida_State_College", "description": "Community college in Brevard County, Florida, U.S."}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.188857+01', '2026-08-07 12:47:33.188857+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('d27c5ee0-52a5-47b3-a44f-11a4c6d04a2e', NULL, '00000000-0000-0000-0000-000000000060', 'Turks and Caicos Islands', 'turks-and-caicos-islands', 'Your digital anchor in North Atlantic Ocean — wherever the diaspora has settled, this is home base. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "Turks and Caicos Islands", "extract": "Turks and Caicos Islands is a British Overseas Territory consisting of the larger Caicos Islands and smaller Turks Islands, two groups of tropical islands in the Lucayan Archipelago of the Atlantic Ocean and northern West Indies. They are known primarily for tourism and as an offshore financial centre. The resident population in 2023 was estimated by The World Factbook at 59,367, making it the third-largest of the British overseas territories by population. However, according to a Department of Statistics estimate in 2022, the population was 47,720.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/a0/Flag_of_the_Turks_and_Caicos_Islands.svg/330px-Flag_of_the_Turks_and_Caicos_Islands.svg.png", "content_url": "https://en.wikipedia.org/wiki/Turks_and_Caicos_Islands", "description": "British Overseas Territory in the North Atlantic Ocean"}', 'b8d256b5-a53a-4cd8-80fc-da35f8df1866', NULL, 'TC', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:54.271217+01', NULL, 'USD', '{"turks and caicos islands",turks-and-caicos-islands,tc,island,community,diaspora}', NULL, 'Americas', 'Caribbean', NULL);
