INSERT INTO public.spaces VALUES ('aea21ed5-a053-4509-8fc1-1d5ff95809af', NULL, '00000000-0000-0000-0000-000000000064', 'Central Michigan University', 'central-michigan-university', NULL, '{"title": "Central Michigan University", "extract": "Central Michigan University is a public research university in Mount Pleasant, Michigan, United States. It was established in 1892 as a private normal school and became a state institution in 1895. CMU is one of the eight research universities in Michigan and is classified among \"R2: Doctoral Universities – High research activity\". It has more than 14,000 students on its Mount Pleasant campus. CMU offers 200 academic programs at the undergraduate, master''s, specialist, and doctoral levels. The Central Michigan Chippewas compete in the NCAA Division I Mid-American Conference in six men''s and ten women''s sports.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/a/a6/Central-Michigan-University-seal.svg/330px-Central-Michigan-University-seal.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Central_Michigan_University", "description": "Public university in Mount Pleasant, Michigan, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.188857+01', '2026-08-07 12:47:33.188857+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('968c66b8-0855-4f19-9af0-0562ec2317e6', NULL, '00000000-0000-0000-0000-000000000064', 'Cerritos College', 'cerritos-college', NULL, '{"title": "Cerritos College", "extract": "Cerritos College is a public community college in Norwalk, California, United States. It was established in 1955 after a collective regional effort through a landmark vote by residents across seven distinct school districts in the Gateway Cities of Southeast Los Angeles.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/8/8c/Cerritos_College_seal.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Cerritos_College", "description": "Community college in Norwalk, California, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.679268+01', '2026-08-07 12:47:33.679268+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
