INSERT INTO public.spaces VALUES ('d3db5768-a4a6-49c8-8c44-3572c0634366', NULL, '00000000-0000-0000-0000-000000000064', 'Eastern Idaho Technical College', 'eastern-idaho-technical-college', NULL, '{"title": "College of Eastern Idaho", "extract": "College of Eastern Idaho (CEI) is a public community college in Idaho Falls, Idaho. It was founded in 1970 as Eastern Idaho Vocational School, then in 1972 was renamed to be called Eastern Idaho Vocational Technical School. In 1989, the college became a technical college and was renamed to Eastern Idaho Technical College. In May 2017, Bonneville County residents voted to create a community college district, allowing Eastern Idaho Technical College to become a community college. In July 2017, the Idaho State Board of Education appointed five community college trustees and completed the transition to community college. Together with the College of Southern Idaho, College of Western Idaho and North Idaho College, CEI is one of only four comprehensive community colleges in Idaho.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/9/96/College_of_Eastern_Idaho_logo.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/College_of_Eastern_Idaho", "description": "Community college in Idaho Falls, Idaho, U.S."}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-07 12:47:33.702225+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('fb5c9fdf-d1ad-4278-aa8c-2b4c60f77d70', NULL, '00000000-0000-0000-0000-000000000064', 'Eastern Gateway Community College', 'eastern-gateway-community-college', NULL, '{"title": "Eastern Gateway Community College", "extract": "Eastern Gateway Community College was a public community college in Steubenville and Youngstown, Ohio, United States. Founded in 1968, it was placed on probation by the Higher Learning Commission in 2021 for concerns about \"assessment, HR record keeping, and data collection and analysis.\" The college began experiencing severe financial distress in 2023 and eventually closed on October 31, 2024.", "content_url": "https://en.wikipedia.org/wiki/Eastern_Gateway_Community_College", "description": "Public community college in Ohio, U.S. (1968–2024)"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-07 12:47:33.702225+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('212ac8e2-6d6d-4a7a-a24c-6f5bf7e6320a', NULL, '00000000-0000-0000-0000-000000000064', 'Eastern Oklahoma State College', 'eastern-oklahoma-state-college', NULL, '{"title": "Eastern Oklahoma State College", "extract": "Eastern Oklahoma State College is a public community college in Wilburton, Oklahoma. It is accredited by the North Central Association of Colleges and Secondary Schools. The school has a branch campus in McAlester and teaching sites in Antlers and Idabel. The enrollment in fall 2023 was 1,292.", "content_url": "https://en.wikipedia.org/wiki/Eastern_Oklahoma_State_College", "description": "Community college in Wilburton, Oklahoma, U.S."}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-07 12:47:33.702225+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('e47d161f-d8a7-4646-9e30-a0a0339d70bf', NULL, '00000000-0000-0000-0000-000000000064', 'Eastern Maine Community College', 'eastern-maine-community-college', NULL, '{"title": "Eastern Maine Community College", "extract": "Eastern Maine Community College (EMCC) is a public community college in Bangor, Maine. It offers over 30 one- and two-year degree programs. The college offers technical, liberal arts, and career programs at the undergraduate level.", "content_url": "https://en.wikipedia.org/wiki/Eastern_Maine_Community_College", "description": "Public college in Bangor, Maine, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-07 12:47:33.702225+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
