INSERT INTO public.spaces VALUES ('0d1c7fbc-d14c-420f-a489-56688a57e0af', NULL, '00000000-0000-0000-0000-000000000060', 'Croatia', 'croatia', 'Your digital anchor in Central and Southeast Europe — wherever the diaspora has settled, this is home base. Home to nearly 3 people, with communities spread far beyond its borders. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "Croatia", "extract": "Croatia, officially the Republic of Croatia, is a country in Central and Southeastern Europe, on the coast of the Adriatic Sea. It borders Slovenia to the northwest, Hungary to the northeast, Serbia to the east, Bosnia and Herzegovina and Montenegro to the southeast, and shares a maritime border with Italy to the west. The Croatian archipelago contains over 1,000 islands and islets, the largest overseas territory on the Adriatic Sea. Its capital, largest city and main cultural and economic centre is Zagreb. Major urban centers include Split, Rijeka, and Osijek. The country is composed of twenty counties spanning 56,594 square kilometres within four administrative regions. Croatia has a population of nearly 3.9 million as of 2026.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/1b/Flag_of_Croatia.svg/330px-Flag_of_Croatia.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Croatia", "description": "Country in Central and Southeast Europe"}', 'e9253575-b090-48ee-a1f1-954ad8210f1a', NULL, 'HR', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:25.025633+01', NULL, 'EUR', '{croatia,hr,europe,island,community,diaspora}', NULL, 'Europe', 'Southern Europe', NULL);
