INSERT INTO public.spaces VALUES ('8ea4964a-828a-40b9-8733-7c23c7e03822', NULL, '00000000-0000-0000-0000-000000000064', 'Centro Universitario Villanueva', 'centro-universitario-villanueva', NULL, '{"title": "Villanueva University", "extract": "Universidad Villanueva is a private university located in Madrid (Spain), affiliated to the Catholic organization Opus Dei. It is the smallest university in Madrid by number of bachelor''s students. It started teaching in the year 2020, although its history as an institution can be traced back to 1977.", "content_url": "https://en.wikipedia.org/wiki/Villanueva_University", "description": "Private university in Madrid, Spain"}', NULL, NULL, 'ES', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.625787+01', '2026-08-07 12:47:33.625787+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('90ea6327-76d8-4477-bb62-175fc28d2498', NULL, '00000000-0000-0000-0000-000000000060', 'Armenia', 'armenia', 'It is set in West Asia, landlocked, sharing borders with Turkey, Georgia, Azerbaijan, and Iran. Whether you''re still in West Asia or building a life elsewhere, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Armenia", "extract": "Armenia, officially the Republic of Armenia, is a landlocked country in the Armenian highlands of West Asia. It is a part of the Caucasus region and is bordered by Turkey to the west, Georgia to the north, Azerbaijan to the east, and Iran and the Azerbaijani exclave of Nakhchivan to the south. Yerevan is the capital, largest city and financial center.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/2f/Flag_of_Armenia.svg/330px-Flag_of_Armenia.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Armenia", "description": "Country in West Asia"}', '9b65bd27-05b3-4586-816f-4708ce844d21', NULL, 'AM', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:04.337307+01', NULL, NULL, '{armenia,am,asia,landlocked,community,diaspora}', NULL, 'Asia', 'Western Asia', NULL);
INSERT INTO public.spaces VALUES ('222f4147-dc96-4e4f-9f19-f8d46f9a3f49', NULL, '00000000-0000-0000-0000-000000000064', 'Century College', 'century-college', NULL, '{"title": "Century College", "extract": "Century College is a public community college in White Bear Lake, Minnesota. It is a member of the Minnesota State system. It was founded in 1967 as Lakewood State Junior College and in 1996 merged with Northeast Metro Technical College to become Century College.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/9/96/Century_College.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Century_College", "description": "Two-year college in White Bear Lake, Minnesota, U.S."}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-07 12:47:33.702225+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
