INSERT INTO public.spaces VALUES ('ede542ab-85f6-4512-b53c-decf8ae8faf6', NULL, '00000000-0000-0000-0000-000000000064', 'Cerro Coso Community College', 'cerro-coso-community-college', NULL, '{"title": "Cerro Coso Community College", "extract": "Cerro Coso Community College is a public community college in the Eastern Sierra region of Southern California. It was established in 1973 as a separate college within the Kern Community College District. The college offers traditional and online courses and two-year degrees. The college serves an area of approximately 18,000-square-miles. Cerro Coso has five instructional sites: Eastern Sierra Center Bishop and Mammoth Lakes, Indian Wells Valley, Kern River Valley, and South Kern. The college also has an Incarcerated Student Education Program in two locations, the California City Correctional Facility and Tehachapi California Correctional Institution.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/42/Cerro_Coso_Community_College-iwv.jpg/330px-Cerro_Coso_Community_College-iwv.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Cerro_Coso_Community_College", "description": "Public college in Ridgecrest, California"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.679268+01', '2026-08-07 12:47:33.679268+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('ef5f29ec-4ffd-45f5-ae47-fd0ac4305bdf', NULL, '00000000-0000-0000-0000-000000000064', 'Chabot College', 'chabot-college', NULL, '{"title": "Chabot College", "extract": "Chabot College is a public community college in Hayward, California. It is part of the Chabot-Las Positas Community College District.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/15/Chabot_College_07819.JPG/330px-Chabot_College_07819.JPG", "content_url": "https://en.wikipedia.org/wiki/Chabot_College", "description": "Community college in Hayward, California, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.679268+01', '2026-08-07 12:47:33.679268+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('65d6e380-3e93-4d6d-8d77-50de1a560223', NULL, '00000000-0000-0000-0000-000000000064', 'Ecole Supérieure de Commerce de Rouen', 'ecole-sup-rieure-de-commerce-de-rouen', NULL, '{"title": "Rouen Business School", "extract": "The Rouen Business School was a leading French business school.\nIt was founded in 1871. On 24 April 2013, Rouen Business School and Reims Management School announced the merger of the two schools into a single entity - NEOMA Business School.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d1/Project2.jpg/330px-Project2.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Rouen_Business_School", "description": "Business school"}', NULL, NULL, 'FR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.384776+01', '2026-08-07 12:47:33.384776+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
