INSERT INTO public.spaces VALUES ('ad02c485-212f-4ef2-8f03-9f6a2638a7e9', NULL, '00000000-0000-0000-0000-000000000064', 'Chaminade University of Honolulu', 'chaminade-university-of-honolulu', NULL, '{"title": "Chaminade University of Honolulu", "extract": "Chaminade University of Honolulu is a private Marianist university in Honolulu, Hawaii, United States. Founded in 1955 by the Society of Mary, Chaminade is located in Kaimuki, Honolulu at the base of St. Louis Heights. Chaminade offers bachelor''s degrees in 23 fields of study and 5 master''s degree programs. Chaminade University is accredited by the WASC Senior College and University Commission.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/2/28/ChaminadeSeal.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Chaminade_University_of_Honolulu", "description": "Marianist university in Hawaii, U.S."}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.726322+01', '2026-08-07 12:47:33.726322+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
