INSERT INTO public.spaces VALUES ('47d3b9be-06ac-4f07-b8e2-a4ccf09fe7ad', NULL, '00000000-0000-0000-0000-000000000064', 'Chabot-Las Positas Community College District', 'chabot-las-positas-community-college-district', NULL, '{"title": "Chabot–Las Positas Community College District", "extract": "The Chabot–Las Positas Community College District is a public school district based in Alameda County, California, in the United States. Colleges in the district include Chabot College in Hayward, and Las Positas College in Livermore.", "content_url": "https://en.wikipedia.org/wiki/Chabot%E2%80%93Las_Positas_Community_College_District", "description": "Local college administrative unit in California, USA"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.188857+01', '2026-08-07 12:47:33.188857+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
