INSERT INTO public.spaces VALUES ('6e683c84-066e-4619-879d-24f38838e76f', NULL, '00000000-0000-0000-0000-000000000064', 'Chatfield College', 'chatfield-college', NULL, '{"title": "Chatfield College", "extract": "Chatfield College was a private Catholic college in St. Martin and Cincinnati, Ohio, United States. Chatfield was founded by the Ursulines of Brown County in 1971. Chatfield offered the Associate of Arts and Associate of Applied Science degrees. The college was accredited by the Higher Learning Commission.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/c8/Chatfield_College_logo.jpg/330px-Chatfield_College_logo.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Chatfield_College", "description": "Private Catholic college in Ohio, U.S."}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-07 12:47:33.702225+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
