INSERT INTO public.spaces VALUES ('c0ddf4b7-5440-496c-b97e-3b1899ee78ae', NULL, '00000000-0000-0000-0000-000000000064', 'Chattahoochee Technical College', 'chattahoochee-technical-college', NULL, '{"title": "Chattahoochee Technical College", "extract": "Chattahoochee Technical College is a public technical college in the U.S. state of Georgia. It is governed by the Technical College System of Georgia and has eight campuses in the north-northwest metro-Atlanta area, and another just outside the region. It is accredited by the Southern Association of Colleges and Schools Commission on Colleges (SACS) to award technical certificates of credit, diplomas, and associate degrees. The college was formed in 2009 as the result of the merger of Appalachian Technical College, Chattahoochee Technical College, and North Metro Technical College.", "content_url": "https://en.wikipedia.org/wiki/Chattahoochee_Technical_College", "description": "Technical college in Georgia, U.S."}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.679268+01', '2026-08-07 12:47:33.679268+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('707b57bb-839a-43d7-be70-429caeddce12', NULL, '00000000-0000-0000-0000-000000000064', 'Chattanooga State Community College', 'chattanooga-state-community-college', NULL, '{"title": "Chattanooga State Community College", "extract": "Chattanooga State Community College is a public community college in Chattanooga, Tennessee. The college is a member of the Tennessee Board of Regents System and is accredited by the Southern Association of Colleges and Schools (SACS). Athletically, Chattanooga State is a member of Region VII of the NJCAA.", "content_url": "https://en.wikipedia.org/wiki/Chattanooga_State_Community_College", "description": "Public college in Chattanooga, Tennessee, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.726322+01', '2026-08-07 12:47:33.726322+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('ed1862a1-5292-4cee-ad50-8706ec5d67db', NULL, '00000000-0000-0000-0000-000000000064', 'Cheju National University', 'cheju-national-university', NULL, '{"title": "Jeju National University", "extract": "Jeju National University is one of ten Flagship Korean National Universities. Founded in 1952 in Jeju City, the provincial capital of Jeju, South Korea. In 2008 Cheju National University and the Jeju National University of Education merged into Jeju National University. The Naewat-dang shamanic paintings are preserved there.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/94/Jnuimage.jpg/330px-Jnuimage.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Jeju_National_University", "description": "University in South Korea"}', NULL, NULL, 'KR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.5184+01', '2026-08-07 12:47:33.5184+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('f6f027f7-babb-43c0-805d-ac67a8489841', NULL, '00000000-0000-0000-0000-000000000064', 'Chaudhary Charan Singh University', 'chaudhary-charan-singh-university', NULL, '{"title": "Chaudhary Charan Singh University", "extract": "Chaudhary Charan Singh University, formerly Meerut University, is a public state university located in Meerut, Uttar Pradesh, India. The university was established in 1965. It was later renamed to its current name after Chaudhary Charan Singh, former Prime minister of India. The university celebrated its silver jubilee in 1991.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/4/41/Chaudhary_Charan_Singh_University_logo.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Chaudhary_Charan_Singh_University", "description": "Public state university in Uttar Pradesh, India"}', NULL, NULL, 'IN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.411195+01', '2026-08-07 12:47:33.411195+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
