INSERT INTO public.spaces VALUES ('b2d4065b-4034-40d6-b966-40b2dde1fdd1', NULL, '00000000-0000-0000-0000-000000000064', 'Chemeketa Community College', 'chemeketa-community-college', NULL, '{"title": "Chemeketa Community College", "extract": "Chemeketa Community College (CCC) is a public community college in Salem, Oregon, with a campus in McMinnville, and education centers in Dallas, Brooks, and Woodburn. In addition, the college has a Center for Business and Industry in downtown Salem that houses the Small Business Development Center. It operates classes and programs benefiting area businesses.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d2/Chemeketa_Community_College.JPG/330px-Chemeketa_Community_College.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Chemeketa_Community_College", "description": "Community college in Salem, Oregon, U.S."}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-07 12:47:33.702225+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
