INSERT INTO public.spaces VALUES ('07ef7b20-bf23-42e9-9154-d22b91b35767', NULL, '00000000-0000-0000-0000-000000000064', 'China University of Political Science and Law', 'china-university-of-political-science-and-law', NULL, '{"title": "China University of Political Science and Law", "extract": "The China University of Political Science and Law, also translated as Zhengfa University, is a national public university in Beijing, China. It is affiliated with the Ministry of Education and co-sponsored with the Beijing Municipal People''s Government. The university is part of the prestigious Project 211 and the Double First-Class Construction.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/3/3e/China_University_of_Political_Science_and_Law.svg/330px-China_University_of_Political_Science_and_Law.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/China_University_of_Political_Science_and_Law", "description": "Public university in Beijing, China"}', NULL, NULL, 'CN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.326239+01', '2026-08-07 12:47:33.326239+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('ce6fe5ca-960c-44f1-9199-4b14bc9646a4', NULL, '00000000-0000-0000-0000-000000000064', 'Chinese People''s Public Security University', 'chinese-people-s-public-security-university', NULL, '{"title": "People''s Public Security University of China", "extract": "The People''s Public Security University of China is a national police academy and public university in Xicheng, Beijing, China. Founded in 1948, it is affiliated with the Ministry of Public Security of China. The university is part of the Double First-Class Construction.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/fc/People%27s_Public_Security_University_of_China%2C_Muxidi_Campus_%2820201023161055%29.jpg/330px-People%27s_Public_Security_University_of_China%2C_Muxidi_Campus_%2820201023161055%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/People''s_Public_Security_University_of_China", "description": "Police college in Beijing, China"}', NULL, NULL, 'CN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.326239+01', '2026-08-07 12:47:33.326239+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
