INSERT INTO public.spaces VALUES ('153b8cd0-9f7c-47cd-abfd-5215703d2a31', NULL, '00000000-0000-0000-0000-000000000064', 'Chinese Culture University', 'chinese-culture-university', NULL, '{"title": "Chinese Culture University", "extract": "Chinese Culture University is a private research university in Yangmingshan in Shilin District, Taipei, Taiwan. Established in 1962, the university is one of the largest universities in Taiwan with an enrollment of about 32,000 students. Satellite campuses are located in the Jianguo, Ximending, and Zhongxiao East Road areas of Taipei City.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/6/66/Chinese_Culture_University_emblem.svg/330px-Chinese_Culture_University_emblem.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Chinese_Culture_University", "description": "Private university in Taipei, Taiwan"}', NULL, NULL, 'TW', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.65283+01', '2026-08-07 12:47:33.65283+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('0dc2d24c-04e1-4d52-a303-be31e585eb8a', NULL, '00000000-0000-0000-0000-000000000064', 'Chittagong University of Engineering and Technology', 'chittagong-university-of-engineering-and-technology', NULL, '{"title": "Chittagong University of Engineering & Technology", "extract": "Chittagong University of Engineering & Technology, commonly referred to as CUET, is a public engineering and technological research university located in Raozan in Chittagong District, Bangladesh. Established in 1968 as the Chittagong Engineering College and gained University status in 1986, this university is a state funded institution, maintaining special emphasis on teaching and research of engineering, technology, architecture and planning under five faculties and seventeen academic departments.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/0/0e/CUET_Vector_Logo.svg/330px-CUET_Vector_Logo.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Chittagong_University_of_Engineering_%26_Technology", "description": "Public university in Chattogram, Bangladesh"}', NULL, NULL, 'BD', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.296289+01', '2026-08-07 12:47:33.296289+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
