INSERT INTO public.spaces VALUES ('01e3847d-059a-431b-805f-f48e621d084f', NULL, '00000000-0000-0000-0000-000000000060', 'United Arab Emirates', 'united-arab-emirates', 'It is set in West Asia, sharing borders with Oman and Saudi Arabia. Whether you''re still in West Asia or building a life elsewhere, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "United Arab Emirates", "extract": "The United Arab Emirates (UAE), also known simply as the Emirates, is a country in West Asia, situated at the eastern end of the Arabian Peninsula. It is a federal semi-constitutional monarchy made up of seven emirates, with Abu Dhabi serving as its national capital. The UAE borders Oman to the east and northeast, and Saudi Arabia to the south and southwest. It shares maritime borders with Saudi Arabia, Qatar, and Iran in the Persian Gulf, and with Oman in the Gulf of Oman. In 2024, the UAE had an estimated population of over 11 million. Dubai is the country''s largest city. Islam is the state religion. Arabic is the official language while English remains the most spoken language and the language of business.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/cb/Flag_of_the_United_Arab_Emirates.svg/330px-Flag_of_the_United_Arab_Emirates.svg.png", "content_url": "https://en.wikipedia.org/wiki/United_Arab_Emirates", "description": "Country in West Asia"}', '8066fe73-201b-424f-8e59-668e6d3834aa', NULL, 'AE', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-07-08 23:07:05.600578+01', '2026-08-07 11:45:56.285864+01', NULL, 'AED', '{"united arab emirates",united-arab-emirates,ae,asia,community,diaspora}', NULL, 'Asia', 'Western Asia', NULL);
