INSERT INTO public.spaces VALUES ('68794f8b-4245-4377-8de2-1671fe02319d', NULL, '00000000-0000-0000-0000-000000000064', 'Chulalongkorn University', 'chulalongkorn-university', NULL, '{"title": "Chulalongkorn University", "extract": "Chulalongkorn University is a public autonomous research university in Bangkok, Thailand. The university was originally founded during King Chulalongkorn''s reign as a school for training royal pages and civil servants in 1899 at the Grand Palace. It was later established as a national university in 1917, making it the oldest institute of higher education in Thailand.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/78/Logo_of_Chulalongkorn_University_%282026%29.svg/330px-Logo_of_Chulalongkorn_University_%282026%29.svg.png", "content_url": "https://en.wikipedia.org/wiki/Chulalongkorn_University", "description": "Public university in Bangkok, Thailand"}', NULL, NULL, 'TH', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.65283+01', '2026-08-07 12:47:33.65283+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('f23e7c0b-b93d-4ed3-9819-4244ca8aa417', NULL, '00000000-0000-0000-0000-000000000064', 'Chukyo University', 'chukyo-university', NULL, '{"title": "Chukyo University", "extract": "Chukyo University  is a private university in Aichi Prefecture, Japan, with campuses in Nagoya and Toyota. The main building is located in Yagoto, Shōwa-ku, Nagoya.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d7/NGO_Showa_20240128-10.jpg/330px-NGO_Showa_20240128-10.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Chukyo_University", "description": "Private university in Aichi prefecture, Japan"}', NULL, NULL, 'JP', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.465646+01', '2026-08-07 12:47:33.465646+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
