INSERT INTO public.spaces VALUES ('e216dc67-4437-47b9-85d8-6b673716281a', NULL, '00000000-0000-0000-0000-000000000064', 'Cisco College', 'cisco-college', NULL, '{"title": "Cisco College", "extract": "Cisco College is a community college in Cisco, Texas and Abilene, Texas. The main campus is 92 acres (370,000 m2) outside of Cisco, and the Abilene Educational Center is 38 acres (150,000 m2) in Abilene. The college is accredited to award associate degrees by the Southern Association of Colleges and Schools.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/0c/Cisco_College_sign%2C_Cisco%2C_TX_IMG_6392.JPG/330px-Cisco_College_sign%2C_Cisco%2C_TX_IMG_6392.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Cisco_College", "description": "Community college in Cisco, Texas, U.S."}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.726322+01', '2026-08-07 12:47:33.726322+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
