INSERT INTO public.spaces VALUES ('0eae2560-3c13-4a51-b65f-fdaea155cb80', NULL, '00000000-0000-0000-0000-000000000064', 'Ecole Supérieure de Commerce de Reims', 'ecole-sup-rieure-de-commerce-de-reims', NULL, '{"title": "École supérieure de commerce de Reims", "extract": "École supérieure de commerce de Reims, is one of France''s leading Grandes Ecoles of management. Founded in 1928, it belongs to Reims Management School (RMS), a group of schools accredited EQUIS, AMBA and AACSB.", "content_url": "https://en.wikipedia.org/wiki/%C3%89cole_sup%C3%A9rieure_de_commerce_de_Reims", "description": ""}', NULL, NULL, 'FR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.384776+01', '2026-08-07 12:47:33.384776+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('69aceac1-e9f8-4569-88dc-caa871443109', NULL, '00000000-0000-0000-0000-000000000064', 'City College of San Francisco', 'city-college-of-san-francisco', NULL, '{"title": "City College of San Francisco", "extract": "City College of San Francisco is a public community college in San Francisco, California, United States. Founded as a junior college in 1935, the college plays an important local role, enrolling as many as 1 in 35 San Francisco residents annually. CCSF is accredited by the Accrediting Commission for Community and Junior Colleges (ACCJC).", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/3/31/City_College_of_San_Francisco_logo.svg/330px-City_College_of_San_Francisco_logo.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/City_College_of_San_Francisco", "description": "Community college in California, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.679268+01', '2026-08-07 12:47:33.679268+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
