INSERT INTO public.spaces VALUES ('0cc490db-530d-4d1a-9419-5e6dff2bbd8e', NULL, '00000000-0000-0000-0000-000000000064', 'Coastline Community College', 'coastline-community-college', NULL, '{"title": "Coastline College", "extract": "Coastline College is a California public community college with mini-campuses in Westminster, Garden Grove, and Newport Beach, and an administration building in Fountain Valley, California. The college offers Associate in Arts degrees, Associate in Science degrees, courses to prepare students to transfer to a four-year college or university, and career and technical courses that can lead to career advancement and/or an occupational certificate. The college was founded in 1976 and is part of the Coast Community College District and the California Community Colleges.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/9/9e/Coastline_College.svg/330px-Coastline_College.svg.png", "content_url": "https://en.wikipedia.org/wiki/Coastline_College", "description": "Community colleges in Orange County, California"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.679268+01', '2026-08-07 12:47:33.679268+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('39db4352-24af-4d1c-9a79-50bfc760dfb6', NULL, '00000000-0000-0000-0000-000000000064', 'Coastal Pines Technical College', 'coastal-pines-technical-college', NULL, '{"title": "Coastal Pines Technical College", "extract": "Coastal Pines Technical College (CPTC) is a community college in Waycross, Georgia, with six branches in other cities. It has a thirteen-county service delivery area (SDA), covering a total of 7,433 square miles, which is the largest SDA in the Technical College System of Georgia (TCSG). Coastal Pines has seven instructional sites in the rural towns of Alma, Baxley, Brunswick, Hazlehurst, Jesup, Kingsland and Waycross in southeastern Georgia, nineteen adult education sites and dual enrollment opportunities with sixteen high schools. The school offers over 130 programs, associate''s degree, and certificate or diploma programs in the areas of allied health, business and computer, personal services, and technical and industrial technology. Students can earn a degree, diploma or certificate in as little as eight weeks to two years.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/42/1300_Building%2C_Coastal_Pines_Technical_College.JPG/330px-1300_Building%2C_Coastal_Pines_Technical_College.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Coastal_Pines_Technical_College", "description": "Community college in Waycross, Georgia, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-07 12:47:33.702225+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('52541a1c-03e9-4329-892c-5e680bc39516', NULL, '00000000-0000-0000-0000-000000000064', 'Coahoma Community College', 'coahoma-community-college', NULL, '{"title": "Coahoma Community College", "extract": "Coahoma Community College (CCC) is a public historically black community college in unincorporated Coahoma County, Mississippi. The college was founded in 1949 and is accredited by the Southern Association of Colleges and Schools Commission on Colleges. It offers associate degree and certificate programs in more than 70 areas of focus.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/0/0d/Coahoma_Community_College_seal.png", "content_url": "https://en.wikipedia.org/wiki/Coahoma_Community_College", "description": "Community college in Coahoma County, Mississippi, U.S."}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-07 12:47:33.702225+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
