INSERT INTO public.spaces VALUES ('c4cb50c3-a963-48a9-a01b-189e5fc2a45c', NULL, '00000000-0000-0000-0000-000000000064', 'Clover Park Technical College', 'clover-park-technical-college', NULL, '{"title": "Clover Park Technical College", "extract": "Clover Park Technical College (CPTC) is a public community college with its main campus in Lakewood, Washington, United States. It also has two other campuses, an aviation-focused South Hill Campus near Puyallup adjacent to Thun Field and the Eastside Training Center in Tacoma.", "content_url": "https://en.wikipedia.org/wiki/Clover_Park_Technical_College", "description": "Public college in Lakewood, Washington, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.726322+01', '2026-08-07 12:47:33.726322+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('842b3d48-6ad9-40c9-b9ce-84af0e19fb34', NULL, '00000000-0000-0000-0000-000000000064', 'Cochin University of Science and Technology', 'cochin-university-of-science-and-technology', NULL, '{"title": "Cochin University of Science and Technology", "extract": "Cochin University of Science and Technology (CUSAT) is a state government-owned autonomous university in Kochi, Kerala, India. It was founded in 1971 and has three campuses: two in Kochi and one in Kuttanad, Alappuzha, some 66 km (41 mi) from Kochi.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/6/6f/Cochin_University_of_Science_and_Technology_Logo.png", "content_url": "https://en.wikipedia.org/wiki/Cochin_University_of_Science_and_Technology", "description": "University in Cochin, Kerala, India"}', NULL, NULL, 'IN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.411195+01', '2026-08-07 12:47:33.411195+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
