INSERT INTO public.spaces VALUES ('16660ba8-78c9-431f-9dda-e80c35aea23d', NULL, '00000000-0000-0000-0000-000000000064', 'Cochise College', 'cochise-college', NULL, '{"title": "Cochise College", "extract": "Cochise College is a public college in Arizona. Founded on September 21, 1964, the school has campuses in Douglas and Sierra Vista, and centers in Benson, Fort Huachuca, and Willcox. Cochise College offers associate degrees in art, applied science, business, elementary education, general studies, and science, and over 30 different certificate programs. The college also offers transfer programs for students to transfer to partner universities.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/a/a5/Cochise_College.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Cochise_College", "description": "Community college in Cochise County, Arizona, U.S."}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.679268+01', '2026-08-07 12:47:33.679268+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('041170cb-2d83-4110-95ae-bc7fcea57663', NULL, '00000000-0000-0000-0000-000000000064', 'Coker College', 'coker-college', NULL, '{"title": "Coker University", "extract": "Coker University is a private university in Hartsville, South Carolina, United States. It was founded in 1908 and is accredited by the Southern Association of Colleges and Schools. Coker''s sports teams, nicknamed the Cobras, compete in NCAA Division II.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/1/1d/Coker_college_seal.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Coker_University", "description": "Private university in Hartsville, South Carolina, U.S."}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.188857+01', '2026-08-07 12:47:33.188857+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('d6c1ab2a-b6a1-47a9-af6e-965c85fac293', NULL, '00000000-0000-0000-0000-000000000064', 'Ecole Supérieure de Commerce de Paris', 'ecole-sup-rieure-de-commerce-de-paris', NULL, '{"title": "ESCP Business School", "extract": "ESCP Business School is a French business school and grande école founded in Paris and based across Europe with campuses in Paris, Berlin, London, Madrid, Turin, and Warsaw. Established in 1819, it is considered the world''s oldest business school. ESCP Business School runs BSc, MBA, Executive MBA, master''s degree programs in finance and management, executive education programs, and PhD programs.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/96/Escp-Paris.jpg/330px-Escp-Paris.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/ESCP_Business_School", "description": "European business school"}', NULL, NULL, 'FR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.384776+01', '2026-08-07 12:47:33.384776+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
