INSERT INTO public.spaces VALUES ('121cb219-f1ba-47ac-aadb-d12b3ec0705e', NULL, '00000000-0000-0000-0000-000000000064', 'Colby College', 'colby-college', NULL, '{"title": "Colby College", "extract": "Colby College is a private liberal arts college in Waterville, Maine, United States. Founded in 1813 as the Maine Literary and Theological Institution, it was renamed Waterville College in 1821. The donations of philanthropist Gardner Colby saw the institution renamed again to Colby University before settling on its current name, reflecting its liberal arts college curriculum, in 1899. Approximately 2,400 students, representing more than 45 states and 80 countries, are enrolled annually. The college offers 58 major fields of study and 38 minors.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/35/Colby_college_maine_seal.svg/330px-Colby_college_maine_seal.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Colby_College", "description": "Private college in Waterville, Maine, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.188857+01', '2026-08-07 12:47:33.188857+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
