INSERT INTO public.spaces VALUES ('9e204a44-5cab-4cfc-8495-8d39e36bbfc2', NULL, '00000000-0000-0000-0000-000000000064', 'College of St. Scholastica', 'college-of-st-scholastica', NULL, '{"title": "College of St. Scholastica", "extract": "The College of St. Scholastica (CSS) is a private Benedictine college in Duluth, Minnesota, United States. It was founded in 1912 by a group of Benedictine Sisters and enrolled about 3,000 students as of 2023. The college offers a liberal arts education and is located on 186 wooded acres overlooking Lake Superior. Saint Scholastica was a Christian hermit traditionally regarded as the founder of the Benedictine nuns.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/b/b9/College_st_scholastica_seal.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/College_of_St._Scholastica", "description": "Private Benedictine college in Duluth, Minnesota, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.188857+01', '2026-08-07 12:47:33.188857+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('9d97efee-d71d-4c0f-9da9-fed554af2754', NULL, '00000000-0000-0000-0000-000000000064', 'College of the Albemarle', 'college-of-the-albemarle', NULL, '{"title": "College of The Albemarle", "extract": "College of The Albemarle (COA) is a public community college in the Albemarle region of northeastern North Carolina. The main campus is in Elizabeth City with satellite campuses in Barco, Manteo and Edenton. Established on December 16, 1960, College of The Albemarle became the first institution of the North Carolina Community College System as chartered by the Community College Act of 1957.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/b/ba/College_of_The_Albemarle_logo.svg/330px-College_of_The_Albemarle_logo.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/College_of_The_Albemarle", "description": "College in North Carolina, United States"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-07 12:47:33.702225+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
