INSERT INTO public.spaces VALUES ('ac5d29e2-d02a-41d6-ab65-23c730b85e41', NULL, '00000000-0000-0000-0000-000000000064', 'American University of Armenia', 'american-university-of-armenia', NULL, '{"title": "American University of Armenia", "extract": "The American University of Armenia (AUA) is a private, independent university in Yerevan, Armenia that is accredited by the Western Association of Schools and Colleges Senior College and University Commission. It is the first U.S.-accredited institution in the former Soviet Union that provides undergraduate and graduate education.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/e3/AUA_official_logo.png/330px-AUA_official_logo.png", "content_url": "https://en.wikipedia.org/wiki/American_University_of_Armenia", "description": "University in Yerevan, Armenia"}', NULL, NULL, 'AM', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.262718+01', '2026-08-07 12:47:33.262718+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('fd944c91-137d-48df-95b7-ca1765cb9b46', NULL, '00000000-0000-0000-0000-000000000064', 'Armenian State Agrarian University', 'armenian-state-agrarian-university', NULL, '{"title": "Armenian National Agrarian University", "extract": "Armenian National Agrarian University (ANAU), is a state university and higher educational institution based in Yerevan, the capital of Armenia. The university trains and prepares specialists for the agricultural sphere.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/01/Armenian_National_Agrarian_University_31.07.2018.jpg/330px-Armenian_National_Agrarian_University_31.07.2018.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Armenian_National_Agrarian_University", "description": "Public university in Yerevan, Armenia"}', NULL, NULL, 'AM', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.262718+01', '2026-08-07 12:47:33.262718+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
