INSERT INTO public.spaces VALUES ('2a1703f3-8247-463d-b136-14337039fa7e', NULL, '00000000-0000-0000-0000-000000000064', 'Columbia Gorge Community College', 'columbia-gorge-community-college', NULL, '{"title": "Columbia Gorge Community College", "extract": "Columbia Gorge Community College (CGCC) is a public community college with campuses in The Dalles and Hood River, Oregon. Established in 1977, it serves residents of Wasco and Hood River counties and the broader Columbia River Gorge region. The college offers transfer degrees, career and technical education programs, adult basic skills, and workforce training. CGCC is accredited by the Northwest Commission on Colleges and Universities and is a member of the Northwest Athletic Conference.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/4e/Columbia_Gorge_Community_College%2C_The_Dalles_-_DPLA_-_a066be0b842fb85b467f2f544d0e516f.jpg/330px-Columbia_Gorge_Community_College%2C_The_Dalles_-_DPLA_-_a066be0b842fb85b467f2f544d0e516f.jpg", "content_url": "https://en.wikipedia.org/wiki/Columbia_Gorge_Community_College", "description": "College in The Dalles, Oregon, U.S."}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-07 12:47:33.702225+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
