INSERT INTO public.spaces VALUES ('258893e1-d827-4493-96ca-ba2615efbfd4', NULL, '00000000-0000-0000-0000-000000000064', 'Columbia Southern University', 'columbia-southern-university', NULL, '{"title": "Columbia Southern University", "extract": "Columbia Southern University is a private for-profit online university based in Orange Beach, Alabama, United States. It was founded in 1993 and is accredited by the Southern Association of Colleges and Schools Commission on Colleges.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/f/f8/Columbia_Southern_University_Seal.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Columbia_Southern_University", "description": "American for-profit online university"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.188857+01', '2026-08-07 12:47:33.188857+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('75706243-c038-4789-a891-fd6ac5f96ae5', NULL, '00000000-0000-0000-0000-000000000064', 'Columbia State Community College', 'columbia-state-community-college', NULL, '{"title": "Columbia State Community College", "extract": "Columbia State Community College is a public community college in Columbia, Tennessee. Founded in 1966, it serves nine counties in southern Middle Tennessee through five campuses. It is accredited by the Southern Association of Colleges and Schools Commission on Colleges to award Associate of Arts, Associate of Science, Associate of Science in Teaching, Associate of Fine Arts, and Associate of Applied Science degrees, and technical certificates.", "content_url": "https://en.wikipedia.org/wiki/Columbia_State_Community_College", "description": "College in Columbia, Tennessee, U.S."}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.726322+01', '2026-08-07 12:47:33.726322+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('8fa245c4-bd9b-4d1a-a05c-d3c839a50a4d', NULL, '00000000-0000-0000-0000-000000000064', 'Columbus State University', 'columbus-state-university', NULL, '{"name": "Columbus State University", "image": "http://commons.wikimedia.org/wiki/Special:FilePath/CSU%20Schuster%20Student%20Success%20Center.JPG", "country": "United States", "founded": "1958-01-01T00:00:00Z", "website": "http://www.columbusstate.edu", "students": "7877", "description": "public institution of higher learning located in Columbus, Georgia, United States", "wikidata_id": "http://www.wikidata.org/entity/Q5150130", "wikipedia_url": "https://en.wikipedia.org/wiki/Q5150130"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.188857+01', '2026-08-07 12:47:33.188857+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('2d0f8e84-2317-4d75-b81c-128b4b70297b', NULL, '00000000-0000-0000-0000-000000000064', 'Columbia-Greene Community College', 'columbia-greene-community-college', NULL, '{"title": "Columbia–Greene Community College", "extract": "Columbia–Greene Community College is a public community college in Hudson, New York. Founded in 1966, it is part of the State University of New York (SUNY) system and is locally sponsored by two rural counties, Columbia and Greene, which have a combined population of about 112,000. The college was originally in Athens, New York until its permanent relocation to the City of Hudson in 1974. It currently offers 32 associate degree programs and five undergraduate certificate programs. C-GCC is accredited by the Middle States Commission on Higher Education and enrolls approximately 1,578 students as of Fall 2018.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/e/ee/Columbia-Greene_Community_College_Seal.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Columbia%E2%80%93Greene_Community_College", "description": "Public college in Hudson, New York, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-07 12:47:33.702225+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('819b8fac-cbbc-486d-9368-271ff26b238d', NULL, '00000000-0000-0000-0000-000000000064', 'Columbus State Community College', 'columbus-state-community-college', NULL, '{"title": "Columbus State Community College", "extract": "Columbus State Community College (CSCC) is a public community college in Columbus, Ohio, United States. Founded as Columbus Area Technician''s School in 1963, it was renamed Columbus Technical Institute in 1965 and was renamed again to its current name in 1987. The college has grown from an initial enrollment of 67 students in 1963 to its current enrollment of over 27,000 students across two campuses, nine regional learning centers, and online courses.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/3/36/Columbus_State_Community_College_seal.svg/330px-Columbus_State_Community_College_seal.svg.png", "content_url": "https://en.wikipedia.org/wiki/Columbus_State_Community_College", "description": "Public college in Columbus, Ohio, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-07 12:47:33.702225+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('1bb2c24c-775a-47fa-b359-c0882895bc6b', NULL, '00000000-0000-0000-0000-000000000064', 'Comenius University in Bratislava', 'comenius-university-in-bratislava', NULL, '{"title": "Comenius University", "extract": "Comenius University Bratislava is the largest university in Slovakia, with most of its faculties located in Bratislava. It was founded in 1919, shortly after the creation of Czechoslovakia. It is named after Jan Amos Comenius, a 17th-century Czech teacher and philosopher.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/0a/Univerzita_Komensk%C3%A9ho.jpg/330px-Univerzita_Komensk%C3%A9ho.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Comenius_University", "description": "Public university in Bratislava, Slovakia"}', NULL, NULL, 'SK', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.625787+01', '2026-08-07 12:47:33.625787+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('98590068-b347-40e4-93c8-47e7656ba082', NULL, '00000000-0000-0000-0000-000000000064', 'Corvinus University of Budapest', 'corvinus-university-of-budapest', NULL, '{"name": "Corvinus University of Budapest", "image": "http://commons.wikimedia.org/wiki/Special:FilePath/Corvinus%20foepulet.jpg", "country": "Hungary", "founded": "1920-01-01T00:00:00Z", "website": "https://uni-corvinus.hu/", "students": "18000", "description": "university", "wikidata_id": "http://www.wikidata.org/entity/Q851164", "wikipedia_url": "https://en.wikipedia.org/wiki/Q851164"}', NULL, NULL, 'HU', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.726322+01', '2026-08-07 12:47:33.726322+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('91ad72aa-03da-4a30-b280-44a28983f815', NULL, '00000000-0000-0000-0000-000000000064', 'Cork Institute of Technology', 'cork-institute-of-technology', NULL, '{"title": "Cork Institute of Technology", "extract": "Cork Institute of Technology was an institute of technology, located in Cork, Ireland. Upon its dissolution, the institute had 17,000 students studying in art, business, engineering, music, drama and science disciplines. The institute had been named as Institute of Technology of the Year in The Sunday Times University Guide for Ireland on numerous occasions. On 1 January 2021, the institute merged with the Institute of Technology, Tralee to become the Munster Technological University, Ireland''s second technological university.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/4/4b/Citcrest.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Cork_Institute_of_Technology", "description": "Former higher educational institution in Ireland"}', NULL, NULL, 'IE', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.465646+01', '2026-08-07 12:47:33.465646+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
