INSERT INTO public.spaces VALUES ('fa24baaa-e3c0-4af8-b127-00d15d71b047', NULL, '00000000-0000-0000-0000-000000000064', 'Australian Defence Force Academy', 'australian-defence-force-academy', NULL, '{"title": "Australian Defence Force Academy", "extract": "The Australian Defence Force Academy (ADFA) is a tri-service military academy that provides military and academic education for junior officers of the Australian Defence Force in the Royal Australian Navy (RAN), Australian Army and Royal Australian Air Force (RAAF) as well as international trainee officers from a variety of countries. In 2016, the academy began accepting civilian students in its undergraduate courses.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/9/9f/Australian_Defence_Force_Academy_coat_of_arms.svg/330px-Australian_Defence_Force_Academy_coat_of_arms.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Australian_Defence_Force_Academy", "description": "Military academy in Canberra tertiary education provided by UNSW"}', NULL, NULL, 'AU', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.296289+01', '2026-08-07 12:47:33.296289+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('86c35efa-c9a5-4b7b-aabd-101be6f46661', NULL, '00000000-0000-0000-0000-000000000064', 'Bond University', 'bond-university', NULL, '{"title": "Bond University", "extract": "Bond University is Australia''s first private not-for-profit university and is located in Robina on the Gold Coast, Queensland. Since its opening on 15 May 1989, Bond University has primarily been a teaching-focused higher education institution featuring a trimester timetable.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/3/3a/Bond_University_Coat_of_Arms.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Bond_University", "description": "Private university in Queensland, Australia"}', NULL, NULL, 'AU', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.296289+01', '2026-08-07 12:47:33.296289+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
