INSERT INTO public.spaces VALUES ('bcdc139b-f981-4f36-b7f7-d6a98b723cfd', NULL, '00000000-0000-0000-0000-000000000064', 'Copenhagen Business School', 'copenhagen-business-school', NULL, '{"title": "Copenhagen Business School", "extract": "Copenhagen Business School, often abbreviated and referred to as CBS, is a public university situated in Copenhagen, Denmark. Founded in 1917, It is considered one of the most prestigious business schools in Western Europe and the world.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/19/Logo_CopenhagenBusinessSchool.svg/330px-Logo_CopenhagenBusinessSchool.svg.png", "content_url": "https://en.wikipedia.org/wiki/Copenhagen_Business_School", "description": "Business school"}', NULL, NULL, 'DK', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.353781+01', '2026-08-07 12:47:33.353781+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('e59c47cd-aee6-4db3-a4ad-dd3b35f4cf18', NULL, '00000000-0000-0000-0000-000000000064', 'Corning Community College', 'corning-community-college', NULL, '{"title": "Corning Community College", "extract": "Corning Community College is a public community college in Corning, New York. It was initiated in 1957 and moved to its Spencer Hill campus in 1963. This two-year college serves three counties: Steuben, Chemung, and Schuyler. It is one of the community colleges in the SUNY system.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/ea/Suny-corning-logo-header.png/330px-Suny-corning-logo-header.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Corning_Community_College", "description": "Community college in Corning, New York, U.S."}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.188857+01', '2026-08-07 12:47:33.188857+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
