INSERT INTO public.spaces VALUES ('ec277a1f-d862-4174-8c18-021bdebfbffe', NULL, '00000000-0000-0000-0000-000000000064', 'CUNY York College', 'cuny-york-college', NULL, '{"title": "York College, City University of New York", "extract": "York College is a public senior college in Jamaica, Queens, New York City, United States. It is a senior college in the City University of New York (CUNY) system. Founded in 1966, York was the first senior college founded under the newly formed CUNY system, which united several previously independent public colleges into a single public university system in 1961. The college is a member-school of Thurgood Marshall College Fund. The college enrolls more than 6,000 students as of fall 2022.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/66/Academic-Core-Building-Guy-Brewer-Blvd.jpg/330px-Academic-Core-Building-Guy-Brewer-Blvd.jpg", "content_url": "https://en.wikipedia.org/wiki/York_College%2C_City_University_of_New_York", "description": "Senior college in Jamaica, Queens, New York, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.726322+01', '2026-08-07 12:47:33.726322+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
