INSERT INTO public.spaces VALUES ('44dffaa7-8857-4cd6-89f1-4a6580d2e702', NULL, '00000000-0000-0000-0000-000000000064', 'CUNY Medgar Evers College', 'cuny-medgar-evers-college', NULL, '{"title": "Medgar Evers College", "extract": "Medgar Evers College is a public college in New York City, United States. It is a senior college of the City University of New York (CUNY), offering baccalaureate and associate degrees. It was established in 1970 in central Brooklyn. It is named after Medgar Evers, an African American civil rights leader assassinated on June 12, 1963.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/1/18/Medgar_Evers_College_Seal.png", "content_url": "https://en.wikipedia.org/wiki/Medgar_Evers_College", "description": "Public college in New York City"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-07 12:47:33.702225+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('ccd48d9c-9bc5-4445-9645-1ab632dcb5be', NULL, '00000000-0000-0000-0000-000000000064', 'Cypress College', 'cypress-college', NULL, '{"title": "Cypress College", "extract": "Cypress College is a public community college in Cypress, California. It is part of the California Community Colleges System and belongs to the North Orange County Community College District. It offers a variety of general education, transfer courses, and 145 vocational programs leading to associate degrees and certificates.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/4/47/CC_logo_tall_4c-general.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Cypress_College", "description": "Public community college in Cypress, California, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.679268+01', '2026-08-07 12:47:33.679268+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
