INSERT INTO public.spaces VALUES ('33ad8c32-1334-478d-8edc-3923d3598b3d', NULL, '00000000-0000-0000-0000-000000000064', 'Darul Ihsan University', 'darul-ihsan-university', NULL, '{"title": "Darul Ihsan University", "extract": "Darul Ihsan University or DIU was a private university in Dhaka, Bangladesh. It was founded by Syed Ali Ashraf in 1989. The government of Bangladesh accredited it as a private university in 1993. The Education Ministry shut down the university on 26 July 2016 for illegally operating numerous branch campuses and for selling higher degree certificates.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/e9/Entrance_to_DIU.JPG/330px-Entrance_to_DIU.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Darul_Ihsan_University", "description": "University in Dhaka, Bangladesh"}', NULL, NULL, 'BD', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.296289+01', '2026-08-07 12:47:33.296289+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
