INSERT INTO public.spaces VALUES ('83441459-3db9-4be5-816a-1ce2fbfe6189', NULL, '00000000-0000-0000-0000-000000000064', 'Darul Huda Islamic University', 'darul-huda-islamic-university', NULL, '{"title": "Darul Huda Islamic University", "extract": "Darul Huda Islamic University or Darul Huda Islamic Academy is an unaccredited Islamic seminary in Malappuram district, Kerala, India. Although it uses the title \"Islamic University\", it is not recognised as a university by the University Grants Commission (UGC). Its managing committee administers Mamburam Makham Shareef, a prominent pilgrimage centre in Kerala. According to reports, the Mampuram Maqam has been under the administration of the Darul Huda Islamic Academy managing committee since 1999. It functions as an independent Sunni Islamic seminary outside the Indian university accreditation system. Established in 1986 it is a Sunni institution for the training of Islamic scholars in India. It provides Islamic religious education and operates undergraduate and postgraduate religious study programmes.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/85/DHIU_Main_Block.jpg/330px-DHIU_Main_Block.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Darul_Huda_Islamic_University", "description": "Unaccredited Islamic seminary in Kerala, India"}', NULL, NULL, 'IN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.411195+01', '2026-08-07 12:47:33.411195+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
