INSERT INTO public.spaces VALUES ('63288852-ed2c-4e5f-aba4-f868bcbb2f4f', NULL, '00000000-0000-0000-0000-000000000064', 'Danville Area Community College', 'danville-area-community-college', NULL, '{"title": "Danville Area Community College", "extract": "Danville Area Community College (DACC) is a public community college in Danville, Illinois. It was founded in 1946 as an extension of the University of Illinois; it has grown into an independent college offering courses in 76 areas of study. These include college transfer, occupational degrees and certificates, re-training, skill development, customized training and areas of special interest. As of the Fall 2022 semester, there were 1924 students enrolled at the college.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/a/a1/Dacc-logo.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Danville_Area_Community_College", "description": "Community college in Danville, Illinois, U.S."}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-07 12:47:33.702225+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
