INSERT INTO public.spaces VALUES ('629f6f2b-dffa-49cb-970b-89bc39d52493', NULL, '00000000-0000-0000-0000-000000000064', 'Denison University', 'denison-university', NULL, '{"title": "Denison University", "extract": "Denison University is a private liberal arts college in Granville, Ohio, United States. One of the earliest colleges established in the former Northwest Territory, Denison University was founded in 1831. It was first called the Granville Literary and Theological Institution, later took the name Granville College, and, in the mid-1850s, was renamed Denison University, in honor of William S. Denison, a major early benefactor. The college enrolled 2,400 students in fall 2025. Students choose from 65 academic programs and 4 pre-professional programs.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/55/Denison_University_seal2.png/330px-Denison_University_seal2.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Denison_University", "description": "Private college in Granville, Ohio, United States"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.188857+01', '2026-08-07 12:47:33.188857+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
