INSERT INTO public.spaces VALUES ('f88f8668-e9da-48ef-ba85-779ef14d8394', NULL, '00000000-0000-0000-0000-000000000060', 'Azerbaijan', 'azerbaijan', 'Landlocked in Eastern Europe and West Asia but connected to the world — this is where the diaspora gathers, no matter how far they''ve traveled. It is set in Eastern Europe and West Asia, landlocked. Share local news, discover events, trade on the marketplace, and tap into remittance rates, scholarship finds, and community resources — all in one place.', '{"title": "Azerbaijan", "extract": "Azerbaijan, officially the Republic of Azerbaijan, is a transcontinental landlocked country at the boundary of Western Asia and Eastern Europe. It is a part of the South Caucasus region and is bounded by the Caspian Sea to the east, Russia''s republic of Dagestan to the north, Georgia to the northwest, Turkey and Armenia to the west, and Iran to the south. Baku is the capital and largest city.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/dd/Flag_of_Azerbaijan.svg/330px-Flag_of_Azerbaijan.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Azerbaijan", "description": "Country in Eastern Europe and West Asia"}', 'e46f0aa0-3172-480d-bfe4-5ae2d76fd79b', NULL, 'AZ', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:06.358493+01', NULL, NULL, '{azerbaijan,az,europe,landlocked,community,diaspora}', NULL, 'Asia', 'Western Asia', NULL);
