INSERT INTO public.spaces VALUES ('cc8d8abd-0025-464c-9b01-705ada6e1975', NULL, '00000000-0000-0000-0000-000000000064', 'Des Moines Area Community College', 'des-moines-area-community-college', NULL, '{"title": "Des Moines Area Community College", "extract": "Des Moines Area Community College (DMACC) is a public community college in central Iowa. The college served 34,206 credit students and 21,164 noncredit students in 2024.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/23/Des_Moines_Area_Community_College_%28DMACC%29_logo.jpg/330px-Des_Moines_Area_Community_College_%28DMACC%29_logo.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Des_Moines_Area_Community_College", "description": "Multi-campus college in central Iowa, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-07 12:47:33.702225+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
