INSERT INTO public.spaces VALUES ('2a132483-edcc-4d27-ab11-898a60bcf3ff', NULL, '00000000-0000-0000-0000-000000000064', 'DePauw University', 'depauw-university', NULL, '{"title": "DePauw University", "extract": "DePauw University is a private liberal arts college in Greencastle, Indiana, United States. It was founded in 1837 as Indiana Asbury College and changed its name to DePauw University in 1884. The college has a Methodist heritage and was founded to be an ecumenical institution of national stature, \"conducted on the most liberal principles, accessible to all religious denominations and designed for the benefit of our citizens in general\".", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/b/bb/DePauw_University_seal.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/DePauw_University", "description": "Private liberal arts college in Greencastle, Indiana, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.188857+01', '2026-08-07 12:47:33.188857+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('e60b7868-6b67-43fb-9f4f-36bf9fe3e338', NULL, '00000000-0000-0000-0000-000000000064', 'Deutsche Hochschule für Verwaltungswissenschaften Speyer', 'deutsche-hochschule-f-r-verwaltungswissenschaften-speyer', NULL, '{"title": "German University of Administrative Sciences Speyer", "extract": "The German University of Administrative Sciences Speyer, is a national graduate school for administrative sciences and public management located in Speyer, Rhineland-Palatinate, Germany. Founded in 1947 by the French occupational authorities as a grande école, today it is operated under the joint responsibility of both the Federal Republic (Bund) and all 16 German states (Länder). It runs four Master''s programs, grants doctoral degrees and habilitations, offers a postgraduate certificate program, and administers programs of executive education. The school is a major training ground for German and international senior government officials. Noted alumni and faculty include former President of Germany Roman Herzog, Professor Niklas Luhmann; former Minister of Defence Christine Lambrecht, current Justice at the Federal Constitutional Court of Germany Heinrich Amadeus Wolff, former President of the Bundesbank Helmut Schlesinger, former Prosecutor General of Germany Alexander von Stahl, and CEO of BASF Jürgen Strube.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/2/2e/German_University_of_Administrative_Sciences_logo.gif?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/German_University_of_Administrative_Sciences_Speyer", "description": "Public management school in Speyer, Germany"}', NULL, NULL, 'DE', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.384776+01', '2026-08-07 12:47:33.384776+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('cff6d39e-3bcc-4f3b-9211-ff1c03cc0bb1', NULL, '00000000-0000-0000-0000-000000000064', 'Deutsche Universität für Verwaltungswissenschaften Speyer', 'deutsche-universit-t-f-r-verwaltungswissenschaften-speyer', NULL, '{"title": "German University of Administrative Sciences Speyer", "extract": "The German University of Administrative Sciences Speyer, is a national graduate school for administrative sciences and public management located in Speyer, Rhineland-Palatinate, Germany. Founded in 1947 by the French occupational authorities as a grande école, today it is operated under the joint responsibility of both the Federal Republic (Bund) and all 16 German states (Länder). It runs four Master''s programs, grants doctoral degrees and habilitations, offers a postgraduate certificate program, and administers programs of executive education. The school is a major training ground for German and international senior government officials. Noted alumni and faculty include former President of Germany Roman Herzog, Professor Niklas Luhmann; former Minister of Defence Christine Lambrecht, current Justice at the Federal Constitutional Court of Germany Heinrich Amadeus Wolff, former President of the Bundesbank Helmut Schlesinger, former Prosecutor General of Germany Alexander von Stahl, and CEO of BASF Jürgen Strube.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/2/2e/German_University_of_Administrative_Sciences_logo.gif?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/German_University_of_Administrative_Sciences_Speyer", "description": "Public management school in Speyer, Germany"}', NULL, NULL, 'DE', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.726322+01', '2026-08-07 12:47:33.726322+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
