INSERT INTO public.spaces VALUES ('717b05b5-7983-4950-abf9-f0998056165c', NULL, '00000000-0000-0000-0000-000000000064', '4th Military Medical University', '4th-military-medical-university', NULL, '{"title": "Air Force Medical University", "extract": "The Air Force Medical University (中国人民解放军空军军医大学) is a public medical university in Xincheng, Xi''an, Shaanxi, China. It is affiliated with the People''s Liberation Army Air Force. The university is part of the Double First-Class Construction. The university was formerly known as the Fourth Military Medical University until 2017.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/c/c7/Fourth_Military_Medical_University_logo.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Air_Force_Medical_University", "description": "Public medical university in Xi''an, China"}', NULL, NULL, 'CN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.326239+01', '2026-08-07 12:47:33.326239+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('12ee628c-73db-4aab-88c6-9e0dbb646fa6', NULL, '00000000-0000-0000-0000-000000000064', 'Deutsche Sporthochschule Köln', 'deutsche-sporthochschule-k-ln', NULL, '{"title": "German Sport University Cologne", "extract": "The German Sport University Cologne is a public university located in Cologne, North Rhine-Westphalia, Germany. Founded in 1947, it is the only higher education institution in Germany focused exclusively on sport and exercise sciences. The university developed from the Deutsche Hochschule für Leibesübungen, which was originally established in Berlin in 1920. It was re-established in Cologne after World War II and gained university status in 1970.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/49/Luftaufnahme_der_Deutschen_Sporthochschule_K%C3%B6ln.jpg/330px-Luftaufnahme_der_Deutschen_Sporthochschule_K%C3%B6ln.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/German_Sport_University_Cologne", "description": "Sport university"}', NULL, NULL, 'DE', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.384776+01', '2026-08-07 12:47:33.384776+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
