INSERT INTO public.spaces VALUES ('27a1ed4c-3d58-4914-8cb1-9c8fa0329be8', NULL, '00000000-0000-0000-0000-000000000064', 'Dublin City University', 'dublin-city-university', NULL, '{"title": "Dublin City University", "extract": "Dublin City University is a university based on the Northside of Dublin, Ireland. Created as the National Institute for Higher Education, Dublin in 1975, it enrolled its first students in 1980, and was elevated to university status in September 1989 by statute.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/b/b2/Dublin_City_University_%28logo%29.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Dublin_City_University", "description": "University in Ireland, founded 1975"}', NULL, NULL, 'IE', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.465646+01', '2026-08-07 12:47:33.465646+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('67715be0-f528-4a19-92ba-2cd40ace7447', NULL, '00000000-0000-0000-0000-000000000064', 'Duale Hochschule Baden-Württemberg', 'duale-hochschule-baden-w-rttemberg', NULL, '{"title": "Baden-Württemberg Cooperative State University", "extract": "The Baden-Württemberg Cooperative State University is an institution of higher education with several campuses throughout the state of Baden-Württemberg, Germany. It offers dual-education bachelor''s-degree programs in cooperation with industry and non-profit institutions in the areas of business administration, engineering, and social services. In 2011, it started a limited master''s program.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/a/a9/DHBW_d_MOS_195x95_rgb_300.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Baden-W%C3%BCrttemberg_Cooperative_State_University", "description": "Higher education institution in Germany"}', NULL, NULL, 'DE', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.726322+01', '2026-08-07 12:47:33.726322+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('815ea3fa-2721-42b5-aa8d-218b67349d79', NULL, '00000000-0000-0000-0000-000000000064', 'Dublin Institute for Advanced Studies', 'dublin-institute-for-advanced-studies', NULL, '{"title": "Dublin Institute for Advanced Studies", "extract": "The Dublin Institute for Advanced Studies (DIAS) is a statutory independent research institute in Dublin, Ireland. It was established, under the Institute For Advanced Studies Act 1940, by the government of the then Taoiseach, Éamon de Valera.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/1e/DIAS_2018.jpg/330px-DIAS_2018.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Dublin_Institute_for_Advanced_Studies", "description": "Irish educational institution and academic publisher"}', NULL, NULL, 'IE', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.465646+01', '2026-08-07 12:47:33.465646+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('5c55c761-bf41-4b79-a0b2-30b04678b2ac', NULL, '00000000-0000-0000-0000-000000000064', 'Duale Hochschule Baden-Württemberg Lörrach', 'duale-hochschule-baden-w-rttemberg-l-rrach', NULL, '{"title": "Baden-Wuerttemberg Cooperative State University Loerrach", "extract": "The Baden-Wuerttemberg Cooperative State University Loerrach (DHBW-Loerrach) was founded in 1981 as Berufsakademie Lörrach. It offers workplace-focused, cooperative degree courses. This means that students alternate between learning the theory at school and applying it on the job in a three-months rhythm. Besides Loerrach, seven other schools of cooperative education and three branch campuses were founded in Baden-Wuerttemberg since the beginning of 1974.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/ac/Duale_Hochschule_BW_-_L%C3%B6rrach_-_Bibliothek.jpg/330px-Duale_Hochschule_BW_-_L%C3%B6rrach_-_Bibliothek.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Baden-Wuerttemberg_Cooperative_State_University_Loerrach", "description": "University in Germany"}', NULL, NULL, 'DE', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.726322+01', '2026-08-07 12:47:33.726322+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
