INSERT INTO public.spaces VALUES ('c6be21a4-94c3-4e71-a1e7-2d94a43c3e8d', NULL, '00000000-0000-0000-0000-000000000064', 'Elizabethtown Community and Technical College', 'elizabethtown-community-and-technical-college', NULL, '{"title": "Elizabethtown Community and Technical College", "extract": "Elizabethtown Community and Technical College (ECTC) is a public community college in Elizabethtown, Kentucky. It is part of the Kentucky Community and Technical College System (KCTCS).", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/80/Elizabethtowncommunitycollege.JPG/330px-Elizabethtowncommunitycollege.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Elizabethtown_Community_and_Technical_College", "description": "Public college in Elizabethtown, Kentucky, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-07 12:47:33.702225+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('b31226d6-2c82-4e63-8537-85f1524a2d52', NULL, '00000000-0000-0000-0000-000000000064', 'Elms College', 'elms-college', NULL, '{"title": "Elms College", "extract": "The College of Our Lady of the Elms, often called Elms College, is a private Catholic college in Chicopee, Massachusetts, United States.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/d/d0/Seal_of_Elms_College.svg/330px-Seal_of_Elms_College.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Elms_College", "description": "Catholic college in Chicopee, Massachusetts, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.753691+01', '2026-08-07 12:47:33.753691+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
