INSERT INTO public.spaces VALUES ('90e52e66-fe13-42e6-94a5-253735c63c6b', NULL, '00000000-0000-0000-0000-000000000064', 'European School of Economics', 'european-school-of-economics', NULL, '{"title": "European School of Economics", "extract": "The European School of Economics (ESE) is a private college of higher education. It is accredited by ASIC, validated by Richmond, The American International University in London, and is a registered UK learning provider. ESE offers UK bachelor''s degree, master''s degree, MBA, and specialised short programmes at its centres in London, Rome, Milan, Florence, Genoa and Madrid.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/b/b5/European_School_of_Economics_logo.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/European_School_of_Economics", "description": ""}', NULL, NULL, 'IT', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.465646+01', '2026-08-07 12:47:33.465646+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('380052b9-6e17-421a-829f-6cefeb313caa', NULL, '00000000-0000-0000-0000-000000000064', 'European University Institute', 'european-university-institute', NULL, '{"title": "European University Institute", "extract": "The European University Institute (EUI) is an international postgraduate, post-doctoral University, and intergovernmental organisation located in Fiesole, Italy. Founded in 1972, The EUI is mainly funded by 24 EU member states and the European Union (Erasmus+).", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/9b/New_Logo_EUI_2021_SVG.svg/330px-New_Logo_EUI_2021_SVG.svg.png", "content_url": "https://en.wikipedia.org/wiki/European_University_Institute", "description": "Teaching and research institute"}', NULL, NULL, 'IT', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.465646+01', '2026-08-07 12:47:33.465646+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('f0cf4b6c-ca14-43cd-b468-baca94d13070', '2e61ed5d-f1a0-4752-b994-731c0d4a34dd', '00000000-0000-0000-0000-000000000061', 'Tucumán', 'ar-tucumán', NULL, NULL, NULL, NULL, 'T', 'state', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-09 18:23:11.186227+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('42b9a7c7-d762-4d4f-a3ed-d4e5ff80a72d', NULL, '00000000-0000-0000-0000-000000000064', 'European University Cyprus', 'european-university-cyprus', NULL, '{"title": "European University Cyprus", "extract": "The European University Cyprus (EUC) is a private university in Nicosia, Cyprus and Frankfurt, Germany, which evolved out of Cyprus College, one of the oldest institutions of higher education in Cyprus. Admission to European University Cyprus is based on applicants'' academic records and performance. The institution has a current enrollment of over 12,250 students with international students representing about 70% of the student body. It provides internationally recognized undergraduate, graduate, and doctorate degrees. The programs of study are graded based on the European Credit Transfer and Accumulation System (ECTS). All bachelor''s, master''s and Ph.D. programs have been approved by The Cyprus Agency of Quality Assurance and Accreditation in Higher Education (CYQAA) and are recognized worldwide. European University Cyprus cooperates with several universities all over the world. It participates in Erasmus+ program and enables students, academics and staff to travel and study at several universities in Europe and beyond.", "content_url": "https://en.wikipedia.org/wiki/European_University_Cyprus", "description": "Private university in Nicosia, Cyprus"}', NULL, NULL, 'CY', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.353781+01', '2026-08-07 12:47:33.353781+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
