INSERT INTO public.spaces VALUES ('c796faa7-b18d-4ef7-a280-114c9173ad9b', NULL, '00000000-0000-0000-0000-000000000064', 'James Cook University of North Queensland', 'james-cook-university-of-north-queensland', NULL, '{"title": "James Cook University", "extract": "James Cook University (JCU) is a public university in North Queensland, Australia. The second oldest university in Queensland, JCU is a teaching and research institution. The university''s main campuses are located in the tropical cities of Cairns and Townsville, and one in the city state of Singapore. JCU also has study centres in Mount Isa, Mackay, Thursday Island and Rockhampton. A Brisbane campus delivers undergraduate and postgraduate courses to international students. The university''s main fields of research include environmental sciences, biological sciences, mathematical sciences, earth sciences, agricultural and veterinary sciences, technology and medical and health sciences.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/9/96/James_Cook_University_Armorial_Ensigns.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/James_Cook_University", "description": "Public university in North Queensland, Australia"}', '73abd391-c382-45ae-89a5-90616f4cfcc7', NULL, 'AU', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.296289+01', '2026-08-09 02:51:16.892363+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
