INSERT INTO public.spaces VALUES ('86d545e4-1eee-478f-9410-28c5a2b0c850', NULL, '00000000-0000-0000-0000-000000000064', 'Sewanee, University of the South', 'sewanee-university-of-the-south', NULL, '{"title": "Sewanee: The University of the South", "extract": "The University of the South, familiarly known as Sewanee, is a private Episcopal liberal arts college in Sewanee, Tennessee, United States. It is owned by 28 southern dioceses of the Episcopal Church, and its School of Theology is an official seminary of the church. The campus consists of 13,000 acres (53 km2) of scenic mountain property atop the Cumberland Plateau, with the developed portion occupying about 1,000 acres (4.0 km2).", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/d/db/Seal_of_The_University_of_the_South.svg/330px-Seal_of_The_University_of_the_South.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Sewanee%3A_The_University_of_the_South", "description": "Private university in Sewanee, Tennessee, US"}', 'ca4d41c6-3491-4a92-924c-678165093ed3', NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.233464+01', '2026-08-09 06:28:18.010281+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
