INSERT INTO public.spaces VALUES ('9a190960-f650-4547-95aa-b49b77da99f3', NULL, '00000000-0000-0000-0000-000000000064', 'Ryazan State Pedagogical University', 'ryazan-state-pedagogical-university', NULL, '{"title": "Ryazan State University", "extract": "The Ryazan State University named for S. A. Yesenin is a university in Ryazan, Ryazan Oblast, Russia. It was founded in 1915. It bears the name of Russian poet Sergei Yesenin, who grew up in the region.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/dc/%D0%9E%D0%B1%D1%89%D0%B8%D0%B9_%D0%B2%D0%B8%D0%B4_%D0%BD%D0%B0_%D0%B3%D0%BB%D0%B0%D0%B2%D0%BD%D1%8B%D0%B9_%D0%BA%D0%BE%D1%80%D0%BF%D1%83%D1%81_%D0%A0%D0%93%D0%A3_%D0%B8%D0%BC%D0%B5%D0%BD%D0%B8_%D0%A1._%D0%90._%D0%95%D1%81%D0%B5%D0%BD%D0%B8%D0%BD%D0%B0.jpg/330px-%D0%9E%D0%B1%D1%89%D0%B8%D0%B9_%D0%B2%D0%B8%D0%B4_%D0%BD%D0%B0_%D0%B3%D0%BB%D0%B0%D0%B2%D0%BD%D1%8B%D0%B9_%D0%BA%D0%BE%D1%80%D0%BF%D1%83%D1%81_%D0%A0%D0%93%D0%A3_%D0%B8%D0%BC%D0%B5%D0%BD%D0%B8_%D0%A1._%D0%90._%D0%95%D1%81%D0%B5%D0%BD%D0%B8%D0%BD%D0%B0.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Ryazan_State_University", "description": "Building"}', 'd325e464-d731-4161-986b-32f18fd43058', NULL, 'RU', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.60068+01', '2026-08-09 13:08:18.496292+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
