INSERT INTO public.spaces VALUES ('a42d6563-5d6a-45e8-a7e4-71d1803c7261', NULL, '00000000-0000-0000-0000-000000000064', 'Erzurum Technical University', 'erzurum-technical-university', NULL, '{"title": "Erzurum Technical University", "extract": "Erzurum Technical University, is a public university in Erzurum, Turkey. It was established by law no. 6005 adopted by the Grand National Assembly of Turkey on 21 July 2010, along with 6 other public universities. The founding rector was Prof. Dr. Muammer Yaylalı. The university started its academic activities in 2012.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/39/Erzurum_Technical_University_logo.svg/330px-Erzurum_Technical_University_logo.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Erzurum_Technical_University", "description": "State university in Erzurum, Turkey"}', NULL, NULL, 'TR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.679268+01', '2026-08-07 12:47:33.679268+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('54f29145-c572-4dd9-808e-6007db5ad76b', NULL, '00000000-0000-0000-0000-000000000064', 'Escuela Bancaria y Comercial', 'escuela-bancaria-y-comercial', NULL, '{"title": "Escuela Bancaria y Comercial", "extract": "Escuela Bancaria y Comercial (EBC) is a higher education institution which markets itself as The Business School of Mexico. Since its establishment in 1929 by National Action Party founder Manuel Gómez Morín, the school has spread from its Mexico City base to further campuses across Mexico.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/88/Rectoria-ebc.jpg/330px-Rectoria-ebc.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Escuela_Bancaria_y_Comercial", "description": ""}', NULL, NULL, 'MX', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.543021+01', '2026-08-07 12:47:33.543021+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('c01c4ac2-9780-408f-8c93-4fd94d0755d1', NULL, '00000000-0000-0000-0000-000000000064', 'Escuela Colombiana de Ingeniería Julio Garavito', 'escuela-colombiana-de-ingenier-a-julio-garavito', NULL, '{"title": "Escuela Colombiana de Ingeniería", "extract": "The Escuela Colombiana de Ingeniería Julio Garavito is a private engineering-based university. The school is located on a 70-acre (280,000 m2) campus in a beautiful natural environment in the north part of Bogotá and has approximately 4,600 students in undergraduate and graduate programs. It includes laboratories, computer systems, one of the largest collections of engineering texts and journals in Colombia as well as international and national access to information via the internet.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/c/cb/Escuela_colombiana_de_ingenieria_logo2.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Escuela_Colombiana_de_Ingenier%C3%ADa", "description": ""}', NULL, NULL, 'CO', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.353781+01', '2026-08-07 12:47:33.353781+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('9f3d488f-397d-4100-ab05-50e904a7eacf', NULL, '00000000-0000-0000-0000-000000000064', 'Fachhochschule Gelsenkirchen', 'fachhochschule-gelsenkirchen', NULL, '{"title": "Fachhochschule", "extract": "A Fachhochschule, abbreviated FH, is a university of applied sciences (UAS), in other words a German tertiary education institution that provides professional education in many applied sciences and applied arts, such as engineering, technology, business, architecture, design, and industrial design.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/49/Fachhochschule_K%C3%B6ln_-_Campus_S%C3%BCdstadt%2C_GWZ-2984.jpg/330px-Fachhochschule_K%C3%B6ln_-_Campus_S%C3%BCdstadt%2C_GWZ-2984.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Fachhochschule", "description": "Type of vocational educational institution in German-speaking countries"}', NULL, NULL, 'DE', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.411195+01', '2026-08-07 12:47:33.411195+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('59e92773-31aa-4fb3-82ca-9af0ec6185af', NULL, '00000000-0000-0000-0000-000000000064', 'Fachhochschule Gießen-Friedberg', 'fachhochschule-gie-en-friedberg', NULL, '{"title": "University of Applied Sciences Mittelhessen", "extract": "The Technische Hochschule Mittelhessen University of Applied Sciences is a German University of Applied Sciences (UAS) for bachelor''s and master''s studies with campuses in the Central Hessian cities of Giessen, Friedberg, and Wetzlar, as well as satellite locations in Bad Hersfeld, Bad Wildungen, Bad Vilbel, Biedenkopf, Limburg an der Lahn, and Frankenberg (Eder). It fulfils an important regional function with its location between the Frankfurt Rhine-Main region, and northern Hesse.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d0/THM_Technische_Hochschule_Mittelhessen_University_of_Applied_Sciences_english_logo.svg/330px-THM_Technische_Hochschule_Mittelhessen_University_of_Applied_Sciences_english_logo.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/University_of_Applied_Sciences_Mittelhessen", "description": "German university of applied sciences"}', NULL, NULL, 'DE', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.411195+01', '2026-08-07 12:47:33.411195+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('737e4b09-d644-446d-b8c1-4e877dfeeb33', NULL, '00000000-0000-0000-0000-000000000064', 'Fachhochschule Koblenz', 'fachhochschule-koblenz', NULL, '{"title": "Koblenz University of Applied Sciences", "extract": "Koblenz University of Applied Sciences is a public university in Rhineland-Palatinate. Although the present university was established in 1996, it has a rich tradition in higher education. The roots of today''s Faculty of Materials Engineering, Glass and Ceramics in Hoehr‑Grenzhausen, come down to the 19th century.", "content_url": "https://en.wikipedia.org/wiki/Koblenz_University_of_Applied_Sciences", "description": "Public university in Rhineland-Palatinate, Germany"}', NULL, NULL, 'DE', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.411195+01', '2026-08-07 12:47:33.411195+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
