INSERT INTO public.spaces VALUES ('18db8207-adc7-4d78-a4bf-e95ea13d57c2', NULL, '00000000-0000-0000-0000-000000000064', 'Fachhochschule Kiel', 'fachhochschule-kiel', NULL, '{"title": "Kiel University of Applied Sciences", "extract": "The Kiel University of Applied Sciences is a University of Applied Sciences, established in 1969. It is one of three public institutions of higher learning in Kiel, Germany. \nIt provides around 30 Bachelor''s and Master''s degrees, supplementary degrees and continuing education courses by the faculties of Agriculture, Business Management, Computer Science & Electrical Engineering, Mechanical Engineering, Media and Social Work and Health.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/bd/FH_Kiel_Campus_Kiel_Dietrichsdorf_Schwentine_02.jpg/330px-FH_Kiel_Campus_Kiel_Dietrichsdorf_Schwentine_02.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Kiel_University_of_Applied_Sciences", "description": "University in Kiel, Germany"}', NULL, NULL, 'DE', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.411195+01', '2026-08-07 12:47:33.411195+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('ae1399f2-3ed0-4762-877d-b120e0f2f27e', NULL, '00000000-0000-0000-0000-000000000064', 'Far Western University', 'far-western-university', NULL, '{"name": "Far Western University", "country": "Nepal", "founded": "2010-08-01T00:00:00Z", "website": "http://fwu.edu.np/", "description": "Public University in Sudurpashchim province of Nepal", "wikidata_id": "http://www.wikidata.org/entity/Q16975691", "wikipedia_url": "https://en.wikipedia.org/wiki/Q16975691"}', NULL, NULL, 'NP', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.753691+01', '2026-08-07 12:47:33.753691+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
