INSERT INTO public.spaces VALUES ('ef9a6d45-dff0-44e9-bd3d-b8988d4eafde', NULL, '00000000-0000-0000-0000-000000000064', 'Faculté Universitaire des Sciences Agronomiques de Gembloux', 'facult-universitaire-des-sciences-agronomiques-de-gembloux', NULL, '{"title": "Gembloux Agro-Bio Tech", "extract": "Gembloux Agro-Bio Tech (GxABT), located in Gembloux, Belgium, is one of the eleven faculties of the University of Liège. Founded in 1860 and previously known as the Faculté universitaire des sciences agronomiques de Gembloux, it is Belgium''s oldest educational and research institution dedicated to agronomic sciences and biological engineering. It is the only school in Belgium to be accredited by the French Commission des Titres d''Ingénieur allowing the university to deliver the Diplôme d''Ingénieur engineering degree. The school is also accredited by the EUR-ACE label, the highest European quality label for engineering degree programmes at Bachelor and Master level.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/e9/Gembloux_JPG002.jpg/330px-Gembloux_JPG002.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Gembloux_Agro-Bio_Tech", "description": "Faculty of the University of Liège, Belgium"}', NULL, NULL, 'BE', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.296289+01', '2026-08-07 12:47:33.296289+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('1f9425bb-824e-409c-8d89-4457b1163531', NULL, '00000000-0000-0000-0000-000000000064', 'Fairfield University', 'fairfield-university', NULL, '{"title": "Fairfield University", "extract": "Fairfield University is a private Catholic university in Fairfield, Connecticut, United States. It was founded by the Jesuits in 1942. In the fall of 2024, the university had about 5,400 full-time undergraduate students and 1,500 graduate students, including full-time and part-time students. It offers bachelor''s degrees, master''s degrees, and doctoral degrees through its five schools and colleges and, since 2023, associate degrees.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/e/e0/Fairfield_University_seal.svg/330px-Fairfield_University_seal.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Fairfield_University", "description": "Jesuit university in Connecticut, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.753691+01', '2026-08-07 12:47:33.753691+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
