INSERT INTO public.spaces VALUES ('3fb43da0-f612-43db-81fb-a4cc9e0ae0fe', NULL, '00000000-0000-0000-0000-000000000064', 'FON University', 'fon-university', NULL, '{"title": "FON University", "extract": "The American University of Europe-FON, or AUE-FON University is a private university with headquarters in Skopje, North Macedonia. Established in 2003, it is one of the first private universities in North Macedonia. The University received accreditation after the 2002 changes to the Higher Education Law, which liberalized the establishment of higher education institutions.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/aa/FON_University.jpg/330px-FON_University.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/FON_University", "description": "University in Skopje, North Macedonia"}', NULL, NULL, 'MK', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.5184+01', '2026-08-07 12:47:33.5184+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('f98e6f12-f5f3-4240-a40c-fada496e400d', NULL, '00000000-0000-0000-0000-000000000064', 'Fordham University', 'fordham-university', NULL, '{"title": "Fordham University", "extract": "Fordham University is a private Jesuit research university in New York City, United States. Established in 1841, it is named after the Fordham neighborhood of the Bronx in which its original campus is located. Fordham is the oldest Catholic and Jesuit university in the northeastern United States and the third-oldest university in New York City.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/3/3e/Fordham_University_seal.svg/330px-Fordham_University_seal.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Fordham_University", "description": "Jesuit university in New York City, New York, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.188857+01', '2026-08-07 12:47:33.188857+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
