INSERT INTO public.spaces VALUES ('42f93f79-46c8-4c9d-a467-adda3e202bde', NULL, '00000000-0000-0000-0000-000000000064', 'Fort Peck Community College', 'fort-peck-community-college', NULL, '{"title": "Fort Peck Community College", "extract": "Fort Peck Community College (FPCC) is a public tribal land-grant community college in Poplar, Montana. The college is located on the Fort Peck Assiniboine & Sioux Reservation in the northeast corner of Montana, which encompasses over two million acres. The college also has a satellite campus in Wolf Point.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/7/7b/Fort_Peck_Community_College.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Fort_Peck_Community_College", "description": "Tribal land-grant community college in Poplar, Montana, U.S."}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-07 12:47:33.702225+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
