INSERT INTO public.spaces VALUES ('26ee7af9-d516-4b2b-9bea-fffab2bd6b2b', NULL, '00000000-0000-0000-0000-000000000064', 'Fukuoka Institute of Technology', 'fukuoka-institute-of-technology', NULL, '{"title": "Fukuoka Institute of Technology", "extract": "Fukuoka Institute of Technology  is a private university in Higashi-ku of Fukuoka, Fukuoka Prefecture, Japan. The predecessor of the school was founded in 1954, and it was chartered as a university in 1963. It is located near Fukkōdaimae Station.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/6/6c/Fukkoudai.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Fukuoka_Institute_of_Technology", "description": "Private university in Fukuoka, Fukuoka, Japan"}', NULL, NULL, 'JP', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.465646+01', '2026-08-07 12:47:33.465646+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('419f62bd-8a02-4cf1-8622-2533daa394d4', NULL, '00000000-0000-0000-0000-000000000064', 'Fukushima University', 'fukushima-university', NULL, '{"title": "Fukushima University", "extract": "Fukushima University , abbreviated to Fukudai (福大), is a national university in Japan. The main campus is located in Kanayagawa, Fukushima City, Fukushima Prefecture.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d0/Fukushima-Univ-LectureHalls-2012050401.jpg/330px-Fukushima-Univ-LectureHalls-2012050401.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Fukushima_University", "description": "National university in Japan"}', NULL, NULL, 'JP', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.465646+01', '2026-08-07 12:47:33.465646+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('e4fcbee8-ba13-4360-a8dc-3b06ff75683f', NULL, '00000000-0000-0000-0000-000000000064', 'Fukuyama University', 'fukuyama-university', NULL, '{"title": "Fukuyama University", "extract": "Fukuyama University  is a private university in Fukuyama, Hiroshima, Japan, established in 1975; in 2024, the university had over 3300 students and offered undergraduate and postgraduate courses in Economics, Sociology, Engineering and /Life Sciences/ Biotechnology.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/a5/Fukuyama_univ01.JPG/330px-Fukuyama_univ01.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Fukuyama_University", "description": "University in Hiroshima, Japan"}', NULL, NULL, 'JP', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.465646+01', '2026-08-07 12:47:33.465646+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('97fa37b6-b833-4a3c-9201-84eaa4dfd93c', NULL, '00000000-0000-0000-0000-000000000064', 'Fukuoka Prefectural University', 'fukuoka-prefectural-university', NULL, '{"title": "Fukuoka Prefectural University", "extract": "Fukuoka Prefectural University  is a public university in Tagawa, Fukuoka, Japan, established in 1992.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/63/Fukuoka_Prefectural_University01.jpg/330px-Fukuoka_Prefectural_University01.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Fukuoka_Prefectural_University", "description": "Higher education institution in Fukuoka Prefecture, Japan"}', NULL, NULL, 'JP', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.465646+01', '2026-08-07 12:47:33.465646+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
