INSERT INTO public.spaces VALUES ('b7d4f39b-8074-4334-ad77-a8245e751cc6', NULL, '00000000-0000-0000-0000-000000000064', 'Full Sail University', 'full-sail-university', NULL, '{"title": "Full Sail University", "extract": "Full Sail University is a private for-profit university in Winter Park, Florida. It was formerly a recording studio in Dayton, Ohio named Full Sail Productions and Full Sail Center for the Recording Arts. The school moved to Florida in 1980, began offering bachelor''s degrees in 2005, and began offering online degrees in 2007. The following year, the school was granted university status by the Florida Department of Education.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/45/Full_sail_university_sign.JPG/330px-Full_sail_university_sign.JPG", "content_url": "https://en.wikipedia.org/wiki/Full_Sail_University", "description": "Private, for-profit university in Winter Park, Florida"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.188857+01', '2026-08-07 12:47:33.188857+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('ab1dbb52-397c-4f57-a317-5a0992a4e57d', NULL, '00000000-0000-0000-0000-000000000064', 'Fulton-Montgomery Community College', 'fulton-montgomery-community-college', NULL, '{"title": "Fulton–Montgomery Community College", "extract": "Fulton–Montgomery Community College (FMCC) is a public community college in Johnstown, New York. It is part of the State University of New York and serves Fulton and Montgomery counties. The college offers 45 degree and certificate programs, 30 campus clubs, and is a member of the NJCAA, offering Division III sports in basketball, soccer, baseball, softball and volleyball. In 2012, new dorms were added to the campus to serve local and out-of-town students.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/2/26/Fulton%E2%80%93Montgomery_Community_College_%28logo%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Fulton%E2%80%93Montgomery_Community_College", "description": "Community college in Johnstown, New York, U.S."}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-07 12:47:33.702225+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
