INSERT INTO public.spaces VALUES ('3bcfac63-fbe6-4d1d-9d73-61fddfa8c80b', NULL, '00000000-0000-0000-0000-000000000064', 'Georg-August Universität Göttingen', 'georg-august-universit-t-g-ttingen', NULL, '{"title": "University of Göttingen", "extract": "The University of Göttingen, officially the Georg August University of Göttingen, is a public research university in the city of Göttingen, Lower Saxony, Germany. Founded in 1734 by George II, King of Great Britain and Elector of Hanover, it began instruction in 1737 and is recognized as the oldest university in Lower Saxony. Recognized for its historic and traditional significance, the university has affiliations with 47 Nobel Prize winners by its own count.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/61/Uni_G%C3%B6ttingen_Siegel.svg/330px-Uni_G%C3%B6ttingen_Siegel.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/University_of_G%C3%B6ttingen", "description": "Public university in Göttingen, Germany"}', NULL, NULL, 'DE', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.411195+01', '2026-08-07 12:47:33.411195+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
