INSERT INTO public.spaces VALUES ('d35286ed-9829-4f30-a324-df67356ac517', NULL, '00000000-0000-0000-0000-000000000064', 'George Brown College', 'george-brown-college', NULL, '{"title": "George Brown Polytechnic", "extract": "The George Brown College of Applied Arts and Technology, branded as George Brown Polytechnic since 2025, is a publicly funded college of applied arts and technology with three campuses in downtown Toronto, Ontario, Canada. Like many other colleges in Ontario, George Brown College was chartered in 1966 by the government of Ontario and opened the following year.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/e2/George_Brown_Polytechnic_logo.svg/330px-George_Brown_Polytechnic_logo.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/George_Brown_Polytechnic", "description": "College in Toronto, Ontario, Canada"}', NULL, NULL, 'CA', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.326239+01', '2026-08-07 12:47:33.326239+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('1fc60f82-7674-47cd-b750-0bad3762b1a8', NULL, '00000000-0000-0000-0000-000000000064', 'Geneva College', 'geneva-college', NULL, '{"title": "Geneva College", "extract": "Geneva College is a private Christian college in Beaver Falls, Pennsylvania, United States. Founded in 1848 in Northwood, Ohio, the college moved to its present location in 1880. It enrolls about 1,400 undergraduates in over 30 majors, as well as graduate students in a handful of master''s programs. The undergraduate curriculum emphasizes the humanities and the formation of a Reformed Christian worldview. It is the only undergraduate institution affiliated with the Reformed Presbyterian Church of North America.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/b/b6/Geneva_college_seal.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Geneva_College", "description": "Christian college in Beaver Falls, Pennsylvania, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.188857+01', '2026-08-07 12:47:33.188857+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
