INSERT INTO public.spaces VALUES ('9cd842d4-5cd1-42b1-a76b-7cdc20af6127', NULL, '00000000-0000-0000-0000-000000000064', 'Georgetown University', 'georgetown-university', NULL, '{"title": "Georgetown University", "extract": "Georgetown University is a private Jesuit research university in Washington, D.C., United States. Founded by Bishop John Carroll in 1789, it is the oldest Catholic institution of higher education in the United States, the oldest university in Washington, D.C., and the nation''s first federally chartered university.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d9/Georgetown_University_seal.svg/330px-Georgetown_University_seal.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Georgetown_University", "description": "Private Jesuit university in Washington, D.C."}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.188857+01', '2026-08-07 12:47:33.188857+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
