INSERT INTO public.spaces VALUES ('24726014-6b29-4559-b232-c0bc7c191661', NULL, '00000000-0000-0000-0000-000000000064', 'Glasgow Caledonian University', 'glasgow-caledonian-university', NULL, '{"title": "Glasgow Caledonian University", "extract": "Glasgow Caledonian University, is a public university in Glasgow, Scotland. It was formed in 1993 by the merger of The Queen''s College, Glasgow and Glasgow Polytechnic.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/f4/Glasgow_Caledonian_University_arms.svg/330px-Glasgow_Caledonian_University_arms.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Glasgow_Caledonian_University", "description": "Public university in Glasgow, Scotland"}', NULL, NULL, 'GB', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.65283+01', '2026-08-07 12:47:33.65283+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
