INSERT INTO public.spaces VALUES ('4b54f1f1-d35a-4c64-a9b2-cc1c914ec9b8', NULL, '00000000-0000-0000-0000-000000000064', 'Global Business School Barcelona', 'global-business-school-barcelona', NULL, '{"title": "GBSB Global Business School", "extract": "GBSB Global Business School is a private institution of higher education with campuses in Barcelona and Madrid (Spain), Birkirkara (Malta), and a virtual, online campus. This business school holds international accreditations.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/c/c6/GBSB_Global_Business_School_Logo.png/330px-GBSB_Global_Business_School_Logo.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/GBSB_Global_Business_School", "description": "Business school in Spain"}', NULL, NULL, 'ES', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.625787+01', '2026-08-07 12:47:33.625787+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
