INSERT INTO public.spaces VALUES ('eb6256e5-0928-4f34-8a33-c9341ef5e9ae', NULL, '00000000-0000-0000-0000-000000000064', 'Gloucester County College', 'gloucester-county-college', NULL, '{"title": "Rowan College of South Jersey", "extract": "Rowan College of South Jersey (RCSJ) is a public community college with two campuses in the South Jersey region of New Jersey. The first, Gloucester Main Campus, is in Sewell. The second, Cumberland Branch Campus, is in both Vineland and Millville. The college was established in 1966 as \"Gloucester County College\" (GCC). In 2014, the college changed its name to \"Rowan College of Gloucester County\" when Rowan University and Gloucester County College entered into a partnership. The college then expanded in 2019, combining Rowan College at Gloucester County (RCGC) and Cumberland County College to become Rowan College of South Jersey.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/72/College_Center.jpg/330px-College_Center.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Rowan_College_of_South_Jersey", "description": "Public college in Sewell, New Jersey, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-07 12:47:33.702225+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('3d5901d5-110b-40b3-9b1e-45f180c4a468', NULL, '00000000-0000-0000-0000-000000000064', 'Gokhale Institute of Politics and Economics', 'gokhale-institute-of-politics-and-economics', NULL, '{"title": "Gokhale Institute of Politics and Economics", "extract": "Gokhale Institute of Politics and Economics (GIPE), commonly known as Gokhale Institute, is an Indian economics research and training institute located in Pune. It is one of the oldest institutions of its kind in India.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/40/Full_view_of_Gokhale_Institute_of_Politics_and_Economics_main_building.jpg/330px-Full_view_of_Gokhale_Institute_of_Politics_and_Economics_main_building.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Gokhale_Institute_of_Politics_and_Economics", "description": "Economic research institute in Pune, India"}', NULL, NULL, 'IN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.411195+01', '2026-08-07 12:47:33.411195+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
