INSERT INTO public.spaces VALUES ('5bc94547-481d-417a-9e71-dfa999f138f3', NULL, '00000000-0000-0000-0000-000000000064', 'Great Falls College Montana State University', 'great-falls-college-montana-state-university', NULL, '{"title": "Great Falls College Montana State University", "extract": "Great Falls College–Montana State University is a public community college in Great Falls, Montana. It is affiliated with the Montana State University System and offers Associate of Applied Science (AAS), Associate of Science (AS), and Associate of Arts (AA) degrees as well as several Information Technology Certifications.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/3/39/MSU_Great_Falls_COT_logo.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Great_Falls_College_Montana_State_University", "description": "Community college in Great Falls, Montana, U.S."}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-07 12:47:33.702225+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
