INSERT INTO public.spaces VALUES ('17c00cb6-1bf0-4a17-8999-c0acaeeea924', NULL, '00000000-0000-0000-0000-000000000064', 'Graduate University for Advanced Studies', 'graduate-university-for-advanced-studies', NULL, '{"title": "The Graduate University for Advanced Studies", "extract": "The Graduate University for Advanced Studies, SOKENDAI  is one of the national universities of Japan, headquartered in Shonan Village in the town of Hayama in Kanagawa Prefecture. Sōkendai (総研大), as it is generally called in its abbreviated form, was established in 1988, with Dr. Saburo Nagakura as its president. SOKENDAI is the first national university in Japan having offered exclusively graduate programs. Graduate students are trained at affiliated research institutes distributed around Japan and the world. It has both five-year doctoral programs for students with a bachelor''s degree and three-year programs for those with a master''s degree.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/a6/Sokendai_hayama.jpg/330px-Sokendai_hayama.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/The_Graduate_University_for_Advanced_Studies", "description": "Higher education institution in Kanagawa Prefecture, Japan"}', NULL, NULL, 'JP', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.493186+01', '2026-08-07 12:47:33.493186+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('965ecf21-35f3-4f1f-8f71-d6443fc909f1', NULL, '00000000-0000-0000-0000-000000000064', 'Grays Harbor College', 'grays-harbor-college', NULL, '{"title": "Grays Harbor College", "extract": "Grays Harbor College is a public community college in Aberdeen, Washington, United States. Established in 1930, the college sits on a 120-acre (0.49 km2) campus overlooking the town of Aberdeen and its seaport on the edge of the Pacific Ocean. Additional \"learning centers\" are located in Raymond, Ilwaco, North Aberdeen, and Southside Aberdeen.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/f/fb/GHC_Seal2.gif?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Grays_Harbor_College", "description": "Community college in Aberdeen, Washington, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.726322+01', '2026-08-07 12:47:33.726322+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('a41c537f-c256-4708-831b-13b7ccf11617', NULL, '00000000-0000-0000-0000-000000000064', 'Grand View University', 'grand-view-university', NULL, '{"title": "Grand View University", "extract": "Grand View University is a private liberal arts university in Des Moines, Iowa. Founded in 1896 and affiliated with the Evangelical Lutheran Church in America, the university enrolls approximately 2,000 students and is accredited by the Higher Learning Commission.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/ab/The_Humphrey_Center_at_Grand_View.jpg/330px-The_Humphrey_Center_at_Grand_View.jpg", "content_url": "https://en.wikipedia.org/wiki/Grand_View_University", "description": "Private liberal arts university in Des Moines, Iowa, U.S."}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.753691+01', '2026-08-07 12:47:33.753691+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
