INSERT INTO public.spaces VALUES ('33241ff5-35a9-4202-a137-cb81cf004dda', NULL, '00000000-0000-0000-0000-000000000064', 'Guangzhou University of Traditional Chinese Medicine', 'guangzhou-university-of-traditional-chinese-medicine', NULL, '{"title": "Guangzhou University of Chinese Medicine", "extract": "The Guangzhou University of Chinese Medicine is a provincial public university in Guangzhou, Guangdong, China. It is affiliated with the Province of Guangdong. The university is part of the Double First-Class Construction.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/5d/Gzucm3.JPG/330px-Gzucm3.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Guangzhou_University_of_Chinese_Medicine", "description": "Provincial public university in Guangzhou, Guangdong, China"}', NULL, NULL, 'CN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.326239+01', '2026-08-07 12:47:33.326239+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('794ed571-5fce-419f-ae9b-a30e1e2ccd72', NULL, '00000000-0000-0000-0000-000000000064', 'Guilford College', 'guilford-college', NULL, '{"title": "Guilford College", "extract": "Guilford College is a private liberal arts college in Greensboro, North Carolina. It was founded in 1837 by members of the Religious Society of Friends (Quakers). Guilford has both traditional students and students who attend its Center for Continuing Education (CCE).", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/f/fa/Guilford_College_emblem_%28full%29.svg/330px-Guilford_College_emblem_%28full%29.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Guilford_College", "description": "College in Greensboro, North Carolina, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.188857+01', '2026-08-07 12:47:33.188857+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
