INSERT INTO public.spaces VALUES ('95266ca6-5433-4ce2-b6d5-ac3971cd1a44', NULL, '00000000-0000-0000-0000-000000000064', 'Gubkin Russian State University of Oil and Gas', 'gubkin-russian-state-university-of-oil-and-gas', NULL, '{"title": "Gubkin Russian State University of Oil and Gas", "extract": "The Gubkin Russian State University of Oil and Gas is a public university in Moscow, Russia. The university was founded in 1930 and is named after the geologist Ivan Gubkin. The university is colloquially known as Kerosinka, meaning ''kerosene stove''.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/f8/%D0%A3%D0%BD%D0%B8%D0%B2%D0%B5%D1%80%D1%81%D0%B8%D1%82%D0%B5%D1%82_%D0%BD%D0%B5%D1%84%D1%82%D0%B8_%D0%B8_%D0%B3%D0%B0%D0%B7%D0%B0_%D0%B8%D0%BC.%D0%93%D1%83%D0%B1%D0%BA%D0%B8%D0%BD%D0%B0_-_panoramio.jpg/330px-%D0%A3%D0%BD%D0%B8%D0%B2%D0%B5%D1%80%D1%81%D0%B8%D1%82%D0%B5%D1%82_%D0%BD%D0%B5%D1%84%D1%82%D0%B8_%D0%B8_%D0%B3%D0%B0%D0%B7%D0%B0_%D0%B8%D0%BC.%D0%93%D1%83%D0%B1%D0%BA%D0%B8%D0%BD%D0%B0_-_panoramio.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Gubkin_Russian_State_University_of_Oil_and_Gas", "description": "Public university in Moscow, Russia"}', NULL, NULL, 'RU', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.60068+01', '2026-08-07 12:47:33.60068+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('f8f24328-d2f7-4994-85bf-9f39d06d603b', NULL, '00000000-0000-0000-0000-000000000064', 'Guilford Technical Community College', 'guilford-technical-community-college', NULL, '{"title": "Guilford Technical Community College", "extract": "Guilford Technical Community College is a public community college in the Piedmont Triad of North Carolina. It is the fourth largest institution in the North Carolina Community College System and the largest in the Piedmont Triad. Guilford Technical Community College also has campuses in Jamestown, High Point, Greensboro, and Colfax.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/d/d3/Guilford_Technical_Community_College_Logo.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Guilford_Technical_Community_College", "description": "College in the Piedmont Triad, North Carolina, U.S."}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-07 12:47:33.702225+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
