INSERT INTO public.spaces VALUES ('a60b45ac-77ea-4029-b6bb-f19a19bd625b', NULL, '00000000-0000-0000-0000-000000000064', 'Oregon Graduate Institute of Science and Technology', 'oregon-graduate-institute-of-science-and-technology', NULL, '{"title": "OGI School of Science and Engineering", "extract": "The OGI School of Science and Engineering, located in Hillsboro, Oregon, United States was one of four schools at the Oregon Health and Science University (OHSU). Until June 2001, it functioned independently as a private graduate school, the Oregon Graduate Institute of Science & Technology (OGI). OGI operated four departments and had approximately 330 students. In 2008, the school''s name was changed to the Department of Science and Engineering and by 2010, the department was dissolved and the academic programs and research were disseminated to other OHSU institutes and departments.", "content_url": "https://en.wikipedia.org/wiki/OGI_School_of_Science_and_Engineering", "description": ""}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.233464+01', '2026-08-07 12:47:33.233464+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
