INSERT INTO public.spaces VALUES ('f96b62b1-47e2-4f64-9397-1f882f3de7a9', NULL, '00000000-0000-0000-0000-000000000064', 'STMIK AMIKOM Yogyakarta', 'stmik-amikom-yogyakarta', NULL, '{"title": "University of Amikom Yogyakarta", "extract": "The University of AMIKOM Yogyakarta is a private IT college in Sleman Regency, Special Region of Yogyakarta, Indonesia. The college was established on December 29, 1992, under the auspices of the Yogyakarta AMIKOM Foundation. It has 2 diploma programs, 13 undergraduate programs, and 1 postgraduate program; all are accredited. The university concentrates on efforts to become the world''s leading university in the field of the creative economy based on entrepreneurship. The university currently has more than 11,000 active students, and has more than 3,000 new students every year.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/7/7c/New_Logo_AMIKOM.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/University_of_Amikom_Yogyakarta", "description": "Higher education institution in Sleman, Indonesia"}', '6e373c0c-dcf9-4933-86ee-b8e9809646fe', NULL, 'ID', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.436788+01', '2026-08-09 03:52:20.00993+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
