INSERT INTO public.spaces VALUES ('b66dba9f-440d-4671-aa30-63c374643186', NULL, '00000000-0000-0000-0000-000000000064', 'Gurukula Kangri University', 'gurukula-kangri-university', NULL, '{"title": "Gurukul Kangri University", "extract": "Gurukula Kangri is an Indian government-funded deemed university u/s 3 of the UGC Act 1956 located in Haridwar, Uttarakhand, India. Situated near the bank of the Ganges, Haridwar and about 200 km from New Delhi, the Gurukula Kangri has 25 academic departments covering Engineering, Applied Sciences, Vedic Sciences, Humanities and Social Sciences and Management programs with a strong emphasis on Vedic and Modern Sciences and technological education and research. The university has signed about 34 memorandums of understanding with industries, universities, NGOs, and institutions.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/e/e9/Gurukul_Kangri_Vishwavidyalaya_logo.jpg/330px-Gurukul_Kangri_Vishwavidyalaya_logo.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Gurukul_Kangri_University", "description": "University in Haridwar, India"}', 'f6e01d4c-d9e7-4736-9421-0372122d312b', NULL, 'IN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.411195+01', '2026-08-07 18:43:18.517264+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
