INSERT INTO public.spaces VALUES ('7e99c02a-cf8f-4393-94c5-cafdfa466fee', NULL, '00000000-0000-0000-0000-000000000064', 'National Institute of Technology Hamirpur', 'national-institute-of-technology-hamirpur', NULL, '{"title": "National Institute of Technology, Hamirpur", "extract": "National Institute of Technology Hamirpur is a public technical university located in Hamirpur, Himachal Pradesh, India. It was declared to be an Institute of National Importance by the Government of India under the Institutes of Technology Act.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/b/b8/National_Institute_of_Technology%2C_Hamirpur_Logo.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/National_Institute_of_Technology%2C_Hamirpur", "description": "Institute in Hamirpur, Himachal Pradesh, India"}', 'e7d5d5bc-2d38-45db-b20b-553dfae896ed', NULL, 'IN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.436788+01', '2026-08-07 18:50:16.530174+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('f481e00e-c6d9-4a97-b011-b2d2af002f2a', NULL, '00000000-0000-0000-0000-000000000064', 'National Institute of Technology Jamshedpur', 'national-institute-of-technology-jamshedpur', NULL, '{"title": "National Institute of Technology, Jamshedpur", "extract": "National Institute of Technology Jamshedpur is an Institute of National Importance for Technical Education located at Jamshedpur, Jharkhand, India. Established as a Regional Institute of Technology on 15 August 1960, it was upgraded to National Institute of Technology (NIT) on 27 December 2002 with the status of a Deemed University. It is one of the 31 NITs in India, and as such is directly under the control of the Ministry of Education (MHRD). It is the third in the chain of 8 NITs established as a part of the Second Five Year Plan (1956–61) by the Government of India.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/7/7d/National_Institute_of_Technology%2C_Jamshedpur_Logo.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/National_Institute_of_Technology%2C_Jamshedpur", "description": "Educational institute in India"}', 'f0d0007b-40fa-4056-9946-17616dcf52d6', NULL, 'IN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.436788+01', '2026-08-07 18:50:21.675694+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('3a6e7d7e-3abb-47fe-adea-4d3fa6020892', NULL, '00000000-0000-0000-0000-000000000064', 'Dr. Ram Manohar Lohia Avadh University', 'dr-ram-manohar-lohia-avadh-university', NULL, '{"title": "Dr. Ram Manohar Lohia Avadh University", "extract": "Dr. Ram Manohar Lohia Avadh University, commonly known as Avadh University, is a state university located in Faizabad, Ayodhya district, Uttar Pradesh, India. It was established in 1975 by the government of Uttar Pradesh. Presently, the university is catering education to about 5 lakhs regular/private students through its nine residential PG departments and on campus Institute of Engineering along-with more than 600 affiliated colleges.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/3/30/Dr._Ram_Manohar_Lohia_Avadh_University_logo.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Dr._Ram_Manohar_Lohia_Avadh_University", "description": "Public University in Ayodhya"}', 'd7098944-1f69-444f-8f99-301b40f496f8', NULL, 'IN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.436788+01', '2026-08-07 18:52:20.814614+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
