INSERT INTO public.spaces VALUES ('c31ee8dc-73e8-4339-b0ac-2032d783a3eb', NULL, '00000000-0000-0000-0000-000000000064', 'Minnesota State College-Southeast Technical', 'minnesota-state-college-southeast-technical', NULL, '{"title": "Minnesota State College Southeast", "extract": "Minnesota State College Southeast is a public technical and community college with two campuses in Minnesota, one in Red Wing and another in Winona. The two campuses were originally two separate vocational institutes. The college is part of the Minnesota State Colleges and Universities system. The Red Wing campus is nationally renowned for its string instrument and woodwind and brass instrument repair programs. There are only a few colleges in the nation which offer these programs. The United States Marine Corps and US Navy send their band instrument repair techs to the school.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/c2/Minnesota_State_College_Southeast.jpg/330px-Minnesota_State_College_Southeast.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Minnesota_State_College_Southeast", "description": "Technical and community college in Minnesota, U.S."}', 'c0654558-a1c0-45ae-8e26-188196c08d14', NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-07 22:23:20.698735+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('c8dde795-5a93-4711-87bc-b1d80af30681', NULL, '00000000-0000-0000-0000-000000000064', 'St Charles Community College', 'st-charles-community-college', NULL, '{"title": "St. Charles Community College", "extract": "St. Charles Community College (SCC) is a public community college in Cottleville, Missouri. Established in 1986, SCC''s first fall semester in 1987 had an enrollment of 1,547 students. It offers associate degrees and certificate programs in the arts, business, sciences, and career-technical fields as well as workforce training and community-based personal and professional development. St. Charles Community College is accredited by The Higher Learning Commission of the North Central Association of Colleges and Schools.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/8/8c/St._Charles_Community_College_%28seal%29.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/St._Charles_Community_College", "description": "Public college in St. Charles, Missouri, US"}', 'eb7e5b3d-e9e2-41da-b862-f41c8c7c8969', NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-07 22:25:18.759536+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
