INSERT INTO public.spaces VALUES ('b0dc9ed7-a8c7-4bc8-86d0-b913a6f05064', NULL, '00000000-0000-0000-0000-000000000064', 'University of Colorado Health Sciences Center', 'university-of-colorado-health-sciences-center', NULL, '{"title": "University of Colorado Anschutz", "extract": "The University of Colorado Anschutz is the academic health sciences campus in Aurora, Colorado, that houses the University of Colorado''s six health sciences-related schools and colleges, including the University of Colorado School of Medicine, the CU Anschutz Skaggs School of Pharmacy and Pharmaceutical Sciences, the CU Anschutz College of Nursing, the CU Anschutz School of Dental Medicine, and the Colorado School of Public Health, as well as the graduate school for various fields in the biological and biomedical sciences. The campus also includes the 184-acre (0.74 km2) Fitzsimons Innovation Community, UCHealth University of Colorado Hospital, Children''s Hospital Colorado, the Rocky Mountain Regional Veterans Affairs hospital, and a residential/retail town center known as 21 Fitzsimons. CU Anschutz is the largest academic health center in the Rocky Mountain region.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/02/Seal_of_the_University_of_Colorado.svg/330px-Seal_of_the_University_of_Colorado.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/University_of_Colorado_Anschutz", "description": "University of Colorado''s health sciences-related schools and colleges"}', 'd2ece831-91c2-4a01-825e-3edcc82fb670', NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.262718+01', '2026-08-07 12:47:33.262718+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
