INSERT INTO public.spaces VALUES ('17c461be-6143-4257-9e4e-8ec9a73420b2', NULL, '00000000-0000-0000-0000-000000000064', 'Wake Forest Baptist Health', 'wake-forest-baptist-health', NULL, '{"title": "Atrium Health Wake Forest Baptist", "extract": "Atrium Health Wake Forest Baptist is an academic medical center and health system located in Winston-Salem, North Carolina, and part of Charlotte-based Advocate Health. It is the largest employer in Forsyth County, with more than 19,220 employees and a total of 198 buildings on 428 acres. In addition to the main, tertiary-care hospital in Winston-Salem known as Atrium Health Wake Forest Baptist Medical Center, the Atrium Health Wake Forest Baptist Health system operates five community hospitals in the surrounding region. The entity includes:Atrium Health Wake Forest Baptist, its clinical enterprise\nWake Forest School of Medicine, its research and education arm\nInnovation Quarter, an operating division involved with partnerships, education, licensing and start-ups.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/35/Atrium_Health_Wake_Forest_Baptist_Hospital_seen_from_US_421.jpg/330px-Atrium_Health_Wake_Forest_Baptist_Hospital_seen_from_US_421.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Atrium_Health_Wake_Forest_Baptist", "description": "Hospital in North Carolina, United States"}', 'ba34e4c6-4755-470a-8796-9929b8dc21d3', NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.188857+01', '2026-08-07 12:47:33.188857+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
