INSERT INTO public.spaces VALUES ('b36592e4-fad2-484f-9a21-e0bb200364b4', NULL, '00000000-0000-0000-0000-000000000064', 'Prague Institute of Chemical Technology', 'prague-institute-of-chemical-technology', NULL, '{"title": "University of Chemistry and Technology, Prague", "extract": "The University of Chemistry and Technology, Prague is the largest university specializing in chemistry in the Czech Republic. Though founded in 1952, UCT Prague has origins dating back to the early nineteenth century and Prague Polytechnic, a precursor to the present-day Czech Technical University in Prague, and, since that time, it has been one of the leading chemistry research universities in Central Europe. More than 3,600 students are accepted every year. In 2014, UCT Prague had 510 academic staff and 361 research staff.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/07/ChemTech_Institute%2C_Prague_Dejvice.jpg/330px-ChemTech_Institute%2C_Prague_Dejvice.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/University_of_Chemistry_and_Technology%2C_Prague", "description": "University in Prague, Czech Republic"}', 'aa035247-b918-4708-97bc-8c328bc45e8a', NULL, 'CZ', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.353781+01', '2026-08-07 12:47:33.353781+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
