INSERT INTO public.spaces VALUES ('1746dd6c-e808-47aa-affe-d95edef961a4', NULL, '00000000-0000-0000-0000-000000000064', 'University College, Thiruvananthapuram', 'university-college-thiruvananthapuram', NULL, '{"title": "University College, Thiruvananthapuram", "extract": "University College, Thiruvananthapuram (UCT) is a public college situated in Palayam, Thiruvananthapuram, India. Established in 1866, it is one of the oldest colleges in Kerala. The college has been accorded \"College with Potential for Excellence\" (CPE) status by the University Grants Commission.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/72/University_College_%2C_Trivandrum.jpg/330px-University_College_%2C_Trivandrum.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/University_College%2C_Thiruvananthapuram", "description": "Public college in Palayam, India"}', '1ced871f-e725-48e5-9644-65c4082c1ebc', NULL, 'IN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.726322+01', '2026-08-09 13:54:18.749281+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
