INSERT INTO public.spaces VALUES ('dc919fbb-07ea-4e95-b205-295bdb49978f', NULL, '00000000-0000-0000-0000-000000000064', 'Phillips-Universität Marburg', 'phillips-universit-t-marburg', NULL, '{"title": "Marburg University", "extract": "Marburg University is a public research university located in Marburg, Germany. It was founded in 1527 by Philip I, Landgrave of Hesse, which makes it one of Germany''s oldest universities and the oldest still operating Protestant university in the world. It is now a public university of the state of Hesse, without religious affiliation.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/9e/Universit%C3%A4t_Marburg_Siegel.svg/330px-Universit%C3%A4t_Marburg_Siegel.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Marburg_University", "description": "Public university in Hesse, Germany"}', 'e1046586-7998-486e-a980-ec41b5e04555', NULL, 'DE', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.411195+01', '2026-08-07 18:32:19.309135+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
