INSERT INTO public.spaces VALUES ('6be6f94d-4ba0-40b1-a828-0267931c29d3', NULL, '00000000-0000-0000-0000-000000000064', 'Bengal Engineering College', 'bengal-engineering-college', NULL, '{"title": "IIEST, Shibpur", "extract": "Indian Institute of Engineering Science and Technology, Shibpur  is a public technologicalresearch university located at Shibpur, Howrah, West Bengal, India. Founded in 1856, it is one of the Institutes of National Importance funded by the Ministry of Education of the Government of India. It is regulated by the Council of NITSER. It is the fourth oldest engineering institute in India. In October 2010, the Union Cabinet approved the proposal for the conversion of the Bengal Engineering and Science University (BESU) at Shibpur to India''s first Indian Institute of Engineering Science and Technology (IIEST). IIEST is a member of the Association of Indian Universities.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/a/ac/IIEST_Shibpur_Logo.svg/330px-IIEST_Shibpur_Logo.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/IIEST%2C_Shibpur", "description": "Research university in West Bengal, India"}', 'b88be38b-be39-44ae-a6d2-cd373ebb6f8b', NULL, 'IN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.411195+01', '2026-08-07 18:41:18.443549+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
