INSERT INTO public.spaces VALUES ('92094d67-c380-4449-9c69-db2fa000b301', NULL, '00000000-0000-0000-0000-000000000064', 'University Medical School of Debrecen', 'university-medical-school-of-debrecen', NULL, '{"title": "University of Debrecen", "extract": "The University of Debrecen is a university located in Debrecen, Hungary. It is the oldest continuously operating institution of higher education in Hungary ever since its establishment in 1538. The university has a well established programme in the English language for international students, particularly in the Medical and Engineering field, which first established education in English in 1886. There are nearly 6000 international students studying at the university.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/73/DebrecenDSCN3583.JPG/330px-DebrecenDSCN3583.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/University_of_Debrecen", "description": "University in Hungary"}', '661463f2-9fe6-4959-ba57-4ef4b5f5d328', NULL, 'HU', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.411195+01', '2026-08-08 01:32:17.650344+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
