INSERT INTO public.spaces VALUES ('c5a48699-0336-4359-bf5f-0387b8f22500', NULL, '00000000-0000-0000-0000-000000000064', 'Lakshmibai National Institute of Physical Education', 'lakshmibai-national-institute-of-physical-education', NULL, '{"title": "Lakshmibai National Institute of Physical Education", "extract": "The Lakshmibai National Institute of Physical Education (LNIPE), formerly Lakshmibai National University of Physical Education, is a higher education institute deemed-to-be-university, located in Gwalior, Madhya Pradesh, India. Under the aegis of Ministry of Youth Affairs and Sports and committed for excellence in physical education, coaching and sports in the country. The campus is on the Agra–Mumbai Highway, at a walking distance of around 500m from Gwalior railway station, Shaktinagar, Gwalior.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/b/b7/Lakshmibai_National_Institute_of_Physical_Education_logo.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Lakshmibai_National_Institute_of_Physical_Education", "description": "Deemed university in Madhya Pradesh"}', '2b0959f2-73b0-4b6d-8bea-2b155f34f07c', NULL, 'IN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.436788+01', '2026-08-07 18:48:18.490396+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
