INSERT INTO public.spaces VALUES ('56837d6c-8306-4da8-b4ee-09db5ed59532', NULL, '00000000-0000-0000-0000-000000000064', 'National Institute of Technology Silchar', 'national-institute-of-technology-silchar', NULL, '{"title": "National Institute of Technology, Silchar", "extract": "National Institute Of Technology Silchar is one of the 31 NITs of India and was established in 1967 as a Regional Engineering College in Silchar. In 2002, it was upgraded to the status of National Institute of Technology and was declared as Institute of National Importance under the National Institutes of Technology Act, 2007.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/7/71/National_Institute_Of_Technology_Silchar_Logo.svg/330px-National_Institute_Of_Technology_Silchar_Logo.svg.png", "content_url": "https://en.wikipedia.org/wiki/National_Institute_of_Technology%2C_Silchar", "description": "Public engineering institution in Silchar, Assam, India"}', '80354bfd-c92b-49b6-bf1e-ff22cb499d47', NULL, 'IN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.436788+01', '2026-08-08 01:43:17.785732+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('3af89c74-c4fa-495c-a49c-6956fa379ae7', NULL, '00000000-0000-0000-0000-000000000064', 'Punjabi University Patiala', 'punjabi-university-patiala', NULL, '{"title": "Punjabi University", "extract": "Punjabi University is a collegiate state public university located in Patiala, Punjab, India. It was established on 30 April 1962 and is only the second university in the world to be named after a language, after Hebrew University of Israel. Originally, it was conceived as a unitary multi-faculty teaching and research university, primarily meant for the development and enrichment of the Punjabi language and culture, but alive to the social and education requirements of the state.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/d/dc/FinalLogo7May2026.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Punjabi_University", "description": "Higher education institute in India"}', '9d2816a7-f9d6-42cb-92cd-f56334ead908', NULL, 'IN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.436788+01', '2026-08-08 01:44:21.810765+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
