INSERT INTO public.spaces VALUES ('8ab507d5-4fe8-4a7f-adff-d89e7c98b260', NULL, '00000000-0000-0000-0000-000000000064', 'Imam Sadegh University', 'imam-sadegh-university', NULL, '{"title": "Imam Sadiq University", "extract": "The Imam Sadiq University is an Islamic private university in Tehran, Iran. Established in 1982, the goal of the university is to combine Islamic research and modern studies, especially humanities. The university was dedicated to training politicians and jurists preaching Islam. Reflecting its commitment to Islamic principles, the university separates educational environments for female and male students.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/2/2a/Imam_Sadiq_University.svg/330px-Imam_Sadiq_University.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Imam_Sadiq_University", "description": "Iranian Islamic private university"}', '0f8f48b3-68f2-4806-bdbd-5f8f223fa768', NULL, 'IR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.465646+01', '2026-08-08 01:59:20.623147+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
