INSERT INTO public.spaces VALUES ('564f80c8-84be-4a02-9d50-60c26cd201d9', NULL, '00000000-0000-0000-0000-000000000064', 'Link Campus University of Malta', 'link-campus-university-of-malta', NULL, '{"title": "Link Campus University", "extract": "\nLink Campus University, formerly Link Campus—University of Malta, is a proprietary, for-profit university located in Rome, Italy. The university was founded in 1999 at the initiative of former Italian President Francesco Cossiga and former Maltese President Guido de Marco, with Vincenzo Scotti, former Italian Minister of the Interior and Foreign Affairs, serving as founding president. The university has trained intelligence and law enforcement personnel from NATO countries and has been described by Italian newspapers as either a \"shady diploma mill or den of spies.\" The university is owned by CEPU, a for-profit Italian franchise chain.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/90/Link_Campus_University.png/330px-Link_Campus_University.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Link_Campus_University", "description": "Private university in Rome, Italy"}', 'ceea4b21-7eba-428b-b9c0-3a428a777f9b', NULL, 'IT', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.465646+01', '2026-08-07 19:19:19.071838+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
