INSERT INTO public.spaces VALUES ('a992237c-99a6-492a-a444-a7e1c68867c2', NULL, '00000000-0000-0000-0000-000000000064', 'Inchon National University of Education', 'inchon-national-university-of-education', NULL, '{"title": "Gyeongin National University of Education", "extract": "Gyeongin National University of Education is a teacher training institution for future public elementary school teachers in South Korea. It was founded on May 23, 1946 under the name of Gaeseong School of Education in Gyeonggi-do. In 2003, the institution changed its name from Inchon National University of Education (INUE) (인천교육대학교) to Gyeongin National University of Education. The university is the largest educational institute for training future elementary school teachers in Korea.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/9/90/Ginuesymbol.PNG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Gyeongin_National_University_of_Education", "description": "Training institution in South Korea"}', '43d9b7c5-b114-44ad-a491-c7c09e701313', NULL, 'KR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.5184+01', '2026-08-08 02:39:22.605391+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
