INSERT INTO public.spaces VALUES ('a86021b0-3358-4f20-80a1-9def4aab86f7', NULL, '00000000-0000-0000-0000-000000000064', 'University College of Gävle', 'university-college-of-g-vle', NULL, '{"title": "Gävle University College", "extract": "University of Gävle is a university college (högskola) located in Gävle, Sweden. It uses the name \"University of Gävle\" in English, although it is officially a ''University College''. The university was established in 1977 and is currently organized into three academies and nine departments.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/7/71/G%C3%A4vle_University_College_logo.jpeg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/G%C3%A4vle_University_College", "description": "University college in Gävle, Sweden"}', '08e79f62-18ee-4823-914c-0f6c084bc130', NULL, 'SE', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.625787+01', '2026-08-08 04:05:20.42184+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('6d6c8dd9-1ff5-49cb-9dd4-1cd8902dfc9b', NULL, '00000000-0000-0000-0000-000000000064', 'Spokane Colleges', 'spokane-colleges', NULL, '{"title": "Community Colleges of Spokane", "extract": "Community Colleges of Spokane is a community college district based in Spokane, Washington. Established in 1963, CCS serves over 28,000 students a year, spread across a 12,300-square-mile (32,000 km2) service district in Eastern Washington. It comprises Spokane Community College and Spokane Falls Community College.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/b/b3/Community_Colleges_of_Spokane.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Community_Colleges_of_Spokane", "description": "Community college district in Spokane, Washington, U.S."}', '7c6d4197-5bb6-4f45-8ce9-080cdd8dfd63', NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.753691+01', '2026-08-09 06:12:18.604445+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
