INSERT INTO public.spaces VALUES ('b6c61280-e600-4f02-bf95-b5253a714756', NULL, '00000000-0000-0000-0000-000000000064', 'Effat College', 'effat-college', NULL, '{"title": "Effat University", "extract": "Effat University is a private non-profit institution of higher education for men and women in Jeddah, Saudi Arabia, operating under the umbrella of King Faisal Charitable Foundation. On 30 January 2009, Effat College became Effat University. The inauguration of its four colleges, the establishment of the Research and Consultancy Institute, and success achieved on the academic, education and social levels, paved the way to becoming a university.", "content_url": "https://en.wikipedia.org/wiki/Effat_University", "description": "Private university in Jeddah, Saudi Arabia"}', NULL, NULL, 'SA', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.625787+01', '2026-08-08 03:52:18.126575+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
