INSERT INTO public.spaces VALUES ('650e4765-54e9-4174-ada3-509f2b3f76e7', NULL, '00000000-0000-0000-0000-000000000064', 'University of Wisconsin - River Falls', 'university-of-wisconsin-river-falls', NULL, '{"title": "University of Wisconsin–River Falls", "extract": "The University of Wisconsin–River Falls is a public university in River Falls, Wisconsin, United States. It is part of the University of Wisconsin System. The 226-acre (91 ha) campus is on the Kinnickinnic River in the St. Croix River Valley. The university has 32 major buildings and two laboratory farms, with a total of 303 acres (123 ha) of land.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/f/fd/Uw_river_falls_seal.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/University_of_Wisconsin%E2%80%93River_Falls", "description": "Public university in River Falls, Wisconsin, U.S."}', '2fe4d5cf-dfde-40fa-b525-4f38ebfbf6a4', NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.262718+01', '2026-08-09 07:03:06.726916+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
