INSERT INTO public.spaces VALUES ('43506f0a-0a4b-4fb7-8dab-ec86b0bc030e', NULL, '00000000-0000-0000-0000-000000000064', 'Montana State University - Billings', 'montana-state-university-billings', NULL, '{"title": "Montana State University Billings", "extract": "Montana State University Billings (MSUB), also known as MSU Billings, is a public university in Billings, Montana, United States. It is the state''s third largest university. Its campus is located on 110 acres in downtown Billings. Formerly Eastern Montana Normal School at its founding in 1927, the Normal School changed its name to Eastern Montana College of Education in 1949. It was again renamed in 1965 as Eastern Montana College (EMC). It merged into the Montana University System in 1994 under its present name. Currently, the university offers over 100 specialized programs for certificates, associate, bachelor''s, and master''s degrees through the university''s five colleges. The five colleges of Montana State University Billings are Liberal Arts & Social Sciences, Business, Health Professions and Science, Education, and City College.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/1/16/Msu_billings_seal.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Montana_State_University_Billings", "description": "Public university in Billings, Montana, US"}', '84a667b3-a9de-4b8f-a1c8-381c6c9d0b73', NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.233464+01', '2026-08-07 23:23:17.863648+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
