INSERT INTO public.spaces VALUES ('7f4cd780-6cdd-4abd-83f0-522965b312d6', NULL, '00000000-0000-0000-0000-000000000064', 'Turku School of Economics and Business Administration', 'turku-school-of-economics-and-business-administration', NULL, '{"title": "Turku School of Economics", "extract": "Turku School of Economics is a unit of the University of Turku located in Turku, Finland. It was established as an independent higher education business school in 1950, until it was acquired by the state in 1977. It was the second largest school of its kind in Finland, with approximately 2,000 graduate and 250 postgraduate students and a staff of 350. In January 2010, Turku School of Economics became the seventh faculty of the University of Turku. Its former rector, Professor Tapio Reponen, is now a vice rector of the University of Turku.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/37/TuKKK2007.JPG/330px-TuKKK2007.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Turku_School_of_Economics", "description": "Faculty of the University of Turku, Finland"}', 'd854b6af-f111-4b49-a1d6-ce852f9ed56b', NULL, 'FI', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.384776+01', '2026-08-09 07:47:18.974773+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('b5e95aa8-7544-403d-b98b-e8e95ca59de6', NULL, '00000000-0000-0000-0000-000000000064', 'Kardan University', 'kardan-university', NULL, '{"title": "Kardan University", "extract": "Kardan University founded in 2002 in Kabul, Afghanistan is the first privately owned university in Afghanistan. It began its operations in a small classroom with 15 students at a time when private higher education was being introduced in the country for the first time.", "content_url": "https://en.wikipedia.org/wiki/Kardan_University", "description": "Private university in Kabul, Afghanistan"}', NULL, NULL, 'AF', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.262718+01', '2026-08-09 10:47:19.894789+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
