INSERT INTO public.spaces VALUES ('8f50a521-31ad-4792-a76b-36e39d3fef8a', NULL, '00000000-0000-0000-0000-000000000064', 'Tongji Medical University', 'tongji-medical-university', NULL, '{"title": "Tongji Medical College", "extract": "Tongji Medical College is the medical school of Huazhong University of Science and Technology, located in Wuhan, China. Formerly Tongji Medical University, it became part of the newly established HUST in 2000. More than 10 graduates of the medical school have been awarded memberships to the Chinese Academy of Sciences and Chinese Academy of Engineering.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/e9/The_Main_Gate_of_Tongji_Medical_College.jpg/330px-The_Main_Gate_of_Tongji_Medical_College.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Tongji_Medical_College", "description": "Medical school in Wuhan, Hubei, China"}', 'c36be719-086e-45ed-a4ae-d82bb9e63a30', NULL, 'CN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.353781+01', '2026-08-10 06:58:04.510865+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
