INSERT INTO public.spaces VALUES ('2c010289-451d-4e19-a242-d328408ff7f4', NULL, '00000000-0000-0000-0000-000000000064', 'Budapest University of Economic Sciences and Public Administration', 'budapest-university-of-economic-sciences-and-public-administration', NULL, '{"title": "Corvinus University of Budapest", "extract": "Corvinus University of Budapest is a private research university in Budapest, Hungary. The university currently has an enrolment of approximately 9,600 students, with a primary focus on business administration, economics, and social sciences, operating in Budapest and Székesfehérvár since 1948. Corvinus University accepts students at six faculties and offer courses leading to degrees at the bachelor, master and doctoral level in specialisations taught in Hungarian, English, French or German.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/57/Corvinus_eng_logo.jpg/330px-Corvinus_eng_logo.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Corvinus_University_of_Budapest", "description": "Research university in Budapest, Hungary"}', '7e63695a-f4b6-49be-9abf-06e51747031c', NULL, 'HU', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.411195+01', '2026-08-08 01:32:19.734671+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
