INSERT INTO public.spaces VALUES ('97603602-538f-475e-b73e-3f108a153153', NULL, '00000000-0000-0000-0000-000000000064', 'Gurukul University', 'gurukul-university', NULL, '{"title": "Gurukul Kangri University", "extract": "Gurukula Kangri is an Indian government-funded deemed university u/s 3 of the UGC Act 1956 located in Haridwar, Uttarakhand, India. Situated near the bank of the Ganges, Haridwar and about 200 km from New Delhi, the Gurukula Kangri has 25 academic departments covering Engineering, Applied Sciences, Vedic Sciences, Humanities and Social Sciences and Management programs with a strong emphasis on Vedic and Modern Sciences and technological education and research. The university has signed about 34 memorandums of understanding with industries, universities, NGOs, and institutions.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/e/e9/Gurukul_Kangri_Vishwavidyalaya_logo.jpg/330px-Gurukul_Kangri_Vishwavidyalaya_logo.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Gurukul_Kangri_University", "description": "University in Haridwar, India"}', '82860e53-6806-42ac-969f-4f1524f3899f', NULL, 'IN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.411195+01', '2026-08-08 01:37:18.090431+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
