INSERT INTO public.spaces VALUES ('edd6d210-4596-417a-9f92-c38be8c560e1', NULL, '00000000-0000-0000-0000-000000000064', 'Govind Ballabh Pant University of Agriculture and Technology', 'govind-ballabh-pant-university-of-agriculture-and-technology', NULL, '{"title": "G. B. Pant University of Agriculture and Technology", "extract": "G. B. Pant University of Agriculture and Technology, also known as Pantnagar University, is the first agricultural university established in Independent India. It was inaugurated by the first Prime Minister of India Jawahar Lal Nehru on 17 November 1960 as the Uttar Pradesh Agricultural University (UPAU) in Pantnagar. Later the name was changed to Govind Ballabh Pant University of Agriculture and Technology in 1972 in memory of the first Chief Minister of Uttar Pradesh, statesman and Bharat Ratna recipient Govind Ballabh Pant. The university is located in the campus town of Pantnagar in Kichha Tehseel and in the district of Udham Singh Nagar near the famous town of Nainital in the State of Uttarakhand. The university is regarded as the harbinger of the Green Revolution in India.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/9/90/Pantnagar_logo.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/G._B._Pant_University_of_Agriculture_and_Technology", "description": "Agricultural university in Pantnagar, Uttarakhand, India"}', '3d96cc50-fcca-4b13-b44f-c8de0e6f8ea2', NULL, 'IN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.411195+01', '2026-08-08 01:36:20.028196+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('1ca4bae2-e27d-4ebe-b96a-a74575c80ab9', NULL, '00000000-0000-0000-0000-000000000064', 'Universidade Castelo Branco', 'universidade-castelo-branco', NULL, '{"name": "Castelo Branco University", "country": "Q155", "founded": "+1971-00-00T00:00:00Z", "website": "http://www.castelobranco.br", "description": "university in Brazil", "wikidata_id": "Q10387777", "wikipedia_url": "https://en.wikipedia.org/wiki/Q10387777"}', NULL, NULL, 'BR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.296289+01', '2026-08-09 11:03:19.809507+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('6e35910f-04bc-4b3b-b88b-19d6c756ebdf', NULL, '00000000-0000-0000-0000-000000000064', 'ICFAI University, Hyderabad', 'icfai-university-hyderabad', NULL, '{"title": "Education in Hyderabad", "extract": "Hyderabad is an important seat of learning in southern India. The city hosts three central universities, three deemed universities, and six state universities. Osmania University is one of the oldest universities in India. Many institutes for education like University of Hyderabad, Jawaharlal Nehru Technological University, Hyderabad, International Institute of Information Technology, Indian Institute of Technology, Hyderabad, ICFAI Foundation for Higher Education, Tata Institute of Fundamental Research, Hyderabad, Birla Institute of Technology and Science, Pilani – Hyderabad, Sri Sarada Institute of Science and Technology and medical colleges like Nizam''s Institute of Medical Sciences are located there. Also based in the city are the Institute of Public Enterprise and the National Academy of Legal Studies & Research (NALSAR). Hyderabad has various research institutes such as the Indian Institute of Chemical Technology, Centre for Cellular and Molecular Biology. It is also the home of Maulana Azad National Urdu University as well as Dr. B.R. Ambedkar Open University.", "content_url": "https://en.wikipedia.org/wiki/Education_in_Hyderabad", "description": ""}', NULL, NULL, 'IN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.436788+01', '2026-08-08 07:52:17.710966+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
