INSERT INTO public.spaces VALUES ('369b607b-95f5-428d-9e27-ac563d62cd9b', NULL, '00000000-0000-0000-0000-000000000064', 'National Institute of Technology Surathkal', 'national-institute-of-technology-surathkal', NULL, '{"title": "National Institute of Technology, Karnataka", "extract": "The National Institute of Technology Karnataka (NITK), also known as NITK Surathkal and formerly known as Karnataka Regional Engineering College (KREC), is a public technical university located in Surathkal, Mangaluru. Established in 1960 as KREC, it has since evolved into one of the 31 National Institutes of Technology in India. It is recognized as an Institute of National Importance by the Government of India. The institute features a suburban campus situated in close proximity to the Arabian Sea, with National Highway 66 running through the campus and serving as a major access route. NITK Surathkal is ranked as one of the prestigious engineering institutions in India.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/c/cc/NITK_Emblem.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/National_Institute_of_Technology%2C_Karnataka", "description": "Engineering university at Surathkal, Mangalore"}', 'caa6e413-4a35-4377-9e12-b7ac2bebfb2a', NULL, 'IN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.436788+01', '2026-08-08 07:57:19.308863+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('611a1f51-6eed-45a5-aa66-75f84c62af37', NULL, '00000000-0000-0000-0000-000000000064', 'Sikkim Manipal University of Health, Medical and Technological Sciences', 'sikkim-manipal-university-of-health-medical-and-technological-sciences', NULL, '{"title": "Sikkim Manipal University", "extract": "Sikkim Manipal University (SMU), formerly Sikkim Manipal University of Health, Medical and Technological Sciences, is a private university located in Gangtok, Sikkim, India. The Sikkim Manipal University started its journey in 1992, after the signing of an agreement between the Government of Sikkim and the Manipal Education & Medical Group (MEMG). The university was officially established in 1995 as Sikkim Manipal University of Health, Medical and Technological Sciences through The Sikkim Manipal University of Health, Medical and Technological Science Act, 1995. The name was changed to Sikkim Manipal University in 2010 through The Sikkim Manipal University of Health, Medical, and Technological Sciences (Amendment) Act, 2009.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/3/30/Logo_of_Sikkim_Manipal_University.jpg/330px-Logo_of_Sikkim_Manipal_University.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Sikkim_Manipal_University", "description": "Private & public university in Sikkim, India"}', 'ba723f0a-c913-4845-a292-2f8506b9efe0', NULL, 'IN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.436788+01', '2026-08-08 07:59:17.290219+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
