INSERT INTO public.spaces VALUES ('7ce0219b-1f1f-45d9-93f0-7df69dd99dd8', NULL, '00000000-0000-0000-0000-000000000064', 'South Gujarat University', 'south-gujarat-university', NULL, '{"title": "Veer Narmad South Gujarat University", "extract": "Veer Narmad South Gujarat University is a public university located in the city of Surat, Gujarat, India. Previously known as South Gujarat University, it was renamed as Veer Narmad South Gujarat University (VNSGU) in 2004 in honour of the famous scholar and Gujarati poet Narmad. Established in 1965, the university offers undergraduate and postgraduate courses, including non-traditional postgraduate departments such as public administration, rural studies, comparative literature, and aquatic biology.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/1/11/VNSGU_logo.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Veer_Narmad_South_Gujarat_University", "description": "Public university in Surat, Gujarat, India"}', 'e4bf6070-689b-4c05-be93-468957b25aff', NULL, 'IN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.436788+01', '2026-08-08 01:45:17.976426+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
