INSERT INTO public.spaces VALUES ('c6fb6227-a05f-495e-8be8-f1196e4a0e75', NULL, '00000000-0000-0000-0000-000000000064', 'Kitakyushu University', 'kitakyushu-university', NULL, '{"title": "University of Kitakyushu", "extract": "The University of Kitakyushu  is a public university in Kitakyushu, Japan. The main campus is located next to Keibajomae station on the Kitakyushu monorail. The second campus is in the academic zone of Wakamatsu-ku, Kitakyushu called Gakujutsu Kenkyu Toshi. The university was founded as a language academy in 1946 to help communication with the nearby American base at what is now called Yamada Ryokuchi.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/51/Kitakyushu_university.jpg/330px-Kitakyushu_university.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/University_of_Kitakyushu", "description": "University in Fukuoka Prefecture, Japan"}', 'a014a9c3-d650-4a76-8b43-79e8cfab65b5', NULL, 'JP', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.493186+01', '2026-08-08 02:17:17.007998+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('2ad91c91-8d78-4707-b838-748bea72c7c9', NULL, '00000000-0000-0000-0000-000000000064', 'University of Venice', 'university-of-venice', NULL, '{"title": "Ca'' Foscari University of Venice", "extract": "Ca'' Foscari University of Venice, or simply Ca'' Foscari, is a public research university and business school in Venice, Italy. Since its foundation in 1868, it has been housed in the Venetian Gothic palace of Ca'' Foscari, from which it takes its name. The palace stands on the Grand Canal, between the Rialto and San Marco, in the sestiere of Dorsoduro, while the rest of the University is scattered around the historical centre. In addition to the historical centre of Venice, Ca'' Foscari also has campuses in Mestre and Treviso.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/bc/Logo_Universit%C3%A0_Ca%27_Foscari_Venezia.svg/330px-Logo_Universit%C3%A0_Ca%27_Foscari_Venezia.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Ca''_Foscari_University_of_Venice", "description": "Public university in Venice, Italy"}', '19d2fa46-b0e9-4a92-9bfd-ae9f8b87da8c', NULL, 'IT', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.465646+01', '2026-08-08 08:22:19.976116+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
