INSERT INTO public.spaces VALUES ('b9a5374e-55dc-4797-b33e-59d4391a6540', NULL, '00000000-0000-0000-0000-000000000064', 'Kangnung National University', 'kangnung-national-university', NULL, '{"title": "Gangneung–Wonju National University", "extract": "Gangneung–Wonju National University is a national research university with two campuses, in Gangneung and Wonju, South Korea. Founded in 1946, GWNU is situated on the east coast of the country. The institution traces its roots to Gangneung Normal School and Wonju Nursing Higher Technical School, which were established in 1946 and 1967, respectively. The two schools merged in 2007, and the institution was renamed in 2009.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/6b/Gwnu-ui.png/330px-Gwnu-ui.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Gangneung%E2%80%93Wonju_National_University", "description": "National research university in South Korea"}', '2e34a037-b320-4f19-a22c-6288dddd93df', NULL, 'KR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.5184+01', '2026-08-09 08:41:18.246804+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
