INSERT INTO public.spaces VALUES ('43589086-9783-4f1f-96ac-9fc5a2884704', NULL, '00000000-0000-0000-0000-000000000064', 'Lumbini Buddhist University', 'lumbini-buddhist-university', NULL, '{"title": "Lumbini Buddhist University", "extract": "Lumbini Buddhist University is a tertiary educational institution in Lumbini, Nepal, the birthplace of the Buddha. The idea for the university was conceived at the First World Buddhist Summit held in Lumbini in 1998, and it was officially formed on 17 June 2004. The Lumbini Buddhist University Act promulgated on 10 November 2006 confirmed its legal status as well as setting out that the university would receive financial assistance from the government of Nepal.", "content_url": "https://en.wikipedia.org/wiki/Lumbini_Buddhist_University", "description": "University in Napal"}', NULL, NULL, 'NP', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.543021+01', '2026-08-08 09:12:16.356228+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
