INSERT INTO public.spaces VALUES ('a21899ef-208f-424f-aac5-c88e7e1aa851', NULL, '00000000-0000-0000-0000-000000000064', 'UNESCO-IHE Institute for Water Education', 'unesco-ihe-institute-for-water-education', NULL, '{"title": "IHE Delft Institute for Water Education", "extract": "IHE Delft Institute for Water Education is the largest international graduate water education facility in the world and is based in Delft, Netherlands. IHE Delft cooperates with the city of Delft and water related institutes based in Delft. The Institute confers fully accredited MSc degrees, and PhD degrees together with partners in the Netherlands. Since 1957 the Institute has provided graduate education to more than 23,000 water professionals from over 190 countries, and is a flagship institute in the UN-Water family.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/ef/IHE_Delft_building_Westvest_7_Delft_LR.jpg/330px-IHE_Delft_building_Westvest_7_Delft_LR.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/IHE_Delft_Institute_for_Water_Education", "description": "Institute for water education in The Netherlands"}', '144ea94f-900f-40c2-a0c0-e55b549624b6', NULL, 'NL', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.543021+01', '2026-08-08 03:07:19.424643+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
