INSERT INTO public.spaces VALUES ('65d053b4-67be-46d9-ae66-606836bd422b', NULL, '00000000-0000-0000-0000-000000000064', 'University of Negros Occidental-Recoletos', 'university-of-negros-occidental-recoletos', NULL, '{"title": "University of Negros Occidental – Recoletos", "extract": "The University of Negros Occidental – Recoletos, Incorporated, is a private, Catholic coeducational basic and higher education institution administered by the Order of Augustinian Recollects in Bacolod, Negros Occidental, Philippines. It was founded in 1941.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/3/36/UNO-R_logo.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/University_of_Negros_Occidental_%E2%80%93_Recoletos", "description": "Roman Catholic university in Bacolod, Philippines"}', 'c0b182c4-d0b3-4bef-9979-6003023f3017', NULL, 'PH', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.573335+01', '2026-08-08 09:30:19.447871+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('ed5e1da8-2d4e-46fe-b6c9-86d00debcec4', NULL, '00000000-0000-0000-0000-000000000064', 'Korea Advanced Institute of Science & Technology', 'korea-advanced-institute-of-science-technology', NULL, '{"title": "KAIST", "extract": "KAIST is a national research university located in Daedeok Innopolis, Daejeon, South Korea. KAIST was established by the Korean government in 1971 as the nation''s first public, research-oriented science and engineering institution. KAIST has been internationally accredited in business education, and hosts the Secretariat of the Association of Asia-Pacific Business Schools (AAPBS). KAIST has 10,504 full-time students and 1,342 faculty researchers and had a total budget of US$765 million in 2013, of which US$459 million was from research contracts.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/0a/KAIST_logo.svg/330px-KAIST_logo.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/KAIST", "description": "South Korean public research university"}', 'df0bf896-93a5-4153-a3e3-d7df4ac9b81c', NULL, 'KR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.5184+01', '2026-08-09 08:42:15.881247+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
