INSERT INTO public.spaces VALUES ('9c00d578-512b-4949-a6ee-436a3ad7eb26', NULL, '00000000-0000-0000-0000-000000000064', 'St. Petersburg State Polytechnical University', 'st-petersburg-state-polytechnical-university', NULL, '{"title": "Peter the Great St. Petersburg Polytechnic University", "extract": "Peter the Great St. Petersburg Polytechnic University, abbreviated as SPbPU, is a public technical university located in Saint Petersburg, Russia. The university houses one of the country''s most advanced research labs in hydro–aerodynamics. The university''s alumni include Nobel Prize winners, such as Pyotr Kapitsa and Zhores Alferov, physicists and atomic weapon designers such as Yulii Khariton, Nikolay Dukhov, Abram Ioffe, Aleksandr Leipunskii, and Yakov Zeldovich, aircraft designers and aerospace engineers, such as Yulii Khariton, Oleg Antonov, Nikolai Polikarpov, and Georgy Beriev, and chess grandmasters, such as David Bronstein. The university offers academic programs at the Bachelor, Master''s, and Doctorate degree levels. SPbPU consists of structural units called Institutes divided into three categories: Engineering Institutes, Physical Institutes, and Economics and Humanities Institutes. In 2022, the university was ranked #301 in the world in the Times Higher Education (THE) World University Rankings, #393 in QS World University Rankings, #679 in Best Global Universities Rankings by U.S. News & World Report, and #1,005 by Center for World University Rankings.", "content_url": "https://en.wikipedia.org/wiki/Peter_the_Great_St._Petersburg_Polytechnic_University", "description": "Technical university in Saint Petersburg, Russia"}', NULL, NULL, 'RU', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.60068+01', '2026-08-08 09:49:18.620888+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
