INSERT INTO public.spaces VALUES ('651cb2e6-be58-4894-aa9d-6be507344e8c', NULL, '00000000-0000-0000-0000-000000000064', 'Kalmar University College', 'kalmar-university-college', NULL, '{"title": "Linnaeus University", "extract": "Linnaeus University (LNU) (Swedish: Linnéuniversitetet) is a state university in the historical province (landskap) of Småland, Sweden, with campuses located in the cities of Växjö and Kalmar. Linnaeus University was established in 2010 by a merger of former Växjö University and Kalmar University (Högskolan i Kalmar), and is named in honour of the Swedish botanist Carl Linnaeus.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/38/Kampradlectur.jpg/330px-Kampradlectur.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Linnaeus_University", "description": "University in Sweden"}', '3256df9b-1255-4b74-a4de-c3cf74558a54', NULL, 'SE', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.625787+01', '2026-08-08 10:06:20.386471+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
