INSERT INTO public.spaces VALUES ('92f835c7-1c38-455f-8c30-fcf6ffb0a233', NULL, '00000000-0000-0000-0000-000000000064', 'University of Arkansas Community College-Hope', 'university-of-arkansas-community-college-hope', NULL, '{"title": "University of Arkansas Hope-Texarkana", "extract": "The University of Arkansas Hope-Texarkana (UAHT) is a public community college in Hope and Texarkana, Arkansas. It is affiliated with the University of Arkansas System as a result a merger by act of the Arkansas Legislature in 1995 and is accredited by the North Central Association of Colleges and Schools. UAHT is an open-access institution that enrolls over 1,500 students at its 2 campuses. The college is located on a 72-acre site originally obtained by the citizens of the area for Red River Vocational-Technical School, which was established in 1965.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/43/UAHT_Logo_Red.png/330px-UAHT_Logo_Red.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/University_of_Arkansas_Hope-Texarkana", "description": "Community college in Arkansas, U.S."}', 'cccfd417-0c74-49bb-be28-64004abd4f1c', NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.679268+01', '2026-08-08 10:40:19.828165+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
