INSERT INTO public.spaces VALUES ('c1154e64-4d0e-49bd-8d87-ad3c41cf693e', NULL, '00000000-0000-0000-0000-000000000064', 'University of Science & Arts of Oklahoma', 'university-of-science-arts-of-oklahoma', NULL, '{"title": "University of Science and Arts of Oklahoma", "extract": "The University of Science and Arts of Oklahoma (USAO) is a public liberal arts college in Chickasha, Oklahoma. It is the only public college in Oklahoma with a strictly liberal arts–focused curriculum and is a member of the Council of Public Liberal Arts Colleges. USAO is an undergraduate-only institution and grants bachelor''s degrees in a variety of subject areas. The school was founded in 1908 as a school for women and from 1912 to 1965 was known as Oklahoma College for Women. It became coeducational in 1965 and today educates approximately 800 students. In 2001, the entire Oklahoma College for Women campus was listed as a national historic district.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/8/89/USAOklahoma_seal.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/University_of_Science_and_Arts_of_Oklahoma", "description": "Public university in Chickasha, Oklahoma, US"}', 'eed61503-9b66-4cf6-8aa3-035e32ad5c05', NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.262718+01', '2026-08-08 06:08:18.942058+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
