INSERT INTO public.spaces VALUES ('ae97a73c-8369-4f45-bd80-1d20f94464ce', NULL, '00000000-0000-0000-0000-000000000064', 'Sabzevar Teacher Training University', 'sabzevar-teacher-training-university', NULL, '{"title": "Hakim Sabzevari University", "extract": "Hakim Sabzevari University is one of the most developed public universities in Sabzevar city at Razavi Khorasan province, Iran.It was established in 1987 as a branch of Tarbiat Moallem University of Tehran but later became independent and it was renamed to Hakim Sabzevari University in 2011, after Hadi Sabzevari, a prominent Iranian philosopher and theologian. HSU offers 139 bachelors, masters, and Ph.D. programs to more than 8152 male and female students studying under about 263 faculty members in 10 departments. According to the Islamic World Science Citation Center statistics, HSU is ranked 41st in Iran amongst other universities of Ministry of Science, Research and Technology. The university currently consists of 10 faculties.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/e1/HakimSABZ.jpg/330px-HakimSABZ.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Hakim_Sabzevari_University", "description": "Public university in Iran"}', 'b87d302b-1dce-477c-ad19-5ef27efc1f58', NULL, 'IR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.465646+01', '2026-08-08 14:00:16.682777+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
