INSERT INTO public.spaces VALUES ('44070be8-2692-49db-9bd7-7fc97b334b3e', NULL, '00000000-0000-0000-0000-000000000064', 'Agder University College', 'agder-university-college', NULL, '{"title": "University of Agder", "extract": "The University of Agder, formerly known as Agder College and Agder University College, is a public university with campuses in Kristiansand and Grimstad, Norway. The institution was established as a university college (høgskole) in 1994 through the merger of the Agder University College and five other colleges, including a technical college and a nursing school, and was granted the status of a full university in 2007.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/54/Uiakristiansand.png/330px-Uiakristiansand.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/University_of_Agder", "description": "Public university in Norway"}', '95bf3c14-1ca6-40a3-87db-ea526bea94ff', NULL, 'NO', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.543021+01', '2026-08-08 09:18:18.911443+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
