INSERT INTO public.spaces VALUES ('8272ad16-c2b9-4197-882b-5786519fbe77', NULL, '00000000-0000-0000-0000-000000000064', 'St Cloud Technical and Community College', 'st-cloud-technical-and-community-college', NULL, '{"title": "St. Cloud Technical and Community College", "extract": "St. Cloud Technical and Community College is a public technical college and community college in St. Cloud, Minnesota, United States. Founded in 1948 and formerly called St. Cloud Technical College and St. Cloud Vocational Technical College, it is part of the Minnesota State Colleges and Universities system. The college grants Associate of Arts, Associate of Science, and Associate of Applied Science degrees in several majors; it also grants certificates and advanced technical certificates.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/e/e5/St._Cloud_Tech_logo.jpg/330px-St._Cloud_Tech_logo.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/St._Cloud_Technical_and_Community_College", "description": "Community college in St. Cloud, Minnesota, U.S."}', '04519914-0e3d-4382-84dd-f091228a72ab', NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-08 10:52:19.197943+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
