INSERT INTO public.spaces VALUES ('9568a7cf-9b1d-4275-bee3-98dc1a0d5739', NULL, '00000000-0000-0000-0000-000000000064', 'Dhaka University of Engineering and Technology', 'dhaka-university-of-engineering-and-technology', NULL, '{"title": "Dhaka University of Engineering & Technology, Gazipur", "extract": "Dhaka University of Engineering & Technology, Gazipur, commonly known as DUET, formerly BIT Dhaka, is a public engineering and technological research university in Gazipur, Bangladesh, which focuses on the study of engineering and architecture. DUET is one of the top engineering PhD granting research universities in Bangladesh. It requires diploma engineers candidates, graduated from polytechnic institutes or technical schools affiliated with the Bangladesh Technical Education Board for undergraduate enrollment.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/8/82/CrestofDUET.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Dhaka_University_of_Engineering_%26_Technology%2C_Gazipur", "description": "Public university in Gazipur, Bangladesh"}', '45c4365e-7c89-42b0-a4b1-0991453ca0b0', NULL, 'BD', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.296289+01', '2026-08-09 10:59:18.958554+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
