INSERT INTO public.spaces VALUES ('fae59346-e913-4322-b62c-81b1a18c4a36', NULL, '00000000-0000-0000-0000-000000000064', 'Defense Language Institute Foreign Language Center', 'defense-language-institute-foreign-language-center', NULL, '{"title": "Defense Language Institute", "extract": "The Defense Language Institute (DLI) is a United States Department of Defense (DoD) educational and research institution consisting of two separate entities which provide linguistic and cultural instruction to the Department of Defense, other federal agencies and numerous customers around the world. The Defense Language Institute is responsible for the Defense Language Program, and the bulk of the Defense Language Institute''s activities involve educating DoD members in assigned languages, and international personnel in English. Other functions include planning, curriculum development, and research in second-language acquisition.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/79/Defense_Language_Institute_copy.png/330px-Defense_Language_Institute_copy.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Defense_Language_Institute", "description": "Educational agency of the U.S. Department of Defense"}', '37472b8f-0c3c-493d-9608-a26a735875b1', NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.188857+01', '2026-08-08 12:24:16.943328+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
