INSERT INTO public.spaces VALUES ('d97a97f8-c502-4490-ac4b-1c328717b50c', NULL, '00000000-0000-0000-0000-000000000064', 'Helsinki School of Economics and Business Administration', 'helsinki-school-of-economics-and-business-administration', NULL, '{"title": "Aalto University School of Business", "extract": "The Aalto University School of Business is the largest business school in Finland. Founded in 1911, it is the second oldest business school in Finland and one of the oldest business schools in the Nordic countries. The school became part of Aalto University on 1 January 2010. It has been previously known as the Helsinki School of Economics, the Helsinki School of Economics and Business Administration, and during 2010–2012 the Aalto University School of Economics.", "content_url": "https://en.wikipedia.org/wiki/Aalto_University_School_of_Business", "description": "Business school in Espoo, Finland"}', NULL, NULL, 'FI', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.384776+01', '2026-08-08 18:23:19.34628+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
