INSERT INTO public.spaces VALUES ('4de92798-d79b-45fc-958a-652b9b6be18d', NULL, '00000000-0000-0000-0000-000000000064', 'Université Paris-Sorbonne (Paris IV)', 'universit-paris-sorbonne-paris-iv', NULL, '{"title": "Paris-Sorbonne University", "extract": "Paris-Sorbonne University was a public research university in Paris, France, active from 1971 to 2017. It was the main inheritor of the Faculty of Humanities of the University of Paris. In 2018, it merged with Pierre and Marie Curie University and some smaller entities to form a new university called Sorbonne University and became its Faculty of Arts and Humanities.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/4/42/Logo-Sorbonne.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Paris-Sorbonne_University", "description": "Former French university existing from 1971 to 2018"}', 'b30741c1-7d43-4109-beeb-263a867d1280', NULL, 'FR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.384776+01', '2026-08-08 13:15:19.734341+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
