INSERT INTO public.spaces VALUES ('afab2e7d-1662-4572-a6d0-7dbec5ad307a', NULL, '00000000-0000-0000-0000-000000000064', 'National Institute of Technology Durgapur', 'national-institute-of-technology-durgapur', NULL, '{"title": "National Institute of Technology, Durgapur", "extract": "National Institute of Technology Durgapur, formerly known as Regional Engineering College, Durgapur, is a public technical university in the city of Durgapur in West Bengal, India. Founded in 1960, it is one of India''s oldest technical universities. It is located on a campus of 187 acres (0.75 km²).", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/f/f1/NIT_Durgapur_Logo.svg/330px-NIT_Durgapur_Logo.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/National_Institute_of_Technology%2C_Durgapur", "description": "Public technical university in Durgapur, West Bengal"}', '6d23777f-2532-4062-be3d-bdefd9c99b1f', NULL, 'IN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.436788+01', '2026-08-08 18:52:19.605297+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
