INSERT INTO public.spaces VALUES ('c6637b89-7c0d-42c1-accb-4fe4ffa00ae3', NULL, '00000000-0000-0000-0000-000000000064', 'Indiana University - Bloomington', 'indiana-university-bloomington', NULL, '{"title": "Indiana University Bloomington", "extract": "Indiana University Bloomington is a public research university in Bloomington, Indiana, United States. It is the flagship campus of Indiana University and is its largest campus, with over 48,000 students. Established as the state''s seminary in 1820, the name was changed to \"Indiana College\" in 1829 and to \"Indiana University\" in 1838.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/5/5d/Indiana_University_seal.svg/330px-Indiana_University_seal.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Indiana_University_Bloomington", "description": "Public research university in Bloomington, Indiana, U.S."}', 'a013847f-b19a-411f-89b3-f3c326761237', NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.233464+01', '2026-08-09 10:29:19.404421+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
