INSERT INTO public.spaces VALUES ('0d5a1148-5701-43d6-9f29-275bb68062e8', NULL, '00000000-0000-0000-0000-000000000064', 'University of Engineering and Technology Peshawar', 'university-of-engineering-and-technology-peshawar', NULL, '{"title": "University of Engineering & Technology, Peshawar", "extract": "The University of Engineering and Technology, Peshawar , formerly known as NWFP University of Engineering and Technology, is a public university located in Peshawar, Khyber Pakhtunkhwa, Pakistan. Formerly known as NWFP University of Engineering and Technology until 2010, it an institution of higher learning in Pakistan with a strong emphasis on the development of science and engineering. The university offers undergraduate and post-graduate programs in various engineering disciplines. The university is also a member of the Association of Commonwealth Universities of the United Kingdom. The university was regarded as one of the best engineering schools in the country and was ranked in 7th position nationwide in the category of \"Engineering and Technology\" by HEC, the highest governing body of higher education in Pakistan. According to Times Higher Education World University Rankings 2023, the university is ranked in 801-1000th worldwide and in 251-300th position in Asia.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/9/95/University_of_Engineering_and_Technology_Peshawar_logo.svg/330px-University_of_Engineering_and_Technology_Peshawar_logo.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/University_of_Engineering_%26_Technology%2C_Peshawar", "description": "University in Peshawar, Pakistan"}', '3e4b1312-48a4-4754-b488-fa1f1c886d3d', NULL, 'PK', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.573335+01', '2026-08-08 20:04:16.967343+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
