INSERT INTO public.spaces VALUES ('2a5acc6b-e1fb-43ca-b797-1be881de1cf5', NULL, '00000000-0000-0000-0000-000000000064', 'George Fox College', 'george-fox-college', NULL, '{"title": "George Fox University", "extract": "George Fox University is a private Christian university in Newberg, Oregon, United States. Founded in 1891 as a school for Quakers, as of 2026, it is now the largest private university in Oregon with more than 4,000 students combined between its main campus in Newberg, its centers in Portland and Redmond, and online. The 108-acre (44 ha) main campus is near downtown Newberg, near the junction of Oregon Route 99W and Oregon Route 219. George Fox competes athletically at the NCAA Division III level in the Northwest Conference as the Bruins. The school colors are navy blue and old gold. The university is associated with the Evangelical Friends Church International and is a member of the Wesleyan Holiness Connection.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/7/78/George_fox_univ_seal.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/George_Fox_University", "description": "Christian university in Newberg, Oregon, US"}', '1ccdfb69-7025-481a-96e7-d64f31dcaa21', NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.188857+01', '2026-08-08 17:01:18.137012+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
