INSERT INTO public.spaces VALUES ('04327e9e-f59e-49e9-8669-4b459c63c8e2', NULL, '00000000-0000-0000-0000-000000000064', 'Federal University of Technology, Owerri', 'federal-university-of-technology-owerri', NULL, '{"title": "Federal University of Technology Owerri", "extract": "The Federal University of Technology Owerri (FUTO) is a federal university in Owerri West, Owerri, the capital of Imo State, Nigeria. The university is bounded by the communities of Eziobodo, Ihiagwa, Obinze, Okolochi and Emeabiam. It is the premier federal university of technology in Nigeria. The university was established in 1980 by Nigeria''s first executive president, Shehu Shagari to ensure Nigeria''s technological development.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/1/16/FUTO_logo.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Federal_University_of_Technology_Owerri", "description": "Public university in Owerri, Nigeria"}', '0e15ee49-ca99-4414-ab17-9334628767d1', NULL, 'NG', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.543021+01', '2026-08-09 00:36:20.615433+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
