INSERT INTO public.spaces VALUES ('7382096a-2a5b-49f3-9619-597bca5fca7b', NULL, '00000000-0000-0000-0000-000000000064', 'Asheville-Buncombe Technical Community College', 'asheville-buncombe-technical-community-college', NULL, '{"title": "Asheville–Buncombe Technical Community College", "extract": "Asheville–Buncombe Technical Community College is a public community college in Asheville, North Carolina. Established in 1959, the college is one of the oldest in the North Carolina Community College System and serves Buncombe and Madison counties across four different campuses, although students from anywhere may enroll. As of the 2014–15 school year, the curriculum enrollment was 10,070 and continuing education enrollment was 14,053 students. As of 2019–20, the college is the seventh largest in the North Carolina system and the largest in Western North Carolina. A-B Tech offers more than 120 degrees, diplomas, and certificates.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/c7/Asheville_Campus_aerial.jpg/330px-Asheville_Campus_aerial.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Asheville%E2%80%93Buncombe_Technical_Community_College", "description": "Public college in Asheville, North Carolina, US"}', '31a8eb82-930b-488c-9222-34fd4f01d201', NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-08 21:21:20.520345+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
