INSERT INTO public.spaces VALUES ('e9b5e495-766a-4073-bad1-15383bbdcfce', NULL, '00000000-0000-0000-0000-000000000064', 'Saveetha School of Engineering', 'saveetha-school-of-engineering', NULL, '{"title": "Saveetha Institute of Medical and Technical Sciences", "extract": "Saveetha Institute of Medical And Technical Sciences is a private and deemed-to-be-university located in Chennai, Tamil Nadu, India. It has nine disciplines of studies: Dental College, School of Management, School of Law, School of Engineering, College of Liberal Arts and Sciences, School of Physiotherapy, School of Nursing and Medical College. The first three disciplines are in Poonamalle while the rest are in Thandalam.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/2/21/Saveetha_Institute_of_Medical_And_Technical_Sciences_Logo.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Saveetha_Institute_of_Medical_and_Technical_Sciences", "description": "University in Tamil Nadu, India"}', '926b6840-8712-4a3f-bd8a-ac5f5a3b24f0', NULL, 'IN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.726322+01', '2026-08-08 21:38:17.593785+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('aef691c5-efe3-4641-a058-5f3016eb7ec8', NULL, '00000000-0000-0000-0000-000000000064', 'Southeast Technical Institute', 'southeast-technical-institute', NULL, '{"title": "Southeast Technical College", "extract": "Southeast Technical College (STC), sometimes called Southeast Tech, is a two-year technical community college in Sioux Falls, South Dakota, United States. Southeast Area Vocational Technical School was founded in 1968 and first operated out of various buildings across Sioux Falls. In 1989, it moved onto its current campus and changed its name to Southeast Vocational Technical Institute. It shortened its name to Southeast Technical Institute in 1993, before adopting its current name following a statewide restructure of the technical college system in 2020. It offers associate degrees and certificates in programs related to business, technology, healthcare, trades, and other sectors. The institution is accredited by the Higher Learning Commission (HLC).", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/da/Southeast_Tech.jpg/330px-Southeast_Tech.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Southeast_Technical_College", "description": "Community college in Sioux Falls, South Dakota, U.S."}', '4916ace0-62ef-4a9a-9569-7c3f6144576f', NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.726322+01', '2026-08-09 01:54:19.996744+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
