INSERT INTO public.spaces VALUES ('5d7a962b-30f1-4223-9402-9192230ad76f', NULL, '00000000-0000-0000-0000-000000000064', 'Mary Baldwin College', 'mary-baldwin-college', NULL, '{"title": "Mary Baldwin University", "extract": "Mary Baldwin University is a private university in Staunton, Virginia, United States. It was founded in 1842 as \"Augusta Female Seminary\". Mary Baldwin University is home to the Mary Baldwin College for Women, a residential college and women''s college with a focus on liberal arts and leadership, as well as co-educational residential college for undergraduate programs within its University College structure. MBU also offers co-educational graduate degrees as well as undergraduate degree and certificate programs for working professionals and non-traditional students.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/9/91/Mary_Baldwin_University_seal.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Mary_Baldwin_University", "description": "Private university in Staunton, Virginia, U.S."}', '58f7ffd7-45a3-45b3-a6c7-4528c2496cee', NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.233464+01', '2026-08-08 21:57:19.053555+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
