INSERT INTO public.spaces VALUES ('05d06178-349f-43e8-ae9c-d49cd22fbcf8', NULL, '00000000-0000-0000-0000-000000000064', 'University of Arkansas - Little Rock', 'university-of-arkansas-little-rock', NULL, '{"title": "University of Arkansas at Little Rock", "extract": "The University of Arkansas at Little Rock is a public research university in Little Rock, Arkansas, United States. The university resides on a 250-acre (100 ha) campus, which encompasses more than 56 buildings including the Center for Nanotechnology Integrative Sciences, the Emerging Analytics Center, the Sequoyah Research Center, and the Ottenheimer Library. Additionally, UA Little Rock houses special learning facilities that include a learning resource center, art galleries, KUAR public radio station, and a campus-wide wireless network. It is classified among \"R2: Doctoral Universities – High research activity\".", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/8/86/University_of_Arkansas_at_Little_Rock_Seal.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/University_of_Arkansas_at_Little_Rock", "description": "Public university in Little Rock, Arkansas, US"}', '29825dc7-45bb-46fe-9b18-3d12ff9776e6', NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.233464+01', '2026-08-09 02:34:22.16189+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('0e4e1782-f6bf-401d-a9e3-17a9adda002a', NULL, '00000000-0000-0000-0000-000000000064', 'University of Massachusetts at Dartmouth', 'university-of-massachusetts-at-dartmouth', NULL, '{"title": "University of Massachusetts Dartmouth", "extract": "The University of Massachusetts Dartmouth is a public research university in Dartmouth, Massachusetts. It is the southernmost campus of the University of Massachusetts system. Formerly \"Southeastern Massachusetts University\", it was merged into the University of Massachusetts system in 1991.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/2/24/University_of_Massachusetts_Dartmouth_seal.svg/330px-University_of_Massachusetts_Dartmouth_seal.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/University_of_Massachusetts_Dartmouth", "description": "Public university in Dartmouth, Massachusetts, U.S."}', 'c26ff822-2a44-4edb-b954-1ae5636642a0', NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.262718+01', '2026-08-09 02:36:22.458474+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
