INSERT INTO public.spaces VALUES ('9562c568-323c-43dc-aaed-ac163c044076', NULL, '00000000-0000-0000-0000-000000000064', 'St. Matthews University', 'st-matthews-university', NULL, '{"title": "St. Matthew''s University", "extract": "St. Matthew''s University (SMU) is a private medical school located on Grand Cayman, Cayman Islands in the Caribbean. SMU has a School of Medicine and a School of Veterinary Medicine, which confer Doctor of Medicine (MD) and Doctor of Veterinary Medicine (DVM) degrees, respectively. St. Matthew''s University is owned by Global University Systems, which also owns Saba University School of Medicine and Medical University of the Americas.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/2/2f/St._Matthew%27s_University_logo.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/St._Matthew''s_University", "description": "For-profit Cayman Islands university"}', 'f1d3b5f1-517d-4827-99a0-5726abe2b0a4', NULL, 'KY', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.326239+01', '2026-08-09 03:09:17.264808+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('e8d2f7c6-9a0d-464c-9297-d37b47762f6d', NULL, '00000000-0000-0000-0000-000000000064', 'Shandong Economic University', 'shandong-economic-university', NULL, '{"title": "Shandong University of Finance and Economics", "extract": "Shandong University of Finance and Economics is a public research university in Jinan, Shandong province, China. It is a full-time comprehensive institution of higher education which was founded upon approval by Shandong Provincial Government in 1952 and originally known as Shandong Institute of Finance and Economics. The current university resulted from a merger of two second-tier universities - the Shandong University of Finance (山东财政学院) and the Shandong Economic University (山东经济学院) in 2011.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/4/45/Shandong_university_finance_economics.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Shandong_University_of_Finance_and_Economics", "description": "Higher Education Institution in Shandong, China"}', 'ac0d7755-70f9-40bf-9f35-5e480dafd30c', NULL, 'CN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.353781+01', '2026-08-09 03:13:20.258463+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
