INSERT INTO public.spaces VALUES ('b427a2e3-e363-4512-b2b0-e4f9da803b4e', NULL, '00000000-0000-0000-0000-000000000064', 'University of Mysore', 'university-of-mysore', NULL, '{"title": "University of Mysore", "extract": "The University of Mysore is a public state university in Mysore, Karnataka, India. The university was founded during the reign of Maharaja Krishnaraja Wadiyar IV and the premiership of Sir M. Visvesvaraya. The university is recognised by the University Grants Commission for offering higher studies degree courses on-campus as well as online. It was inaugurated on 27 July 1916. Its first chancellor was the maharaja himself; the first Vice-Chancellor was H. V. Nanjundaiah. This was the first university outside of British administered Indian provinces, the sixth in the Indian subcontinent as a whole, and the first in Karnataka. It is a state university of the affiliating type, and was deemed autonomous within the Republic of India on 3 March 1956, when it gained recognition from the University Grants Commission.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/2/2c/Coat_of_arms_of_the_University_of_Mysore.svg/330px-Coat_of_arms_of_the_University_of_Mysore.svg.png", "content_url": "https://en.wikipedia.org/wiki/University_of_Mysore", "description": "State University in Karnataka"}', '5bed7caf-aded-45b8-9e42-102fa0ad8624', NULL, 'IN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.436788+01', '2026-08-08 23:40:01.005711+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
