INSERT INTO public.spaces VALUES ('b303fcd4-f5d5-4781-9b0d-62eddb1e8a7e', NULL, '00000000-0000-0000-0000-000000000064', 'Janus Pannonius University', 'janus-pannonius-university', NULL, '{"title": "University of Pécs", "extract": "The University of Pécs is one of the largest higher education institutions in Hungary. The history of the university began in the Middle Ages, when in 1367, at the request of King Louis I the Great, Pope Urban V granted permission to found the institution. This made it the first university in Hungary and the fourth in Central Europe.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/66/University_of_P%C3%A9cs%2C_logo_from_2025.svg/330px-University_of_P%C3%A9cs%2C_logo_from_2025.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/University_of_P%C3%A9cs", "description": "University in Hungary"}', 'aecb64ce-e727-4e85-91e8-aeabce79ddc0', NULL, 'HU', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.411195+01', '2026-08-09 03:43:17.638415+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('324cad9e-332a-42de-9ec2-c186ef223855', NULL, '00000000-0000-0000-0000-000000000064', 'University of Music and Fine Arts', 'university-of-music-and-fine-arts', NULL, '{"title": "Art school", "extract": "An art school is an educational institution with a primary focus on practice and related theory in the visual arts and design. This includes fine art – especially illustration, painting, contemporary art, sculpture, and graphic design. They may be independent or operate within a larger institution, such as a university. Some may be associated with an art museum.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/03/Bashkirtseff_-_In_the_Studio.jpg/330px-Bashkirtseff_-_In_the_Studio.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Art_school", "description": "Educational institution for visual arts"}', '3fad843d-b409-48a0-b69c-c069b15365e9', NULL, 'IN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.436788+01', '2026-08-09 03:49:19.763681+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
