INSERT INTO public.spaces VALUES ('9728f44f-8275-4356-9c3a-3a31a8dfdb2e', NULL, '00000000-0000-0000-0000-000000000064', 'University of Dublin, Trinity College', 'university-of-dublin-trinity-college', NULL, '{"title": "Trinity College Dublin", "extract": "The College of the Holy and Undivided Trinity of Queen Elizabeth near Dublin, branded by the board as Trinity College, the University of Dublin, and officially incorporated as Trinity College Dublin (TCD) (Irish: Coláiste na Tríonóide, Baile Átha Cliath), is the sole constituent college of the University of Dublin in Ireland. Founded in 1592 by Queen Elizabeth I through a royal charter, it is one of the seven ancient universities of Great Britain and Ireland. As Ireland''s oldest university, Trinity contributed to Irish literature during the Victorian and Georgian eras and played a notable role in the recognition of Dublin as a UNESCO City of Literature.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d7/The_entrance_of_the_historic_Trinity_College_%28Unsplash%29.jpg/330px-The_entrance_of_the_historic_Trinity_College_%28Unsplash%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Trinity_College_Dublin", "description": "Sole college of the University of Dublin"}', '63911924-dae8-41d6-b0f3-d285445f8a64', NULL, 'IE', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.465646+01', '2026-08-08 23:53:19.654374+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
