INSERT INTO public.spaces VALUES ('b378e5a1-2aff-4175-826d-1aeb8d2e55d8', NULL, '00000000-0000-0000-0000-000000000064', 'Lurleen B Wallace Community College', 'lurleen-b-wallace-community-college', NULL, '{"title": "Lurleen B. Wallace Community College", "extract": "Lurleen B. Wallace Community College (LBWCC) is a public community college with campuses in Andalusia, Greenville, Opp, and Luverne, Alabama. As of the fall 2010 semester, the college has an enrollment of 1,790 students across all campuses. The college was founded in 1969 and named for Governor Lurleen Burns Wallace. In 1992, it opened the campus in Greenville. In 2003, LBWCC merged with Douglas MacArthur State Technical College, which opened in 1965. Athletic teams representing LBWCC compete in the Alabama Community College Conference of the National Junior College Athletic Association.", "content_url": "https://en.wikipedia.org/wiki/Lurleen_B._Wallace_Community_College", "description": "Multi-campus public college in Alabama, US"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.679268+01', '2026-08-09 05:39:16.732959+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
