INSERT INTO public.spaces VALUES ('458e107c-0db3-4ccf-bcc6-12ba4dff77e5', NULL, '00000000-0000-0000-0000-000000000064', 'CUNY LaGuardia Community College', 'cuny-laguardia-community-college', NULL, '{"title": "LaGuardia Community College", "extract": "LaGuardia Community College is a public community college in New York City. It is in the Long Island City neighborhood of Queens in and part of the City University of New York. LaGuardia is named after former congressman and New York City mayor Fiorello H. LaGuardia. The college offers associate degrees in the arts, sciences, and applied sciences, as well as continuing education programs.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/97/LGCC_Bldg_E_across_Thomson_avenue_jeh.jpg/330px-LGCC_Bldg_E_across_Thomson_avenue_jeh.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/LaGuardia_Community_College", "description": "Community college in Queens, New York"}', 'd8eebb94-0b39-4281-b1dc-39657d3f4dab', NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-09 01:51:19.64816+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
