INSERT INTO public.spaces VALUES ('95fba515-a0c4-4885-9859-798c59cae176', NULL, '00000000-0000-0000-0000-000000000064', 'CUNY Hostos Community College', 'cuny-hostos-community-college', NULL, '{"title": "Hostos Community College", "extract": "Eugenio María de Hostos Community College of The City University of New York is a public community college in the South Bronx, New York City. It is part of the City University of New York (CUNY) system and was created by an act of the Board of Higher Education in 1968 in response to demands from the Hispanic/Puerto Rican community, which was urging for the establishment of a college to serve the people of the South Bronx. At the time it opened, it was considered the only bilingual education college in the region; this policy became more limited after 1997, but the college still offers many courses in Spanish. In 1970, the college admitted its first class of 623 students at the site of a former tire factory. Several years later, the college moved to a larger site nearby at 149th Street and Grand Concourse. The college also operates a location at the prow building of the Bronx Terminal Market.", "content_url": "https://en.wikipedia.org/wiki/Hostos_Community_College", "description": "Community college in the Bronx, New York, U.S."}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-09 05:53:19.966981+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
