INSERT INTO public.spaces VALUES ('bc89b113-0484-4b8f-8962-eecfdf2dac19', NULL, '00000000-0000-0000-0000-000000000064', 'St. Petersburg State Theatre Arts Academy', 'st-petersburg-state-theatre-arts-academy', NULL, '{"title": "Russian State Institute of Performing Arts", "extract": "The Russian State Institute of Performing Arts, formerly known as St Petersburg Theatre Arts Academy, formerly Leningrad State Institute of Theatre, Music, and Cinema (LGITMiK), is a theatre school in Saint Petersburg. It is the oldest Russian state theatre school, being founded in 1779, and has incorporated several mergers of other institutions during its history, including the Ostrovsky Leningrad Theatre Institute and the Leningrad Institute of Art History.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/33/St._Petersburg_State_Theatre_Arts_Academy.jpg/330px-St._Petersburg_State_Theatre_Arts_Academy.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Russian_State_Institute_of_Performing_Arts", "description": "Theatre school in St. Petersburg, Russia"}', '9d0c2dd5-a616-4e40-9167-baa2801f3cf3', NULL, 'RU', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.60068+01', '2026-08-11 11:46:05.458662+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
