INSERT INTO public.spaces VALUES ('5df8ddd4-5427-404f-a6ff-74fa548876c4', NULL, '00000000-0000-0000-0000-000000000064', 'Tucson University', 'tucson-university', NULL, '{"title": "University of Arizona", "extract": "The University of Arizona is a public land-grant research university in Tucson, Arizona, United States. Founded in 1885 by the 13th Arizona Territorial Legislature, it was the first university established in the Arizona Territory. The University of Arizona is one of three universities governed by the Arizona Board of Regents. As of fall 2025, the university enrolled 54,384 students in 22 separate colleges/schools, including the Eller College of Management, the Wyant College of Optical Sciences, the College of Medicine – Phoenix, the College of Medicine – Tucson, and the James E. Rogers College of Law.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/e/e4/University_of_Arizona_seal.svg/330px-University_of_Arizona_seal.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/University_of_Arizona", "description": "Public university in Tucson, Arizona, US"}', '9226a3cd-2a4a-4caf-ae0b-cbd56a6296c1', NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.233464+01', '2026-08-12 01:12:16.040866+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('f94d42fd-2189-43e3-bc7d-f2ee95133e3b', NULL, '00000000-0000-0000-0000-000000000064', 'University of Missouri - Rolla', 'university-of-missouri-rolla', NULL, '{"title": "Missouri University of Science and Technology", "extract": "The Missouri University of Science and Technology is a public research university in Rolla, Missouri, United States. It is a member institution of the University of Missouri System. Most of its 6,456 students (2023) study engineering, business, sciences, and mathematics. Known primarily for its engineering school, Missouri S&T offers degree programs in business and management systems, information science and technology, sciences, social sciences, humanities, and arts. It is classified as a \"STEM-dominant\", R1 university with \"very high research spending and doctorate production\".", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/8/87/Missouri_University_of_Science_and_Technology_emblem.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Missouri_University_of_Science_and_Technology", "description": "Public university in Rolla, Missouri, US"}', '14dac4f8-c7ab-4791-93a4-4ce84bd9dae5', NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.262718+01', '2026-08-12 01:12:16.99593+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('c71ac67b-e1a1-495b-8375-cac44669d7a9', NULL, '00000000-0000-0000-0000-000000000064', 'Palm Beach Atlantic College', 'palm-beach-atlantic-college', NULL, '{"title": "Palm Beach Atlantic University", "extract": "Palm Beach Atlantic University (PBA) is a private nondenominational Christian university in West Palm Beach, Florida. PBA''s nine colleges focus on the liberal arts with a select collection of professional studies. In 2024, PBA''s undergraduate enrollment was approximately 2,600.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/34/Pbau_staduents_%28cropped%29.jpg/330px-Pbau_staduents_%28cropped%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Palm_Beach_Atlantic_University", "description": "Christian university in West Palm Beach, Florida, U.S."}', 'd7cf338d-e0d0-42a4-8558-2b25a164504e', NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.233464+01', '2026-08-12 01:13:17.83087+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
