INSERT INTO public.spaces VALUES ('840147cf-7376-4662-b4a8-4c52879722d5', NULL, '00000000-0000-0000-0000-000000000064', 'Grodno State Agrarian University', 'grodno-state-agrarian-university', NULL, '{"title": "Grodno State Agrarian University", "extract": "The Grodno State Agrarian University is one of four agricultural universities in Belarus, established in 1951 in Grodno. It employs over 760 staff including over 320 academic educators. The GSAU offers some 13 different fields of study, 7 faculties in Agricultural Sciences, Economic Sciences, Veterinary Medicine, Food Production.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/90/Logo-ggau-1024.png/330px-Logo-ggau-1024.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Grodno_State_Agrarian_University", "description": "Public university in Grodno, Belarus"}', '1eed9d32-f25e-424b-b8f1-b46a5c365a9b', NULL, 'BY', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.296289+01', '2026-08-12 01:18:16.254129+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
