INSERT INTO public.spaces VALUES ('38185887-d3cc-4d6d-b2d9-b5d2271170b8', NULL, '00000000-0000-0000-0000-000000000064', 'Université Paul Sabatier (Toulouse III)', 'universit-paul-sabatier-toulouse-iii', NULL, '{"title": "Toulouse III - Paul Sabatier University", "extract": "Paul Sabatier University was a French university, in the Academy of Toulouse. It was one of the several successor universities of the University of Toulouse, established in 1229, making it one of the earliest universities to emerge in Europe. On January 1, 2023, the existing Toulouse University System, which included Toulouse III, was renamed the Université de Toulouse. Then, on January 1, 2025, Toulouse III – Paul Sabatier University adopted the name Université de Toulouse, absorbing and incorporating the former Toulouse University System, with the Purpan Engineering School as a graduate school.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/2/29/Paul_Sabatier_University_%28logo%29.svg/330px-Paul_Sabatier_University_%28logo%29.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Toulouse_III_-_Paul_Sabatier_University", "description": "French university founded in 1229"}', '619d8d9e-8bb1-4696-b2ac-74e348dff16c', NULL, 'FR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.384776+01', '2026-08-12 01:25:17.315015+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
