INSERT INTO public.spaces VALUES ('43465672-5504-4afd-8252-73666042429b', NULL, '00000000-0000-0000-0000-000000000064', 'Osaka University of Education', 'osaka-university-of-education', NULL, '{"title": "Osaka Kyoiku University", "extract": "Osaka Kyoiku University  is a national university with headquarters in the city of Kashiwara, Osaka Prefecture, Japan and a branch campus in Tennōji-ku in the prefectural capital city of Osaka. It was established in 1949 by the merger of two predecessor institutions. Its short name is Daikyōdai. The university specializes in educating teachers. Unique among the national universities is its five-year program of nighttime study.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/96/Oosakakyoiku.jpg/330px-Oosakakyoiku.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Osaka_Kyoiku_University", "description": ""}', 'd5191406-0605-49d0-83f3-fdebb15f60c2', NULL, 'JP', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.493186+01', '2026-08-12 01:36:17.540403+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
