INSERT INTO public.spaces VALUES ('f205600b-8aa6-406a-b322-72981e754b2f', NULL, '00000000-0000-0000-0000-000000000064', 'Mendel University of Agriculture and Forestry', 'mendel-university-of-agriculture-and-forestry', NULL, '{"title": "Mendel University in Brno", "extract": "Mendel University in Brno is located in Brno, Czech Republic. It was founded on 24 July 1919 on the basis of the former Tábor Academy. The university comprises five faculties and one institute - the Faculty of AgriSciences, Faculty of Forestry and Wood Technology, Faculty of Business and Economics, Faculty of Horticulture, Faculty of Regional Development and International Studies and Institute of Lifelong Education. Since 1994, the university has been named afterGregor Johann Mendel, the botanist and \"father of genetics\", who conducted much of his research in Brno.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/90/Mendelu_logo_2019.jpg/330px-Mendelu_logo_2019.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Mendel_University_in_Brno", "description": "Agricultural university in Brno, Czech Republic"}', '699a7a8b-1d17-491a-b13c-49aea209c70d', NULL, 'CZ', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.353781+01', '2026-08-14 01:44:21.119267+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
