INSERT INTO public.spaces VALUES ('d0154541-888e-4f5d-8967-811724ae4fc4', NULL, '00000000-0000-0000-0000-000000000064', 'Orissa University of Agriculture and Technology', 'orissa-university-of-agriculture-and-technology', NULL, '{"title": "Odisha University of Agriculture and Technology", "extract": "Odisha University of Agriculture and Technology (OUAT) was established in Bhubaneswar, Odisha, India in 1962 by then Chief Minister Shri Biju Patnaik. It is the second oldest agricultural university in the country. It is dedicated to agriculture-related research, extension and education.\nThe university has 11 constituent colleges and separate wings for research, extension services and planning, monitoring & evaluation, etc.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/9/90/Orissa_University_of_Agriculture_and_Technology_logo.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Odisha_University_of_Agriculture_and_Technology", "description": "Public agricultural university in Odisha, India"}', '917cb5a4-bbb8-47cc-b5e7-7a15541d055e', NULL, 'IN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.411195+01', '2026-08-16 21:04:21.98136+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('6a881159-b787-4187-bf85-8eae12c073a5', NULL, '00000000-0000-0000-0000-000000000064', 'University of Wisconsin - Stevens Point', 'university-of-wisconsin-stevens-point', NULL, '{"title": "University of Wisconsin–Stevens Point", "extract": "The University of Wisconsin–Stevens Point is a public university in Stevens Point, Wisconsin, United States. Established in 1894, it is part of the University of Wisconsin System. UW-Stevens Point grants associate, baccalaureate, and master''s degrees, as well as doctoral degrees in audiology, educational sustainability, and physical therapy. The 406-acre (164 ha) main campus includes the 280-acre (113 ha) Schmeeckle Reserve, 15 academic buildings, and 13 residence halls. UWSP also has two branch campuses located in Wausau and Marshfield.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/8/8d/UW-Stevens_Point_Logo.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/University_of_Wisconsin%E2%80%93Stevens_Point", "description": "Public university in Stevens Point, Wisconsin, US"}', '81cbb6b7-9e6f-405a-8af0-33513467d0a0', NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.262718+01', '2026-08-16 21:04:35.353444+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
