INSERT INTO public.spaces VALUES ('69bc03d6-4d7e-42fb-be27-16ec5a909611', NULL, '00000000-0000-0000-0000-000000000064', 'University of Milan - Bicocca', 'university-of-milan-bicocca', NULL, '{"title": "University of Milano-Bicocca", "extract": "The University of Milano-Bicocca is a public university located in Milan, Italy, providing undergraduate, graduate and post-graduate education. Established in 1998, it was ranked by the Times Higher Education 2014 ranking of the best 100 Universities under 50 years old as number 21 worldwide and first in Italy. It was created to reduce University of Milan''s overload.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/2/25/Milano-Bicocca_University_logo.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/University_of_Milano-Bicocca", "description": "Public university in Milan, Italy"}', '212a6745-e5f1-45c7-89a9-68f952d826c1', NULL, 'IT', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.465646+01', '2026-08-18 19:06:18.087939+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
