INSERT INTO public.spaces VALUES ('c82f8286-88ab-46d4-b2eb-4ec5bc63ce07', NULL, '00000000-0000-0000-0000-000000000064', 'National Institute of Technology Warangal', 'national-institute-of-technology-warangal', NULL, '{"title": "National Institute of Technology, Warangal", "extract": "The National Institute of Technology Warangal is a public technical and research university located in Warangal, India. It is recognised as an Institute of National Importance by the Government of India. The foundation stone for this institute was laid by then Prime Minister Jawaharlal Nehru on 10 October 1959, the first in the chain of 31 NITs in the country. The institute was renamed as the National Institute of Technology, Warangal in 2002.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/f/fb/National_Institute_of_Technology%2C_Warangal_logo.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/National_Institute_of_Technology%2C_Warangal", "description": "Engineering institute in Warangal, India"}', '3787dad8-b602-4b39-a3e8-e98978376fea', NULL, 'IN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.436788+01', '2026-08-24 00:15:08.696889+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('3f65e8a9-5f61-4770-99de-e1ce2b8738f7', NULL, '00000000-0000-0000-0000-000000000064', 'Technical University of Iasi', 'technical-university-of-iasi', NULL, '{"title": "Gheorghe Asachi Technical University of Iași", "extract": "The Gheorghe Asachi Technical University of Iași is a public university located in Iași, Iași County, Western Moldavia, Romania. Classified by the Ministry of Education as an advanced research and education university, it has the oldest tradition in Romania in engineering education. Gheorghe Asachi Technical University is a member of the Romanian Alliance of Technical Universities (ARUT).", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/6/65/TUI_Iasi_Seal.gif?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Gheorghe_Asachi_Technical_University_of_Ia%C8%99i", "description": "Public university in Iași, Romania"}', 'f288e7d3-1928-439b-805a-b07f3d276713', NULL, 'RO', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.60068+01', '2026-08-24 00:10:12.477217+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
