INSERT INTO public.spaces VALUES ('522db436-fd55-4d89-bd29-52806ffd837f', NULL, '00000000-0000-0000-0000-000000000064', 'Paichai University', 'paichai-university', NULL, '{"title": "Pai Chai University", "extract": "Pai Chai University (Korean: 배재대학교) is a private university located in Daejeon, South Korea. It is one of the oldest modern universities in the country. Its campus is located in Seo-gu, in Daejeon metropolitan city, on the lower slopes of Yeonja Mountain. It has a present-day student body of about 14,000. Undergraduate programs are administered by the Colleges of Humanities, Foreign Studies, Business Administration, Social Sciences, Tourism Management, Natural Sciences, Engineering, Performing Inter-media Arts and Fine Arts. Numerous graduate programs in these fields are provided as well.", "content_url": "https://en.wikipedia.org/wiki/Pai_Chai_University", "description": "University in Daejeon, South Korea"}', NULL, NULL, 'KR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.5184+01', '2026-08-31 02:30:03.724069+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('8bbd23eb-8db5-4e9b-94ad-232e5e86c8f6', NULL, '00000000-0000-0000-0000-000000000060', 'Antarctica', 'antarctica', 'Rooted here, reaching across continents — this space bridges home and diaspora. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "Antarctica", "extract": "Antarctica is Earth''s southernmost and least-populated continent. Situated almost entirely south of the Antarctic Circle and surrounded by the Southern Ocean, it contains the geographic South Pole. Antarctica is the fifth-largest continent, being about 40% larger than Europe, and has an area of 14,200,000 km2 (5,500,000 sq mi). Most of Antarctica is covered by the Antarctic ice sheet, with an average thickness of 1.9 km (1.2 mi).", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/f2/Antarctica_%28orthographic_projection%29.svg/330px-Antarctica_%28orthographic_projection%29.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Antarctica", "description": "Earth''s southernmost continent"}', '9801c192-7bf1-4001-a5e7-556fada0ca79', NULL, 'AQ', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:02.824883+01', NULL, NULL, '{antarctica,aq,community,diaspora}', NULL, 'Polar', 'Global', NULL);
