INSERT INTO public.spaces VALUES ('1787ab41-74c7-4909-8edf-f253257ffe6d', NULL, '00000000-0000-0000-0000-000000000064', 'Semmelweis University of Medical Sciences', 'semmelweis-university-of-medical-sciences', NULL, '{"title": "Semmelweis University", "extract": "Semmelweis University is a research-led medical school in Budapest, Hungary, founded in 1769. With six faculties and a doctoral school it covers all aspects of medical and health sciences.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/07/Logo_univsemmelweis.svg/330px-Logo_univsemmelweis.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Semmelweis_University", "description": "Hungarian medical school"}', '3856a089-61dc-45bc-9cc1-5ecaf6bba0c9', NULL, 'HU', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.411195+01', '2026-08-27 06:01:08.360356+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
