INSERT INTO public.spaces VALUES ('e9b94d16-3a26-4668-baca-ee178f4fce57', NULL, '00000000-0000-0000-0000-000000000060', 'Barbados', 'barbados', 'Rooted here, reaching across continents — this space bridges home and diaspora. Bridgetown is the capital. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "Barbados", "extract": "Barbados is an island nation in the Caribbean located in the Atlantic Ocean. It is part of the Lesser Antilles of the West Indies and is the southern and easternmost island of the Caribbean region. It lies on the boundary of the South American and Caribbean plates. Its capital and largest city is Bridgetown.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/ef/Flag_of_Barbados.svg/330px-Flag_of_Barbados.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Barbados", "description": "Island nation in the Atlantic Ocean"}', '01baec78-fbfe-41a8-a54a-c91fcfd3c1f2', NULL, 'BB', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:07.873026+01', NULL, NULL, '{barbados,bb,island,community,diaspora}', NULL, 'Americas', 'Caribbean', NULL);
INSERT INTO public.spaces VALUES ('dcd1d99a-89f6-41e4-a58b-f03c2a0cedb3', NULL, '00000000-0000-0000-0000-000000000060', 'South Africa', 'south-africa', 'From Southern Africa to cities and towns across the globe — this is the gathering point for a diaspora that never lost touch with home. It is set in Southern Africa. Share local news, discover events, trade on the marketplace, and tap into remittance rates, scholarship finds, and community resources — all in one place.', '{"title": "South Africa", "extract": "South Africa, officially the Republic of South Africa (RSA), is the southernmost country in Africa. Its nine provinces are bounded to the south by 2,798 kilometres of coastline that stretches along the South Atlantic, and Indian Ocean; to the north by the neighbouring countries of Namibia, Botswana, and Zimbabwe \nto the east and northeast by Mozambique, and Eswatini, and it encloses Lesotho. Covering an area of 1,221,037 square kilometres, the country has a population of over 63 million people, making it the sixth-most populated country in Africa.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/af/Flag_of_South_Africa.svg/330px-Flag_of_South_Africa.svg.png", "content_url": "https://en.wikipedia.org/wiki/South_Africa", "description": "Country in Southern Africa"}', '731b5e07-5ba2-4f99-afc8-236de95de307', NULL, 'ZA', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-07-08 23:07:05.600578+01', '2026-08-07 11:45:41.178987+01', NULL, 'ZAR', '{"south africa",south-africa,za,africa,community,diaspora}', NULL, 'Africa', 'Southern Africa', NULL);
INSERT INTO public.spaces VALUES ('08c8955e-2e54-4864-9f06-16f3a1f8fb57', NULL, '00000000-0000-0000-0000-000000000060', 'Burundi', 'burundi', 'Every journey out of East Africa carries a story — of ambition, of longing, of roots that stretch but never break. From the Rift Valley to the cities where the diaspora now lives, the connection to home runs deep. Discover local businesses, share news from home, find events near you, and build a network that spans borders — all on JapaConnect.', '{"title": "Burundi", "extract": "Burundi, officially the Republic of Burundi, is a landlocked country in East Africa. It is located in the Great Rift Valley at the junction between the African Great Lakes region and Southeastern Africa, with a population of over 14 million people. It is bordered by Rwanda to the north, Tanzania to the east and southeast, and the Democratic Republic of the Congo to the west; Lake Tanganyika lies along its southwestern border. The political capital city is Gitega and the economic capital and largest city is Bujumbura.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/50/Flag_of_Burundi.svg/330px-Flag_of_Burundi.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Burundi", "description": "Country in East Africa"}', '9142d1bf-4667-4a7a-8854-93b714f87698', NULL, 'BI', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:16.45277+01', NULL, NULL, '{burundi,bi,africa,landlocked,community,diaspora}', NULL, 'Africa', 'Eastern Africa', NULL);
INSERT INTO public.spaces VALUES ('591a6daf-7ec8-4c3e-8c74-6d16aae3f63d', NULL, '00000000-0000-0000-0000-000000000060', 'Cambodia', 'cambodia', 'Every journey out of Southeast Asia carries a story — of ambition, of longing, of roots that stretch but never break. Discover local businesses, share news from home, find events near you, and build a network that spans borders — all on JapaConnect.', '{"title": "Cambodia", "extract": "Cambodia, officially the Kingdom of Cambodia, is a country in Mainland Southeast Asia. It is bordered by Thailand to the northwest, Laos to the north, and Vietnam to the east, and has a coastline along the Gulf of Thailand in the southwest. It spans an area of about 181,035 km2 (69,898 sq mi), dominated by a low-lying plain and the confluence of the Mekong river and Tonlé Sap, Southeast Asia''s largest lake. It is dominated by a tropical climate. Cambodia has a population of about 17 million people, the majority of which are ethnically Khmer. Its capital and most populous city is Phnom Penh, followed by Siem Reap and Battambang.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/83/Flag_of_Cambodia.svg/330px-Flag_of_Cambodia.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Cambodia", "description": "Country in Southeast Asia"}', '0379b59d-cbb5-45bd-85ed-345c4b122fb2', NULL, 'KH', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:16.957288+01', NULL, NULL, '{cambodia,kh,asia,community,diaspora}', NULL, 'Asia', 'South-Eastern Asia', NULL);
INSERT INTO public.spaces VALUES ('01ce90a1-6d06-4121-babf-a2c01dd72a6a', NULL, '00000000-0000-0000-0000-000000000060', 'Eswatini', 'eswatini', 'Smallest country in Africa in Southern Africa, shaped by mountainous terrain. It is set in Southern Africa, landlocked, sharing borders with Africa and Mozambique, with Mbabane as its capital. From the streets of Mbabane to diaspora communities worldwide, this is your space to connect, trade, and stay rooted.', '{"title": "Eswatini", "extract": "Eswatini, formally the Kingdom of Eswatini, also known by its former official names Swaziland and the Kingdom of Swaziland, is a landlocked country in Southern Africa. It is bordered by South Africa on all sides except the east, where it shares a border with Mozambique. At no more than 200 km (120 mi) north to south and 130 km (81 mi) east to west, Eswatini is the second smallest country in Africa. However, its climate and topography are diverse, ranging from a cool and mountainous highveld to a hot and dry lowveld. The executive capital and largest city is Mbabane, and the legislative and second capital is Lobamba.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/fb/Flag_of_Eswatini.svg/330px-Flag_of_Eswatini.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Eswatini", "description": "Country in Southern Africa"}', '45109e76-9113-4c52-b4e8-627f6e192d04', NULL, 'SZ', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:33.098145+01', NULL, NULL, '{eswatini,sz,africa,landlocked,community,diaspora}', NULL, 'Africa', 'Southern Africa', NULL);
INSERT INTO public.spaces VALUES ('24c34aba-dbd8-4ca9-b4a2-dc5acb6ce045', NULL, '00000000-0000-0000-0000-000000000060', 'Ethiopia', 'ethiopia', 'Every journey out of East Africa carries a story — of ambition, of longing, of roots that stretch but never break. From tectonic plate boundaries to the cities where the diaspora now lives, the connection to home runs deep. Discover local businesses, share news from home, find events near you, and build a network that spans borders — all on JapaConnect.', '{"title": "Ethiopia", "extract": "Ethiopia, officially the Federal Democratic Republic of Ethiopia (FDRE), is a landlocked country located in the Horn of Africa region of East Africa. It shares borders with Eritrea to the north, Djibouti to the northeast, Somalia to the southeast, Kenya to the south, South Sudan to the west, and Sudan to the northwest. Ethiopia covers a land area of 1,104,300 km2 (426,400 sq mi). As of 2026, it has around 138 million inhabitants, making it the 10th-most populous country in the world and 2nd most populous country in Africa. The national capital and largest city, Addis Ababa, lies several kilometres west of the East African Rift that splits the country into the African and Somali tectonic plates.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/71/Flag_of_Ethiopia.svg/330px-Flag_of_Ethiopia.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Ethiopia", "description": "Country in East Africa"}', '723cb004-befd-40c7-ac6e-93bad4eb435c', NULL, 'ET', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:33.601592+01', NULL, NULL, '{ethiopia,et,africa,landlocked,community,diaspora}', NULL, 'Africa', 'Eastern Africa', NULL);
INSERT INTO public.spaces VALUES ('0d1185ef-e36c-4c95-8c30-c828125960fa', NULL, '00000000-0000-0000-0000-000000000060', 'French Guiana', 'french-guiana', 'Your digital anchor — wherever the diaspora has settled, this is home base. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "French Guiana", "extract": "French Guiana, also known by its French name Guyane, is an overseas department and region of France located on the northern coast of South America in the Guianas and the West Indies. Bordered by Suriname to the west and Brazil to the east and south, French Guiana covers a total area of 84,000 km2 (32,000 sq mi) and a land area of 83,534 km2 (32,253 sq mi). As of January 2026, it is home to 298,554 people.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/97/French_Guiana_in_France_2016.svg/330px-French_Guiana_in_France_2016.svg.png", "content_url": "https://en.wikipedia.org/wiki/French_Guiana", "description": "Overseas department of France"}', '543e4769-326f-41ce-a64a-46f3e19478ee', NULL, 'GF', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:36.619671+01', NULL, 'EUR', '{"french guiana",french-guiana,gf,community,diaspora}', NULL, 'Americas', 'South America', NULL);
INSERT INTO public.spaces VALUES ('926aaf5f-2067-4642-89a3-935821d0cd71', NULL, '00000000-0000-0000-0000-000000000060', 'Chad', 'chad', 'Surrounded by Libya, Sudan, Central African Republic, and Cameroon, yet its people have crossed every border and ocean — this space bridges home and diaspora. A population of 20 million calls it home. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "Chad", "extract": "Chad, officially the Republic of Chad, is a landlocked country in Central Africa. It is bordered by Libya to the north, Sudan to the east, the Central African Republic to the south, Cameroon to the southwest, Nigeria to the southwest, and Niger to the west. Chad has a population of 20 million, of which 1.6 million live in the capital and largest city of N''Djamena. With a total area of around 1,300,000 km2 (500,000 sq mi), Chad is the fifth-largest country in Africa and the twentieth largest nation by area.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/4b/Flag_of_Chad.svg/330px-Flag_of_Chad.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Chad", "description": "Country in Central Africa"}', '3a368d85-a27d-4924-b9f8-1b140e839efb', NULL, 'TD', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:19.978942+01', NULL, NULL, '{chad,td,africa,landlocked,community,diaspora}', NULL, 'Africa', 'Middle Africa', NULL);
INSERT INTO public.spaces VALUES ('064b3e30-35ae-47d1-b769-ec7d47b7a938', NULL, '00000000-0000-0000-0000-000000000060', 'Congo', 'congo', 'Your digital anchor — wherever the diaspora has settled, this is home base. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "Congo", "extract": "Congo or The Congo may refer to:Congo River, in central Africa\nCongo Basin, the sedimentary basin of the river\nDemocratic Republic of the Congo, the larger country to the southeast, sometimes referred to as \"Congo-Kinshasa\"\nRepublic of the Congo, the smaller country to the northwest, sometimes referred to as \"Congo-Brazzaville\"", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/3b/Disambiguator_map_for_countries_named_Congo.svg/330px-Disambiguator_map_for_countries_named_Congo.svg.png", "content_url": "https://en.wikipedia.org/wiki/Congo", "description": "Topics referred to by the same term"}', '5f4ed895-784d-4ba4-8c99-15f4d0dd9f82', NULL, 'CG', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:23.506208+01', NULL, NULL, '{congo,cg,community,diaspora}', NULL, 'Africa', 'Middle Africa', NULL);
INSERT INTO public.spaces VALUES ('85f9e0a3-c442-48c7-be2c-dddecf3a97c7', NULL, '00000000-0000-0000-0000-000000000060', 'Georgia', 'georgia', 'Your digital anchor — wherever the diaspora has settled, this is home base. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "Georgia", "extract": "Georgia most commonly refers to:Georgia (country), a country in the South Caucasus\nGeorgia, a state in the United States", "thumbnail": "", "content_url": "https://en.wikipedia.org/wiki/Georgia", "description": "Topics referred to by the same term"}', '4d554c10-790c-488a-a6d5-ac898cf245f5', NULL, 'GE', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:38.631702+01', NULL, NULL, '{georgia,ge,community,diaspora}', NULL, 'Asia', 'Western Asia', NULL);
INSERT INTO public.spaces VALUES ('f1c4ca64-76a7-48b0-a28d-53fd1fd37dd1', NULL, '00000000-0000-0000-0000-000000000060', 'Jordan', 'jordan', 'It is set in West Asia, sharing borders with Syria, Iraq, Saudi Arabia, and Israel. Whether you''re still in West Asia or building a life elsewhere, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Jordan", "extract": "Jordan, officially the Hashemite Kingdom of Jordan, is a country in the Southern Levant region of West Asia. Jordan is bordered by Syria to the north, Iraq to the east, Saudi Arabia to the south, and both Israel and Palestine to the west. The Jordan River, flowing into the Dead Sea, is located along the country''s western border within the Jordan Rift Valley. Jordan has a small coastline along the Red Sea in its southwest, separated by the Gulf of Aqaba from Egypt. Amman is the country''s capital and largest city, as well as the most populous city in the Levant.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/c0/Flag_of_Jordan.svg/330px-Flag_of_Jordan.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Jordan", "description": "Country in West Asia"}', 'd55e6910-ebc6-4ebd-a192-401d316fe9fb', NULL, 'JO', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:54.269382+01', NULL, NULL, '{jordan,jo,asia,community,diaspora}', NULL, 'Asia', 'Western Asia', NULL);
INSERT INTO public.spaces VALUES ('e35ceebe-b0ad-4dba-9cf0-423d41bb7f39', NULL, '00000000-0000-0000-0000-000000000060', 'Mali', 'mali', 'Your digital anchor in West Africa — from Bamako to the farthest corners of the diaspora, everything flows through here. A landlocked nation whose people have crossed every border to build lives abroad. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "Mali", "extract": "Mali, officially the Republic of Mali, is a landlocked country in West Africa. It is the eighth-largest country in Africa and the 23rd largest country in the world, with an area of 1,240,192 square kilometres (478,841 sq mi). It is bordered to the north by Algeria, to the east by Niger, to the northwest by Mauritania, to the south by Burkina Faso and Ivory Coast, and to the west by Guinea and Senegal. The population is about 25.20 million, 47.19% of which are estimated to be under age 15 in 2024. Its capital and largest city is Bamako. French was the official language until 2022, when it was replaced by 13 African languages, with Bambara being the first language of the majority of the population.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/92/Flag_of_Mali.svg/330px-Flag_of_Mali.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Mali", "description": "Country in West Africa"}', '591d816a-d23b-469d-b8e5-fba4d8f9c1fa', NULL, 'ML', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:04.861729+01', NULL, NULL, '{mali,ml,africa,landlocked,community,diaspora}', NULL, 'Africa', 'Western Africa', NULL);
INSERT INTO public.spaces VALUES ('bd5e9bef-61f8-4caa-ac19-d1a3dc3f3350', NULL, '00000000-0000-0000-0000-000000000060', 'Mozambique', 'mozambique', 'From Southeastern Africa to cities and towns across the globe — this is the gathering point for a diaspora that never lost touch with home. It is set in Southeastern Africa, sharing borders with Tanzania, Malawi, Zambia, and Zimbabwe, with Maputo as its capital.', '{"title": "Mozambique", "extract": "Mozambique, officially the Republic of Mozambique, is a country in Southeast Africa bordered by the Indian Ocean to the east, Tanzania to the north, Malawi and Zambia to the northwest, Zimbabwe to the west, and Eswatini and South Africa to the south and southwest. The sovereign state is separated from the Comoros, Mayotte, and Madagascar through the Mozambique Channel to the east. The capital and largest city is Maputo.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d0/Flag_of_Mozambique.svg/330px-Flag_of_Mozambique.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Mozambique", "description": "Country in Southeastern Africa"}', '7f933b0a-a74b-4212-afaf-76f07d7f8f60', NULL, 'MZ', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:12.931739+01', NULL, NULL, '{mozambique,mz,africa,community,diaspora}', NULL, 'Africa', 'Eastern Africa', NULL);
INSERT INTO public.spaces VALUES ('43bf510c-a295-4883-81e1-12a92264080d', NULL, '00000000-0000-0000-0000-000000000060', 'Sierra Leone', 'sierra-leone', 'From West Africa to cities and towns across the globe — this is the gathering point for a diaspora that never lost touch with home. It is set in West Africa, sharing borders with Liberia and Guinea. Share local news, discover events, trade on the marketplace, and tap into remittance rates, scholarship finds, and community resources — all in one place.', '{"title": "Sierra Leone", "extract": "Sierra Leone, officially the Republic of Sierra Leone, is a country on the west coast of West Africa. It is bordered to the southeast by Liberia and by Guinea to the north. Sierra Leone''s land area is 73,252 km2 (28,283 sq mi). It has a tropical climate and environments ranging from savannahs to rainforests. As of the 2023 census, Sierra Leone had a population of 8,460,512. Freetown is its capital and largest city.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/17/Flag_of_Sierra_Leone.svg/330px-Flag_of_Sierra_Leone.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Sierra_Leone", "description": "Country in West Africa"}', '271cd6f5-bdfd-469d-8eee-1f0a240312af', NULL, 'SL', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:37.653655+01', NULL, NULL, '{"sierra leone",sierra-leone,sl,africa,community,diaspora}', NULL, 'Africa', 'Western Africa', NULL);
INSERT INTO public.spaces VALUES ('b9a7b0e6-0965-40c7-8812-3ba2b5b1ef4e', NULL, '00000000-0000-0000-0000-000000000060', 'Seychelles', 'seychelles', 'It is an island nation, with Victoria as its capital. From the streets of Victoria to diaspora communities worldwide, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Seychelles", "extract": "Seychelles, officially the Republic of Seychelles, is an archipelagic country consisting of 115 islands in the Indian Ocean. Its capital and largest city, Victoria, is 1,500 kilometres east of mainland Africa. Nearby island countries and territories include the Maldives, Comoros, Madagascar, Mauritius, and the French overseas departments of Mayotte and Réunion to the south; and the Chagos Archipelago to the east.\nSeychelles is the smallest country in Africa as well as the least populated sovereign African country, with an estimated population of 100,600 in 2022.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/fc/Flag_of_Seychelles.svg/330px-Flag_of_Seychelles.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Seychelles", "description": "Island country in the Indian Ocean"}', 'd36ee125-17f2-4b86-8c46-9155b92aaf1e', NULL, 'SC', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:37.148636+01', NULL, NULL, '{seychelles,sc,island,community,diaspora}', NULL, 'Africa', 'Eastern Africa', NULL);
INSERT INTO public.spaces VALUES ('c2ee3910-f295-4059-afd4-03824a5788ce', NULL, '00000000-0000-0000-0000-000000000060', 'Turkmenistan', 'turkmenistan', 'Landlocked in Central Asia but connected to the world — this is where the diaspora gathers, no matter how far they''ve traveled. It is set in Central Asia, landlocked, sharing borders with Kazakhstan, Uzbekistan, Afghanistan, and Iran. Share local news, discover events, trade on the marketplace, and tap into remittance rates, scholarship finds, and community resources — all in one place.', '{"title": "Turkmenistan", "extract": "Turkmenistan is a landlocked country in Central Asia, bordered by Kazakhstan and Uzbekistan to the north, Afghanistan to the southeast, Iran to the south and southwest, and the Caspian Sea to the west. It is one of six independent Turkic states. Ashgabat is the capital and largest city. With over 7 million people, Turkmenistan is the 35th most-populous country in Asia and has the lowest population of the Central Asian republics while being one of the most sparsely populated nations located on the Asian continent.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/1b/Flag_of_Turkmenistan.svg/330px-Flag_of_Turkmenistan.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Turkmenistan", "description": "Country in Central Asia"}', '05b3a7d8-26bf-4e08-8200-15f797bbdd28', NULL, 'TM', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:53.766967+01', NULL, NULL, '{turkmenistan,tm,asia,landlocked,community,diaspora}', NULL, 'Asia', 'Central Asia', NULL);
INSERT INTO public.spaces VALUES ('4eac3d7a-71ed-4fa3-9fe5-615217319127', NULL, '00000000-0000-0000-0000-000000000060', 'Liechtenstein', 'liechtenstein', 'Every journey out of Central Europe carries a story — of ambition, of longing, of roots that stretch but never break. Discover local businesses, share news from home, find events near you, and build a network that spans borders — all on JapaConnect.', '{"title": "Liechtenstein", "extract": "Liechtenstein, officially the Principality of Liechtenstein, is a doubly landlocked country in the Central European Alps. A microstate, it is located between Austria to the east and north-east and Switzerland to the north-west, west and south.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/47/Flag_of_Liechtenstein.svg/330px-Flag_of_Liechtenstein.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Liechtenstein", "description": "Microstate in Central Europe"}', '2246e813-8df5-4b49-b971-7a220de6b9d7', NULL, 'LI', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:00.8302+01', NULL, 'CHF', '{liechtenstein,li,europe,landlocked,community,diaspora}', NULL, 'Europe', 'Western Europe', NULL);
INSERT INTO public.spaces VALUES ('b1188ec9-8bd6-49ea-8a5c-cce4480541d4', NULL, '00000000-0000-0000-0000-000000000060', 'Reunion', 'reunion', 'Whether you''re home or building a life elsewhere, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Reunion", "extract": "Reunion may refer to:Class reunion\nFamily reunion", "thumbnail": "", "content_url": "https://en.wikipedia.org/wiki/Reunion", "description": "Topics referred to by the same term"}', '6f813047-f5f8-4fbd-a218-63196d689e27', NULL, 'RE', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:28.569815+01', NULL, 'EUR', '{reunion,re,community,diaspora}', NULL, 'Africa', 'Eastern Africa', NULL);
INSERT INTO public.spaces VALUES ('d6640f85-97b6-4385-90b3-3d5864d3b177', NULL, '00000000-0000-0000-0000-000000000060', 'Hungary', 'hungary', 'Every journey out of Central Europe carries a story — of ambition, of longing, of roots that stretch but never break. Discover local businesses, share news from home, find events near you, and build a network that spans borders — all on JapaConnect.', '{"title": "Hungary", "extract": "Hungary is a landlocked country in Central Europe. Spanning much of the Carpathian Basin, it is bordered by Slovakia to the north, Ukraine to the northeast, Romania to the east and southeast, Serbia to the south, both Croatia and Slovenia to the southwest, and Austria to the west. Hungary lies within the Danube River''s drainage basin, and is dominated by great lowland plains. It has a population of over 9.5 million, consisting mostly of ethnic Hungarians (Magyars) and a significant Romani minority. Hungarian is the official language, and among the few in Europe outside the Indo-European family. Budapest is the country''s capital and its largest city, and the dominant cultural and economic centre.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/c1/Flag_of_Hungary.svg/330px-Flag_of_Hungary.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Hungary", "description": "Country in Central Europe"}', '3b06ccf2-5ef1-4bf8-99f6-b1f2d1d8cbc0', NULL, 'HU', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:47.71529+01', NULL, NULL, '{hungary,hu,europe,landlocked,community,diaspora}', NULL, 'Europe', 'Eastern Europe', NULL);
INSERT INTO public.spaces VALUES ('4a9c3e4e-e08e-4983-9cd0-834407b49a83', NULL, '00000000-0000-0000-0000-000000000060', 'Israel', 'israel', 'Rooted in West Asia, sharing borders with Lebanon, Syria, Jordan, and Egypt, and reaching across continents — this space bridges home and diaspora. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "Israel", "extract": "Israel, officially the State of Israel, is a country in the Southern Levant region of West Asia. It is bordered by Lebanon to the north, Syria to the northeast, Jordan to the east, and Egypt to the southwest. Israel''s western coast lies on the Mediterranean Sea, its southern tip reaches the Red Sea, and to the east is Earth''s lowest point near the Dead Sea. Jerusalem is the government seat and proclaimed capital, while Tel Aviv is Israel''s largest urban area and economic centre.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d4/Flag_of_Israel.svg/330px-Flag_of_Israel.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Israel", "description": "Country in West Asia"}', 'abd07a2c-5122-4e8f-88e5-63050e745d00', NULL, 'IL', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:51.245855+01', NULL, NULL, '{israel,il,asia,community,diaspora}', NULL, 'Asia', 'Western Asia', NULL);
INSERT INTO public.spaces VALUES ('ce0187c0-0b8e-40e3-aaa1-468370209a18', NULL, '00000000-0000-0000-0000-000000000060', 'Martinique', 'martinique', 'From here to the world — this is where the diaspora gathers, no matter how far they''ve traveled. Share local news, discover events, trade on the marketplace, and tap into remittance rates, scholarship finds, and community resources — all in one place.', '{"title": "Martinique", "extract": "Martinique is an island in the Lesser Antilles of the West Indies, in the eastern Caribbean Sea. A part of the French West Indies (Antilles), Martinique is an overseas department and region and a single territorial collectivity of France.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/21/Martinique-de-haut_%28cropped%29.jpg/330px-Martinique-de-haut_%28cropped%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Martinique", "description": "Overseas department and region of France"}', '3b866824-072f-4dd0-a3d8-76c7fd3ea23e', NULL, 'MQ', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:06.880286+01', NULL, 'EUR', '{martinique,mq,island,community,diaspora}', NULL, 'Americas', 'Caribbean', NULL);
INSERT INTO public.spaces VALUES ('6a2f9f0a-06e3-46f0-945e-8f7bdabece09', NULL, '00000000-0000-0000-0000-000000000060', 'Moldova', 'moldova', 'Your digital anchor in Eastern Europe — wherever the diaspora has settled, this is home base. Home to 2 people, with communities spread far beyond its borders. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "Moldova", "extract": "Moldova, officially the Republic of Moldova, is a landlocked country in Eastern Europe, with an area of 33,843 km2 (13,067 sq mi) and a population of 2.38 million. Moldova is bordered by Romania to the west and Ukraine to the north, east, and south. The unrecognised breakaway state of Transnistria lies across the Dniester river on the country''s eastern border with Ukraine. Moldova is a parliamentary democratic republic with its capital in Chișinău, the country''s largest city and main cultural and commercial centre.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/27/Flag_of_Moldova.svg/330px-Flag_of_Moldova.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Moldova", "description": "Country in Eastern Europe"}', '6e0c2c7e-1845-4b11-8279-a618aa9fc84a', NULL, 'MD', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:09.906453+01', NULL, NULL, '{moldova,md,europe,landlocked,community,diaspora}', NULL, 'Europe', 'Eastern Europe', NULL);
INSERT INTO public.spaces VALUES ('f8621f71-7164-4180-838f-cd5132db9e31', NULL, '00000000-0000-0000-0000-000000000060', 'Saudi Arabia', 'saudi-arabia', 'From West Asia to cities and towns across the globe — this is the gathering point for a diaspora that never lost touch with home. It is set in West Asia, with Riyadh as its capital. Share local news, discover events, trade on the marketplace, and tap into remittance rates, scholarship finds, and community resources — all in one place.', '{"title": "Saudi Arabia", "extract": "Saudi Arabia, officially the Kingdom of Saudi Arabia (KSA), is a country in West Asia. Located in the centre of the Middle East, it covers the bulk of the Arabian Peninsula and has a land area of about 2,150,000 km2 (830,000 sq mi), making it the fifth-largest country in Asia, the largest in the Middle East, and the twelfth-largest in the world. It is bordered by the Red Sea to the west; Jordan, Iraq, and Kuwait to the north; the Arabian Gulf, Bahrain, Qatar and the United Arab Emirates to the east; Oman to the southeast; and Yemen to the south. The Gulf of Aqaba in the northwest separates Saudi Arabia from Egypt and Israel. Saudi Arabia is the only country with a coastline along both the Red Sea and the Arabian Gulf, and most of its terrain consists of arid desert, lowland, steppe, and mountains. The capital and largest city is Riyadh; other major cities include Jeddah and the two holiest cities in Islam, Mecca and Medina. With a population of 33.7 million, Saudi Arabia is the sixth most populous country in the Arab world.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/0d/Flag_of_Saudi_Arabia.svg/330px-Flag_of_Saudi_Arabia.svg.png", "content_url": "https://en.wikipedia.org/wiki/Saudi_Arabia", "description": "Country in West Asia"}', 'c2ae94e4-7399-4b3b-8333-c522686bd798', NULL, 'SA', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:35.633805+01', NULL, NULL, '{"saudi arabia",saudi-arabia,sa,asia,community,diaspora}', NULL, 'Asia', 'Western Asia', NULL);
INSERT INTO public.spaces VALUES ('6dc3af51-9a56-44f2-9bcc-7c4324501949', NULL, '00000000-0000-0000-0000-000000000060', 'Nauru', 'nauru', 'An island in Oceania, but its diaspora spans the globe — this space is the bridge between here and everywhere. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "Nauru", "extract": "Nauru, officially the Republic of Naoero, formerly known as Pleasant Island, is an island country and microstate in the South Pacific Ocean. It lies within the Micronesia subregion of Oceania, with its nearest neighbour being Banaba about 300 kilometres (190 mi) to the east.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/30/Flag_of_Nauru.svg/330px-Flag_of_Nauru.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Nauru", "description": "Island country in Oceania"}', 'ce17941f-d65f-4c3d-b6f5-e85dbddef612', NULL, 'NR', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:14.444699+01', NULL, NULL, '{nauru,nr,oceania,island,community,diaspora}', NULL, 'Oceania', 'Micronesia', NULL);
INSERT INTO public.spaces VALUES ('73c3988b-5b01-4584-a8ad-c2cce7a109b5', NULL, '00000000-0000-0000-0000-000000000060', 'Palau', 'palau', 'Every journey out of Western Pacific carries a story — of ambition, of longing, of roots that stretch but never break. Discover local businesses, share news from home, find events near you, and build a network that spans borders — all on JapaConnect.', '{"title": "Palau", "extract": "Palau, officially the Republic of Palau, is an island country located in the Micronesia subregion of Oceania in the western Pacific Ocean. The Republic of Palau consists of approximately 340 islands and is the western part of the Caroline Islands, while the eastern and central parts make up the Federated States of Micronesia.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/48/Flag_of_Palau.svg/330px-Flag_of_Palau.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Palau", "description": "Country in the Western Pacific"}', '529cd480-9a58-4794-9ed3-cac61c3cc450', NULL, 'PW', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:22.510797+01', NULL, 'USD', '{palau,pw,pacific,island,community,diaspora}', NULL, 'Oceania', 'Micronesia', NULL);
INSERT INTO public.spaces VALUES ('b0bec59e-c3ea-4a32-b460-511e6a3fdeb8', NULL, '00000000-0000-0000-0000-000000000060', 'Russia', 'russia', 'Most populous country in Europe and the ninth-most populous in the world in Eastern Europe and North Asia,. It is set in Eastern Europe and North Asia. Whether you''re still in Eastern Europe and North Asia or building a life elsewhere, this is your space to connect, trade, and stay rooted.', '{"title": "Russia", "extract": "Russia, or the Russian Federation, is a country in Eastern Europe and North Asia. It is the largest country in the world, spanning eleven time zones and sharing land borders with fourteen countries. With a population of over 140 million, Russia is the most populous country in Europe and the ninth-most populous in the world. It is a highly urbanised country, with sixteen of its urban areas having more than 1 million inhabitants. Moscow, the most populous metropolitan area in Europe, is the capital and largest city of Russia, while Saint Petersburg is its second-largest city and a major cultural centre.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/f/f3/Flag_of_Russia.svg/330px-Flag_of_Russia.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Russia", "description": "Country in Eastern Europe and North Asia"}', '9318e428-f5af-4c2f-9049-a5b52f259be6', NULL, 'RU', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:29.579995+01', NULL, NULL, '{russia,ru,europe,community,diaspora}', NULL, 'Europe', 'Eastern Europe', NULL);
INSERT INTO public.spaces VALUES ('048b239d-5aec-468b-8701-238c8efc32ef', NULL, '00000000-0000-0000-0000-000000000060', 'Senegal', 'senegal', 'Rooted in West Africa, sharing borders with Mauritania, Mali, Guinea, and Guinea-Bissau, and reaching across continents — this space bridges home and diaspora. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "Senegal", "extract": "Senegal, officially the Republic of Senegal, is the westernmost country of mainland West Africa, situated along the Atlantic Ocean coast. It borders Mauritania to the north, Mali to the east, Guinea to the southeast and Guinea-Bissau to the southwest. Senegal nearly surrounds the Gambia, a country occupying a narrow strip of land along the banks of the Gambia River, which separates Senegal''s southern region of Casamance from the rest of the country. It also shares a maritime border with Cape Verde. The capital and largest city of Senegal is Dakar.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/fd/Flag_of_Senegal.svg/330px-Flag_of_Senegal.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Senegal", "description": "Country in West Africa"}', 'c5b8bc69-2317-4577-8384-b2982b06dd3a', NULL, 'SN', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:36.137598+01', NULL, NULL, '{senegal,sn,africa,community,diaspora}', NULL, 'Africa', 'Western Africa', NULL);
INSERT INTO public.spaces VALUES ('1c5dd2c9-da50-465c-b61c-489aeff8bf9d', NULL, '00000000-0000-0000-0000-000000000064', 'Sul Ross State University', 'sul-ross-state-university', NULL, '{"logo": "http://commons.wikimedia.org/wiki/Special:FilePath/Sul%20Ross%20State%20University%20wordmark.png", "name": "Sul Ross State University", "image": "http://commons.wikimedia.org/wiki/Special:FilePath/Sul%20Ross%20State%20University%20Alpine%20Texas%20DSC%205570%20ad.JPG", "country": "Q30", "founded": "+1917-00-00T00:00:00Z", "website": "https://www.sulross.edu/", "students": "+2345", "description": "public university in Alpine, Texas", "wikidata_id": "Q7635933", "wikipedia_url": "https://en.wikipedia.org/wiki/Q7635933"}', '33c0ea39-d35d-4b63-a894-4cd6f00155b3', NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.233464+01', '2026-08-09 10:42:19.224747+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('4babe959-7cb0-4a1c-867d-83e0cf3fdd70', NULL, '00000000-0000-0000-0000-000000000060', 'Sudan', 'sudan', 'Your digital anchor in Northeast Africa — wherever the diaspora has settled, this is home base. Home to 51 people, with communities spread far beyond its borders. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "Sudan", "extract": "Sudan, officially the Republic of the Sudan, is a country in Northeast Africa. It borders the Central African Republic to the southwest, Chad to the west, Libya to the northwest, Egypt to the north, the Red Sea to the east, Eritrea and Ethiopia to the southeast, and South Sudan to the south. Sudan has a population of 51.8 million people as of 2025 and occupies 1,886,068 square kilometres, making it Africa''s third-largest country by area. Sudan''s capital and most populous city is Khartoum.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/01/Flag_of_Sudan.svg/330px-Flag_of_Sudan.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Sudan", "description": "Country in Northeast Africa"}', '07134657-d002-4990-99c1-49bb5bd20ffd', NULL, 'SD', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:44.198248+01', NULL, NULL, '{sudan,sd,africa,community,diaspora}', NULL, 'Africa', 'Northern Africa', NULL);
INSERT INTO public.spaces VALUES ('84275c67-a267-4008-bb39-378017dda059', NULL, '00000000-0000-0000-0000-000000000060', 'Sweden', 'sweden', 'Every journey out of northern Europe carries a story — of ambition, of longing, of roots that stretch but never break. From the capital, Stockholm, to the cities where the diaspora now lives, the connection to home runs deep. Discover local businesses, share news from home, find events near you, and build a network that spans borders — all on JapaConnect.', '{"title": "Sweden", "extract": "Sweden, formally the Kingdom of Sweden, is a Nordic country located on the Scandinavian Peninsula in Northern Europe. It borders Norway to the west and north, and Finland to the east, and shares a maritime border with Denmark to the south. At 450,295 square kilometres (173,860 sq mi) and with a population of 10.6 million, Sweden is the largest and most populous Nordic country, and is the fifth-largest country in Europe. Its capital and largest city is Stockholm. The population density is 25.5 inhabitants per square kilometre (66/sq mi), and 88% of Swedes reside in urban areas, mostly in the southern and central portions of the country. Sweden''s urban areas together cover 1.5% of its land area. Sweden has a diverse climate owing to the length of the country, which ranges from 55°N to 69°N.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/4/4c/Flag_of_Sweden.svg/330px-Flag_of_Sweden.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Sweden", "description": "Country in northern Europe"}', '35fc178f-8264-4f51-bfb8-29c95664dd8d', NULL, 'SE', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:45.7089+01', NULL, NULL, '{sweden,se,europe,community,diaspora}', NULL, 'Europe', 'Northern Europe', NULL);
INSERT INTO public.spaces VALUES ('92f75c87-e291-4907-9a66-94acd1266734', NULL, '00000000-0000-0000-0000-000000000060', 'Uruguay', 'uruguay', 'Every journey out of South America carries a story — of ambition, of longing, of roots that stretch but never break. From the capital, Montevideo, to the cities where the diaspora now lives, the connection to home runs deep. Discover local businesses, share news from home, find events near you, and build a network that spans borders — all on JapaConnect.', '{"title": "Uruguay", "extract": "Uruguay, officially the Oriental Republic of Uruguay, is a country in South America. It shares borders with Argentina to its west and southwest and Brazil to its north and northeast, while bordering the Río de la Plata to the south and the Atlantic Ocean to the southeast. It is part of the Southern Cone region of South America. Uruguay covers an area of approximately 176,215 square kilometers (68,037 sq mi). It has a population of almost 3.5 million people, of whom nearly 2 million live in the metropolitan area of its capital and largest city, Montevideo.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/fe/Flag_of_Uruguay.svg/330px-Flag_of_Uruguay.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Uruguay", "description": "Country in South America"}', 'e5163f6f-42af-4e11-8ad2-c46940406293', NULL, 'UY', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:58.308473+01', NULL, NULL, '{uruguay,uy,"south america",community,diaspora}', NULL, 'Americas', 'South America', NULL);
INSERT INTO public.spaces VALUES ('429d5cdb-ba54-4d81-979b-bebc0499af43', NULL, '00000000-0000-0000-0000-000000000060', 'Vietnam', 'vietnam', 'Every journey out of Southeast Asia carries a story — of ambition, of longing, of roots that stretch but never break. From the capital, Hanoi, to the cities where the diaspora now lives, the connection to home runs deep. Discover local businesses, share news from home, find events near you, and build a network that spans borders — all on JapaConnect.', '{"title": "Vietnam", "extract": "Vietnam, officially the Socialist Republic of Viet Nam (SRV), is a country at the eastern edge of Mainland Southeast Asia. With an area of about 331,000 square kilometres and a population of over 102 million, it is the world''s 16th-most populous country. One of two communist states in Southeast Asia, Vietnam is bordered by China to the north, and Laos and Cambodia to the west; it lies along the Gulf of Thailand to the southwest and the South China Sea to the east, where it has shared and disputed maritime borders with other countries. Its capital is Hanoi, while its largest city is Ho Chi Minh City.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/21/Flag_of_Vietnam.svg/330px-Flag_of_Vietnam.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Vietnam", "description": "Country in Southeast Asia"}', '74501a0d-2d5b-4c19-86e6-664979e2ae7b', NULL, 'VN', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:46:00.839829+01', NULL, NULL, '{vietnam,vn,asia,community,diaspora}', NULL, 'Asia', 'South-Eastern Asia', NULL);
INSERT INTO public.spaces VALUES ('0e9cc573-8a97-405d-99b1-5b802bd785fd', NULL, '00000000-0000-0000-0000-000000000060', 'Cook Islands', 'cook-islands', 'It is set in South Pacific Ocean, an island nation, with Avarua as its capital. From the streets of Avarua to diaspora communities worldwide, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Cook Islands", "extract": "The Cook Islands is an island country and associated state of New Zealand in Polynesia, part of Oceania, in the South Pacific Ocean. The country consists of 15 islands whose total land area is approximately 236.7 square kilometres (91 sq mi). The Cook Islands Exclusive Economic Zone (EEZ) covers 1,960,027 square kilometres (756,771 sq mi) of ocean. The capital is Avarua, located on the island of Rarotonga.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/35/Flag_of_the_Cook_Islands.svg/330px-Flag_of_the_Cook_Islands.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Cook_Islands", "description": "Country in the South Pacific Ocean"}', 'ca2bc3a9-85b6-4d08-950b-8738b4d1a8f7', NULL, 'CK', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:24.015909+01', NULL, NULL, '{"cook islands",cook-islands,ck,pacific,island,community,diaspora}', NULL, 'Oceania', 'Polynesia', NULL);
INSERT INTO public.spaces VALUES ('dc0b8824-866c-4bb5-998a-16a303c0343e', NULL, '00000000-0000-0000-0000-000000000060', 'Nicaragua', 'nicaragua', 'Your digital anchor in Central America — wherever the diaspora has settled, this is home base. Home to 7 people, with communities spread far beyond its borders. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "Nicaragua", "extract": "Nicaragua, officially the Republic of Nicaragua, is a country in Central America, comprising 130,370 square kilometers (50,340 sq mi). With a population of 7,097,329 as of 2026, it is the third-most populous country in Central America after Guatemala and Honduras, and the largest by area in all of Central America.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/19/Flag_of_Nicaragua.svg/330px-Flag_of_Nicaragua.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Nicaragua", "description": "Country in Central America"}', '394d7057-cff4-4391-b056-ca30a0fee2ad', NULL, 'NI', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:16.968172+01', NULL, NULL, '{nicaragua,ni,"central america",community,diaspora}', NULL, 'Americas', 'Central America', NULL);
INSERT INTO public.spaces VALUES ('0a4e9197-b3aa-4ca4-bb97-1627896e1b97', NULL, '00000000-0000-0000-0000-000000000060', 'Honduras', 'honduras', 'It is set in Central America, sharing borders with Guatemala, El Salvador, Nicaragua, and Fonseca, with Tegucigalpa as its capital. From the streets of Tegucigalpa to diaspora communities worldwide, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Honduras", "extract": "Honduras, officially the Republic of Honduras, is a country in Central America. It is bordered to the west by Guatemala, to the southwest by El Salvador, to the southeast by Nicaragua, to the south by the Pacific Ocean at the Gulf of Fonseca, and to the north by the Gulf of Honduras, a large inlet of the Caribbean Sea. Its capital and largest city is Tegucigalpa.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/79/Flag_of_Honduras_%281949%E2%80%932022%2C_2026%E2%80%93present%29.svg/330px-Flag_of_Honduras_%281949%E2%80%932022%2C_2026%E2%80%93present%29.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Honduras", "description": "Country in Central America"}', '948c5a92-d0e2-49c7-9384-f6c3c71c0285', NULL, 'HN', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:46.706103+01', NULL, NULL, '{honduras,hn,"central america",community,diaspora}', NULL, 'Americas', 'Central America', NULL);
INSERT INTO public.spaces VALUES ('bd73dc70-26b2-409b-999f-66ab12ab1e32', NULL, '00000000-0000-0000-0000-000000000060', 'Norfolk Island', 'norfolk-island', 'It is with Kingston as its capital. From the streets of Kingston to diaspora communities worldwide, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Norfolk Island", "extract": "Norfolk Island is an external territory of Australia located in the Pacific Ocean between New Zealand and New Caledonia, 1,412 kilometres (877 mi) directly east of Australia''s Evans Head and about 900 kilometres (560 mi) from Lord Howe Island. Together with the neighbouring Phillip Island and Nepean Island, the three islands collectively form the Territory of Norfolk Island. At the 2021 census, it had 2,188 inhabitants living on a total area of about 35 km2 (14 sq mi). Its capital is Kingston.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/48/Flag_of_Norfolk_Island.svg/330px-Flag_of_Norfolk_Island.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Norfolk_Island", "description": "External territory of Australia"}', 'bbfc55d8-baa5-4d2f-99a3-c1141ac64df3', NULL, 'NF', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:18.986469+01', NULL, NULL, '{"norfolk island",norfolk-island,nf,island,community,diaspora}', NULL, 'Oceania', 'Australia and New Zealand', NULL);
INSERT INTO public.spaces VALUES ('703f748b-1bcf-4333-9243-027ca1dfc3da', NULL, '00000000-0000-0000-0000-000000000060', 'North Korea', 'north-korea', 'Rooted in East Asia, sharing borders with China, Russia, Yalu Amnok, and Tumen, and reaching across continents — this space bridges home and diaspora. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "North Korea", "extract": "North Korea, officially the Democratic People''s Republic of Korea (DPRK), is a country in East Asia. It constitutes the northern half of the Korean Peninsula and borders China and Russia to the north at the Yalu (Amnok) and Tumen rivers, and South Korea to the south at the Korean Demilitarized Zone (DMZ). The country''s western border is formed by the Yellow Sea, while its eastern border is defined by the Sea of Japan. Pyongyang is the capital and largest city.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/86/Flag_of_North_Korea_%2820-33%29.svg/330px-Flag_of_North_Korea_%2820-33%29.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/North_Korea", "description": "Country in East Asia"}', '542986cd-36dd-45bd-9996-59db116c555d', NULL, 'KP', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:19.99438+01', NULL, NULL, '{"north korea",north-korea,kp,asia,community,diaspora}', NULL, 'Asia', 'Eastern Asia', NULL);
INSERT INTO public.spaces VALUES ('6be687b7-6912-4d35-b807-e121c87a849d', NULL, '00000000-0000-0000-0000-000000000060', 'Norway', 'norway', 'From northern Europe to cities and towns across the globe — this is the gathering point for a diaspora that never lost touch with home. It is set in northern Europe, sharing borders with Finland and Russia, with Oslo as its capital. Share local news, discover events, trade on the marketplace, and tap into remittance rates, scholarship finds, and community resources — all in one place.', '{"title": "Norway", "extract": "Norway, officially the Kingdom of Norway, is a Nordic country comprising the western and northernmost parts of the Scandinavian Peninsula in Northern Europe, the remote Arctic island Jan Mayen and the archipelago Svalbard. Bouvet Island, located in the Subantarctic, is a dependency, and not a part of the Kingdom; Norway also claims the Antarctic territories of Peter I Island and Queen Maud Land. Norway has a population of approximately 5.6 million, and a total area of 385,207 square kilometres (148,729 sq mi). Its capital and largest city is Oslo. The country shares a long eastern border with Sweden, and is bordered by Finland and Russia to the northeast. Norway has an extensive coastline facing the Skagerrak strait, the North Sea, the Norwegian Sea, and the Barents Sea.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d9/Flag_of_Norway.svg/330px-Flag_of_Norway.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Norway", "description": "Country in northern Europe"}', '763d7dd7-da5d-4d30-84a3-3ce166bcc84e', NULL, 'NO', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:21.002396+01', NULL, NULL, '{norway,no,europe,island,community,diaspora}', NULL, 'Europe', 'Northern Europe', NULL);
INSERT INTO public.spaces VALUES ('9a621074-85f2-4d87-9950-3a83f6c83bce', NULL, '00000000-0000-0000-0000-000000000064', 'Slovak Medical University', 'slovak-medical-university', NULL, '{"name": "Slovak Medical University", "image": "http://commons.wikimedia.org/wiki/Special:FilePath/SZU%2005.jpg", "country": "Q214", "founded": "+2002-00-00T00:00:00Z", "website": "http://www.szu.sk", "description": "public university in Slovakia", "wikidata_id": "Q1466307", "wikipedia_url": "https://en.wikipedia.org/wiki/Q1466307"}', NULL, NULL, 'SK', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.625787+01', '2026-08-21 07:06:18.412737+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('70d6f542-d738-489c-86f0-1e56e7dd23ac', NULL, '00000000-0000-0000-0000-000000000060', 'Samoa', 'samoa', 'Your digital anchor on this island — wherever the diaspora has settled, this is home base. An island nation whose diaspora has reached every corner of the world. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "Samoa", "extract": "Samoa, officially the Independent State of Samoa, is an island country in Polynesia, a part of Oceania, which is in the South Pacific Ocean. It consists of two main islands, two smaller, inhabited islands, and several smaller, uninhabited islands, including the Aleipata Islands. Samoa is located 64 km west of American Samoa, 889 km northeast of Tonga, 1,152 km northeast of Fiji, 483 km east of Wallis and Futuna, 1,151 km southeast of Tuvalu, 519 km south of Tokelau, 4,190 km southwest of Hawaii, and 610 km northwest of Niue. The capital and largest city is Apia.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/31/Flag_of_Samoa.svg/330px-Flag_of_Samoa.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Samoa", "description": "Island country in the Pacific Ocean"}', '850a95d8-1515-4079-8120-3297f3926d01', NULL, 'WS', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:34.120798+01', NULL, NULL, '{samoa,ws,pacific,island,community,diaspora}', NULL, 'Oceania', 'Polynesia', NULL);
INSERT INTO public.spaces VALUES ('6750eff3-d221-41ac-83ef-d206498e864e', NULL, '00000000-0000-0000-0000-000000000060', 'South Georgia', 'south-georgia', 'From South Atlantic Ocean to cities and towns across the globe — this is the gathering point for a diaspora that never lost touch with home. It is set in South Atlantic Ocean. Share local news, discover events, trade on the marketplace, and tap into remittance rates, scholarship finds, and community resources — all in one place.', '{"title": "South Georgia", "extract": "South Georgia is an island in the South Atlantic Ocean that is part of the British Overseas Territory of South Georgia and the South Sandwich Islands. It lies around 1,400 kilometres east of the Falkland Islands. Stretching in the east–west direction, South Georgia is around 170 kilometres (106 mi) long and has a maximum width of 35 kilometres (22 mi). The terrain is mountainous, with the central ridge rising to 2,935 metres (9,629 ft) at Mount Paget. The northern coast is indented with numerous bays and fjords, serving as harbours.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/32/South_Georgia_Island_as_seen_by_Sentinel-2.jpg/330px-South_Georgia_Island_as_seen_by_Sentinel-2.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/South_Georgia", "description": "Island in the South Atlantic Ocean"}', 'a0086eb3-b63b-4c5c-99a7-702973e50f5b', NULL, 'GS', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:41.68235+01', NULL, 'GBP', '{"south georgia",south-georgia,gs,island,community,diaspora}', NULL, 'Americas', 'South America', NULL);
INSERT INTO public.spaces VALUES ('04a10e25-b229-4758-9ff7-b838e36fd620', NULL, '00000000-0000-0000-0000-000000000060', 'Aland Islands', 'aland-islands', 'From here to the world — this is where the diaspora gathers, no matter how far they''ve traveled. It is with Mariehamn as its capital. Share local news, discover events, trade on the marketplace, and tap into remittance rates, scholarship finds, and community resources — all in one place.', '{"title": "Åland", "extract": "Åland is an autonomous and demilitarised region of Finland. Receiving its autonomy in 1920, it is the smallest region of Finland by both area and population (30,654), constituting 0.51% of Finland''s land area and 0.54% of its population. Its official language is Swedish and the capital city is Mariehamn.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/Flag_of_%C3%85land.svg/330px-Flag_of_%C3%85land.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/%C3%85land", "description": "Autonomous region of Finland"}', '419b49ba-2da3-4e4e-a1bb-846a1f4e7d55', NULL, 'AX', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:43:58.716251+01', NULL, 'EUR', '{"aland islands",aland-islands,ax,community,diaspora}', NULL, 'Europe', 'Northern Europe', NULL);
INSERT INTO public.spaces VALUES ('02e6b9ed-11e4-4be0-9ff5-4350b18c0d43', NULL, '00000000-0000-0000-0000-000000000060', 'Angola', 'angola', 'Every journey out of Southern Africa carries a story — of ambition, of longing, of roots that stretch but never break. Discover local businesses, share news from home, find events near you, and build a network that spans borders — all on JapaConnect.', '{"title": "Angola", "extract": "Angola, officially the Republic of Angola, is a country on the western coast of Southern Africa. It is the second-largest Portuguese-speaking (Lusophone) country after Brazil in both total area and population and is the seventh-largest country in Africa. It is bordered by Namibia to the south, the Democratic Republic of the Congo to the north, Zambia to the east, and the Atlantic Ocean to the west. Angola has an exclave province, the province of Cabinda, that borders the Republic of the Congo and the Democratic Republic of the Congo. The capital and most populous city is Luanda.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/9d/Flag_of_Angola.svg/330px-Flag_of_Angola.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Angola", "description": "Country in Southern Africa"}', '0958be47-3c21-4dd0-aa71-bde2700b93da', NULL, 'AO', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:01.818241+01', NULL, NULL, '{angola,ao,africa,community,diaspora}', NULL, 'Africa', 'Middle Africa', NULL);
INSERT INTO public.spaces VALUES ('89c8fba9-5f97-4afa-987a-aa6133192263', NULL, '00000000-0000-0000-0000-000000000060', 'Aruba', 'aruba', 'Whether you''re home or building a life elsewhere, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Aruba", "extract": "Aruba, officially the Country of Aruba, is an island constituent country within the Kingdom of the Netherlands, in the southern Caribbean Sea 29 kilometres (18 mi) north of the Venezuelan peninsula of Paraguaná and 80 kilometres (50 mi) northwest of Curaçao. In 1986, Aruba became a constituent country within the Kingdom of the Netherlands and acquired the official name.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/f6/Flag_of_Aruba.svg/330px-Flag_of_Aruba.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Aruba", "description": "Country of the Kingdom of the Netherlands"}', 'a630c419-04b5-477c-9d65-4d29d6077e2f', NULL, 'AW', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:04.843446+01', NULL, NULL, '{aruba,aw,island,community,diaspora}', NULL, 'Americas', 'Caribbean', NULL);
INSERT INTO public.spaces VALUES ('d3ce9ae3-82db-4d7a-8d06-519cdf2f9661', NULL, '00000000-0000-0000-0000-000000000064', 'Rock Valley College', 'rock-valley-college', NULL, '{"name": "Rock Valley College", "image": "http://commons.wikimedia.org/wiki/Special:FilePath/RVC%20Mascot%20%28Arvee%20the%20Golden%20Eagle%29.jpg", "country": "Q30", "founded": "+1965-00-00T00:00:00Z", "website": "http://www.rockvalleycollege.edu", "students": "+5762", "description": "Two-year college in Rockford, Illinois, U.S.", "wikidata_id": "Q7354736", "wikipedia_url": "https://en.wikipedia.org/wiki/Q7354736"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-21 07:09:14.457077+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('d558a350-29a8-4c42-b3a0-6604d0da1824', NULL, '00000000-0000-0000-0000-000000000060', 'Austria', 'austria', 'Every journey out of Central Europe carries a story — of ambition, of longing, of roots that stretch but never break. Discover local businesses, share news from home, find events near you, and build a network that spans borders — all on JapaConnect.', '{"title": "Austria", "extract": "Austria, formally the Republic of Austria, is a landlocked country in Central Europe, lying in the Eastern Alps. It is a federation of nine states, of which the capital Vienna is the most populous city and state. Austria is bordered by Germany to the northwest, the Czech Republic to the north, Slovakia to the northeast, Hungary to the east, Slovenia and Italy to the south, and Switzerland and Liechtenstein to the west. The country occupies an area of 83,879 km2 (32,386 sq mi) and has a population of about 9.2 million.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/41/Flag_of_Austria.svg/330px-Flag_of_Austria.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Austria", "description": "Country in Central Europe"}', 'ca6cc774-1052-493e-b63e-728af4aa99d4', NULL, 'AT', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:05.8536+01', NULL, 'EUR', '{austria,at,europe,landlocked,community,diaspora}', NULL, 'Europe', 'Western Europe', NULL);
INSERT INTO public.spaces VALUES ('aaf26902-7d74-4b1b-aa9b-85db0cc0f4fa', NULL, '00000000-0000-0000-0000-000000000060', 'Bolivia', 'bolivia', 'Landlocked in South America but connected to the world — this is where the diaspora gathers, no matter how far they''ve traveled. It is set in South America, landlocked, sharing borders with Brazil, Paraguay, Argentina, and Chile, with Sucre as its capital.', '{"title": "Bolivia", "extract": "Bolivia, officially the Plurinational State of Bolivia, is a landlocked country located in central South America. Its geography primarily consists of an Andean region to the west and tropical lowlands to the east and north. The country has a diverse environment, including the vast Amazonian plain, the Gran Chaco, temperate valleys, the high-altitude Altiplano plateau, snow-capped peaks, and mountains, encompassing a wide range of climates and biomes across its regions and cities. It includes part of the Pantanal, the largest tropical wetland in the world, along its eastern border. Bolivia is bordered by Brazil to the north and east, Paraguay to the southeast, Argentina to the south, Chile to the southwest, and Peru to the west. The seat of government is La Paz, which contains the executive, legislative, and electoral branches of government, while the constitutional capital is Sucre, the seat of the judiciary. While most population and urban centers lie in the Andean region, the largest city and principal industrial center is Santa Cruz de la Sierra, located in the eastern tropical lowlands.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/48/Flag_of_Bolivia.svg/330px-Flag_of_Bolivia.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Bolivia", "description": "Country in South America"}', 'b6eeba56-c5e8-4c7f-8b6e-d299bf74fc34', NULL, 'BO', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:11.40397+01', NULL, NULL, '{bolivia,bo,"south america",landlocked,community,diaspora}', NULL, 'Americas', 'South America', NULL);
INSERT INTO public.spaces VALUES ('bee12d93-3cc9-4e9d-a88a-29855e099cdf', NULL, '00000000-0000-0000-0000-000000000060', 'Bouvet Island', 'bouvet-island', 'Every journey carries a story — of ambition, of longing, of roots that stretch but never break. From the Mid-Atlantic Ridge to the cities where the diaspora now lives, the connection to home runs deep. Discover local businesses, share news from home, find events near you, and build a network that spans borders — all on JapaConnect.', '{"title": "Bouvet Island", "extract": "Bouvet Island is an uninhabited subantarctic volcanic island and dependency of Norway. A protected nature reserve situated in the South Atlantic Ocean at the southern end of the Mid-Atlantic Ridge, it is the world''s most remote island. Located north of 60°S latitude, Bouvet Island is not part of the southern region covered by the Antarctic Treaty System.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/73/Bouvet_Island_on_the_globe_%28Antarctica_centered%29.svg/330px-Bouvet_Island_on_the_globe_%28Antarctica_centered%29.svg.png", "content_url": "https://en.wikipedia.org/wiki/Bouvet_Island", "description": "Uninhabited subantarctic volcanic island"}', 'ae1af0fa-6cf8-4baf-b4a5-99d26f5092b2', NULL, 'BV', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:13.423665+01', NULL, NULL, '{"bouvet island",bouvet-island,bv,island,community,diaspora}', NULL, 'Global', 'Global', NULL);
INSERT INTO public.spaces VALUES ('63ee9cbf-1b63-4ac8-981a-c8cdeba9480a', NULL, '00000000-0000-0000-0000-000000000060', 'Madagascar', 'madagascar', 'It is an island nation, with Antananarivo as its capital. From the streets of Antananarivo to diaspora communities worldwide, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Madagascar", "extract": "Madagascar, officially the Republic of Madagascar, is an island country in the Indian Ocean that includes the island of Madagascar and numerous smaller peripheral islands. Lying off the southeastern coast of Africa, it is the world''s fourth-largest island, the second-largest island country, and the 46th-largest country overall. Its capital and largest city is Antananarivo.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/2f/Madagascar_%28centered_orthographic_projection%29.svg/330px-Madagascar_%28centered_orthographic_projection%29.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Madagascar", "description": "African island country in the Indian Ocean"}', 'e47eccb1-d705-4db6-b15e-a0eeed310535', NULL, 'MG', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:02.843985+01', NULL, NULL, '{madagascar,mg,africa,island,community,diaspora}', NULL, 'Africa', 'Eastern Africa', NULL);
INSERT INTO public.spaces VALUES ('178fee53-b5a0-47f5-b096-2aa14cb0289a', NULL, '00000000-0000-0000-0000-000000000060', 'Micronesia', 'micronesia', 'Every journey carries a story — of ambition, of longing, of roots that stretch but never break. Discover local businesses, share news from home, find events near you, and build a network that spans borders — all on JapaConnect.', '{"title": "Micronesia", "extract": "Micronesia is a subregion of Oceania, consisting of approximately 2,000 small islands in the Northwestern Pacific Ocean. It has a close shared cultural history with three other island regions: Maritime Southeast Asia to the west, Polynesia to the east, and Melanesia to the south—as well as with the wider community of Austronesian peoples.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/b0/Micronesian_Cultural_Area.png/330px-Micronesian_Cultural_Area.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Micronesia", "description": "Subregion of Oceania"}', 'da0fdf0f-91f2-4be2-9fb0-a4f0d41d2ffd', NULL, 'FM', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:09.401116+01', NULL, 'USD', '{micronesia,fm,oceania,island,community,diaspora}', NULL, 'Oceania', 'Micronesia', NULL);
INSERT INTO public.spaces VALUES ('02d78965-403d-4bbe-9c9b-4a0191177ba6', NULL, '00000000-0000-0000-0000-000000000060', 'Czech Republic', 'czech-republic', 'Your digital anchor in Central Europe — from Prague to the farthest corners of the diaspora, everything flows through here. A landlocked nation whose people have crossed every border to build lives abroad. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "Czech Republic", "extract": "The Czech Republic, also known as Czechia and historically known as Bohemia, is a landlocked country in Central Europe. The country is bordered by Austria to the south, Germany to the west, Poland to the northeast, and Slovakia to the southeast. The Czech Republic has a hilly landscape that covers an area of 78,871 square kilometers (30,452 sq mi) with a mostly temperate continental and oceanic climate. The capital and largest city is Prague; other major cities and urban areas include Brno, Ostrava, Plzeň and Liberec.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/cb/Flag_of_the_Czech_Republic.svg/330px-Flag_of_the_Czech_Republic.svg.png", "content_url": "https://en.wikipedia.org/wiki/Czech_Republic", "description": "Country in Central Europe"}', '6bb6f23d-81de-4239-a40e-36c76cb9618a', NULL, 'CZ', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:27.044088+01', NULL, NULL, '{"czech republic",czech-republic,cz,europe,landlocked,community,diaspora}', NULL, 'Europe', 'Eastern Europe', NULL);
INSERT INTO public.spaces VALUES ('5702cbff-592f-4bcc-89e6-8281f65e4591', NULL, '00000000-0000-0000-0000-000000000060', 'Denmark', 'denmark', 'It is set in northern Europe. Whether you''re still in northern Europe or building a life elsewhere, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Denmark", "extract": "Denmark is a Nordic country in Northern Europe. It is the metropole and most populous constituent of the Kingdom of Denmark, also known as the Danish Realm, a constitutionally unitary state that includes the autonomous territories of the Faroe Islands and Greenland in the north Atlantic Ocean. Metropolitan Denmark, also called \"continental Denmark\" or \"Denmark proper\", consists of the northern Jutland peninsula and an archipelago of 406 islands. It is the southernmost of the Scandinavian countries, lying southwest of Sweden, south of Norway, and north of Germany, with which it shares a short border. Metropolitan Denmark is situated between the North Sea to the west and the Baltic Sea to the east.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/9c/Flag_of_Denmark.svg/330px-Flag_of_Denmark.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Denmark", "description": "Country in northern Europe"}', '2fa3ea66-0c46-4c7a-89f3-fc33acfa7e9a', NULL, 'DK', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:28.053954+01', NULL, NULL, '{denmark,dk,europe,island,community,diaspora}', NULL, 'Europe', 'Northern Europe', NULL);
INSERT INTO public.spaces VALUES ('388b0475-8243-4f96-9b7f-db298af0e6d4', NULL, '00000000-0000-0000-0000-000000000060', 'El Salvador', 'el-salvador', 'Your digital anchor in Central America — from San Salvador to the farthest corners of the diaspora, everything flows through here. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "El Salvador", "extract": "El Salvador, officially the Republic of El Salvador, is a country in Central America. It is bordered on the northeast by Honduras, on the northwest by Guatemala, and on the south by the Pacific Ocean. El Salvador''s capital and largest city is San Salvador. El Salvador''s population in 2024 was 6 million.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/34/Flag_of_El_Salvador.svg/330px-Flag_of_El_Salvador.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/El_Salvador", "description": "Country in Central America"}', 'dfe43a1d-6027-4e1f-8bfe-5159ac550282', NULL, 'SV', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:31.079777+01', NULL, 'USD', '{"el salvador",el-salvador,sv,"central america",community,diaspora}', NULL, 'Americas', 'Central America', NULL);
INSERT INTO public.spaces VALUES ('32eea80b-7c9f-4fcc-a708-b6ba997d8be6', NULL, '00000000-0000-0000-0000-000000000060', 'Gabon', 'gabon', 'Your digital anchor in Central Africa — wherever the diaspora has settled, this is home base. A land of coastal plains and an equatorial location, shaped by geography and history into something uniquely its own. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "Gabon", "extract": "Gabon, officially the Gabonese Republic, is a country on the Atlantic coast of Central Africa, lying on the equator. It is bordered by Equatorial Guinea to the northwest, Cameroon to the north, the Republic of the Congo to the east and south, while sharing a maritime border with São Tomé and Príncipe to the west in the Gulf of Guinea. It has an area of 270,000 square kilometres (100,000 sq mi) and a population of 2.3 million people. There are coastal plains, mountains, and a savanna in the east. Libreville is the country''s capital and largest city; other major cities include Port-Gentil and Franceville.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/04/Flag_of_Gabon.svg/330px-Flag_of_Gabon.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Gabon", "description": "Country in Central Africa"}', '74429d2b-dc34-4896-b556-c3e40f352d2c', NULL, 'GA', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:38.12914+01', NULL, NULL, '{gabon,ga,africa,community,diaspora}', NULL, 'Africa', 'Middle Africa', NULL);
INSERT INTO public.spaces VALUES ('f5954a76-beee-4450-b5e7-e06f0a8d5dd1', NULL, '00000000-0000-0000-0000-000000000060', 'Guernsey', 'guernsey', 'From here to the world — this is where the diaspora gathers, no matter how far they''ve traveled. Share local news, discover events, trade on the marketplace, and tap into remittance rates, scholarship finds, and community resources — all in one place.', '{"title": "Guernsey", "extract": "Guernsey is the second-largest island in the Channel Islands, located 27 miles (43 km) west of the Cotentin Peninsula, Normandy. It is the largest island in the Bailiwick of Guernsey, which includes five other inhabited islands – Alderney, Herm, Jethou, Brecqhou and Sark – and many small islets and rocks. The bailiwick has a population of 63,950, the vast majority of whom live on Guernsey, and the island has a land area of 24 square miles (62 km2).", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/ef/Guernsey-Guernsey.png/330px-Guernsey-Guernsey.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Guernsey", "description": "English Channel island near Normandy"}', '56c01103-6089-4081-b707-bdb01350dd3e', NULL, 'GG', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:43.679327+01', NULL, 'GBP', '{guernsey,gg,island,community,diaspora}', NULL, 'Europe', 'Northern Europe', NULL);
INSERT INTO public.spaces VALUES ('2059e70f-eb1c-45f2-a4ea-ab9804eab529', NULL, '00000000-0000-0000-0000-000000000064', 'Istanbul Medeniyet University', 'istanbul-medeniyet-university', NULL, '{"logo": "http://commons.wikimedia.org/wiki/Special:FilePath/%C4%B0stanbul%20Medeniyet%20%C3%9Cniversitesi%20logo.svg", "name": "Istanbul Medeniyet University", "image": "http://commons.wikimedia.org/wiki/Special:FilePath/Medeniyet%20%C3%BCniversitesi.jpg", "country": "Q43", "founded": "+2010-07-21T00:00:00Z", "website": "http://www.medeniyet.edu.tr/", "description": "state university in İstanbul, Turkey", "wikidata_id": "Q11158752", "wikipedia_url": "https://en.wikipedia.org/wiki/Q11158752"}', '18052eec-01aa-4cc6-92cf-f706bfa7d14c', NULL, 'TR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.679268+01', '2026-08-10 00:05:18.237108+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('b4687119-0d61-4248-9d53-4486303f3a2c', NULL, '00000000-0000-0000-0000-000000000060', 'Guinea-Bissau', 'guinea-bissau', 'It is set in West Africa, sharing borders with Senegal and Guinea. Whether you''re still in West Africa or building a life elsewhere, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Guinea-Bissau", "extract": "Guinea-Bissau, officially the Republic of Guinea-Bissau, is a country in West Africa that covers 36,125 square kilometres (13,948 sq mi) with an estimated population of 2,080,000. It borders Senegal to its north and Guinea to its southeast.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/01/Flag_of_Guinea-Bissau.svg/330px-Flag_of_Guinea-Bissau.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Guinea-Bissau", "description": "Country in West Africa"}', 'd2337a43-e01b-4b85-a97e-07825edd68a4', NULL, 'GW', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:44.688762+01', NULL, NULL, '{guinea-bissau,gw,africa,community,diaspora}', NULL, 'Africa', 'Western Africa', NULL);
INSERT INTO public.spaces VALUES ('7124a1cd-9db3-4905-9b6c-150ec7e603b3', NULL, '00000000-0000-0000-0000-000000000060', 'Hong Kong S.A.R.', 'hong-kong-sar', 'Your digital anchor — wherever the diaspora has settled, this is home base. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "Hong Kong", "extract": "Hong Kong is a special administrative region of China. Situated on China''s southern coast just south of Shenzhen, it consists of Hong Kong Island, Kowloon, and the New Territories. With 7.5 million residents in a 1,114-square-kilometre (430 sq mi) territory, Hong Kong is the fourth-most densely populated region in the world.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/5b/Flag_of_Hong_Kong.svg/330px-Flag_of_Hong_Kong.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Hong_Kong", "description": "Special administrative region of China"}', '6f165a47-7db8-49a7-a254-a51fd0c0fc19', NULL, 'HK', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:47.210738+01', NULL, NULL, '{"hong kong s.a.r.",hong-kong-sar,hk,island,community,diaspora}', NULL, 'Asia', 'Eastern Asia', NULL);
INSERT INTO public.spaces VALUES ('d045834e-0e9a-4457-99f3-dee26476dc9c', NULL, '00000000-0000-0000-0000-000000000060', 'India', 'india', 'From South Asia to cities and towns across the globe — this is the gathering point for a diaspora that never lost touch with home. It is set in South Asia, sharing borders with Pakistan. Share local news, discover events, trade on the marketplace, and tap into remittance rates, scholarship finds, and community resources — all in one place.', '{"title": "India", "extract": "India, officially the Republic of India, is a country in South Asia. It is the world''s seventh-largest country by area and the largest by population. Bounded by the Indian Ocean on the south, the Arabian Sea on the southwest, and the Bay of Bengal on the southeast, it shares land borders with Pakistan to the west; China, Nepal, and Bhutan to the north; and Bangladesh and Myanmar to the east. In the Indian Ocean, India is near Sri Lanka and the Maldives.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/4/41/Flag_of_India.svg/330px-Flag_of_India.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/India", "description": "Country in South Asia"}', '926fad0e-2a98-4846-9668-656ff63a8630', NULL, 'IN', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:48.721064+01', NULL, NULL, '{india,in,asia,community,diaspora}', NULL, 'Asia', 'Southern Asia', NULL);
INSERT INTO public.spaces VALUES ('5537b4dd-352a-42ab-b6cf-ac801321cec7', NULL, '00000000-0000-0000-0000-000000000060', 'Kazakhstan', 'kazakhstan', 'Landlocked in Eastern Europe and Central Asia but connected to the world — this is where the diaspora gathers, no matter how far they''ve traveled. It is set in Eastern Europe and Central Asia, landlocked, sharing borders with Russia, China, Kyrgyzstan, and Uzbekistan, with Astana as its capital.', '{"title": "Kazakhstan", "extract": "Kazakhstan, officially the Republic of Kazakhstan, is a landlocked country situated primarily in Central Asia, with a portion of its territory extending into Eastern Europe. It borders Russia to the north and west, China to the east, Kyrgyzstan to the southeast, Uzbekistan to the south, and Turkmenistan to the southwest, and it has a coastline along the Caspian Sea. The capital is Astana, and the country''s largest city and principal cultural and economic center is Almaty, which served as the capital until 1997.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d3/Flag_of_Kazakhstan.svg/330px-Flag_of_Kazakhstan.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Kazakhstan", "description": "Country in Eastern Europe and Central Asia"}', 'e6a18fcc-0065-4895-a0ab-56680c3ce5ce', NULL, 'KZ', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:54.774386+01', NULL, NULL, '{kazakhstan,kz,europe,landlocked,community,diaspora}', NULL, 'Asia', 'Central Asia', NULL);
INSERT INTO public.spaces VALUES ('33a5f84e-b551-473c-ad5c-fc4f33b2484d', NULL, '00000000-0000-0000-0000-000000000060', 'Libya', 'libya', 'Your digital anchor in North Africa — from Tripoli to the farthest corners of the diaspora, everything flows through here. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "Libya", "extract": "Libya, officially the State of Libya, is a country in the Maghreb region of North Africa. It borders the Mediterranean Sea to the north, Egypt to the east, Sudan to the southeast, Chad to the south, Niger to the southwest, Algeria to the west, and Tunisia to the northwest. With an area of almost 1.8 million km2 (700,000 sq mi), Libya is the fourth-largest country in Africa and the Arab world, and the 16th-largest in the world. The country claims 32,000 square kilometres of southeastern Algeria, south of the Libyan town of Ghat. The capital and largest city is Tripoli, located in the northwest and containing over a million of Libya''s seven million people.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/05/Flag_of_Libya.svg/330px-Flag_of_Libya.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Libya", "description": "Country in North Africa"}', 'b3023239-57eb-490f-a307-45b5bb1be38f', NULL, 'LY', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:00.327213+01', NULL, NULL, '{libya,ly,africa,community,diaspora}', NULL, 'Africa', 'Northern Africa', NULL);
INSERT INTO public.spaces VALUES ('0d10d9e8-8bcc-4c3c-b756-3aed6677a83d', NULL, '00000000-0000-0000-0000-000000000060', 'Marshall Islands', 'marshall-islands', 'An island nation with a worldwide footprint — this is where the diaspora comes home. It is an island nation. Share local news, discover events, trade on the marketplace, and tap into remittance rates, scholarship finds, and community resources — all in one place.', '{"title": "Marshall Islands", "extract": "The Marshall Islands, officially the Republic of the Marshall Islands, is an archipelagic country in Oceania. The sovereign state lies west of the International Date Line and north of the equator in the Micronesia region of the Northwestern Pacific Ocean.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/2e/Flag_of_the_Marshall_Islands.svg/330px-Flag_of_the_Marshall_Islands.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Marshall_Islands", "description": "Island country in the Pacific Ocean"}', '13ac2f92-4563-4d08-a53d-8ef20ef39b0e', NULL, 'MH', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:06.375975+01', NULL, 'USD', '{"marshall islands",marshall-islands,mh,pacific,island,community,diaspora}', NULL, 'Oceania', 'Micronesia', NULL);
INSERT INTO public.spaces VALUES ('94cab7ef-6de9-4076-ab24-552650253d56', NULL, '00000000-0000-0000-0000-000000000060', 'Myanmar', 'myanmar', 'From Southeast Asia to cities and towns across the globe — this is the gathering point for a diaspora that never lost touch with home. It is set in Southeast Asia, sharing borders with India, Bangladesh, China, and Laos, with Naypyidaw as its capital.', '{"title": "Myanmar", "extract": "Myanmar, officially the Republic of the Union of Myanmar and also referred to as Burma, is a country in northwest Southeast Asia. It is the largest country by area in Mainland Southeast Asia and has a population of about 55 million. It is bordered by India and Bangladesh to the northwest, China to the northeast, Laos and Thailand to the east and southeast, and the Andaman Sea and the Bay of Bengal to the south and southwest. The country''s capital city is Naypyidaw, while its largest city is Yangon.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/8c/Flag_of_Myanmar.svg/330px-Flag_of_Myanmar.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Myanmar", "description": "Country in Southeast Asia"}', '400d4366-b93f-4423-a58e-34bba438f094', NULL, 'MM', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:13.436016+01', NULL, NULL, '{myanmar,mm,asia,community,diaspora}', NULL, 'Asia', 'South-Eastern Asia', NULL);
INSERT INTO public.spaces VALUES ('dddb1650-8e74-41f8-aa8e-ac04587fc5e3', NULL, '00000000-0000-0000-0000-000000000060', 'Saint-Barthelemy', 'saint-barthelemy', 'Rooted here, reaching across continents — this space bridges home and diaspora. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "Saint Barthélemy", "extract": "Saint Barthélemy, officially the Territorial Collectivity of Saint Barthélemy, also known as St. Barts and St. Barths (English) or St. Barth (French), is an overseas collectivity of France in the Caribbean. The island lies about 30 kilometres (19 mi) southeast of the island of Saint Martin. It is northeast of the Dutch islands of Saba and Sint Eustatius, and north of the independent country of Saint Kitts and Nevis.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/b4/Flag_of_Saint_Barth%C3%A9lemy_%28local%29.svg/330px-Flag_of_Saint_Barth%C3%A9lemy_%28local%29.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Saint_Barth%C3%A9lemy", "description": "Overseas collectivity of France"}', '133ea48b-2793-460a-8b64-a724d34dd643', NULL, 'BL', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:30.589609+01', NULL, 'EUR', '{saint-barthelemy,bl,island,community,diaspora}', NULL, 'Americas', 'Caribbean', NULL);
INSERT INTO public.spaces VALUES ('23f0436e-7e6b-4cbe-95e4-b6d4d7cf93d6', NULL, '00000000-0000-0000-0000-000000000060', 'Serbia', 'serbia', 'Surrounded by Hungary, Romania, Bulgaria, and Macedonia, yet its people have crossed every border and ocean — this space bridges home and diaspora. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "Serbia", "extract": "Serbia, officially the Republic of Serbia, is a landlocked country in Southeastern and Central Europe. Located in the Balkans, it is bordered by Hungary to the north, Romania to the northeast, Bulgaria to the southeast, North Macedonia to the south, Croatia to the northwest, Bosnia and Herzegovina to the west, and Montenegro to the southwest. Serbia also claims to share a border with Albania through the disputed territory of Kosovo. Serbia has about 6.5 million inhabitants, excluding Kosovo. Belgrade, Serbia''s capital, is also its largest city.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/ff/Flag_of_Serbia.svg/330px-Flag_of_Serbia.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Serbia", "description": "Country in Southeast and Central Europe"}', '4537fdeb-04c4-4439-beb9-61768d90655f', NULL, 'RS', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:36.643393+01', NULL, NULL, '{serbia,rs,europe,landlocked,community,diaspora}', NULL, 'Europe', 'Southern Europe', NULL);
INSERT INTO public.spaces VALUES ('5bb5e029-6cd6-4296-aec0-fdb9ee019f87', NULL, '00000000-0000-0000-0000-000000000060', 'Sint Maarten (Dutch part)', 'sint-maarten-dutch-part', 'It is with Philipsburg as its capital. From the streets of Philipsburg to diaspora communities worldwide, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Sint Maarten", "extract": "Sint Maarten is a constituent country of the Kingdom of the Netherlands located in the Caribbean region of North America. With a population of 58,477 as of June 2023 on an area of 34 km2 (13 sq mi), it encompasses the southern 44% of the divided island of Saint Martin, while the northern 56% of the island constitutes the French overseas collectivity of Saint Martin. Sint Maarten''s capital is Philipsburg. Collectively, Sint Maarten and the other Dutch islands in the Caribbean are often called the Dutch Caribbean.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d3/Flag_of_Sint_Maarten.svg/330px-Flag_of_Sint_Maarten.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Sint_Maarten", "description": "Dutch Caribbean island country"}', 'dc1237fa-9625-473a-bc2f-4b137c5e283e', NULL, 'SX', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:38.662901+01', NULL, NULL, '{"sint maarten (dutch part)",sint-maarten-dutch-part,sx,caribbean,island,community,diaspora}', NULL, 'Americas', 'Caribbean', NULL);
INSERT INTO public.spaces VALUES ('b0ce48fe-e7a0-45dc-8017-52787a453155', NULL, '00000000-0000-0000-0000-000000000060', 'The Bahamas', 'the-bahamas', 'It is set in Caribbean, an island nation, with Nassau on the island of New Providence as its capital. From the streets of Nassau on the island of New Providence to diaspora communities worldwide, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "The Bahamas", "extract": "The Bahamas, officially the Commonwealth of The Bahamas, is an archipelagic country in the Caribbean located within the Lucayan Archipelago in the Atlantic Ocean. The country comprises 700 islands, and more than 2,500 cays in the Atlantic Ocean, located north of Cuba and north-west of the island of Hispaniola and the Turks and Caicos Islands, southeast of the US state of Florida and east of the Florida Keys. The capital and largest city is Nassau on the island of New Providence. The Royal Bahamas Defence Force describes the Bahamas'' territory as encompassing 470,000 km2 (180,000 sq mi) of ocean space.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/93/Flag_of_the_Bahamas.svg/330px-Flag_of_the_Bahamas.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/The_Bahamas", "description": "Country of islands in the Caribbean"}', '8395df36-2168-412c-8efa-6b54f33d9cbe', NULL, 'BS', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:49.234806+01', NULL, NULL, '{"the bahamas",the-bahamas,bs,caribbean,island,community,diaspora}', NULL, 'Americas', 'Caribbean', NULL);
INSERT INTO public.spaces VALUES ('45f13264-2076-4701-9d1f-c23a5272a267', NULL, '00000000-0000-0000-0000-000000000060', 'Trinidad and Tobago', 'trinidad-and-tobago', 'An island nation in Caribbean with a diaspora scattered across every continent — this space brings them all back to one table. It is set in Caribbean, an island nation, with Port of Spain as its capital. Share local news, discover events, trade on the marketplace, and tap into remittance rates, scholarship finds, and community resources — all in one place.', '{"title": "Trinidad and Tobago", "extract": "Trinidad and Tobago, officially the Republic of Trinidad and Tobago, is the southernmost archipelagic country in the Caribbean, comprising the main islands of Trinidad and Tobago, along with several smaller islets. The capital city is Port of Spain, while its largest and most populous municipality is Chaguanas. Trinidad and Tobago comprises the southernmost islands of the Caribbean eastern islands chain, and it is close to the continent of South America, being north to northeast of Venezuela and northwest of Guyana.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/64/Flag_of_Trinidad_and_Tobago.svg/330px-Flag_of_Trinidad_and_Tobago.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Trinidad_and_Tobago", "description": "Country in the Caribbean"}', '5816842f-3a19-49d2-add1-6dff8d4cf018', NULL, 'TT', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:52.255168+01', NULL, NULL, '{"trinidad and tobago",trinidad-and-tobago,tt,caribbean,island,community,diaspora}', NULL, 'Americas', 'Caribbean', NULL);
INSERT INTO public.spaces VALUES ('b4c383ad-0e03-4072-b175-33f4e9c521ea', NULL, '00000000-0000-0000-0000-000000000060', 'Vanuatu', 'vanuatu', 'An island nation in Oceania with a diaspora scattered across every continent — this space brings them all back to one table. It is set in Oceania, an island nation. Share local news, discover events, trade on the marketplace, and tap into remittance rates, scholarship finds, and community resources — all in one place.', '{"title": "Vanuatu", "extract": "Vanuatu, officially the Republic of Vanuatu, is an archipelagic country in Melanesia located in the South Pacific Ocean. The archipelago, which is of volcanic origin, is 1,750 km (1,090 mi) east of northern Australia, 540 km (340 mi) northeast of New Caledonia, east of New Guinea, southeast of Solomon Islands, and west of Fiji.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/6e/Flag_of_Vanuatu_%28official%29.svg/330px-Flag_of_Vanuatu_%28official%29.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Vanuatu", "description": "Country in Oceania"}', '6cc82b9e-3195-4a96-b9b3-ddadfe5cc5c1', NULL, 'VU', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:59.318031+01', NULL, NULL, '{vanuatu,vu,oceania,island,community,diaspora}', NULL, 'Oceania', 'Melanesia', NULL);
INSERT INTO public.spaces VALUES ('f296baed-b52b-4d68-aef1-0fd3ce4531af', NULL, '00000000-0000-0000-0000-000000000060', 'Niue', 'niue', 'It is an island nation. Whether you''re home or building a life elsewhere, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Niue", "extract": "Niue is a self-governing island country in free association with New Zealand. It is situated in the South Pacific Ocean, is part of Polynesia, and is predominantly inhabited by Polynesians. As one of the world''s largest coral islands, Niue is nicknamed \"The Rock\", which comes from the traditional name \"Rock of Polynesia\".", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/01/Flag_of_Niue.svg/330px-Flag_of_Niue.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Niue", "description": "Island country"}', '4280360b-d810-4cd0-9705-d10dba602cdd', NULL, 'NU', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:18.482065+01', NULL, NULL, '{niue,nu,island,community,diaspora}', NULL, 'Oceania', 'Polynesia', NULL);
INSERT INTO public.spaces VALUES ('12f74d83-a900-473a-b5e6-0a990264d492', NULL, '00000000-0000-0000-0000-000000000060', 'Bermuda', 'bermuda', 'Every journey out of North Atlantic carries a story — of ambition, of longing, of roots that stretch but never break. Discover local businesses, share news from home, find events near you, and build a network that spans borders — all on JapaConnect.', '{"title": "Bermuda", "extract": "Bermuda is a British Overseas Territory in the North Atlantic Ocean. The closest land outside the territory is in the US state of North Carolina, about 1,035 km (643 mi) to the west-northwest.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/bf/Flag_of_Bermuda.svg/330px-Flag_of_Bermuda.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Bermuda", "description": "British Overseas Territory in the North Atlantic"}', 'c3ec1df6-201d-4188-afbe-4470d05f58cc', NULL, 'BM', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:10.393411+01', NULL, NULL, '{bermuda,bm,community,diaspora}', NULL, 'Americas', 'Northern America', NULL);
INSERT INTO public.spaces VALUES ('62510f0a-9627-44d4-bf47-7a4415428209', NULL, '00000000-0000-0000-0000-000000000060', 'Bonaire, Sint Eustatius and Saba', 'bonaire-sint-eustatius-and-saba', 'Every journey carries a story — of ambition, of longing, of roots that stretch but never break. Discover local businesses, share news from home, find events near you, and build a network that spans borders — all on JapaConnect.', '{"title": "Caribbean Netherlands", "extract": "The Caribbean Netherlands is a geographic region of the Netherlands located outside Europe, in the Caribbean, consisting of three special municipalities. These are the islands of Bonaire, Sint Eustatius, and Saba, as they are also known in legislation, or the BES islands for short. The islands are officially classified as public bodies in the Netherlands and as overseas territories of the European Union; as such, European Union law does not automatically apply to them.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/20/Flag_of_the_Netherlands.svg/330px-Flag_of_the_Netherlands.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Caribbean_Netherlands", "description": "Caribbean municipalities of the Netherlands"}', '22c286b0-6f93-4686-acb5-14e0b28d69cf', NULL, 'BQ', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:11.908981+01', NULL, 'USD', '{"bonaire, sint eustatius and saba",bonaire-sint-eustatius-and-saba,bq,caribbean,island,community,diaspora}', NULL, 'Americas', 'Caribbean', NULL);
INSERT INTO public.spaces VALUES ('b1fabc9e-407b-4f9e-8ee8-989ff7737ceb', NULL, '00000000-0000-0000-0000-000000000060', 'Saint Helena', 'saint-helena', 'Your digital anchor in South Atlantic Ocean — wherever the diaspora has settled, this is home base. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "Saint Helena", "extract": "Saint Helena is a volcanic tropical island located in the South Atlantic Ocean, west of Africa. The nearest countries geographically are Angola and Namibia. The island is about 1,950 km (1,210 mi) west of Angola, and 4,000 km (2,500 mi) east of Rio de Janeiro, Brazil. It is one of the three constituent parts of Saint Helena, Ascension and Tristan da Cunha, a British overseas territory.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/00/Flag_of_Saint_Helena.svg/330px-Flag_of_Saint_Helena.svg.png", "content_url": "https://en.wikipedia.org/wiki/Saint_Helena", "description": "British Overseas Territory in the South Atlantic Ocean"}', 'c141239d-d5df-4868-978f-70d54aa3922d', NULL, 'SH', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:31.094198+01', NULL, NULL, '{"saint helena",saint-helena,sh,island,community,diaspora}', NULL, 'Africa', 'Western Africa', NULL);
INSERT INTO public.spaces VALUES ('d6352a2c-50e2-436f-8787-3475fc0506d2', NULL, '00000000-0000-0000-0000-000000000060', 'Bulgaria', 'bulgaria', 'Your digital anchor in Southeastern Europe — wherever the diaspora has settled, this is home base. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "Bulgaria", "extract": "Bulgaria, officially the Republic of Bulgaria, is a country in Southeastern Europe. It is situated on the eastern portion of the Balkans directly south of the Danube river and west of the Black Sea. Bulgaria is bordered by Greece and Turkey to the south, Serbia and North Macedonia to the west, and Romania across the Danube river to the north. It covers a territory of 110,994 square kilometres (42,855 sq mi), making it the tenth largest within the European Union and the sixteenth-largest country in Europe by area. Sofia is the nation''s capital and largest city; other major cities include Plovdiv, Varna, and Burgas.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/9a/Flag_of_Bulgaria.svg/330px-Flag_of_Bulgaria.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Bulgaria", "description": "Country in Southeastern Europe"}', '1d83eb09-c7d0-44ac-ad07-4fc3e5857144', NULL, 'BG', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:15.443976+01', NULL, 'EUR', '{bulgaria,bg,europe,community,diaspora}', NULL, 'Europe', 'Eastern Europe', NULL);
INSERT INTO public.spaces VALUES ('9066a347-3cba-4f78-a733-561215256093', NULL, '00000000-0000-0000-0000-000000000060', 'Comoros', 'comoros', 'Rooted here, reaching across continents — this space bridges home and diaspora. Moroni is the capital. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "Comoros", "extract": "The Comoros, officially the Union of the Comoros, is an archipelagic country made up of three islands in Southeast Africa, located at the northern end of the Mozambique Channel in the Indian Ocean. Its capital and largest city is Moroni. The predominant religion of the population—and the official state religion—is Islam. Comoros proclaimed its independence from France on 6 July 1975. The country has three official languages: Comorian, French and Arabic. The Comoros is the only country of the Arab League which is entirely in the Southern Hemisphere. It is also a member state of the African Union, the Organisation internationale de la Francophonie, the Organisation of Islamic Co-operation, and the Indian Ocean Commission.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/94/Flag_of_the_Comoros.svg/330px-Flag_of_the_Comoros.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Comoros", "description": "African island country in the Indian Ocean"}', '902c2775-7b56-4f67-b4d4-9887e14912eb', NULL, 'KM', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:23.001636+01', NULL, NULL, '{comoros,km,africa,island,community,diaspora}', NULL, 'Africa', 'Eastern Africa', NULL);
INSERT INTO public.spaces VALUES ('ba064c3e-7fa6-4f84-a695-feca64262ae2', NULL, '00000000-0000-0000-0000-000000000060', 'Egypt', 'egypt', 'Most populous country in the Arab world in North Africa, shaped by the Sahara. It is set in North Africa, sharing borders with Palestine, Israel, Sudan, and Libya. Whether you''re still in North Africa or building a life elsewhere, this is your space to connect, trade, and stay rooted.', '{"title": "Egypt", "extract": "Egypt, officially the Arab Republic of Egypt, is a country spanning the northeast corner of Africa and southwest corner of Asia via the Sinai Peninsula. It is bordered by the Mediterranean Sea to the north, Palestine and Israel to the northeast, the Red Sea to the east, Sudan and the Sahara to the south, and Libya to the west. The Gulf of Aqaba in the northeast separates Egypt from Jordan and Saudi Arabia. Cairo is the capital, largest city, and leading cultural centre, while Alexandria is the second-largest city and an important hub of industry and tourism. With over 107 million inhabitants, Egypt is the most populous country in the Arab world, third-most populous country in Africa, and 15th-most populated in the world.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/fe/Flag_of_Egypt.svg/330px-Flag_of_Egypt.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Egypt", "description": "Country in North Africa"}', '2f70b3d6-9189-4d88-81f6-5350928c7890', NULL, 'EG', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:30.575379+01', NULL, NULL, '{egypt,eg,africa,community,diaspora}', NULL, 'Africa', 'Northern Africa', NULL);
INSERT INTO public.spaces VALUES ('e06a249c-6c0a-4286-8561-92d459618568', NULL, '00000000-0000-0000-0000-000000000060', 'French Southern Territories', 'french-southern-territories', 'Rooted here, reaching across continents — this space bridges home and diaspora. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "French Southern and Antarctic Lands", "extract": "The French Southern and Antarctic Lands is an overseas territory of France.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/a7/Flag_of_the_French_Southern_and_Antarctic_Lands.svg/330px-Flag_of_the_French_Southern_and_Antarctic_Lands.svg.png", "content_url": "https://en.wikipedia.org/wiki/French_Southern_and_Antarctic_Lands", "description": "Overseas territory of France"}', '1d6ae3e6-68fd-4d2a-9055-7af3d7209add', NULL, 'TF', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:37.62608+01', NULL, 'EUR', '{"french southern territories",french-southern-territories,tf,community,diaspora}', NULL, 'Africa', 'Southern Africa', NULL);
INSERT INTO public.spaces VALUES ('9b84588d-2775-4329-a359-11cf1d213a21', NULL, '00000000-0000-0000-0000-000000000064', 'Universidad CES', 'universidad-ces', NULL, '{"logo": "http://commons.wikimedia.org/wiki/Special:FilePath/LogoUCV%202018.png", "name": "Cesar Vallejo University", "image": "http://commons.wikimedia.org/wiki/Special:FilePath/Frontis%20LosOlivos.tif", "country": "Q419", "founded": "+1991-11-12T00:00:00Z", "website": "https://www.ucv.edu.pe", "description": "private university in Peru", "wikidata_id": "Q2340018", "wikipedia_url": "https://en.wikipedia.org/wiki/Q2340018"}', '068156c6-b162-45ef-a932-18acb2ef22a9', NULL, 'CO', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.353781+01', '2026-08-09 21:05:04.473272+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('b710fee7-6b8e-4823-9b71-201db26fb0ea', NULL, '00000000-0000-0000-0000-000000000060', 'Guam', 'guam', 'Every journey out of Micronesia carries a story — of ambition, of longing, of roots that stretch but never break. From the capital, Hagåtña, to the cities where the diaspora now lives, the connection to home runs deep. Discover local businesses, share news from home, find events near you, and build a network that spans borders — all on JapaConnect.', '{"title": "Guam", "extract": "Guam is an organized, unincorporated territory of the United States in the Micronesia subregion of the western Pacific Ocean. Guam''s capital is Hagåtña, and the most populous village is Dededo. It is the westernmost point and territory of the United States, reckoned from the geographic center of the U.S. In Oceania, Guam is the largest and southernmost of the Mariana Islands and the largest island in Micronesia. As of 2022, its population was 168,801. Chamorros are its largest ethnic group, but a minority on the multiethnic island. The territory spans 210 square miles and has a population density of 775 per square mile (299/km2).", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/07/Flag_of_Guam.svg/330px-Flag_of_Guam.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Guam", "description": "U.S. territory in Micronesia"}', 'dd3dfa5b-5591-4252-89e6-6c28e0fdf272', NULL, 'GU', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:42.669533+01', NULL, 'USD', '{guam,gu,island,community,diaspora}', NULL, 'Oceania', 'Micronesia', NULL);
INSERT INTO public.spaces VALUES ('2cf936f0-e8d9-462c-9160-c2201d861c0e', NULL, '00000000-0000-0000-0000-000000000060', 'Costa Rica', 'costa-rica', 'It is set in Central America, sharing borders with Nicaragua, Panama, Ecuador, and Cocos Island, with San José as its capital. From the streets of San José to diaspora communities worldwide, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Costa Rica", "extract": "Costa Rica, officially the Republic of Costa Rica, is a country in Central America. It borders Nicaragua to the north, the Caribbean Sea to the northeast, Panama to the southeast, and the Pacific Ocean to the southwest, sharing a maritime border with Ecuador to the south of Cocos Island. It has a population of around five million in a land area of nearly 51,180 km2 (19,760 sq mi); the capital and largest city is San José, home to around 350,000 residents and two million people in the surrounding metropolitan area.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/f2/Flag_of_Costa_Rica.svg/330px-Flag_of_Costa_Rica.svg.png", "content_url": "https://en.wikipedia.org/wiki/Costa_Rica", "description": "Country in Central America"}', 'da724de0-dfec-4b00-8e3e-729c22dde9c9', NULL, 'CR', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:24.520923+01', NULL, NULL, '{"costa rica",costa-rica,cr,"central america",island,community,diaspora}', NULL, 'Americas', 'Central America', NULL);
INSERT INTO public.spaces VALUES ('e9093735-300a-489e-97ae-3d06391291bd', NULL, '00000000-0000-0000-0000-000000000060', 'Man (Isle of)', 'man-isle-of', 'Every journey out of Irish Sea carries a story — of ambition, of longing, of roots that stretch but never break. Discover local businesses, share news from home, find events near you, and build a network that spans borders — all on JapaConnect.', '{"title": "Isle of Man", "extract": "The Isle of Man, also known simply as Man or Mann, is a self-governing British Crown Dependency in the Irish Sea, between Great Britain and Ireland. As head of state, Charles III holds the title Lord of Mann and is represented by a Lieutenant Governor. The government of the United Kingdom is responsible for the Isle of Man''s military defence and represents it abroad, but the Isle of Man still has a separate international identity.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/5d/Flag_of_the_Isle_of_Mann.svg/330px-Flag_of_the_Isle_of_Mann.svg.png", "content_url": "https://en.wikipedia.org/wiki/Isle_of_Man", "description": "British Crown Dependency in the Irish Sea"}', 'e41be1f2-4ccd-4371-b15f-f4d5c5b17299', NULL, 'IM', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:05.871545+01', NULL, 'GBP', '{"man (isle of)",man-isle-of,im,community,diaspora}', NULL, 'Europe', 'Northern Europe', NULL);
INSERT INTO public.spaces VALUES ('82648317-e968-43ba-afdf-8e61de8b510a', NULL, '00000000-0000-0000-0000-000000000060', 'Panama', 'panama', 'From Central America to cities and towns across the globe — this is the gathering point for a diaspora that never lost touch with home. It is set in Central America, sharing borders with Costa Rica and Colombia, with Panama City as its capital.', '{"title": "Panama", "extract": "Panama, officially the Republic of Panama, is a country located at the southern end of Central America in North America, bordering South America. It is bordered by Costa Rica to the west, Colombia to the southeast, the Caribbean Sea to the north, and the Pacific Ocean to the south. Its capital and largest city is Panama City, whose metropolitan area is home to nearly half of the country''s over 4 million inhabitants.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/ab/Flag_of_Panama.svg/330px-Flag_of_Panama.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Panama", "description": "Country in Central America"}', '34953dc4-3357-4280-b305-b08740eb4ab5', NULL, 'PA', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:23.51844+01', NULL, NULL, '{panama,pa,"central america",community,diaspora}', NULL, 'Americas', 'Central America', NULL);
INSERT INTO public.spaces VALUES ('c058556c-1a5d-45b1-a7be-1b007b0a7567', NULL, '00000000-0000-0000-0000-000000000060', 'Pitcairn Island', 'pitcairn-island', 'It is set in Pitcairn Islands, British Overseas Territories. Whether you''re still in Pitcairn Islands, British Overseas Territories or building a life elsewhere, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Pitcairn Island", "extract": "Pitcairn Island is the only inhabited island of the Pitcairn Islands, in the southern Pacific Ocean, of which many of the 40 inhabitants are descendants of mutineers of HMS Bounty.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/2c/Pitcairnsatellite.png/330px-Pitcairnsatellite.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Pitcairn_Island", "description": "Only inhabited island in the Pitcairn Islands, British Overseas Territories"}', 'fe4aaebe-b497-4e4f-9e9b-a68423ff5114', NULL, 'PN', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:26.045453+01', NULL, NULL, '{"pitcairn island",pitcairn-island,pn,island,community,diaspora}', NULL, 'Oceania', 'Polynesia', NULL);
INSERT INTO public.spaces VALUES ('24de1c1f-031d-4b80-8f73-be0c114c000c', NULL, '00000000-0000-0000-0000-000000000064', 'Mustafa Kemal University', 'mustafa-kemal-university', NULL, '{"logo": "http://commons.wikimedia.org/wiki/Special:FilePath/MKU.png", "name": "Hatay Mustafa Kemal University", "country": "Q43", "founded": "+1992-00-00T00:00:00Z", "website": "http://www.mku.edu.tr/", "description": "state university in Hatay, Turkey", "wikidata_id": "Q10952014", "wikipedia_url": "https://en.wikipedia.org/wiki/Q10952014"}', '023952a3-798a-4f9d-be09-d1e807198993', NULL, 'TR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.65283+01', '2026-08-09 16:30:20.404888+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('bd737f18-f623-4ca0-b60e-803f6690ae86', NULL, '00000000-0000-0000-0000-000000000060', 'Gibraltar', 'gibraltar', 'From Iberia to cities and towns across the globe — this is the gathering point for a diaspora that never lost touch with home. It is set in Iberia, sharing borders with Spain. Share local news, discover events, trade on the marketplace, and tap into remittance rates, scholarship finds, and community resources — all in one place.', '{"title": "Gibraltar", "extract": "Gibraltar is a British Overseas Territory and city located at the southern tip of the Iberian Peninsula, on the Bay of Gibraltar, near the exit of the Mediterranean Sea into the Atlantic Ocean. It has an area of 6.8 km2 (2.6 sq mi) and is bordered to the north by Spain. The landscape is dominated by the Rock of Gibraltar, at the foot of which is a densely populated town area. Gibraltar is home to around 34,000 people, primarily Gibraltarians.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/02/Flag_of_Gibraltar.svg/330px-Flag_of_Gibraltar.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Gibraltar", "description": "British Overseas Territory in Iberia"}', 'bb07173f-cf3b-48a4-b9e1-0095536e39f6', NULL, 'GI', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:40.146368+01', NULL, NULL, '{gibraltar,gi,community,diaspora}', NULL, 'Europe', 'Southern Europe', NULL);
INSERT INTO public.spaces VALUES ('34486435-4c64-49e2-a443-5ed0595ed8ea', NULL, '00000000-0000-0000-0000-000000000060', 'Virgin Islands (British)', 'virgin-islands-british', 'It is set in Caribbean. Whether you''re still in Caribbean or building a life elsewhere, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "British Virgin Islands", "extract": "The British Virgin Islands (BVI), officially The Virgin Islands, is a British Overseas Territory in the Caribbean, to the east of Puerto Rico and the US Virgin Islands and north-west of Anguilla. The islands are geographically part of the Virgin Islands archipelago and are located in the Leeward Islands of the Lesser Antilles and part of the West Indies.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/42/Flag_of_the_British_Virgin_Islands.svg/330px-Flag_of_the_British_Virgin_Islands.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/British_Virgin_Islands", "description": "British Overseas Territory in the Caribbean"}', '7c0d3442-8c85-4095-bcf1-7da8e21033a3', NULL, 'VG', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:46:01.350725+01', NULL, 'USD', '{"virgin islands (british)",virgin-islands-british,vg,caribbean,island,community,diaspora}', NULL, 'Americas', 'Caribbean', NULL);
INSERT INTO public.spaces VALUES ('e02aabe6-51a3-48ba-86ce-ee51fc09402d', NULL, '00000000-0000-0000-0000-000000000060', 'Andorra', 'andorra', 'It is set in Southern Europe, landlocked, sharing borders with France and Spain, with Andorra la Vella as its capital. From the streets of Andorra la Vella to diaspora communities worldwide, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Andorra", "extract": "Andorra, officially the Principality of Andorra, is a landlocked country on the Iberian Peninsula, in the eastern Pyrenees in southwestern Europe, bordered by France to the north and Spain to the south. Believed to have been created by Charlemagne, Andorra was ruled by the count of Urgell until 988, when it was transferred to the Diocese of Urgell. Andorra was formed as a polity by a charter in 1278, being a lordship within the Principality of Catalonia until 1715. It is currently headed by two co-princes: the Bishop of Urgell in Catalonia, Spain, and the president of France. Its capital and largest city is Andorra la Vella.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/19/Flag_of_Andorra.svg/330px-Flag_of_Andorra.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Andorra", "description": "Microstate in Southern Europe"}', 'bcc321a6-0d0e-41ad-a198-27d3593deeff', NULL, 'AD', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:01.314314+01', NULL, 'EUR', '{andorra,ad,europe,landlocked,community,diaspora}', NULL, 'Europe', 'Southern Europe', NULL);
INSERT INTO public.spaces VALUES ('5cf12d46-9c07-445f-a5e1-51319a79835d', NULL, '00000000-0000-0000-0000-000000000060', 'Philippines', 'philippines', 'Your digital anchor in Southeast Asia — wherever the diaspora has settled, this is home base. Home to 114 million people, with communities spread far beyond its borders. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "Philippines", "extract": "The Philippines, officially the Republic of the Philippines, is an archipelagic country in Southeast Asia. Located in the western Pacific Ocean, it consists of about 7,641 islands, with a total area of about 300,000 square kilometers, which are broadly categorized in three main geographical divisions from north to south: Luzon, Visayas, and Mindanao. With a population of over 114 million, it is the world''s twelfth-most-populous country.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/99/Flag_of_the_Philippines.svg/330px-Flag_of_the_Philippines.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Philippines", "description": "Archipelagic country in Southeast Asia"}', '8b27cd9d-6bfb-4d21-978c-6d23eb52eb1f', NULL, 'PH', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:25.541552+01', NULL, NULL, '{philippines,ph,asia,island,community,diaspora}', NULL, 'Asia', 'South-Eastern Asia', NULL);
INSERT INTO public.spaces VALUES ('ce8f0042-2985-474e-8f6e-d71c77f575f7', NULL, '00000000-0000-0000-0000-000000000060', 'Cayman Islands', 'cayman-islands', 'It is set in Caribbean, with George Town on Grand Cayman as its capital. From the streets of George Town on Grand Cayman to diaspora communities worldwide, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Cayman Islands", "extract": "The Cayman Islands is a self-governing British Overseas Territory in the western Caribbean. With a population of over 90,000, it is the most populated of all the British Overseas Territories. The 264-square-kilometre (102-square-mile) territory comprises the three islands of Grand Cayman, Cayman Brac and Little Cayman, which are located south of Cuba and north-east of Honduras, between Jamaica and Mexico''s Yucatán Peninsula. The capital city is George Town on Grand Cayman, which is the most populous of the three islands.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/0f/Flag_of_the_Cayman_Islands.svg/330px-Flag_of_the_Cayman_Islands.svg.png", "content_url": "https://en.wikipedia.org/wiki/Cayman_Islands", "description": "British Overseas Territory in the Caribbean"}', 'e63714f2-01ab-4e6c-bf94-4842b92e0488', NULL, 'KY', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:18.97257+01', NULL, NULL, '{"cayman islands",cayman-islands,ky,caribbean,island,community,diaspora}', NULL, 'Americas', 'Caribbean', NULL);
INSERT INTO public.spaces VALUES ('bd94c924-0b43-4b96-bcb0-7751eda40917', NULL, '00000000-0000-0000-0000-000000000060', 'Djibouti', 'djibouti', 'It is set in Horn of Africa, sharing borders with Somalia, Ethiopia, Eritrea, and Aden. Whether you''re still in Horn of Africa or building a life elsewhere, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Djibouti", "extract": "Djibouti, officially the Republic of Djibouti, is a country in the Horn of Africa, bordered by Somalia to the south, Ethiopia to the southwest, Eritrea in the north, and the Red Sea and the Gulf of Aden to the east. The country has an area of 23,200 km2 (8,958 sq mi).", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/34/Flag_of_Djibouti.svg/330px-Flag_of_Djibouti.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Djibouti", "description": "Country in the Horn of Africa"}', 'b743e3fa-1042-405c-b5de-0835101563dc', NULL, 'DJ', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:28.558958+01', NULL, NULL, '{djibouti,dj,africa,community,diaspora}', NULL, 'Africa', 'Eastern Africa', NULL);
INSERT INTO public.spaces VALUES ('1fc8a367-7beb-49e4-bf5c-939257635d84', NULL, '00000000-0000-0000-0000-000000000064', 'Mission College', 'mission-college', NULL, '{"logo": "http://commons.wikimedia.org/wiki/Special:FilePath/Mission%20College%20Logo.jpg", "name": "Mission College", "image": "http://commons.wikimedia.org/wiki/Special:FilePath/2008-1115-002-MissionCollege.jpg", "country": "Q30", "founded": "+1975-00-00T00:00:00Z", "website": "http://www.missioncollege.edu/", "students": "+6504", "description": "public community college in Santa Clara, California, United States", "wikidata_id": "Q6878561", "wikipedia_url": "https://en.wikipedia.org/wiki/Q6878561"}', 'd8b86f10-3f13-46d0-988e-e57d60e8afc3', NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.679268+01', '2026-08-09 19:56:17.662039+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('8881a5c2-1eb1-439d-aaa4-cc5f36fe9a8f', NULL, '00000000-0000-0000-0000-000000000060', 'French Polynesia', 'french-polynesia', 'Rooted in Pacific, reaching across continents — this space bridges home and diaspora. A population of 282 calls it home. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "French Polynesia", "extract": "French Polynesia is an overseas collectivity of France and its sole overseas country; it is classified as a non-self-governing territory by the United Nations. It comprises 121 geographically dispersed islands and atolls stretching over more than 2,000 kilometres (1,200 mi) in the South Pacific Ocean. French Polynesia is associated with the European Union as an overseas country and territory (OCT). The total land area of French Polynesia is 3,521 square kilometres (1,359 sq mi), with a population of 282,596 as of September 2025 of which at least 205,000 live in the Society Islands and the remaining population lives in the rest of the archipelago.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/db/Flag_of_French_Polynesia.svg/330px-Flag_of_French_Polynesia.svg.png", "content_url": "https://en.wikipedia.org/wiki/French_Polynesia", "description": "French overseas collectivity in the Pacific"}', '79c2d300-1e0a-4b15-a852-9bb952c24053', NULL, 'PF', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:37.122909+01', NULL, NULL, '{"french polynesia",french-polynesia,pf,pacific,island,community,diaspora}', NULL, 'Oceania', 'Polynesia', NULL);
INSERT INTO public.spaces VALUES ('244fa6de-f86c-47de-b882-048738a5e0f4', NULL, '00000000-0000-0000-0000-000000000060', 'Grenada', 'grenada', 'An island nation in Caribbean with a diaspora scattered across every continent — this space brings them all back to one table. It is set in Caribbean, an island nation. Share local news, discover events, trade on the marketplace, and tap into remittance rates, scholarship finds, and community resources — all in one place.', '{"title": "Grenada", "extract": "Grenada is an archipelagic country of the West Indies in the eastern Caribbean Sea. The southernmost of the Windward Islands, Grenada is directly south of Saint Vincent and the Grenadines and about 100 miles (160 km) north of Trinidad and the South American mainland.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/bc/Flag_of_Grenada.svg/330px-Flag_of_Grenada.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Grenada", "description": "Country in the Caribbean"}', '672e8b98-225d-4779-acff-38c8324a77eb', NULL, 'GD', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:41.659982+01', NULL, NULL, '{grenada,gd,caribbean,island,community,diaspora}', NULL, 'Americas', 'Caribbean', NULL);
INSERT INTO public.spaces VALUES ('aa6c8c6c-8e05-497f-8745-6082c8c72176', NULL, '00000000-0000-0000-0000-000000000060', 'Indonesia', 'indonesia', 'Your digital anchor in Southeast Asia and Oceania — wherever the diaspora has settled, this is home base. An island nation whose diaspora has reached every corner of the world. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "Indonesia", "extract": "Indonesia, officially the Republic of Indonesia, is a country in Southeast Asia and Oceania, between the Indian and Pacific oceans. Comprising about 17,000 islands, including Sumatra, Java, Sulawesi, and parts of Borneo and New Guinea, Indonesia is the world''s largest archipelagic state and the 14th-largest country by area, at 1,904,569 square kilometres. Indonesia has significant areas of wilderness that support one of the world''s highest levels of biodiversity. It shares land borders with Papua New Guinea, Timor-Leste, and Malaysia, as well as maritime borders with seven other countries, including Australia, Singapore, and the Philippines.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/9f/Flag_of_Indonesia.svg/330px-Flag_of_Indonesia.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Indonesia", "description": "Country in Southeast Asia and Oceania"}', '8396ac85-8f62-42a5-8e3f-6bfa83851f57', NULL, 'ID', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:49.225764+01', NULL, NULL, '{indonesia,id,asia,island,community,diaspora}', NULL, 'Asia', 'South-Eastern Asia', NULL);
INSERT INTO public.spaces VALUES ('cb2411b0-3f0a-4a6f-80c6-94cc9c3b8ad4', NULL, '00000000-0000-0000-0000-000000000060', 'Luxembourg', 'luxembourg', 'It is set in Western Europe, landlocked, sharing borders with Belgium, Germany, and France. Whether you''re still in Western Europe or building a life elsewhere, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Luxembourg", "extract": "Luxembourg, officially the Grand Duchy of Luxembourg, is a landlocked country in Western Europe. It is bordered by Belgium to the west and north, Germany to the east, and France to the south and west. Its capital and most populous city, Luxembourg City, is one of the four institutional seats of the European Union and hosts several EU institutions, notably the Court of Justice of the European Union, the highest judicial authority in the EU.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/da/Flag_of_Luxembourg.svg/330px-Flag_of_Luxembourg.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Luxembourg", "description": "Country in Western Europe"}', '8afd0406-d15b-470d-867d-c88b2d90474c', NULL, 'LU', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:01.836618+01', NULL, 'EUR', '{luxembourg,lu,europe,landlocked,community,diaspora}', NULL, 'Europe', 'Western Europe', NULL);
INSERT INTO public.spaces VALUES ('d215194a-1630-416c-8105-ba1e9997a29d', NULL, '00000000-0000-0000-0000-000000000060', 'Romania', 'romania', 'Largest country in Europe by area in Southeast and Central Europe,. It is set in Southeast and Central Europe, sharing borders with Ukraine, Hungary, Serbia, and Bulgaria. Whether you''re still in Southeast and Central Europe or building a life elsewhere, this is your space to connect, trade, and stay rooted.', '{"title": "Romania", "extract": "Romania is a country in Central and Southeastern Europe. It lies on the lower course of the Danube, north of the Balkan Peninsula, and on the northwestern shore of the Black Sea. It borders Ukraine to the north and east, Hungary to the west, Serbia to the southwest, Bulgaria to the south, Moldova to the east, and the Black Sea to the southeast. It is the twelfth-largest country in Europe by area, covering 238,397 km2 (92,046 mi2), and the sixth-most populous member state of the European Union, with 19 million inhabitants. The capital, largest city and economic centre is Bucharest. Other major cities include Cluj-Napoca, Iași, Constanța, Timișoara and Brașov.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/73/Flag_of_Romania.svg/330px-Flag_of_Romania.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Romania", "description": "Country in Southeast and Central Europe"}', 'c4e1bf61-bd5e-44bc-b405-e5afeb6f19b8', NULL, 'RO', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:29.074885+01', NULL, NULL, '{romania,ro,europe,community,diaspora}', NULL, 'Europe', 'Eastern Europe', NULL);
INSERT INTO public.spaces VALUES ('4368c21b-b416-4192-9690-f2e77115de5c', NULL, '00000000-0000-0000-0000-000000000060', 'Saint Kitts and Nevis', 'saint-kitts-and-nevis', 'An island in West Indies, but its diaspora spans the globe — this space is the bridge between here and everywhere. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "Saint Kitts and Nevis", "extract": "Saint Kitts and Nevis (SKN), officially the Federation of Saint Christopher and Nevis, is an island country located in the Caribbean consisting of the 2 islands of Saint Kitts and Nevis, in the Leeward Islands chain of the Lesser Antilles. With 261 square kilometres (101 sq mi) of territory, and roughly 48,000 inhabitants, it is the smallest sovereign state in the Western Hemisphere, in both area and population, as well as the world''s smallest sovereign federation. The country is a Commonwealth realm, with Charles III as king and head of state.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/fe/Flag_of_Saint_Kitts_and_Nevis.svg/330px-Flag_of_Saint_Kitts_and_Nevis.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Saint_Kitts_and_Nevis", "description": "Country in the West Indies"}', '30d31c3e-ee11-4043-aed3-2fb1c626c038', NULL, 'KN', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:31.598209+01', NULL, NULL, '{"saint kitts and nevis",saint-kitts-and-nevis,kn,island,community,diaspora}', NULL, 'Americas', 'Caribbean', NULL);
INSERT INTO public.spaces VALUES ('2f74d24c-68e4-4b55-acd2-94d7c325d95e', NULL, '00000000-0000-0000-0000-000000000060', 'Western Sahara', 'western-sahara', 'Rooted in north-western Africa, reaching across continents — this space bridges home and diaspora. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "Western Sahara", "extract": "Western Sahara is a United Nations–designated non-self-governing territory in north-western Africa. It has a surface area of 272,000 square kilometres (105,000 sq mi). Western Sahara is the last African colonial state yet to achieve independence and has been dubbed \"Africa''s last colony\". With an estimated 600,000 inhabitants, it is the most sparsely populated territory in Africa and the second most sparsely populated territory in the world after Greenland, consisting mainly of desert flatlands.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/eb/Western_Sahara_%28orthographic_projection%29.svg/330px-Western_Sahara_%28orthographic_projection%29.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Western_Sahara", "description": "Disputed territory in north-western Africa"}', 'fd3b23eb-75f8-404b-a67c-34af4a4eebce', NULL, 'EH', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:46:02.870986+01', NULL, NULL, '{"western sahara",western-sahara,eh,africa,community,diaspora}', NULL, 'Africa', 'Northern Africa', NULL);
INSERT INTO public.spaces VALUES ('879e3cd1-d907-4faf-8027-c79e4261fb26', NULL, '00000000-0000-0000-0000-000000000060', 'Antigua and Barbuda', 'antigua-and-barbuda', 'An island in Lesser Antilles, but its diaspora spans the globe — this space is the bridge between here and everywhere. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "Antigua and Barbuda", "extract": "Antigua and Barbuda is an archipelagic country in the Caribbean composed of Antigua, Barbuda, and dozens of other small islands. Antigua and Barbuda has a total area of 440 km2, making it one of the smallest countries in the Caribbean. The country is mostly flat, with the highest points on Antigua being in the Shekerley Mountains and on Barbuda the Highlands. The country has a tropical savanna climate, with pockets of tropical monsoon in Antigua''s southwest. Its most populated city is St. John''s, followed by All Saints and Bolans. The sole settlement in Barbuda is Codrington. Most of the country resides in the Central Plain that stretches from St. John''s to English Harbour.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/89/Flag_of_Antigua_and_Barbuda.svg/330px-Flag_of_Antigua_and_Barbuda.svg.png", "content_url": "https://en.wikipedia.org/wiki/Antigua_and_Barbuda", "description": "Country in the Lesser Antilles"}', 'b2d1412f-57f4-414d-8780-ea4face00c6e', NULL, 'AG', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:03.32996+01', NULL, NULL, '{"antigua and barbuda",antigua-and-barbuda,ag,island,community,diaspora}', NULL, 'Americas', 'Caribbean', NULL);
INSERT INTO public.spaces VALUES ('2d6e1125-bcc9-4951-86df-8d5ee3e3fb18', NULL, '00000000-0000-0000-0000-000000000060', 'Guyana', 'guyana', 'Rooted in South America, sharing borders with Suriname, Brazil, and Venezuela, and reaching across continents — this space bridges home and diaspora. Georgetown is the capital. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "Guyana", "extract": "Guyana, officially the Co-operative Republic of Guyana, is a country on the northern coast of South America. It is bordered by the Atlantic Ocean to the north, Suriname to the east, Brazil to the south and southwest, and Venezuela to the west. It is part of The Guianas. The capital and largest city is Georgetown.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/99/Flag_of_Guyana.svg/330px-Flag_of_Guyana.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Guyana", "description": "Country in South America"}', '816e24c3-7aed-4b74-aa6b-957dc83b0d5c', NULL, 'GY', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:45.192581+01', NULL, NULL, '{guyana,gy,"south america",community,diaspora}', NULL, 'Americas', 'South America', NULL);
INSERT INTO public.spaces VALUES ('226ef7e5-3f9c-450e-9d04-7825705bfdf2', NULL, '00000000-0000-0000-0000-000000000060', 'Bahrain', 'bahrain', 'An island in West Asia, but its diaspora spans the globe — this space is the bridge between here and everywhere. Manama is the capital. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "Bahrain", "extract": "Bahrain, officially the Kingdom of Bahrain, is an island country in the eastern part of Arabian Peninsula in West Asia. Situated near the western shore of the Persian Gulf, the country comprises a small archipelago of 33 natural islands and an additional 50 artificial islands, centered on Bahrain Island, which makes up around 80 percent of the country''s landmass. Bahrain is situated between Qatar and the northeastern coast of Saudi Arabia, to which it is connected by the King Fahd Causeway. The population is 1,588,670 as of 2024, of whom 739,736 are Bahraini nationals, and 848,934 are expatriates. Bahrain spans some 760 square kilometres (290 sq mi) and is the third-smallest nation in Asia after Maldives and Singapore. The capital and largest city is Manama.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/2c/Flag_of_Bahrain.svg/330px-Flag_of_Bahrain.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Bahrain", "description": "Country in West Asia"}', '838fe563-73f1-4101-af2f-039dc865969c', NULL, 'BH', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:06.863849+01', NULL, NULL, '{bahrain,bh,asia,island,community,diaspora}', NULL, 'Asia', 'Western Asia', NULL);
INSERT INTO public.spaces VALUES ('bd5f9a9b-1405-4b09-850a-ea718a1a9260', NULL, '00000000-0000-0000-0000-000000000060', 'Cyprus', 'cyprus', 'It is an island nation. Whether you''re home or building a life elsewhere, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Cyprus", "extract": "Cyprus, officially the Republic of Cyprus, is an island country in the eastern Mediterranean Sea, located off the coast of the Levant mainland in West Asia. The island of Cyprus, which is the third largest and third most populous island in the Mediterranean, is divided along the United Nations Buffer Zone between the internationally recognised Republic of Cyprus and the Turkish Republic of Northern Cyprus, which is recognised only by Turkey. The south of the island also hosts the British sovereign military bases of Akrotiri and Dhekelia. The capital and largest city of Cyprus is Nicosia.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d4/Flag_of_Cyprus.svg/330px-Flag_of_Cyprus.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Cyprus", "description": "Island country in the Mediterranean Sea"}', '91ceb5b6-fca6-4fe0-9436-2e3c0935bce9', NULL, 'CY', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:26.539183+01', NULL, 'EUR', '{cyprus,cy,island,community,diaspora}', NULL, 'Europe', 'Southern Europe', NULL);
INSERT INTO public.spaces VALUES ('27ac61b9-8e7a-465d-867b-4a689b397086', NULL, '00000000-0000-0000-0000-000000000060', 'Ecuador', 'ecuador', 'Your digital anchor in South America — from Quito to the farthest corners of the diaspora, everything flows through here. From the capital to Guayaquil and beyond, the diaspora carries the spirit of home wherever they go. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "Ecuador", "extract": "Ecuador, officially the Republic of Ecuador, is a country in northwestern South America, bordered by Colombia on the north, Peru on the east and south, and the Pacific Ocean on the west. It also includes the Galápagos Province which contains the Galápagos Islands in the Pacific, about 1,000 kilometers west of the mainland. The country''s capital is Quito, and the largest city is Guayaquil.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/e8/Flag_of_Ecuador.svg/330px-Flag_of_Ecuador.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Ecuador", "description": "Country in South America"}', 'c4e50924-3036-4a41-bc1f-ca15a7d1b70e', NULL, 'EC', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:30.069875+01', NULL, 'USD', '{ecuador,ec,"south america",island,community,diaspora}', NULL, 'Americas', 'South America', NULL);
INSERT INTO public.spaces VALUES ('6cef6dcd-be3f-4b45-bb2b-bfa46c6f4757', NULL, '00000000-0000-0000-0000-000000000060', 'Guinea', 'guinea', 'It is set in West Africa, sharing borders with Guinea-Bissau, Senegal, Mali, and Sierra Leone. Whether you''re still in West Africa or building a life elsewhere, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Guinea", "extract": "Guinea, officially the Republic of Guinea, is a coastal country located in West Africa. It borders the Atlantic Ocean to the west, Guinea-Bissau to the northwest, Senegal to the north, Mali to the northeast, Ivory Coast to the southeast, and Sierra Leone and Liberia to the south. It is sometimes referred to as Guinea-Conakry, after its capital Conakry, to distinguish it from other territories in the eponymous region, such as Guinea-Bissau and Equatorial Guinea. At the census held on 1 July 2025, Guinea had a population of over 17.5 million and an area of 245,857 square kilometres (94,926 sq mi).", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/ed/Flag_of_Guinea.svg/330px-Flag_of_Guinea.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Guinea", "description": "Country in West Africa"}', 'aaa8e863-442e-45f2-a386-3a7650eb6773', NULL, 'GN', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:44.184375+01', NULL, NULL, '{guinea,gn,africa,community,diaspora}', NULL, 'Africa', 'Western Africa', NULL);
INSERT INTO public.spaces VALUES ('5e9c1e67-ada1-4fda-810a-ba2fe8ca208e', NULL, '00000000-0000-0000-0000-000000000060', 'Maldives', 'maldives', 'It is set in South Asia, an island nation. Whether you''re still in South Asia or building a life elsewhere, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Maldives", "extract": "The Maldives, officially the Republic of Maldives, and historically known as the Maldive Islands, is an archipelagic country in South Asia, located in the Indian Ocean, near the southeastern boundary of the Arabian Sea. The Maldives is located southwest of India and Sri Lanka, about 750 kilometres from the Asian continent''s mainland. The Maldives'' chain of 26 atolls stretches across the equator from Ihavandhippolhu Atoll in the north to Addu Atoll in the south.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/0f/Flag_of_Maldives.svg/330px-Flag_of_Maldives.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Maldives", "description": "Island country in South Asia"}', '8765a88e-2945-4aed-8f7e-ed6ad74ffbf5', NULL, 'MV', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:04.355147+01', NULL, NULL, '{maldives,mv,asia,island,community,diaspora}', NULL, 'Asia', 'Southern Asia', NULL);
INSERT INTO public.spaces VALUES ('f89c08ca-b621-4223-9c0d-d33ee1590404', NULL, '00000000-0000-0000-0000-000000000060', 'Latvia', 'latvia', 'Every journey out of Northern Europe carries a story — of ambition, of longing, of roots that stretch but never break. From the capital, Riga, to the cities where the diaspora now lives, the connection to home runs deep. Discover local businesses, share news from home, find events near you, and build a network that spans borders — all on JapaConnect.', '{"title": "Latvia", "extract": "Latvia, officially the Republic of Latvia, is a country in the Baltic region of northern Europe. It is one of the three Baltic states, along with Estonia to the north and Lithuania to the south. It borders Russia to the east and Belarus to the southeast and shares a maritime border with Sweden to the west. Latvia covers an area of 64,573 km2 (24,932 sq mi), with a population of 1.83 million. The country has a temperate seasonal climate. Its capital and largest city is Riga. Latvians, who are the titular nation and comprise 65.5% of the country''s population, belong to the ethnolinguistic group of the Balts and speak Latvian. Russians are the most prominent minority in the country, at almost a quarter of the population; 37.7% of the population speak Russian as their native tongue.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/84/Flag_of_Latvia.svg/330px-Flag_of_Latvia.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Latvia", "description": "Country in Northern Europe"}', '9f3d572a-d0a6-4004-b34f-1e914a20ddce', NULL, 'LV', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:58.303281+01', NULL, 'EUR', '{latvia,lv,europe,community,diaspora}', NULL, 'Europe', 'Northern Europe', NULL);
INSERT INTO public.spaces VALUES ('20270fc5-39f0-4b51-8c40-c40233cc33bf', NULL, '00000000-0000-0000-0000-000000000060', 'Lithuania', 'lithuania', 'Your digital anchor in Northern Europe — from Vilnius to the farthest corners of the diaspora, everything flows through here. Home to 2 people, with communities spread far beyond its borders. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "Lithuania", "extract": "Lithuania, officially the Republic of Lithuania, is a country in the Baltic region of Europe. It is one of three Baltic states and lies on the eastern shore of the Baltic Sea, bordered by Latvia to the north, Belarus to the east and south, Poland to the south, and the Russian semi-exclave of Kaliningrad Oblast to the southwest, with a maritime border with Sweden to the west. Lithuania covers an area of 65,300 km2 (25,200 sq mi), and has a population of 2.9 million. Its capital and largest city is Vilnius; other major cities include Kaunas, Klaipėda, Šiauliai and Panevėžys. Lithuanians are the titular nation, belong to the ethnolinguistic group of Balts, and speak Lithuanian.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/11/Flag_of_Lithuania.svg/330px-Flag_of_Lithuania.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Lithuania", "description": "Country in Northern Europe"}', '1b87b923-2a2e-444f-ac22-b588a513fa47', NULL, 'LT', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:01.333459+01', NULL, 'EUR', '{lithuania,lt,europe,community,diaspora}', NULL, 'Europe', 'Northern Europe', NULL);
INSERT INTO public.spaces VALUES ('43d240b6-6ecb-4f8d-82e2-744760b46f3b', NULL, '00000000-0000-0000-0000-000000000060', 'Malawi', 'malawi', 'Surrounded by Zambia, Tanzania, and Mozambique, yet its people have crossed every border and ocean — this space bridges home and diaspora. A population of 22 calls it home. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "Malawi", "extract": "Malawi, officially the Republic of Malawi, is a landlocked country in Southeast Africa. It is bordered by Zambia to the west, Tanzania to the north and northeast, and Mozambique to the east, south, and southwest. Malawi spans over 118,484 km2 (45,747 sq mi) and has a population of 22,224,282. Lilongwe is its capital and largest city.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d1/Flag_of_Malawi.svg/330px-Flag_of_Malawi.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Malawi", "description": "Country in Southeastern Africa"}', '2661d34f-e583-44a7-9ddc-607a1446b19d', NULL, 'MW', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:03.34764+01', NULL, NULL, '{malawi,mw,africa,landlocked,community,diaspora}', NULL, 'Africa', 'Eastern Africa', NULL);
INSERT INTO public.spaces VALUES ('1b861486-8e7d-4601-b98a-2269447badf2', NULL, '00000000-0000-0000-0000-000000000060', 'North Macedonia', 'north-macedonia', 'Your digital anchor in Southeast Europe — wherever the diaspora has settled, this is home base. Home to 1 people, with communities spread far beyond its borders. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "North Macedonia", "extract": "North Macedonia, officially the Republic of North Macedonia, is a landlocked country in Southeast Europe. It shares land borders with Greece to the south, Albania to the west, Bulgaria to the east, Kosovo to the northwest and Serbia to the north. It constitutes approximately the northern third of the larger geographical region of Macedonia. Skopje, the capital and largest city, is home to a quarter of the country''s population of over 1.83 million. The majority of the residents are ethnic Macedonians, a South Slavic people. Albanians form a significant minority at around 25%, followed by Turks, Roma, Serbs, Bosniaks, Aromanians and a few other minorities.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/79/Flag_of_North_Macedonia.svg/330px-Flag_of_North_Macedonia.svg.png", "content_url": "https://en.wikipedia.org/wiki/North_Macedonia", "description": "Country in Southeast Europe"}', 'ee94f6a7-b074-46f4-b2e5-494246e74f0a', NULL, 'MK', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:20.498265+01', NULL, NULL, '{"north macedonia",north-macedonia,mk,europe,landlocked,community,diaspora}', NULL, 'Europe', 'Southern Europe', NULL);
INSERT INTO public.spaces VALUES ('2b6c6901-db27-4799-a1aa-603e57f87fdb', NULL, '00000000-0000-0000-0000-000000000060', 'Pakistan', 'pakistan', 'Your digital anchor in South Asia — wherever the diaspora has settled, this is home base. Home to 241 people, with communities spread far beyond its borders. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "Pakistan", "extract": "Pakistan, officially the Islamic Republic of Pakistan, is a country in South Asia. It is the fifth-most populous country, with a population of over 241.5 million, having the second-largest Muslim population as of 2023. Islamabad is the nation''s capital, while Karachi is its largest city and financial centre. Pakistan is the 33rd-largest country by area. Bounded by the Arabian Sea on the south, the Gulf of Oman on the southwest, and the Sir Creek on the southeast, it shares land borders with India to the east; Afghanistan to the west; Iran to the southwest; and China to the northeast. It shares a maritime border with Oman in the Gulf of Oman, and is separated from Tajikistan in the northwest by Afghanistan''s narrow Wakhan Corridor.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/32/Flag_of_Pakistan.svg/330px-Flag_of_Pakistan.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Pakistan", "description": "Country in South Asia"}', '28b14fe2-1eac-4ff4-b636-3ea8b33dff40', NULL, 'PK', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:22.007714+01', NULL, NULL, '{pakistan,pk,asia,community,diaspora}', NULL, 'Asia', 'Southern Asia', NULL);
INSERT INTO public.spaces VALUES ('0868640b-4b68-4460-b01a-fed64f7989a3', NULL, '00000000-0000-0000-0000-000000000060', 'Solomon Islands', 'solomon-islands', 'An island in Melanesia, but its diaspora spans the globe — this space is the bridge between here and everywhere. Honiara is the capital; a population of 828 calls it home. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "Solomon Islands", "extract": "Solomon Islands, also known simply as the Solomons, is an archipelagic country consisting of six major islands and over 1,000 smaller islands in Melanesia, Oceania, to the north-east of Australia. It is adjacent to Bougainville to the west, New Caledonia and Vanuatu to the south-east, Fiji, Tuvalu, and Wallis and Futuna to the east, and the Federated States of Micronesia and Nauru to the north. It has a total area of 28,896 square kilometres, and a population of 828,857 according to official estimates from 2025. Its capital and largest city, Honiara, is located on the largest island, Guadalcanal. The country takes its name from the wider area of the Solomon Islands archipelago, which is a collection of Melanesian islands that also includes the Autonomous Region of Bougainville, but excludes the Santa Cruz Islands.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/74/Flag_of_the_Solomon_Islands.svg/330px-Flag_of_the_Solomon_Islands.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Solomon_Islands", "description": "Island country in Melanesia"}', '18cbbd77-5b71-41de-a3ce-6cec4fe104a8', NULL, 'SB', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:40.172218+01', NULL, NULL, '{"solomon islands",solomon-islands,sb,island,community,diaspora}', NULL, 'Oceania', 'Melanesia', NULL);
INSERT INTO public.spaces VALUES ('3eec498a-8fc0-45b6-a278-d6a2178449b9', NULL, '00000000-0000-0000-0000-000000000060', 'Svalbard and Jan Mayen Islands', 'svalbard-and-jan-mayen-islands', 'From here to the world — this is where the diaspora gathers, no matter how far they''ve traveled. Share local news, discover events, trade on the marketplace, and tap into remittance rates, scholarship finds, and community resources — all in one place.', '{"title": "Svalbard and Jan Mayen", "extract": "Svalbard and Jan Mayen is a statistical designation defined by ISO 3166-1 for a collective grouping of two remote jurisdictions of Norway: Svalbard and Jan Mayen. While the two are combined for the purposes of the International Organization for Standardization (ISO) category, they are not administratively related. This has further resulted in the country code top-level domain .sj being issued for Svalbard and Jan Mayen, and ISO 3166-2:SJ. The United Nations Statistics Division also uses this code, but has named it the Svalbard and Jan Mayen Islands.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/9c/Svalbard_and_Jan_Mayen_in_the_world_%28W3%29.svg/330px-Svalbard_and_Jan_Mayen_in_the_world_%28W3%29.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Svalbard_and_Jan_Mayen", "description": "Two parts of Norway under separate jurisdictions"}', '150ac3c0-3559-4437-8374-80a5981b99c7', NULL, 'SJ', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:45.204437+01', NULL, NULL, '{"svalbard and jan mayen islands",svalbard-and-jan-mayen-islands,sj,island,community,diaspora}', NULL, 'Europe', 'Northern Europe', NULL);
INSERT INTO public.spaces VALUES ('aa37bdbe-0ab3-4f8e-be91-2283359ee122', NULL, '00000000-0000-0000-0000-000000000060', 'Switzerland', 'switzerland', 'Landlocked in Central Europe but connected to the world — this is where the diaspora gathers, no matter how far they''ve traveled. It is set in Central Europe, landlocked, sharing borders with Germany, France, Austria, and Liechtenstein. Share local news, discover events, trade on the marketplace, and tap into remittance rates, scholarship finds, and community resources — all in one place.', '{"title": "Switzerland", "extract": "Switzerland, officially the Swiss Confederation, is a landlocked country located at the intersection of Central, Western, and Southern Europe. It is bordered by Germany to the north, France to the west, Austria and Liechtenstein to the east, and Italy to the south. Switzerland is geographically divided among the Swiss Alps, the Swiss Plateau, and the Jura Mountains; the Alps cover most of the country''s territory, whereas the majority of its 9 million people are concentrated on the plateau, which hosts many of the largest cities and economic centres, including Zurich, Geneva, Basel, Bern, Lausanne, Winterthur, and Lucerne.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/08/Flag_of_Switzerland_%28Pantone%29.svg/330px-Flag_of_Switzerland_%28Pantone%29.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Switzerland", "description": "Country in Central Europe"}', 'b1df0c46-64dd-4e32-905c-4011fb2961f0', NULL, 'CH', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:46.212615+01', NULL, 'CHF', '{switzerland,ch,europe,landlocked,community,diaspora}', NULL, 'Europe', 'Western Europe', NULL);
INSERT INTO public.spaces VALUES ('c6f729a6-6faf-41a9-a00a-7ed093f53170', NULL, '00000000-0000-0000-0000-000000000064', 'Hanoi University of Technology', 'hanoi-university-of-technology', NULL, '{"title": "Hanoi University of Science and Technology", "extract": "The Hanoi University of Science and Technology is the first and largest technical university in Vietnam. In May 2010 its name in English was changed to Hanoi University of Science and Technology, this was made with the goal to promote research and training alongside the university''s purpose besides technology transfer. The name in Vietnamese and French remain the same — Đại học Bách khoa Hà Nội and Institut Polytechnique de Hanoi respectively. HUST is a multidisciplinary technical university.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/8/8e/%C4%90%E1%BA%A1i_h%E1%BB%8Dc_B%C3%A1ch_khoa_H%C3%A0_N%E1%BB%99i_%28logo%29.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "content_url": "https://en.wikipedia.org/wiki/Hanoi_University_of_Science_and_Technology", "description": "University in Hanoi, Vietnam"}', 'fd1af768-41f3-4d6b-95e9-ab9990652207', NULL, 'VN', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.679268+01', '2026-08-24 00:22:13.650564+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('22abb4c0-92bb-49fd-abcb-374b2b64f322', NULL, '00000000-0000-0000-0000-000000000060', 'Tokelau', 'tokelau', 'From southern Pacific Ocean to cities and towns across the globe — this is the gathering point for a diaspora that never lost touch with home. It is set in southern Pacific Ocean. Share local news, discover events, trade on the marketplace, and tap into remittance rates, scholarship finds, and community resources — all in one place.', '{"title": "Tokelau", "extract": "Tokelau is a dependent territory of New Zealand in the southern Pacific Ocean. It consists of three tropical coral atolls: Atafu, Nukunonu, and Fakaofo. They have a combined land area of 10 km2 (4 sq mi). In addition to these three, Swains Island, which forms part of the same archipelago, is the subject of an ongoing territorial dispute, while being currently administered by the United States as part of American Samoa. Tokelau lies north of the Samoan Islands, east of Tuvalu, south of the Phoenix Islands, southwest of the more distant Line Islands, and northwest of the Cook Islands. The islands sit in the south east hemisphere.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/8e/Flag_of_Tokelau.svg/330px-Flag_of_Tokelau.svg.png", "content_url": "https://en.wikipedia.org/wiki/Tokelau", "description": "Dependent territory of New Zealand in the southern Pacific Ocean"}', '5c0c77c2-c889-4b74-a25d-a461dd070629', NULL, 'TK', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:51.247742+01', NULL, NULL, '{tokelau,tk,pacific,island,community,diaspora}', NULL, 'Oceania', 'Polynesia', NULL);
INSERT INTO public.spaces VALUES ('d49c2acb-4d0f-4d1b-b19e-717209e8671f', NULL, '00000000-0000-0000-0000-000000000060', 'Guatemala', 'guatemala', 'Rooted in Central America, sharing borders with Mexico, Belize, Honduras, and El Salvador, and reaching across continents — this space bridges home and diaspora. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "Guatemala", "extract": "Guatemala, officially the Republic of Guatemala, is a country in northern Central America. It is bordered to the north and west by Mexico, to the northeast by Belize, to the east by Honduras, and to the southeast by El Salvador. It is bounded by the Pacific Ocean to the south and the Gulf of Honduras to the northeast.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/ec/Flag_of_Guatemala.svg/330px-Flag_of_Guatemala.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Guatemala", "description": "Country in Central America"}', '71f113d8-a34a-4794-82e1-114715674e4b', NULL, 'GT', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:43.174277+01', NULL, NULL, '{guatemala,gt,"central america",community,diaspora}', NULL, 'Americas', 'Central America', NULL);
INSERT INTO public.spaces VALUES ('b13f3334-481b-4fb1-9699-08d4ef5a3624', NULL, '00000000-0000-0000-0000-000000000060', 'United States Minor Outlying Islands', 'united-states-minor-outlying-islands', 'Your digital anchor — wherever the diaspora has settled, this is home base. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "United States Minor Outlying Islands", "extract": "The United States Minor Outlying Islands is a statistical designation applying to the minor outlying islands and groups of islands that comprise eight United States insular areas and territories in the Pacific Ocean and one in the Caribbean Sea.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/96/Flag_of_the_United_States_%28DDD-F-416E_specifications%29.svg/330px-Flag_of_the_United_States_%28DDD-F-416E_specifications%29.svg.png", "content_url": "https://en.wikipedia.org/wiki/United_States_Minor_Outlying_Islands", "description": "U.S. statistical designation of small islands"}', '6adc4fe7-a7ab-44a7-956c-976eac33c69a', NULL, 'UM', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:57.803086+01', NULL, 'USD', '{"united states minor outlying islands",united-states-minor-outlying-islands,um,island,community,diaspora}', NULL, 'Americas', 'Northern America', NULL);
INSERT INTO public.spaces VALUES ('d80db3d4-9469-4b6e-a29d-fa37c639e428', NULL, '00000000-0000-0000-0000-000000000060', 'Zambia', 'zambia', 'It is set in Southern Africa, landlocked, sharing borders with Democratic Republic, Congo Tanzania, Malawi, and Mozambique. Whether you''re still in Southern Africa or building a life elsewhere, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Zambia", "extract": "Zambia, officially the Republic of Zambia, is a landlocked country in Southern Africa. It is bordered to the north by the Democratic Republic of the Congo, Tanzania to the northeast, Malawi to the east, Mozambique to the southeast, Zimbabwe and Botswana to the south, Namibia to the southwest, and Angola to the west. The capital city of Zambia is Lusaka, located in the south-central part of Zambia. The population is concentrated mainly around Lusaka in the south and the Copperbelt Province to the north, the core economic hubs of Zambia.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/06/Flag_of_Zambia.svg/330px-Flag_of_Zambia.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Zambia", "description": "Country in Southern Africa"}', '70f93c50-fcd4-4a33-8b84-4970af88bfbc', NULL, 'ZM', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:46:03.877259+01', NULL, NULL, '{zambia,zm,africa,landlocked,community,diaspora}', NULL, 'Africa', 'Southern Africa', NULL);
INSERT INTO public.spaces VALUES ('2c84f817-07d5-4546-8fa7-9f9d2dda926c', NULL, '00000000-0000-0000-0000-000000000060', 'Belarus', 'belarus', 'Surrounded by Russia, Ukraine, Poland, and Lithuania, yet its people have crossed every border and ocean — this space bridges home and diaspora. A population of 9 calls it home. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "Belarus", "extract": "Belarus, officially the Republic of Belarus, is a landlocked country in Eastern Europe. It is bordered by Russia to the east and northeast, Ukraine to the south, Poland to the west, and Lithuania and Latvia to the northwest. Belarus spans an area of 207,600 square kilometres (80,200 sq mi) with a population of 9.1 million. The country has a hemiboreal climate and is administratively divided into six regions. Minsk is the capital and largest city; it is administered separately as a city with special status.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/85/Flag_of_Belarus.svg/330px-Flag_of_Belarus.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Belarus", "description": "Country in Eastern Europe"}', '2122c890-db09-4ebc-be9f-a4f39676e298', NULL, 'BY', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:08.378753+01', NULL, NULL, '{belarus,by,europe,landlocked,community,diaspora}', NULL, 'Europe', 'Eastern Europe', NULL);
INSERT INTO public.spaces VALUES ('734f2369-75fc-401a-8dab-e6cbe8971915', NULL, '00000000-0000-0000-0000-000000000064', 'University of Alaska', 'university-of-alaska', NULL, '{"logo": "http://commons.wikimedia.org/wiki/Special:FilePath/Univ%20alaska%20fairbanks%20textlogo.png", "name": "University of Alaska Fairbanks", "image": "http://commons.wikimedia.org/wiki/Special:FilePath/University%20of%20Alaska%20Museum%20of%20the%20North%20ENBLA01.jpg", "country": "Q30", "founded": "+1917-00-00T00:00:00Z", "website": "https://www.uaf.edu/", "students": "+6813", "description": "university", "wikidata_id": "Q1285262", "wikipedia_url": "https://en.wikipedia.org/wiki/Q1285262"}', 'c9b9983e-b99b-4825-a335-b83d3c84cffc', NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.233464+01', '2026-08-09 02:35:18.381865+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('485eeaf2-b1ef-46d0-a6f3-8dc6b45ca43c', NULL, '00000000-0000-0000-0000-000000000060', 'Bhutan', 'bhutan', 'Landlocked in South Asia but connected to the world — this is where the diaspora gathers, no matter how far they''ve traveled. It is set in South Asia, landlocked. Share local news, discover events, trade on the marketplace, and tap into remittance rates, scholarship finds, and community resources — all in one place.', '{"title": "Bhutan", "extract": "Bhutan, officially the Kingdom of Bhutan, is a landlocked country in South Asia, located in the Eastern Himalayas, bordering China to the north and northwest and India to the south and southeast. With a population of over 800,000 (800,871) and a territory of 38,394 square kilometres (14,824 sq mi), Bhutan ranks 133rd in land area and 160th in population. It is a democratic constitutional monarchy with a king as the head of state and a prime minister as the head of government. The Je Khenpo is the head of the state religion, Vajrayana Buddhism.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/91/Flag_of_Bhutan.svg/330px-Flag_of_Bhutan.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Bhutan", "description": "Country in South Asia"}', '8b6a199f-7d60-4e3f-8b90-4fdb1ea2a2a2', NULL, 'BT', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:10.898929+01', NULL, NULL, '{bhutan,bt,asia,landlocked,community,diaspora}', NULL, 'Asia', 'Southern Asia', NULL);
INSERT INTO public.spaces VALUES ('8b4346af-1f85-4cf6-bb14-08d302874d6a', NULL, '00000000-0000-0000-0000-000000000060', 'Jamaica', 'jamaica', 'Rooted here, reaching across continents — this space bridges home and diaspora. A population of in the Caribbean calls it home. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "Jamaica", "extract": "Jamaica is an island country in the Caribbean, covering 10,991 square kilometres (4,244 sq mi). It is the third-largest island in the Greater Antilles and the Caribbean, after Cuba and the island of Hispaniola. Jamaica lies about 145 km (78 nmi) south of Cuba, 191 km (103 nmi) west of Hispaniola, and 215 km (116 nmi) southeast of the Cayman Islands. With 2.8 million people, Jamaica is the third most populous Anglophone country in the Americas and the fourth most populous country in the Caribbean. Kingston is the country''s capital and largest city.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/0a/Flag_of_Jamaica.svg/330px-Flag_of_Jamaica.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Jamaica", "description": "Caribbean nation"}', '85ba8d98-eca2-4148-8588-a74a06649544', NULL, 'JM', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:52.756986+01', NULL, NULL, '{jamaica,jm,caribbean,island,community,diaspora}', NULL, 'Americas', 'Caribbean', NULL);
INSERT INTO public.spaces VALUES ('6d3c7964-7048-4fa7-ae7a-0b6853586a20', NULL, '00000000-0000-0000-0000-000000000060', 'Botswana', 'botswana', 'Most sparsely populated countries in the world in Southern Africa,. It is set in Southern Africa, landlocked, sharing borders with Africa, Namibia, Zambia, and Zimbabwe. Whether you''re still in Southern Africa or building a life elsewhere, this is your space to connect, trade, and stay rooted.', '{"title": "Botswana", "extract": "Botswana, officially the Republic of Botswana, is a landlocked country in Southern Africa. Botswana is topographically flat, with approximately 70% of its territory being a part of the Kalahari Desert. It is bordered by South Africa to the south and southeast, Namibia to the west and north, Zambia to the north, and Zimbabwe to the northeast. With a population of slightly over 2.4 million people and a comparable land area to France, Botswana is one of the most sparsely populated countries in the world. While it is not enshrined by statutory law, Botswana is de facto the nation state of the Batswana people, who constitute nearly 80% of the population while legally undistinguished Kalanga people, who account for another 11%, are the single largest ethnic minority.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/fa/Flag_of_Botswana.svg/330px-Flag_of_Botswana.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Botswana", "description": "Country in Southern Africa"}', '3b1cd35e-f7e4-4c53-906a-022e9c0ecf3f', NULL, 'BW', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:12.92088+01', NULL, NULL, '{botswana,bw,africa,landlocked,community,diaspora}', NULL, 'Africa', 'Southern Africa', NULL);
INSERT INTO public.spaces VALUES ('2208e78f-c195-4b4a-be9b-08f6d832671b', NULL, '00000000-0000-0000-0000-000000000060', 'British Indian Ocean Territory', 'british-indian-ocean-territory', 'Your digital anchor — wherever the diaspora has settled, this is home base. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "British Indian Ocean Territory", "extract": "The British Indian Ocean Territory (BIOT) is a British Overseas Territory situated in the Indian Ocean. The territory comprises the seven atolls of the Chagos Archipelago with over 1,000 individual islands, many very small, amounting to a total land area of 60 square kilometres. The largest and most southerly island is Diego Garcia, 27 square kilometres, the site of a Joint Military Facility of the United Kingdom and the United States. Official administration is remote from London, though the local capital is often regarded as being on Diego Garcia.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/12/Flag_of_the_British_Indian_Ocean_Territory_2025.svg/330px-Flag_of_the_British_Indian_Ocean_Territory_2025.svg.png", "content_url": "https://en.wikipedia.org/wiki/British_Indian_Ocean_Territory", "description": "British Overseas Territory in the Indian Ocean"}', 'a56a493b-e42d-4c4b-8a3f-98a16a5984a3', NULL, 'IO', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:14.430479+01', NULL, 'USD', '{"british indian ocean territory",british-indian-ocean-territory,io,island,community,diaspora}', NULL, 'Africa', 'Eastern Africa', NULL);
INSERT INTO public.spaces VALUES ('b4cd6625-482a-409e-8a21-2f6910a33acd', NULL, '00000000-0000-0000-0000-000000000060', 'Cameroon', 'cameroon', 'From Central Africa to cities and towns across the globe — this is the gathering point for a diaspora that never lost touch with home. It is set in Central Africa. Share local news, discover events, trade on the marketplace, and tap into remittance rates, scholarship finds, and community resources — all in one place.', '{"title": "Cameroon", "extract": "Cameroon, officially the Republic of Cameroon, is a country in Central Africa. It shares boundaries with Nigeria to the west and north, Chad to the northeast, the Central African Republic to the east, and Equatorial Guinea, Gabon, and the Republic of the Congo to the south. Its coastline lies on the Bight of Biafra, part of the Gulf of Guinea, and the Atlantic Ocean. Due to its strategic position at the crossroads between West Africa and Central Africa, it has been categorized as being in both geostrategic locations. Cameroon''s population of nearly 31 million people speak 250 native languages, in addition to the national tongues of English and French. The capital city of the country is Yaoundé.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/4f/Flag_of_Cameroon.svg/330px-Flag_of_Cameroon.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Cameroon", "description": "Country in Central Africa"}', '2830e41c-5b9b-40bf-894f-9393569f1a4f', NULL, 'CM', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:17.461953+01', NULL, NULL, '{cameroon,cm,africa,community,diaspora}', NULL, 'Africa', 'Middle Africa', NULL);
INSERT INTO public.spaces VALUES ('10e82ed8-5e57-4cc8-9760-1153941fad61', NULL, '00000000-0000-0000-0000-000000000060', 'Christmas Island', 'christmas-island', 'Your digital anchor — wherever the diaspora has settled, this is home base. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "Christmas Island", "extract": "\nChristmas Island, officially the Territory of Christmas Island, is an Australian external territory in the Indian Ocean comprising the island of the same name. It is about 350 kilometres south of Java and Sumatra and about 1,550 km (840 nmi) north-west of the closest point on the Australian mainland. It has an area of 135 square kilometres (52 sq mi). Christmas Island''s geographic isolation and history of minimal human disturbance has led to a high level of endemism among its flora and fauna, which is of interest to scientists and naturalists. The territory derives its name from its discovery on Christmas Day 1643 by Captain William Mynors.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/67/Flag_of_Christmas_Island.svg/330px-Flag_of_Christmas_Island.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Christmas_Island", "description": "External territory of Australia"}', '29e2631e-3206-429d-9113-d7d02ac863a9', NULL, 'CX', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:21.490414+01', NULL, NULL, '{"christmas island",christmas-island,cx,island,community,diaspora}', NULL, 'Oceania', 'Australia and New Zealand', NULL);
INSERT INTO public.spaces VALUES ('5bb678ed-a758-4cdb-bbdb-b19bfed5f78d', NULL, '00000000-0000-0000-0000-000000000060', 'Curaçao', 'curaçao', 'Every journey carries a story — of ambition, of longing, of roots that stretch but never break. Discover local businesses, share news from home, find events near you, and build a network that spans borders — all on JapaConnect.', '{"title": "Curaçao", "extract": "Curaçao, officially the Country of Curaçao, is a constituent country within the Kingdom of the Netherlands. It is an island country located in the southern Caribbean Sea, specifically the Dutch Caribbean region, about 65 km (40 mi) north of Venezuela and 80 km (50 mi) southeast of Aruba. Curaçao includes the main island of Curaçao, and the much smaller, uninhabited island of Klein Curaçao.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/b1/Flag_of_Cura%C3%A7ao.svg/330px-Flag_of_Cura%C3%A7ao.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Cura%C3%A7ao", "description": "Island country within the Kingdom of the Netherlands"}', '36ce8477-f0e2-4d95-9964-17ca333bb515', NULL, 'CW', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:26.034688+01', NULL, NULL, '{curaçao,cw,island,community,diaspora}', NULL, 'Americas', 'Caribbean', NULL);
INSERT INTO public.spaces VALUES ('d55be607-4011-4244-99a4-82c67c2915d4', NULL, '00000000-0000-0000-0000-000000000060', 'Kosovo', 'kosovo', 'It is set in Southeast Europe, landlocked, sharing borders with Albania, Montenegro, Serbia, and Macedonia. Whether you''re still in Southeast Europe or building a life elsewhere, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Kosovo", "extract": "Kosovo, officially the Republic of Kosovo, is a landlocked country in Southeast Europe with partial diplomatic recognition. It is bordered by Albania to the southwest, Montenegro to the west, Serbia to the north and east, and North Macedonia to the southeast. It covers an area of 10,887 km2 (4,203 sq mi) and has a population of nearly 1.6 million, of whom the vast majority are ethnic Albanians. Kosovo has a varied terrain, with high plains along with rolling hills and mountains, some of which have an altitude over 2,500 m (8,200 ft). Its climate is mainly continental with some Mediterranean and Alpine influences. Kosovo''s capital and most populous city is Pristina; other major cities and urban areas include Prizren, Ferizaj, Gjilan, and Peja.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/1f/Flag_of_Kosovo.svg/330px-Flag_of_Kosovo.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Kosovo", "description": "Country in Southeast Europe"}', 'cdcfb8df-87a3-4be1-a1a8-fc3292ed341d', NULL, 'XK', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:56.287708+01', NULL, 'EUR', '{kosovo,xk,europe,landlocked,community,diaspora}', NULL, 'Europe', 'Eastern Europe', NULL);
INSERT INTO public.spaces VALUES ('4802abf1-b527-4b81-a728-0c2360b7a387', NULL, '00000000-0000-0000-0000-000000000060', 'Laos', 'laos', 'Every journey out of Southeast Asia carries a story — of ambition, of longing, of roots that stretch but never break. Discover local businesses, share news from home, find events near you, and build a network that spans borders — all on JapaConnect.', '{"title": "Laos", "extract": "Laos, officially the Lao People''s Democratic Republic (LPDR), is a country in Mainland Southeast Asia, and the only landlocked country in Southeast Asia. It is bordered by Myanmar and China to the northwest, Vietnam to the east, Cambodia to the southeast, and Thailand to the west and southwest. Laos has a population of more than 7.5 million, and its capital and most populous city is Vientiane. It has three UNESCO World Heritage Sites: the town of Luang Prabang, the temple complex of Vat Phou, and the Plain of Jars. The 2021 completion of the Boten–Vientiane railway, Laotian section of the Laos–China Railway, connects Vientiane to Kunming. Laos participates in the Greater Mekong Subregion economic cooperation programme and is a member of ASEAN, the Asia-Pacific Trade Agreement, East Asia Summit, La Francophonie, and the World Trade Organization.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/56/Flag_of_Laos.svg/330px-Flag_of_Laos.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Laos", "description": "Country in Southeast Asia"}', '41001550-7a1f-4a7d-8260-81097146027b', NULL, 'LA', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:57.799358+01', NULL, NULL, '{laos,la,asia,landlocked,community,diaspora}', NULL, 'Asia', 'South-Eastern Asia', NULL);
INSERT INTO public.spaces VALUES ('d5a619bc-5213-4712-acb2-0a81eeff8ce6', NULL, '00000000-0000-0000-0000-000000000060', 'Liberia', 'liberia', 'It is set in West Africa, sharing borders with Sierra Leone and Guinea, with Monrovia as its capital. From the streets of Monrovia to diaspora communities worldwide, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Liberia", "extract": "Liberia, officially the Republic of Liberia, is a country on the West African coast. It is bordered by Sierra Leone to its northwest, Guinea to its north, Ivory Coast to its east, and the Atlantic Ocean to its south and southwest. It has a population of around 5.5 million and covers an area of 43,000 square miles (111,369 km2). The official language is English, though over 20 indigenous languages are spoken, reflecting the country''s ethnic and cultural diversity. The capital and largest city is Monrovia.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/b8/Flag_of_Liberia.svg/330px-Flag_of_Liberia.svg.png", "content_url": "https://en.wikipedia.org/wiki/Liberia", "description": "Country in West Africa"}', '3eb0cd1b-bfbd-4163-b95a-e0153dcb4209', NULL, 'LR', 'country', 1, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:27:37.438608+01', '2026-08-07 11:44:59.822827+01', NULL, NULL, '{liberia,lr,africa,community,diaspora}', NULL, 'Africa', 'Western Africa', NULL);
INSERT INTO public.spaces VALUES ('b54018dc-4237-469c-a840-8c1e5702ed55', NULL, '00000000-0000-0000-0000-000000000060', 'Malta', 'malta', 'An island nation with a worldwide footprint — this is where the diaspora comes home. It is an island nation, with Valletta as its capital. Share local news, discover events, trade on the marketplace, and tap into remittance rates, scholarship finds, and community resources — all in one place.', '{"title": "Malta", "extract": "Malta, officially the Republic of Malta, is an island country located in the central Mediterranean Sea. It consists of an archipelago which is 80 km (50 mi) south of Italy, 284 km (176 mi) east of Tunisia, and 333 km (207 mi) north of Libya. The two official languages are Maltese and English; Maltese is recognised as the national language. The country''s capital is Valletta, which is the smallest capital city in the European Union by both area and population.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/73/Flag_of_Malta.svg/330px-Flag_of_Malta.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Malta", "description": "Mediterranean island country"}', 'b58bb404-5b2a-4a40-ab90-b1372d7c32cb', NULL, 'MT', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:05.366665+01', NULL, 'EUR', '{malta,mt,island,community,diaspora}', NULL, 'Europe', 'Southern Europe', NULL);
INSERT INTO public.spaces VALUES ('b807b163-63fb-41ba-b632-fa473489a381', NULL, '00000000-0000-0000-0000-000000000060', 'Mexico', 'mexico', 'Rooted in North America, reaching across continents — this space bridges home and diaspora. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "Mexico", "extract": "Mexico, officially the United Mexican States, is a country in North America. It is the northernmost country in Latin America, bordering the United States of America to the north and Guatemala and Belize to the southeast, while having maritime boundaries with the Pacific Ocean to the west, the Caribbean Sea to the southeast, and the Gulf of Mexico to the east. Mexico covers 1,972,550 km2, and is the thirteenth-largest country in the world by land area. With a population exceeding 134 million as of 2026, Mexico is the tenth-most populous country in the world and is home to the largest number of native Spanish speakers. Mexico City is the capital and largest city in Mexico, which ranks among the most populous metropolitan areas in the world.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/fc/Flag_of_Mexico.svg/330px-Flag_of_Mexico.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Mexico", "description": "Country in North America"}', 'd6ca2c31-19e8-45c5-8f19-7e11021233fb', NULL, 'MX', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:08.896607+01', NULL, NULL, '{mexico,mx,"north america",community,diaspora}', NULL, 'Americas', 'Northern America', NULL);
INSERT INTO public.spaces VALUES ('b4a0240a-0b90-4e59-ba06-f2d98c34b9ae', NULL, '00000000-0000-0000-0000-000000000060', 'Palestinian Territory Occupied', 'palestinian-territory-occupied', 'From West Asia to cities and towns across the globe — this is the gathering point for a diaspora that never lost touch with home. It is set in West Asia, sharing borders with Israel, Bank, Jordan, and Gaza Strip, with Jerusalem as its capital.', '{"title": "Palestine", "extract": "Palestine, officially the State of Palestine, is a country in the Southern Levant region of West Asia. It encompasses the West Bank, including East Jerusalem, and the Gaza Strip, both of which are occupied by Israel. These territories are collectively known as the Palestinian territories, or occupied Palestinian territory. They share the vast majority of their borders with Israel, with the West Bank bordering Jordan to the east and the Gaza Strip bordering Egypt to the southwest. It has a total land area of 6,020 square kilometers (2,320 sq mi) while its population exceeds five million. Its proclaimed capital is Jerusalem, while Ramallah serves as its de facto administrative center. Gaza was its largest city prior to Israel''s forced evacuations in 2023, ordered by Israel following Hamas''s October 7 attacks.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/00/Flag_of_Palestine.svg/330px-Flag_of_Palestine.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Palestine", "description": "Country in West Asia"}', '48060434-7a3d-49b7-8d86-005943ebc09b', NULL, 'PS', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:23.014683+01', NULL, NULL, '{"palestinian territory occupied",palestinian-territory-occupied,ps,asia,community,diaspora}', NULL, 'Asia', 'Western Asia', NULL);
INSERT INTO public.spaces VALUES ('7b236b53-be7e-4c85-9d4d-d4b9f4e4dd8e', NULL, '00000000-0000-0000-0000-000000000060', 'Slovenia', 'slovenia', 'Rooted in Central Europe, sharing borders with Italy, Austria, Hungary, and Croatia, and reaching across continents — this space bridges home and diaspora. A population of approximately 2 calls it home; the landscape is defined by mountainous terrain. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "Slovenia", "extract": "Slovenia, officially the Republic of Slovenia, is a country in Central Europe. It borders Italy to the west, Austria to the north, Hungary to the northeast, and Croatia to the south and southeast; its southwestern boundary consists of a 46.6-kilometre (29.0 mi) coastline on the Adriatic Sea. The country is mostly mountainous and forested, covering 20,271 square kilometres (7,827 sq mi), with a population of approximately 2.1 million people. Slovene is the official language. Slovenia has a predominantly temperate continental climate, with the exception of the Slovene Littoral and the Julian Alps. Ljubljana, the capital and largest city, is geographically situated near the centre of the country. Other larger urban centers include Maribor, Ptuj, Kranj, Celje, Koper, Novo Mesto, Velenje, Nova Gorica, Sežana, Murska Sobota, and Jesenice.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/f0/Flag_of_Slovenia.svg/330px-Flag_of_Slovenia.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Slovenia", "description": "Country in Central Europe"}', '6caf46d2-ab7b-4c7d-a369-830a29498db2', NULL, 'SI', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:39.669033+01', NULL, 'EUR', '{slovenia,si,europe,community,diaspora}', NULL, 'Europe', 'Southern Europe', NULL);
INSERT INTO public.spaces VALUES ('975f3f8a-7708-4531-b65b-2ed485d1146d', '9b54a87a-f538-4c78-89af-adc13cd8170a', '00000000-0000-0000-0000-000000000062', 'Ikeja', 'ikeja', NULL, '{"title": "Ikeja", "extract": "Ikeja is the capital city of Lagos State in southwestern Nigeria. Its population, as of the 2006 census, is 313,196. Prior to the emergence of military rule in the early 1980s, Ikeja was a residential and commercial town with shopping malls, pharmacies and government reservation areas. Ikeja is part of Metropolitan Lagos and lies 17 km northwest of Lagos city proper. The Murtala Muhammed International Airport is located in the city. Ikeja is also home to Femi Kuti''s Africa Shrine and Lagbaja''s Motherland, both venues for live music. Its Ikeja City Mall is the largest shopping mall on the Lagos State mainland. Ikeja also has its own radio station, broadcasting both in English and in Yoruba.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/3e/2013_airport_Ikeja_Lagos_Nigeria_12999337914.jpg/330px-2013_airport_Ikeja_Lagos_Nigeria_12999337914.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Ikeja", "description": "Capital city of Lagos State, Nigeria"}', NULL, NULL, NULL, 'city', 1, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-21 10:52:51.100178+01', '2026-08-21 10:52:52.76563+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('a20d3bd8-0534-425e-b91e-935012302c9d', NULL, '00000000-0000-0000-0000-000000000060', 'Spain', 'spain', 'Your digital anchor in Southern and Western Europe — from Madrid to the farthest corners of the diaspora, everything flows through here. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "Spain", "extract": "Spain, officially the Kingdom of Spain, is a country in Southern and Western Europe with territories in North Africa. Featuring the southernmost point of continental Europe, it is the largest country in Southern Europe and the fourth-most populous European Union (EU) member state. Spanning the majority of the Iberian Peninsula, its territory also includes the Canary Islands, in the Eastern Atlantic Ocean; the Balearic Islands, in the Western Mediterranean Sea; and the autonomous cities of Ceuta and Melilla, in mainland Africa. Peninsular Spain is bordered to the north by France, Andorra, and the Bay of Biscay; to the east and south by the Mediterranean Sea, Gibraltar and Morocco ; and to the west by Portugal and the Atlantic Ocean. Spain''s capital and largest city is Madrid; other major urban areas include Barcelona, Valencia, Zaragoza, Seville, Bilbao, Málaga, Murcia, Palma de Mallorca and Las Palmas.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/24/Flag_of_the_Kingdom_of_Spain.svg/330px-Flag_of_the_Kingdom_of_Spain.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Spain", "description": "Country in Southern and Western Europe"}', 'c2813650-e2e7-48d5-8c11-e93874029a08', NULL, 'ES', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:43.191768+01', NULL, 'EUR', '{spain,es,europe,island,community,diaspora}', NULL, 'Europe', 'Southern Europe', NULL);
INSERT INTO public.spaces VALUES ('782e276a-960f-4d55-985b-d82b4d46f31c', NULL, '00000000-0000-0000-0000-000000000060', 'Greece', 'greece', 'Your digital anchor in Southeastern Europe — from Athens to the farthest corners of the diaspora, everything flows through here. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "Greece", "extract": "Greece, officially the Hellenic Republic, is a country of 10 million people on the southern tip of the Balkan peninsula in Southeastern Europe. With nine regions and thousands of islands, it has the longest coastline on the Mediterranean. The Ionian Sea is west of the mainland, Albania northwest, and North Macedonia and Bulgaria north. Turkey is east both by land and the Aegean Sea. The capital, Athens, is the largest Greek city, followed by Thessaloniki and Patras.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/5c/Flag_of_Greece.svg/330px-Flag_of_Greece.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Greece", "description": "Country in Southeastern Europe"}', '9bc170a9-5b90-4593-9b1a-85a16b834a5b', NULL, 'GR', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:40.65117+01', NULL, 'EUR', '{greece,gr,europe,island,community,diaspora}', NULL, 'Europe', 'Southern Europe', NULL);
INSERT INTO public.spaces VALUES ('03734988-11e7-47a4-8341-71028d8df363', NULL, '00000000-0000-0000-0000-000000000060', 'Taiwan', 'taiwan', 'Your digital anchor in East Asia — wherever the diaspora has settled, this is home base. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "Taiwan", "extract": "Taiwan, officially the Republic of China (ROC), is a country in East Asia. The main island of Taiwan, also known as Formosa, lies between the East and South China Seas in the northwestern Pacific Ocean, with the People''s Republic of China (PRC) to the northwest, Japan to the northeast, and the Philippines to the south. It has an area of 35,808 square kilometers, with mountain ranges dominating the eastern two-thirds and plains in the western third, where its highly urbanized population is concentrated. The combined territories under ROC control consist of 168 islands in total covering 36,193 square kilometers. The largest metropolitan area is formed by Taipei, New Taipei City, and Keelung. With around 23.9 million inhabitants, Taiwan is among the most densely populated countries.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/72/Flag_of_the_Republic_of_China.svg/330px-Flag_of_the_Republic_of_China.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Taiwan", "description": "Country in East Asia"}', 'bf31efec-b71c-4d4f-8338-5ad7d64131c4', NULL, 'TW', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:47.219963+01', NULL, NULL, '{taiwan,tw,asia,island,community,diaspora}', NULL, 'Asia', 'Eastern Asia', NULL);
INSERT INTO public.spaces VALUES ('03fdc3a9-a2cd-4e77-9118-043c92f7528b', NULL, '00000000-0000-0000-0000-000000000060', 'Tanzania', 'tanzania', 'Your digital anchor in East Africa — wherever the diaspora has settled, this is home base. A land of an equatorial location, shaped by geography and history into something uniquely its own. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "Tanzania", "extract": "Tanzania, officially the United Republic of Tanzania, is a country in East Africa within the African Great Lakes region. It is bordered by Uganda to the northwest, Kenya to the northeast, the Indian Ocean to the east, Mozambique and Malawi to the south, Zambia to the southwest, and Rwanda, Burundi, and the Democratic Republic of the Congo to the west. According to a 2024 estimate, Tanzania has a population of around 67.5 million, making it the most populous African country located entirely south of the equator.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/38/Flag_of_Tanzania.svg/330px-Flag_of_Tanzania.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Tanzania", "description": "Country in East Africa"}', 'b5daf0d1-9688-4f53-a17b-dcefb598d97e', NULL, 'TZ', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:48.227424+01', NULL, NULL, '{tanzania,tz,africa,community,diaspora}', NULL, 'Africa', 'Eastern Africa', NULL);
INSERT INTO public.spaces VALUES ('52060125-488d-49e5-8ebd-5364b6843a84', NULL, '00000000-0000-0000-0000-000000000060', 'Thailand', 'thailand', 'From Southeast Asia to cities and towns across the globe — this is the gathering point for a diaspora that never lost touch with home. It is set in Southeast Asia, sharing borders with Myanmar, Laos, Cambodia, and Malaysia, with Bangkok as its capital.', '{"title": "Thailand", "extract": "Thailand, officially the Kingdom of Thailand, and formerly known as Siam, is a country located in Mainland Southeast Asia. It shares land borders with Myanmar to the west and northwest, Laos to the east and northeast, Cambodia to the southeast, and Malaysia to the south. Its maritime boundaries include the Gulf of Thailand and the Andaman Sea and shares maritime borders with Vietnam, Indonesia, and India. Thailand has a population of nearly 66 million people and covers an area of approximately 513,115 km2. The capital and largest city is Bangkok.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/a9/Flag_of_Thailand.svg/330px-Flag_of_Thailand.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Thailand", "description": "Country in Southeast Asia"}', 'c6fe1b93-75f0-4ec4-b9c9-e4bc1dd1c91a', NULL, 'TH', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:48.731089+01', NULL, NULL, '{thailand,th,asia,community,diaspora}', NULL, 'Asia', 'South-Eastern Asia', NULL);
INSERT INTO public.spaces VALUES ('84bb6e10-cb9b-438c-b25b-60c1a555bc3a', NULL, '00000000-0000-0000-0000-000000000060', 'Timor-Leste', 'timor-leste', 'Your digital anchor in Southeast Asia — wherever the diaspora has settled, this is home base. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "Timor-Leste", "extract": "Timor-Leste, also known as East Timor, officially the Democratic Republic of Timor-Leste, is a country in Southeast Asia. It comprises the eastern half of the island of Timor, the coastal exclave of Oecusse in the island''s northwest, and the islands of Atauro and Jaco, for a total land area of 15,007 square kilometres (5,794 sq mi). Timor-Leste shares a land border with Indonesia to the west; Australia is the country''s southern neighbour, across the Timor Sea. Dili, on the north coast of Timor, is its capital and largest city.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/26/Flag_of_East_Timor.svg/330px-Flag_of_East_Timor.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Timor-Leste", "description": "Country in Southeast Asia"}', '45a9d16d-f1c6-4d0e-a2fa-02b12b241146', NULL, 'TL', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:50.242105+01', NULL, 'USD', '{timor-leste,tl,asia,island,community,diaspora}', NULL, 'Asia', 'South-Eastern Asia', NULL);
INSERT INTO public.spaces VALUES ('0831b862-5aba-42b6-a193-efdc978a9adf', NULL, '00000000-0000-0000-0000-000000000060', 'Uzbekistan', 'uzbekistan', 'It is set in Central Asia, landlocked, sharing borders with Kazakhstan, Kyrgyzstan, Tajikistan, and Afghanistan. Whether you''re still in Central Asia or building a life elsewhere, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Uzbekistan", "extract": "Uzbekistan, officially the Republic of Uzbekistan, is a sovereign, doubly landlocked country located in Central Asia. It is bordered by Kazakhstan to the north, Kyrgyzstan to the northeast, Tajikistan to the southeast, Afghanistan to the south, and Turkmenistan to the south-west. It is one of only two doubly landlocked countries in the world, the other being Liechtenstein. The country has a population of more than 39 million, making it the most populous Republic in Central Asia. Uzbekistan is a member of the Organisation of Turkic States. Uzbek, spoken by the Uzbek people who form more than 89% of the population, is the official language of the country. Russian and Tajik are significant minority languages, with Russian serving as a lingua franca. Tajik is primarily spoken by Tajiks living in the southern parts of the country, such as Samarkand and Bukhara.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/84/Flag_of_Uzbekistan.svg/330px-Flag_of_Uzbekistan.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Uzbekistan", "description": "Country in Central Asia"}', '1a6e35c7-58d6-48b4-874e-52ed20b5b050', NULL, 'UZ', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:58.813543+01', NULL, NULL, '{uzbekistan,uz,asia,landlocked,community,diaspora}', NULL, 'Asia', 'Central Asia', NULL);
INSERT INTO public.spaces VALUES ('13296cb0-75ab-4fd6-9052-c36d938c6205', NULL, '00000000-0000-0000-0000-000000000060', 'Anguilla', 'anguilla', 'Rooted in Leeward Islands, reaching across continents — this space bridges home and diaspora. The Valley is the capital; a population of approximately 15 calls it home. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "Anguilla", "extract": "Anguilla is a British Overseas Territory of the Caribbean region in the North Atlantic Ocean. It is one of the most northerly of the Leeward Islands in the Lesser Antilles, lying east of Puerto Rico and the Virgin Islands and directly north of Saint Martin. The territory consists of the main island of Anguilla, approximately 16 miles long by 3 miles (5 km) wide at its widest point, together with a number of much smaller islands and cays with no permanent population. The territory''s capital is The Valley. The total land area of the territory is 35 square miles (91 km2), with a population of approximately 15,753 in 2021.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/b4/Flag_of_Anguilla.svg/330px-Flag_of_Anguilla.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Anguilla", "description": "British Overseas Territory in the Leeward Islands"}', '9a2eb3a4-666e-432d-967f-b4a4dcaf6fb9', NULL, 'AI', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:02.320797+01', NULL, NULL, '{anguilla,ai,island,community,diaspora}', NULL, 'Americas', 'Caribbean', NULL);
INSERT INTO public.spaces VALUES ('7e3634f9-7889-47a2-b435-2f183280783e', NULL, '00000000-0000-0000-0000-000000000060', 'Belize', 'belize', 'Rooted in Central America, sharing borders with Mexico and Guatemala, and reaching across continents — this space bridges home and diaspora. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "Belize", "extract": "Belize is a country on the north-eastern coast of Central America. It is bordered by Mexico to the north, the Caribbean Sea to the east, and Guatemala to the west and south. It also shares a maritime boundary with Honduras to the southeast. Part of the Caribbean region, Belize is a member of the Caribbean Community (CARICOM) and the Commonwealth Caribbean, the historical British West Indies.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/e7/Flag_of_Belize.svg/330px-Flag_of_Belize.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Belize", "description": "Country in Central America"}', 'be43936c-217c-446a-b7ef-761e70da6a4e', NULL, 'BZ', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:09.387467+01', NULL, NULL, '{belize,bz,"central america",community,diaspora}', NULL, 'Americas', 'Central America', NULL);
INSERT INTO public.spaces VALUES ('e941dda5-106b-47c8-bbad-9fd73887acf5', NULL, '00000000-0000-0000-0000-000000000060', 'Central African Republic', 'central-african-republic', 'It is set in Central Africa, landlocked, sharing borders with Chad, Sudan, Democratic Republic, and Congo, with Bangui as its capital. From the streets of Bangui to diaspora communities worldwide, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Central African Republic", "extract": "The Central African Republic (CAR) is a landlocked country in Central Africa. It is bordered by Chad to the north, Sudan to the northeast, South Sudan to the east, the Democratic Republic of the Congo to the south, the Republic of the Congo to the southwest, and Cameroon to the west. The Central African Republic covers a land area of about 620,000 square kilometres (240,000 sq mi). As of 2024, it has a population of 5,357,744, consisting of about 80 ethnic groups. Having been a French colony under the name Ubangi-Shari, French is its official language, with Sango, a Ngbandi-based creole language, as the national and co-official language. Its capital and largest city is Bangui, which sits on the country''s southern border with the Democratic Republic of the Congo.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/6f/Flag_of_the_Central_African_Republic.svg/330px-Flag_of_the_Central_African_Republic.svg.png", "content_url": "https://en.wikipedia.org/wiki/Central_African_Republic", "description": "Country in Central Africa"}', '167229fa-3fb5-4f6a-b462-4244c1676298', NULL, 'CF', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:19.475874+01', NULL, NULL, '{"central african republic",central-african-republic,cf,africa,landlocked,community,diaspora}', NULL, 'Africa', 'Middle Africa', NULL);
INSERT INTO public.spaces VALUES ('5afd86e4-593e-4d63-b2a6-00a089df4006', 'fb748908-9430-41ca-8868-35748692c6dc', '00000000-0000-0000-0000-000000000062', 'Bensonville', 'bensonville', NULL, '{"title": "Bensonville", "extract": "Bensonville is the capital city of Montserrado County, Liberia. As of the 2008 national census, its population stood at 4,089. Bensonville is located 20 miles (32 km) away from the national capital, Monrovia, which is also located in Montserrado County. It is a commercial center for the surrounding agricultural area.", "content_url": "https://en.wikipedia.org/wiki/Bensonville", "description": "Capital of Montserrado County, Liberia"}', NULL, NULL, NULL, 'city', 1, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-21 10:53:37.596884+01', '2026-08-21 10:53:38.07128+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('c638ab2d-35c8-45f3-b823-578aeec68e07', NULL, '00000000-0000-0000-0000-000000000064', 'Universidade Federal de Mato Grosso', 'universidade-federal-de-mato-grosso', NULL, '{"logo": "http://commons.wikimedia.org/wiki/Special:FilePath/Escudo%20ufmt.jpg", "name": "Federal University of Mato Grosso", "image": "http://commons.wikimedia.org/wiki/Special:FilePath/Reitoria%20da%20UFMT.jpg", "country": "Q155", "founded": "+1970-01-01T00:00:00Z", "website": "https://www.ufmt.br/", "description": "university in Brazil", "wikidata_id": "Q7894374", "wikipedia_url": "https://en.wikipedia.org/wiki/Q7894374"}', '27e775f8-0f40-4e37-b493-8d0d7947b729', NULL, 'BR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.296289+01', '2026-08-09 11:03:18.109342+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('0679ce9c-5984-4001-930a-8356e5f357b0', NULL, '00000000-0000-0000-0000-000000000060', 'Mauritania', 'mauritania', 'From West Africa to cities and towns across the globe — this is the gathering point for a diaspora that never lost touch with home. It is set in West Africa, sharing borders with Algeria, Mali, and Senegal, with Nouakchott as its capital. Share local news, discover events, trade on the marketplace, and tap into remittance rates, scholarship finds, and community resources — all in one place.', '{"title": "Mauritania", "extract": "Mauritania, officially and also known as the Islamic Republic of Mauritania, is a country in the Maghreb region of West Africa. It is bordered by the Atlantic Ocean to the west, Western Sahara to the north and northwest, Algeria to the northeast, Mali to the east and southeast, and Senegal to the southwest. By land area Mauritania is the 11th-largest country in Africa and the 28th-largest in the world; 90% of its territory is in the Sahara desert. Most of its population of 4.3 million live in the temperate south of the country; roughly a third of the population is concentrated in the capital and largest city, Nouakchott, on the Atlantic coast.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/43/Flag_of_Mauritania.svg/330px-Flag_of_Mauritania.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Mauritania", "description": "Country in West Africa"}', '34017ff0-010b-4495-8c4b-2dff85d3f25b', NULL, 'MR', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:07.384665+01', NULL, NULL, '{mauritania,mr,africa,community,diaspora}', NULL, 'Africa', 'Western Africa', NULL);
INSERT INTO public.spaces VALUES ('fdc344e0-7d26-4b29-8926-a4a9ce351ab7', NULL, '00000000-0000-0000-0000-000000000060', 'Greenland', 'greenland', 'Your digital anchor — wherever the diaspora has settled, this is home base. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "Greenland", "extract": "Greenland is an autonomous territory of the Kingdom of Denmark and is the largest of the kingdom''s three constituent parts by land area, the others being Denmark proper and the Faroe Islands. Citizens of Greenland are citizens of Denmark. They are thus citizens of the European Union (EU), although Greenland is not part of the EU. It is the world''s largest island and lies between the Arctic and Atlantic oceans, east of the Canadian Arctic Archipelago. It shares a small 1.2-kilometre (0.75 mi) border with Canada on Hans Island. The capital and largest city is Nuuk. Kaffeklubben Island off the northern coast is the world''s northernmost undisputed point of land – Cape Morris Jesup on the main island was thought to be so until the 1960s. Economically, Greenland is heavily reliant on aid from Denmark, which has averaged 5.4 billion kr. annually in the period 2019–2023, amounting to more than 20% of the territory''s gross domestic product.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/09/Flag_of_Greenland.svg/330px-Flag_of_Greenland.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Greenland", "description": "Autonomous territory of Denmark"}', '22212808-e3c1-46fb-88d0-28fd2819fabe', NULL, 'GL', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:41.155622+01', NULL, NULL, '{greenland,gl,island,community,diaspora}', NULL, 'Americas', 'Northern America', NULL);
INSERT INTO public.spaces VALUES ('f3715d84-c0fe-4072-843a-8c0d996f4395', NULL, '00000000-0000-0000-0000-000000000060', 'Guadeloupe', 'guadeloupe', 'From here to the world — this is where the diaspora gathers, no matter how far they''ve traveled. It is with Basse-Terre as its capital. Share local news, discover events, trade on the marketplace, and tap into remittance rates, scholarship finds, and community resources — all in one place.', '{"title": "Guadeloupe", "extract": "Guadeloupe is an overseas department and region of France in the Caribbean. It consists of six inhabited islands—Basse-Terre, Grande-Terre, Marie-Galante, La Désirade, and two Îles des Saintes—and 30 uninhabited islets and 3 inhabited islets. It is south of Antigua and Barbuda and Montserrat and north of Dominica. The capital city is Basse-Terre, on the southern west coast of Basse-Terre Island; the most populous city is Les Abymes and the main centre of business is neighbouring Pointe-à-Pitre, both on Grande-Terre Island. It had a population of 395,726 in 2024.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d7/Guadeloupe_in_France_2016.svg/330px-Guadeloupe_in_France_2016.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Guadeloupe", "description": "Overseas department and region of France"}', 'f4e77bf4-96be-432a-8ed6-9e67400601fb', NULL, 'GP', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:42.165246+01', NULL, 'EUR', '{guadeloupe,gp,island,community,diaspora}', NULL, 'Americas', 'Caribbean', NULL);
INSERT INTO public.spaces VALUES ('ff1f35bd-730f-4056-88dd-13646b2f492c', NULL, '00000000-0000-0000-0000-000000000060', 'Haiti', 'haiti', 'From Caribbean to cities and towns across the globe — this is the gathering point for a diaspora that never lost touch with home. It is set in Caribbean, with Port-au-Prince as its capital. Share local news, discover events, trade on the marketplace, and tap into remittance rates, scholarship finds, and community resources — all in one place.', '{"title": "Haiti", "extract": "Haiti, officially the Republic of Haiti, is a country in the Caribbean on the island of Hispaniola in the Caribbean Sea, east of Cuba and Jamaica and south of The Bahamas. It occupies the western side of the island, which it shares with the Dominican Republic. Haiti is the third largest country in the Caribbean by area, and with an estimated population of 11.4 million, it is the most populous Caribbean country. The capital and largest city is Port-au-Prince.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/56/Flag_of_Haiti.svg/330px-Flag_of_Haiti.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Haiti", "description": "Country in the Caribbean"}', 'f19b8609-7a17-43f0-b928-346f46dc80d8', NULL, 'HT', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:45.69699+01', NULL, NULL, '{haiti,ht,caribbean,island,community,diaspora}', NULL, 'Americas', 'Caribbean', NULL);
INSERT INTO public.spaces VALUES ('98e5bf36-9146-4eb7-8962-68621c9a0c5d', '9b54a87a-f538-4c78-89af-adc13cd8170a', '00000000-0000-0000-0000-000000000062', 'Surulere', 'surulere', NULL, NULL, NULL, NULL, NULL, 'city', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-21 11:41:02.295375+01', '2026-08-21 11:41:02.295375+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('30fc8304-96d2-4439-9d05-2979f8a990a1', NULL, '00000000-0000-0000-0000-000000000060', 'Ireland', 'ireland', 'Rooted in North Atlantic Ocean, reaching across continents — this space bridges home and diaspora. A population of the entire island is just over 7 million calls it home. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "Ireland", "extract": "Ireland is an island in the North Atlantic Ocean, in Northwestern Europe. Geopolitically, the island is divided between the Republic of Ireland and Northern Ireland. It is separated from Great Britain to its east by the North Channel, the Irish Sea, and St George''s Channel. Ireland is the second-largest island of the British Isles, the third-largest in Europe, and the twentieth-largest in the world. As of 2022, the population of the entire island is just over 7 million, with 5.1 million in the Republic of Ireland and 1.9 million in Northern Ireland, ranking it the second-most populous island in Europe after Great Britain.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/74/Ireland_%28MODIS%29.jpg/330px-Ireland_%28MODIS%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Ireland", "description": "Island in the North Atlantic Ocean"}', '60392042-d1db-495a-8953-27df3b5e138d', NULL, 'IE', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-07-08 23:07:05.600578+01', '2026-08-07 11:44:50.742282+01', NULL, 'EUR', '{ireland,ie,island,community,diaspora}', NULL, 'Europe', 'Northern Europe', NULL);
INSERT INTO public.spaces VALUES ('2fe9f5fc-f6e9-49a1-8287-c28255c83900', NULL, '00000000-0000-0000-0000-000000000060', 'Kyrgyzstan', 'kyrgyzstan', 'Every journey out of Central Asia carries a story — of ambition, of longing, of roots that stretch but never break. Discover local businesses, share news from home, find events near you, and build a network that spans borders — all on JapaConnect.', '{"title": "Kyrgyzstan", "extract": "Kyrgyzstan, officially the Kyrgyz Republic, formerly known as Kirghizia, is a landlocked country in the eastern regions of Central Asia, lying in the Tian Shan and Pamir mountain ranges. It is bordered by Kazakhstan to the north, Uzbekistan to the west, Tajikistan to the south, and China to the east and southeast. Kyrgyzstan''s capital and largest city is Bishkek which lies on the northern border with Kazakhstan. Ethnic Kyrgyz make up the majority of the country''s over 7.4 million people, followed by significant minorities of Uzbeks and Russians.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/c7/Flag_of_Kyrgyzstan.svg/330px-Flag_of_Kyrgyzstan.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Kyrgyzstan", "description": "Country in Central Asia"}', '93c65cbf-8c6a-49a8-b890-b9f695661961', NULL, 'KG', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:57.295407+01', NULL, NULL, '{kyrgyzstan,kg,asia,landlocked,community,diaspora}', NULL, 'Asia', 'Central Asia', NULL);
INSERT INTO public.spaces VALUES ('f7e9b012-c7da-4c9d-afbe-698a8c836ced', NULL, '00000000-0000-0000-0000-000000000060', 'Mayotte', 'mayotte', 'Every journey carries a story — of ambition, of longing, of roots that stretch but never break. Discover local businesses, share news from home, find events near you, and build a network that spans borders — all on JapaConnect.', '{"title": "Mayotte", "extract": "Mayotte, officially the Department of Mayotte, is an overseas department and region and single territorial collectivity of France. It is one of the overseas departments of France as well as one of the 18 regions of France, with the same status as the departments of Metropolitan France. It is an outermost region of the European Union and, as an overseas department of France, part of the eurozone.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/ab/D%C3%A9partement_976_in_France_%28zoom%29.svg/330px-D%C3%A9partement_976_in_France_%28zoom%29.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Mayotte", "description": "Overseas department of France"}', '79cddb0c-2c83-47ee-a8a2-2ef8537e996d', NULL, 'YT', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:08.392444+01', NULL, 'EUR', '{mayotte,yt,community,diaspora}', NULL, 'Africa', 'Eastern Africa', NULL);
INSERT INTO public.spaces VALUES ('73e5e637-de66-4e13-8bdf-e601c2488947', NULL, '00000000-0000-0000-0000-000000000060', 'Montserrat', 'montserrat', 'It is set in Caribbean. Whether you''re still in Caribbean or building a life elsewhere, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Montserrat", "extract": "Montserrat is a British Overseas Territory in the Caribbean. It is part of the Leeward Islands, the northern portion of the Lesser Antilles chain of the West Indies. Montserrat is about 16 km (10 mi) long and 11 km (7 mi) wide, with roughly 40 km (25 mi) of coastline. It is nicknamed \"The Emerald Isle of the Caribbean\" both for its resemblance to coastal Ireland and for the Irish ancestry of many of its inhabitants. Montserrat is the only non-fully sovereign full member of the Caribbean Community and the Organisation of Eastern Caribbean States, although it is not the only dependency in the Caribbean.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d0/Flag_of_Montserrat.svg/330px-Flag_of_Montserrat.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Montserrat", "description": "British Overseas Territory in the Caribbean"}', 'fc9d9729-472b-49d7-9c49-7181b900fe70', NULL, 'MS', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:11.924175+01', NULL, NULL, '{montserrat,ms,caribbean,island,community,diaspora}', NULL, 'Americas', 'Caribbean', NULL);
INSERT INTO public.spaces VALUES ('49f0f9bb-b10d-41fc-84a9-53f01df1b4bd', NULL, '00000000-0000-0000-0000-000000000060', 'Netherlands', 'netherlands', 'Every journey out of Northwestern Europe and the Caribbean carries a story — of ambition, of longing, of roots that stretch but never break. Discover local businesses, share news from home, find events near you, and build a network that spans borders — all on JapaConnect.', '{"title": "Netherlands", "extract": "The Netherlands, also informally known as Holland, is a country in Northwestern Europe, with overseas territories in the Caribbean. It is the largest of the four constituent countries of the Kingdom of the Netherlands. The Netherlands consists of twelve provinces and three overseas special municipalities. European Netherlands has land borders with Germany to the east and with Belgium to the south, and a coastline to the north and west. It shares maritime borders with the United Kingdom, Germany, and Belgium in the North Sea. The official language is Dutch, with West Frisian as a secondary official language in the province of Friesland. Dutch, English, and Papiamento are official in the Caribbean territories. People from the Netherlands are referred to as Dutch.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/20/Flag_of_the_Netherlands.svg/330px-Flag_of_the_Netherlands.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Netherlands", "description": "Country in Northwestern Europe and the Caribbean"}', '039b34d5-16f8-459c-bf9b-a56226edd7e1', NULL, 'NL', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-07-08 23:07:05.600578+01', '2026-08-07 11:45:15.453483+01', NULL, 'EUR', '{netherlands,nl,europe,community,diaspora}', NULL, 'Europe', 'Western Europe', NULL);
INSERT INTO public.spaces VALUES ('d5343809-5095-47f9-94cd-fb20f1c0ec13', '9b54a87a-f538-4c78-89af-adc13cd8170a', '00000000-0000-0000-0000-000000000062', 'Yaba', 'yaba', NULL, NULL, NULL, NULL, NULL, 'city', 1, 0, 1, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-21 11:44:58.128522+01', '2026-08-21 11:44:58.128522+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('ed76ac5a-c678-409a-9ae3-f6f7cb02fc36', NULL, '00000000-0000-0000-0000-000000000060', 'Peru', 'peru', 'Your digital anchor in South America — from Lima to the farthest corners of the diaspora, everything flows through here. A land of rainforests and arid plains, shaped by geography and history into something uniquely its own. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "Peru", "extract": "Peru, officially the Republic of Peru, is a country in western South America. It is bordered to the north by Ecuador and Colombia, to the east by Brazil, to the southeast by Bolivia, to the south by Chile, and to the south and west by the Pacific Ocean. Peru is a megadiverse country, with habitats ranging from the arid plains of the Pacific coastal region in the west, to the peaks of the Andes mountains extending from the north to the southeast of the country, to the tropical Amazon basin rainforest in the east with the Amazon River. Peru has a population of over 32 million, and its capital and largest city is Lima. At 1,285,216 km2 (496,225 sq mi), Peru is the 19th largest country in the world, and the third largest in South America.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/cf/Flag_of_Peru.svg/330px-Flag_of_Peru.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Peru", "description": "Country in South America"}', '85d2d172-3701-4d42-8ef2-d6dccd94f33b', NULL, 'PE', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:25.037196+01', NULL, NULL, '{peru,pe,"south america",community,diaspora}', NULL, 'Americas', 'South America', NULL);
INSERT INTO public.spaces VALUES ('80960a69-fd57-454d-a8af-64580f08042c', NULL, '00000000-0000-0000-0000-000000000060', 'Paraguay', 'paraguay', 'It is set in South America, landlocked, sharing borders with Bolivia, Brazil, and Argentina, with Asunción as its capital. From the streets of Asunción to diaspora communities worldwide, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Paraguay", "extract": "Paraguay, officially the Republic of Paraguay, is a landlocked country located in the central region of South America. It borders Bolivia to the northwest and north, Brazil to the northeast and east, and Argentina to the southeast, south, and west. Paraguay has access to the Atlantic Ocean via the Paraná–Paraguay Waterway, a system of navigable channels shared by five countries. The country is governed as a unitary presidential republic composed of a capital district and seventeen departments. Its capital and largest city is Asunción. It dates its independence from Spain to 1811.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/27/Flag_of_Paraguay.svg/330px-Flag_of_Paraguay.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Paraguay", "description": "Country in South America"}', '28a2e82f-e393-48a8-86a8-057ce84ad53b', NULL, 'PY', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:24.532392+01', NULL, NULL, '{paraguay,py,"south america",landlocked,community,diaspora}', NULL, 'Americas', 'South America', NULL);
INSERT INTO public.spaces VALUES ('f557062f-511e-4804-9844-10111eef8fdd', NULL, '00000000-0000-0000-0000-000000000060', 'Rwanda', 'rwanda', 'Landlocked in East Africa but connected to the world — this is where the diaspora gathers, no matter how far they''ve traveled. It is set in East Africa, landlocked, sharing borders with Uganda, Tanzania, Burundi, and Democratic Republic, with Kigali as its capital.', '{"title": "Rwanda", "extract": "Rwanda, officially the Republic of Rwanda, is a landlocked country in East Africa. Its geography is dominated by mountains in the west and savanna in the southeast. The largest and most notable lakes are mainly in the western and northern regions of the country, and several volcanoes that form part of the Virunga volcanic chain are primarily in the northwest. The climate is considered tropical highland, with two rainy seasons and two dry seasons each year. Its capital and largest city is Kigali, located at the centre of the country, at 1,567 metres above sea level. Rwanda lies a few degrees south of the Equator in the Great Rift Valley of East Africa. Rwanda is bordered by Uganda to the north, Tanzania to the east, Burundi to the south, and the Democratic Republic of the Congo to the west. With a population of about 14 million people living within a total area of 26,338 square kilometres (10,169 sq mi), of which land accounts for about 93.7%, Rwanda is the 21st most densely populated country in the world, with an average of about 578 people per square kilometre.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/17/Flag_of_Rwanda.svg/330px-Flag_of_Rwanda.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Rwanda", "description": "Country in East Africa"}', '7535ebc2-c987-446a-8957-711250823a79', NULL, 'RW', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:30.08509+01', NULL, NULL, '{rwanda,rw,africa,landlocked,community,diaspora}', NULL, 'Africa', 'Eastern Africa', NULL);
INSERT INTO public.spaces VALUES ('040209aa-fdaf-4644-bd8b-52d446a2f6b3', NULL, '00000000-0000-0000-0000-000000000060', 'Saint Lucia', 'saint-lucia', 'Your digital anchor in West Indies in the eastern Caribbean Sea — from Castries to the farthest corners of the diaspora, everything flows through here. Home to 184 people, with communities spread far beyond its borders. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "Saint Lucia", "extract": "Saint Lucia is an island country in the eastern and southern Caribbean. Part of the Windward Islands of the Lesser Antilles, it is located north/northeast of the island of Saint Vincent, northwest of Barbados and south of Martinique. It covers a land area of 617 km2 (238 sq mi) with an officially estimated population of over 184,100 people as of mid 2023. The nation''s capital and largest city is Castries.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/9f/Flag_of_Saint_Lucia.svg/330px-Flag_of_Saint_Lucia.svg.png", "content_url": "https://en.wikipedia.org/wiki/Saint_Lucia", "description": "Country in the West Indies in the eastern Caribbean Sea"}', '9d09973a-8f8b-4e76-bf28-af5ef88d2bd6', NULL, 'LC', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:32.102597+01', NULL, NULL, '{"saint lucia",saint-lucia,lc,caribbean,island,community,diaspora}', NULL, 'Americas', 'Caribbean', NULL);
INSERT INTO public.spaces VALUES ('9c71e2c8-e83b-4d79-967d-c46e6eb280a6', NULL, '00000000-0000-0000-0000-000000000060', 'Saint Pierre and Miquelon', 'saint-pierre-and-miquelon', 'Whether you''re home or building a life elsewhere, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Saint Pierre and Miquelon", "extract": "Saint Pierre and Miquelon, officially the Territorial Collectivity of Saint Pierre and Miquelon, is a self-governing territorial overseas collectivity of France in the northwestern Atlantic Ocean, located off the Canadian island of Newfoundland. St. Pierre and Miquelon is an archipelago of eight islands, covering 242 km2 (93 sq mi) of land. It had an estimated population of 5,513 in 2026 and its residents are French citizens; they elect their own deputy to the National Assembly and participate in senatorial and presidential elections.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/74/Flag_of_Saint-Pierre_and_Miquelon.svg/330px-Flag_of_Saint-Pierre_and_Miquelon.svg.png", "content_url": "https://en.wikipedia.org/wiki/Saint_Pierre_and_Miquelon", "description": "Overseas collectivity of France"}', 'ce3e171b-5065-45aa-b27c-c49f2bb74c04', NULL, 'PM', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:33.111563+01', NULL, 'EUR', '{"saint pierre and miquelon",saint-pierre-and-miquelon,pm,island,community,diaspora}', NULL, 'Americas', 'Northern America', NULL);
INSERT INTO public.spaces VALUES ('5f841aa1-1004-49d2-a0a3-5d5986ebac95', NULL, '00000000-0000-0000-0000-000000000060', 'Wallis and Futuna Islands', 'wallis-and-futuna-islands', 'Rooted here, reaching across continents — this space bridges home and diaspora. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "Wallis and Futuna", "extract": "Wallis and Futuna, officially the Territory of the Wallis and Futuna Islands, is a French island collectivity in the South Pacific, situated between Tuvalu to the northwest, Fiji to the southwest, Tonga to the southeast, Samoa to the east, and Tokelau to the northeast.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d2/Flag_of_Wallis_and_Futuna.svg/330px-Flag_of_Wallis_and_Futuna.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Wallis_and_Futuna", "description": "Overseas collectivity of France"}', '7b7aeca1-8d51-4259-8163-e0c19798ca2a', NULL, 'WF', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:46:02.360257+01', NULL, NULL, '{"wallis and futuna islands",wallis-and-futuna-islands,wf,island,community,diaspora}', NULL, 'Oceania', 'Polynesia', NULL);
INSERT INTO public.spaces VALUES ('d13b1104-9805-4a35-974e-ca74cb7ddd78', '9b54a87a-f538-4c78-89af-adc13cd8170a', '00000000-0000-0000-0000-000000000062', 'Oshodi', 'oshodi', NULL, NULL, NULL, NULL, NULL, 'city', 2, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-21 11:54:43.547922+01', '2026-08-21 11:54:43.547922+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('ea5d0c16-b6fb-4949-a072-fba54af7a598', NULL, '00000000-0000-0000-0000-000000000060', 'Brazil', 'brazil', 'Your digital anchor in South America — from Brasília to the farthest corners of the diaspora, everything flows through here. From the capital to São Paulo and beyond, the diaspora carries the spirit of home wherever they go. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "Brazil", "extract": "Brazil, officially the Federative Republic of Brazil, is the largest country in South America. It is also the world''s fifth-largest country by area and the seventh-largest by population, with over 213 million people. Brazil is a federation composed of 26 states and a Federal District, which hosts the capital, Brasília. Its most populous city is São Paulo, followed by Rio de Janeiro. Brazil has the largest Lusophone population in the world and is the only Portuguese-speaking country in the Americas, where it is the official language.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/0/05/Flag_of_Brazil.svg/330px-Flag_of_Brazil.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Brazil", "description": "Country in South America"}', 'f5dc8cbc-74a5-4eb8-a4c2-e2655e78d0b8', NULL, 'BR', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:13.926546+01', NULL, NULL, '{brazil,br,"south america",community,diaspora}', NULL, 'Americas', 'South America', NULL);
INSERT INTO public.spaces VALUES ('021fc256-2e5b-45cc-a167-891113777d7d', NULL, '00000000-0000-0000-0000-000000000060', 'Brunei', 'brunei', 'Rooted in Southeast Asia, reaching across continents — this space bridges home and diaspora. A population of 466 calls it home. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "Brunei", "extract": "Brunei, officially Brunei Darussalam, is a country in Southeast Asia, situated on the northern coast of the island of Borneo. Apart from its coastline on the South China Sea, it is completely surrounded by the Malaysian state of Sarawak, with its territory bifurcated by the Sarawak district of Limbang. Brunei is the only sovereign state entirely on Borneo; the remainder of the island is divided between its multi-landmass neighbours of Malaysia and Indonesia. As of 2025, the country had a population of 466,330, being the least populated country in Asia of whom approximately 64,409 resided in the capital and largest city of Bandar Seri Begawan. Its official language is Malay, and Sunni Islam is the state religion of the country, although other religions are nominally tolerated. The government of Brunei is an absolute monarchy ruled by the Sultan, and it implements a fusion of English common law and jurisprudence inspired by Islam, including sharia.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/9c/Flag_of_Brunei.svg/330px-Flag_of_Brunei.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Brunei", "description": "Country in Southeast Asia"}', '15b73238-0217-4911-b178-5f23239beab7', NULL, 'BN', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:14.933836+01', NULL, NULL, '{brunei,bn,asia,island,community,diaspora}', NULL, 'Asia', 'South-Eastern Asia', NULL);
INSERT INTO public.spaces VALUES ('29920da3-2888-4734-b56b-70e6eca9bb26', NULL, '00000000-0000-0000-0000-000000000060', 'Cuba', 'cuba', 'Every journey out of Caribbean carries a story — of ambition, of longing, of roots that stretch but never break. Discover local businesses, share news from home, find events near you, and build a network that spans borders — all on JapaConnect.', '{"title": "Cuba", "extract": "Cuba, officially the Republic of Cuba, is an island country in the Caribbean. It comprises the eponymous main island as well as 4,195 islands, islets, and cays. Situated at the convergence of the Caribbean Sea, Gulf of Mexico, and Atlantic Ocean, Cuba is located east of the Yucatán Peninsula, south of both Florida and the Bahamas, west of Hispaniola, and north of Jamaica and the Cayman Islands. Havana is the largest city and capital. Cuba is the third-most populous country in the Caribbean after Haiti and Dominican Republic, with about 10 million inhabitants. It is the largest country in the Caribbean by area. Culturally, Cuba is considered part of Latin America.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/bd/Flag_of_Cuba.svg/330px-Flag_of_Cuba.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Cuba", "description": "Country in the Caribbean"}', 'b77e4d14-ec94-496e-b457-d5f47376f5d9', NULL, 'CU', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:25.530276+01', NULL, NULL, '{cuba,cu,caribbean,island,community,diaspora}', NULL, 'Americas', 'Caribbean', NULL);
INSERT INTO public.spaces VALUES ('879b54c0-d36d-43d5-8331-bbba3ff0e239', NULL, '00000000-0000-0000-0000-000000000060', 'Democratic Republic of the Congo', 'democratic-republic-of-the-congo', 'From Central Africa to cities and towns across the globe — this is the gathering point for a diaspora that never lost touch with home. It is set in Central Africa, sharing borders with Republic, Congo, Cabinda, and Angola. Share local news, discover events, trade on the marketplace, and tap into remittance rates, scholarship finds, and community resources — all in one place.', '{"title": "Democratic Republic of the Congo", "extract": "The Democratic Republic of the Congo (DRC), also known as the DR Congo, Congo-Kinshasa, or simply the Congo, and formerly named Zaire, is a country in Central Africa. By land area, it is the second-largest country in Africa and the eleventh-largest in the world. With a population of about 124 million people, the Democratic Republic of the Congo is the fourth-most populous country in Africa and the most populous Francophone country in the world. French is the official and most widely spoken language. There are over 200 indigenous languages, of which Lingala is the most widely spoken. The capital, largest city, and economic center is Kinshasa. The DRC is bordered by the Republic of the Congo, the Cabinda exclave of Angola, and the South Atlantic Ocean to the west; the Central African Republic and South Sudan to the north; Uganda, Rwanda, Burundi, and Tanzania to the east; and Zambia and Angola to the south. Centered on the Congo Basin, most of the DRC''s terrain is covered by dense rainforests and is crossed by many rivers. The east and southeast are mountainous.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/6f/Flag_of_the_Democratic_Republic_of_the_Congo.svg/330px-Flag_of_the_Democratic_Republic_of_the_Congo.svg.png", "content_url": "https://en.wikipedia.org/wiki/Democratic_Republic_of_the_Congo", "description": "Country in Central Africa"}', '031a36d0-8871-4da8-a3ab-fdbea2ec68b3', NULL, 'CD', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:27.549287+01', NULL, NULL, '{"democratic republic of the congo",democratic-republic-of-the-congo,cd,africa,community,diaspora}', NULL, 'Africa', 'Middle Africa', NULL);
INSERT INTO public.spaces VALUES ('29ffee0d-fbb6-4f5e-9cab-8ab0a4945f29', NULL, '00000000-0000-0000-0000-000000000060', 'Lebanon', 'lebanon', 'Rooted in West Asia, sharing borders with Syria and Israel, and reaching across continents — this space bridges home and diaspora. A population of five million and an area of 10 calls it home. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "Lebanon", "extract": "Lebanon, officially the Lebanese Republic, is a country in the Levant region of West Asia. Situated at the crossroads of the Mediterranean Basin and the Arabian Peninsula, it is bordered by Syria to the north and east, Israel to the south, and the Mediterranean Sea to the west; Cyprus lies a short distance from the coastline. Lebanon has a population of more than five million and an area of 10,452 square kilometres (4,036 sq mi). Beirut is the country''s capital and largest city.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/59/Flag_of_Lebanon.svg/330px-Flag_of_Lebanon.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Lebanon", "description": "Country in West Asia"}', '523af035-38be-4e17-a258-13b5b143eb33', NULL, 'LB', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:58.807097+01', NULL, NULL, '{lebanon,lb,asia,community,diaspora}', NULL, 'Asia', 'Western Asia', NULL);
INSERT INTO public.spaces VALUES ('cd2b63ab-48ee-4f25-a5db-de8acddf93e4', NULL, '00000000-0000-0000-0000-000000000060', 'Singapore', 'singapore', 'It is set in Southeast Asia, an island nation. Whether you''re still in Southeast Asia or building a life elsewhere, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Singapore", "extract": "Singapore, officially the Republic of Singapore, is an island country in Southeast Asia. Its territory comprises a main island, over 60 satellite islands and islets, and one outlying islet. The country is about one degree of latitude north of the equator, off the southern tip of the Malay Peninsula, bordering the Strait of Malacca to the west, the Singapore Strait to the south along with the Riau Islands in Indonesia, the South China Sea to the east and the Straits of Johor along with the State of Johor in Malaysia to the north.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/48/Flag_of_Singapore.svg/330px-Flag_of_Singapore.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Singapore", "description": "Island country in Southeast Asia"}', 'c0ad9635-1632-4230-aa3b-094be4dcfa1d', NULL, 'SG', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:38.158529+01', NULL, NULL, '{singapore,sg,asia,island,community,diaspora}', NULL, 'Asia', 'South-Eastern Asia', NULL);
INSERT INTO public.spaces VALUES ('72dd68de-378a-44b6-b173-ab6b50a4443a', NULL, '00000000-0000-0000-0000-000000000060', 'Faroe Islands', 'faroe-islands', 'Rooted here, reaching across continents — this space bridges home and diaspora. Tórshavn is the capital; a population of 54 calls it home. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "Faroe Islands", "extract": "The Faroe Islands, also known as the Faroes, are an archipelago in the North Atlantic Ocean and a rigsdel of the Kingdom of Denmark. Located between Iceland, Norway, and the Hebrides and Shetland isles of Scotland, the islands have a population of 54,870 as of November 2025 and a land area of 1,393 km2 (538 sq mi). The official language is Faroese, which is partially mutually intelligible with Icelandic. The terrain is rugged, dominated by fjords and cliffs with sparse vegetation and few trees. As a result of their proximity to the Arctic Circle, the islands experience perpetual civil twilight during summer nights and very short winter days; nevertheless, they experience a subpolar oceanic climate and mild temperatures year-round due to the Gulf Stream. The capital, Tórshavn, receives the fewest recorded hours of sunshine of any city in the world at only 840 per year.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/3c/Flag_of_the_Faroe_Islands.svg/330px-Flag_of_the_Faroe_Islands.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Faroe_Islands", "description": "Autonomous territory of Denmark"}', 'f970e833-8b3e-47ae-af64-67fa1bd15b89', NULL, 'FO', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:34.60729+01', NULL, NULL, '{"faroe islands",faroe-islands,fo,island,community,diaspora}', NULL, 'Europe', 'Northern Europe', NULL);
INSERT INTO public.spaces VALUES ('4ed58099-6d66-4dd7-b2aa-86077cd17a00', NULL, '00000000-0000-0000-0000-000000000060', 'Iceland', 'iceland', 'Rooted here, reaching across continents — this space bridges home and diaspora. Reykjavík is the capital; the landscape is defined by volcanic activity and geysers. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "Iceland", "extract": "Iceland is a Nordic island country between the Arctic Ocean and the North Atlantic Ocean, located on the Mid-Atlantic Ridge between Europe and North America. It is culturally and politically linked with Europe and is the region''s westernmost and most sparsely populated country. Its capital and largest city is Reykjavík, which is home to about 35% of the country''s roughly 395,000 residents. The official language of the country is Icelandic. Iceland is on a rift between tectonic plates, and its geologic activity includes geysers and frequent volcanic eruptions. The interior consists of a volcanic plateau with sand and lava fields, mountains and glaciers, and many glacial rivers flow to the sea through the lowlands. Iceland is warmed by the Gulf Stream and has a temperate climate, despite being at a latitude just south of the Arctic Circle. Its latitude and marine influence keep summers chilly, and most of its islands have a polar climate.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/ce/Flag_of_Iceland.svg/330px-Flag_of_Iceland.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Iceland", "description": "Island country in the Atlantic Ocean"}', '7a5253a7-5c33-4993-abe4-83355366064f', NULL, 'IS', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:48.218246+01', NULL, NULL, '{iceland,is,island,community,diaspora}', NULL, 'Europe', 'Northern Europe', NULL);
INSERT INTO public.spaces VALUES ('12191764-2acb-4bed-94d9-69575a08220f', NULL, '00000000-0000-0000-0000-000000000060', 'Ivory Coast', 'ivory-coast', 'From West Africa to cities and towns across the globe — this is the gathering point for a diaspora that never lost touch with home. It is set in West Africa, sharing borders with Guinea, Liberia, Mali, and Burkina Faso, with Yamoussoukro as its capital.', '{"title": "Ivory Coast", "extract": "Ivory Coast, also known as Côte d''Ivoire and officially as the Republic of Côte d''Ivoire, is a country on the southern coast of West Africa. Its capital, Yamoussoukro, is located in the centre of the country, while Abidjan is its largest city and economic centre. It borders Guinea to the northwest, Liberia to the west, Mali to the north, Burkina Faso to the northeast, Ghana to the east, and the Atlantic Ocean''s Gulf of Guinea to the south. With 31.5 million inhabitants in 2024, Ivory Coast is the third-most populous country in West Africa after Ghana and Nigeria. Its official language is French, and indigenous languages are also widely used, including Bété, Baoulé, Dyula, Dan, Anyin, and Cebaara Senufo. In total, there are around 78 languages spoken in Ivory Coast. The country has a religiously diverse population, including numerous followers of Islam, Christianity and traditional faiths often entailing animism.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/fe/Flag_of_C%C3%B4te_d%27Ivoire.svg/330px-Flag_of_C%C3%B4te_d%27Ivoire.svg.png", "content_url": "https://en.wikipedia.org/wiki/Ivory_Coast", "description": "Country in West Africa"}', '538d0345-5d3b-4381-9248-1a3786f6ae1a', NULL, 'CI', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:52.253188+01', NULL, NULL, '{"ivory coast",ivory-coast,ci,africa,community,diaspora}', NULL, 'Africa', 'Western Africa', NULL);
INSERT INTO public.spaces VALUES ('95342a8d-13f9-49b3-abe1-306e3b391e63', NULL, '00000000-0000-0000-0000-000000000064', 'Ocean County College', 'ocean-county-college', NULL, '{"name": "Ocean County College", "country": "Q30", "founded": "+1969-00-00T00:00:00Z", "website": "https://www.ocean.edu/", "description": "community college in Ocean County, New Jersey, U.S.", "wikidata_id": "Q7075970", "wikipedia_url": "https://en.wikipedia.org/wiki/Q7075970"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-27 05:59:29.487295+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('5c53da98-9ef7-438a-9ded-a8824d051040', NULL, '00000000-0000-0000-0000-000000000060', 'Mauritius', 'mauritius', 'Rooted here, reaching across continents — this space bridges home and diaspora. Port Louis is the capital. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "Mauritius", "extract": "Mauritius, officially the Republic of Mauritius, is an island country in the Indian Ocean, located about 1,100 nautical miles off the southeastern coast of Africa, east of Madagascar. It includes the main island, as well as Rodrigues, Agaléga, and St. Brandon. The islands of Mauritius and Rodrigues, along with nearby Réunion, are part of the Mascarene Islands. The main island of Mauritius, where the population is concentrated, hosts the capital and largest city, Port Louis. The country spans 2,040 square kilometres (790 sq mi) and has an exclusive economic zone covering approximately 580,000 square nautical miles.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/77/Flag_of_Mauritius.svg/330px-Flag_of_Mauritius.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Mauritius", "description": "Island country in the Indian Ocean"}', '1163f6ca-a4f9-4afa-a80f-cd4497606aeb', NULL, 'MU', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:07.888574+01', NULL, NULL, '{mauritius,mu,island,community,diaspora}', NULL, 'Africa', 'Eastern Africa', NULL);
INSERT INTO public.spaces VALUES ('d428ef53-cd53-4736-92d2-a6351c8f6aa4', NULL, '00000000-0000-0000-0000-000000000060', 'Papua New Guinea', 'papua-new-guinea', 'It is set in Oceania, an island nation, sharing borders with Australia and Solomon Islands, with Port Moresby as its capital. From the streets of Port Moresby to diaspora communities worldwide, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Papua New Guinea", "extract": "Papua New Guinea (PNG), officially the Independent State of Papua New Guinea, is an island country in Oceania that comprises the eastern half of the island of New Guinea and offshore islands in Melanesia, a region of the southwestern Pacific Ocean north of Australia. It has a land border with Indonesia to the west and maritime borders with Australia to the south and the Solomon Islands to the east. Its capital is Port Moresby. The country''s 462,840 km2 (178,700 mi2) includes a large mainland and hundreds of islands.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/e3/Flag_of_Papua_New_Guinea.svg/330px-Flag_of_Papua_New_Guinea.svg.png", "content_url": "https://en.wikipedia.org/wiki/Papua_New_Guinea", "description": "Country in Oceania"}', 'd1886d91-1c64-492d-80d4-5647f4b3dd4f', NULL, 'PG', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:24.021614+01', NULL, NULL, '{"papua new guinea",papua-new-guinea,pg,oceania,island,community,diaspora}', NULL, 'Oceania', 'Melanesia', NULL);
INSERT INTO public.spaces VALUES ('6c5e8558-541e-437d-9dfc-687d08bc67f6', NULL, '00000000-0000-0000-0000-000000000060', 'The Gambia', 'the-gambia', 'Rooted in West Africa, reaching across continents — this space bridges home and diaspora. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "The Gambia", "extract": "The Gambia, officially the Republic of The Gambia, is a country in West Africa. Geographically, The Gambia is the smallest country in continental Africa; it is bounded by Senegal on all sides except for the western part, which is bordered by the Atlantic Ocean.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/77/Flag_of_The_Gambia.svg/330px-Flag_of_The_Gambia.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/The_Gambia", "description": "Country in West Africa"}', 'c49f1536-9191-48e2-a352-3c508163bf71', NULL, 'GM', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:49.738311+01', NULL, NULL, '{"the gambia",the-gambia,gm,africa,community,diaspora}', NULL, 'Africa', 'Western Africa', NULL);
INSERT INTO public.spaces VALUES ('0bc449be-67b5-43d5-be5b-9cb097d6c8f0', NULL, '00000000-0000-0000-0000-000000000060', 'Togo', 'togo', 'Every journey out of West Africa carries a story — of ambition, of longing, of roots that stretch but never break. Discover local businesses, share news from home, find events near you, and build a network that spans borders — all on JapaConnect.', '{"title": "Togo", "extract": "Togo, officially the Togolese Republic, is a country located in West Africa. It is bordered by Ghana to the west, Benin to the east and Burkina Faso to the north. It is one of the least developed countries in the world. It extends north from the Gulf of Guinea to the Burkina Faso-Togo border. It is a small, tropical country, spanning 57,000 square kilometres with a population of approximately 8 million. It has a width of less than 115 km (71 mi) between Ghana and its eastern neighbour Benin.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/68/Flag_of_Togo.svg/330px-Flag_of_Togo.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Togo", "description": "Country in West Africa"}', '542fc5d4-f0d7-45a4-a1ba-82701a5e2a2a', NULL, 'TG', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:50.744977+01', NULL, NULL, '{togo,tg,africa,community,diaspora}', NULL, 'Africa', 'Western Africa', NULL);
INSERT INTO public.spaces VALUES ('3b542064-4060-4b58-a4c3-55b391dfa20d', NULL, '00000000-0000-0000-0000-000000000060', 'Portugal', 'portugal', 'It is set in Southwestern Europe, sharing borders with Spain, with Lisbon as its capital. From the streets of Lisbon to diaspora communities worldwide, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Portugal", "extract": "Portugal, officially the Portuguese Republic, is a country in Southwestern Europe. It is a unitary republic comprising mainland Portugal, located on the southwestern portion of the Iberian Peninsula and bordered by Spain to the north and east, and the archipelagos of Madeira and the Azores in the Atlantic Ocean. The country has a population of over 11.4 million, and Lisbon, its capital, is the largest city. Portugal''s internal waters and territorial sea together account for two-fifths of its territory, and its exclusive economic zone is one of Europe''s largest, while its terrain contains a diverse range of landscapes and regional climates.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/a8/Flag_of_Portugal_%28official%29.svg/330px-Flag_of_Portugal_%28official%29.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Portugal", "description": "Country in Southwestern Europe"}', '18de97a7-bf78-4317-adf3-60ccf7b7bdb8', NULL, 'PT', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:27.055562+01', NULL, 'EUR', '{portugal,pt,europe,community,diaspora}', NULL, 'Europe', 'Southern Europe', NULL);
INSERT INTO public.spaces VALUES ('bbaf3079-2e69-42f1-923e-924b5e48daca', NULL, '00000000-0000-0000-0000-000000000060', 'Qatar', 'qatar', 'From West Asia to cities and towns across the globe — this is the gathering point for a diaspora that never lost touch with home. It is set in West Asia, with Doha as its capital. Share local news, discover events, trade on the marketplace, and tap into remittance rates, scholarship finds, and community resources — all in one place.', '{"title": "Qatar", "extract": "Qatar, officially the State of Qatar, is a country in West Asia. It occupies the Qatar Peninsula on the northeastern coast of the Arabian Peninsula in the Middle East; it shares its sole land border with Saudi Arabia to the south, with the rest of its territory surrounded by the Persian Gulf. The Gulf of Bahrain, an inlet of the Persian Gulf, separates Qatar from nearby Bahrain. The capital is Doha, home to over 80% of the country''s inhabitants. Most of the land area is made up of flat, low-lying desert.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/65/Flag_of_Qatar.svg/330px-Flag_of_Qatar.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Qatar", "description": "Country in West Asia"}', '0fa99234-0dc8-42c1-a295-8adecb284009', NULL, 'QA', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:28.065621+01', NULL, NULL, '{qatar,qa,asia,community,diaspora}', NULL, 'Asia', 'Western Asia', NULL);
INSERT INTO public.spaces VALUES ('88f93306-da02-4afc-9e4d-0602be7ec28c', NULL, '00000000-0000-0000-0000-000000000064', 'State University of New York System', 'state-university-of-new-york-system', NULL, '{"title": "State University of New York", "extract": "The State University of New York is a system of public colleges and universities in the State of New York. Led by chancellor John B. King, the SUNY system has 87,956 employees, including 29,427 faculty members, and some 7,660 degree and certificate programs overall and a $13.37 billion budget.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/9/94/State_University_of_New_York_seal.svg/330px-State_University_of_New_York_seal.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/State_University_of_New_York", "description": "Public university system in New York state"}', '0770f743-9e7b-4579-9cbe-039a8773ff84', NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.233464+01', '2026-08-31 02:32:53.736187+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('798790fa-94bf-4ca9-b504-dd076cfad27c', NULL, '00000000-0000-0000-0000-000000000060', 'Saint Vincent and the Grenadines', 'saint-vincent-and-the-grenadines', 'An island in Caribbean, but its diaspora spans the globe — this space is the bridge between here and everywhere. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "Saint Vincent and the Grenadines", "extract": "Saint Vincent and the Grenadines, sometimes known simply as Saint Vincent, is an archipelagic country in the eastern Caribbean. It is located in the southeast Windward Islands of the Lesser Antilles, which lie in the West Indies, at the southern end of the eastern border between the Caribbean Sea and the Atlantic Ocean. To the north lies Saint Lucia, to the east is Barbados and Grenada lies to the south.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/6d/Flag_of_Saint_Vincent_and_the_Grenadines.svg/330px-Flag_of_Saint_Vincent_and_the_Grenadines.svg.png", "content_url": "https://en.wikipedia.org/wiki/Saint_Vincent_and_the_Grenadines", "description": "Archipelagic country in the Caribbean"}', '587db68c-baf9-4e71-b713-fbf083dcf583', NULL, 'VC', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:33.616347+01', NULL, NULL, '{"saint vincent and the grenadines",saint-vincent-and-the-grenadines,vc,caribbean,island,community,diaspora}', NULL, 'Americas', 'Caribbean', NULL);
INSERT INTO public.spaces VALUES ('c499b5f5-17a5-4101-bee1-d10f4e9bea69', NULL, '00000000-0000-0000-0000-000000000060', 'Slovakia', 'slovakia', 'Second largest city is Košice in Central Europe, shaped by mountainous terrain. It is set in Central Europe, landlocked, sharing borders with Poland, Ukraine, Hungary, and Austria, with Bratislava as its capital. From the streets of Bratislava to diaspora communities worldwide, this is your space to connect, trade, and stay rooted.', '{"title": "Slovakia", "extract": "Slovakia, officially the Slovak Republic, is a landlocked country in Central Europe. It is bordered by Poland to the north, Ukraine to the east, Hungary to the south, Austria to the west, and the Czech Republic to the northwest. Slovakia''s mostly mountainous territory spans about 49,000 km2 (19,000 sq mi), hosting a population exceeding 5.4 million. The capital and largest city is Bratislava, while the second largest city is Košice.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/e6/Flag_of_Slovakia.svg/330px-Flag_of_Slovakia.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Slovakia", "description": "Country in Central Europe"}', '09bc8eaa-1781-47e8-990b-6d7a31e71aea', NULL, 'SK', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:39.165379+01', NULL, 'EUR', '{slovakia,sk,europe,landlocked,community,diaspora}', NULL, 'Europe', 'Eastern Europe', NULL);
INSERT INTO public.spaces VALUES ('1d200f6e-65d9-4597-8a8a-0cc84756bb2d', NULL, '00000000-0000-0000-0000-000000000060', 'Uganda', 'uganda', 'Your digital anchor in East Africa — from Kampala to the farthest corners of the diaspora, everything flows through here. A land of an equatorial location, shaped by geography and history into something uniquely its own. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "Uganda", "extract": "Uganda, officially the Republic of Uganda, is a landlocked country in East Africa. It is bordered to the east by Kenya, to the north by South Sudan, to the west by the Democratic Republic of the Congo, to the south-west by Rwanda, and to the south by Tanzania. The southern part includes a substantial portion of Lake Victoria, shared with Kenya and Tanzania. Uganda is in the African Great Lakes region, lies within the Nile basin, and has a varied equatorial climate. As of 2024, it had a population of 45.9 million, of whom 1.8 million live in the capital and largest city, Kampala.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/4e/Flag_of_Uganda.svg/330px-Flag_of_Uganda.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Uganda", "description": "Country in East Africa"}', 'a74b6010-7b66-4a76-9f61-8879f23e8d2e', NULL, 'UG', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:55.278633+01', NULL, NULL, '{uganda,ug,africa,landlocked,community,diaspora}', NULL, 'Africa', 'Eastern Africa', NULL);
INSERT INTO public.spaces VALUES ('51ea5716-6610-4f67-bc1b-55e5cc46a49b', NULL, '00000000-0000-0000-0000-000000000060', 'Vatican City State (Holy See)', 'vatican-city-state-holy-see', 'Rooted here, reaching across continents — this space bridges home and diaspora. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "Vatican City", "extract": "Vatican City, officially the Vatican City State, often shortened as the Vatican, is a landlocked sovereign city-state in Southern Europe. Ruled by the pope, it is an enclave within the city of Rome, Italy, and serves as the administrative centre of the Catholic Church. Vatican City is governed by the See of Rome, commonly known as the Holy See, itself a sovereign entity under international law, which maintains its temporal power, governance, diplomacy, and spiritual independence. Vatican is also used as a metonym for the Holy See, which is the central governing body of the Catholic Church and Vatican City, comprising the pope and the Roman Curia. The independent state of Vatican City came into existence in 1929 via the Lateran Treaty between the Holy See and the Kingdom of Italy, which spoke of it as a creation, not as a vestige of the much larger Papal States (756–1870), which had previously encompassed much of Central Italy.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/b3/Flag_of_Vatican_City_%282023%E2%80%93present%29.svg/330px-Flag_of_Vatican_City_%282023%E2%80%93present%29.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Vatican_City", "description": "Enclaved Holy See''s independent city-state"}', '4fd8e861-a63c-48d7-a0ab-45d8fb7742d8', NULL, 'VA', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:59.822793+01', NULL, 'EUR', '{"vatican city state (holy see)",vatican-city-state-holy-see,va,landlocked,community,diaspora}', NULL, 'Europe', 'Southern Europe', NULL);
INSERT INTO public.spaces VALUES ('920f0260-e42b-47a7-bcb0-f0e4533d2cdb', NULL, '00000000-0000-0000-0000-000000000060', 'Northern Mariana Islands', 'northern-mariana-islands', 'Your digital anchor — wherever the diaspora has settled, this is home base. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "Northern Mariana Islands", "extract": "The Northern Mariana Islands, officially the Commonwealth of the Northern Mariana Islands (CNMI), is an unincorporated territory and commonwealth of the United States consisting of the 14 northern islands of the Mariana Archipelago in the northwestern Pacific Ocean. The southernmost, Guam, is a separate U.S. territory. The Northern Mariana Islands were listed by the United Nations as a non-self-governing territory until 1990.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/e0/Flag_of_the_Northern_Mariana_Islands.svg/330px-Flag_of_the_Northern_Mariana_Islands.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Northern_Mariana_Islands", "description": "U.S. territory in the Pacific Ocean"}', '076b9b0c-6087-4683-a9cc-a1016b429451', NULL, 'MP', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:19.490363+01', NULL, 'USD', '{"northern mariana islands",northern-mariana-islands,mp,pacific,island,community,diaspora}', NULL, 'Oceania', 'Micronesia', NULL);
INSERT INTO public.spaces VALUES ('73d5916a-809e-4e44-881e-a5200cdc0655', NULL, '00000000-0000-0000-0000-000000000060', 'Poland', 'poland', 'It is set in Central Europe, sharing borders with Lithuania and Russia, with Warsaw as its capital. From the streets of Warsaw to diaspora communities worldwide, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Poland", "extract": "Poland, officially the Republic of Poland, is a country in Central Europe. It extends from the Baltic Sea in the north to the Sudetes and Carpathian Mountains in the south, and borders Lithuania and Russia to the northeast; Belarus and Ukraine to the east; Slovakia and the Czech Republic to the south; and Germany to the west. The territory has a varied landscape, diverse ecosystems, and a temperate climate. Poland is composed of sixteen voivodeships and is the fifth most populous member state of the European Union (EU), with over 38 million people, and the fifth largest EU country by land area, covering 312,696 km2 (120,733 sq mi). The capital and largest city is Warsaw; other major cities include Kraków, Wrocław, Łódź, Poznań, and Gdańsk.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/1/12/Flag_of_Poland.svg/330px-Flag_of_Poland.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Poland", "description": "Country in Central Europe"}', '35dc9669-5e78-4900-8977-2f3dd011756b', NULL, 'PL', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:26.550217+01', NULL, NULL, '{poland,pl,europe,community,diaspora}', NULL, 'Europe', 'Eastern Europe', NULL);
INSERT INTO public.spaces VALUES ('29f25132-65f2-42d3-9bca-4ddf97c69973', NULL, '00000000-0000-0000-0000-000000000060', 'Zimbabwe', 'zimbabwe', 'Your digital anchor in Southeastern Africa — from Harare to the farthest corners of the diaspora, everything flows through here. A landlocked nation whose people have crossed every border to build lives abroad. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "Zimbabwe", "extract": "Zimbabwe, officially the Republic of Zimbabwe, is a landlocked country in Southeast Africa, between the Zambezi and Limpopo River, bordered by South Africa to the south, Botswana to the southwest, Zambia to the north, and Mozambique to the east. The capital and largest city is Harare, and the second largest is Bulawayo.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/6a/Flag_of_Zimbabwe.svg/330px-Flag_of_Zimbabwe.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Zimbabwe", "description": "Country in Southeastern Africa"}', 'b4edbd1c-a23f-474c-86f5-81979a495d47', NULL, 'ZW', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:46:04.380677+01', NULL, NULL, '{zimbabwe,zw,africa,landlocked,community,diaspora}', NULL, 'Africa', 'Eastern Africa', NULL);
INSERT INTO public.spaces VALUES ('4c2b5eba-c04a-4714-9a09-3962b15e3d3a', NULL, '00000000-0000-0000-0000-000000000060', 'Afghanistan', 'afghanistan', 'Every journey out of Central and South Asia carries a story — of ambition, of longing, of roots that stretch but never break. From mountainous terrain to the cities where the diaspora now lives, the connection to home runs deep. Discover local businesses, share news from home, find events near you, and build a network that spans borders — all on JapaConnect.', '{"title": "Afghanistan", "extract": "Afghanistan, officially the Islamic Emirate of Afghanistan, is a landlocked country located at the crossroads of Central and South Asia. It is bordered by Pakistan to the east and south, Iran to the west, Turkmenistan to the northwest, Uzbekistan to the north, Tajikistan to the northeast, and China to the northeast and east. Occupying 652,864 square kilometers (252,072 sq mi) of land, the country is predominantly mountainous with plains in the north and the southwest, which are separated by the Hindu Kush mountain range. Kabul is the country''s capital and largest city. Afghanistan''s population is estimated to be between 35 and 50 million.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/5c/Flag_of_the_Taliban.svg/330px-Flag_of_the_Taliban.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Afghanistan", "description": "Country in Central and South Asia"}', '90ea573b-63a2-45b4-99a8-5a18bf21fc4c', NULL, 'AF', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:43:58.210459+01', NULL, NULL, '{afghanistan,af,asia,landlocked,community,diaspora}', NULL, 'Asia', 'Southern Asia', NULL);
INSERT INTO public.spaces VALUES ('fcd13b10-89c9-49d4-908d-c8dab8ca46b2', NULL, '00000000-0000-0000-0000-000000000060', 'Albania', 'albania', 'From Southeast Europe to cities and towns across the globe — this is the gathering point for a diaspora that never lost touch with home. It is set in Southeast Europe, sharing borders with Montenegro, Kosovo, Macedonia, and Greece. Share local news, discover events, trade on the marketplace, and tap into remittance rates, scholarship finds, and community resources — all in one place.', '{"title": "Albania", "extract": "Albania, officially the Republic of Albania, is a country in Southeast Europe. It is located in the Balkans, on the Adriatic and Ionian Seas within the Mediterranean Sea, and shares land borders with Montenegro to the northwest, Kosovo to the northeast, North Macedonia to the east and Greece to the south. With an area of 28,748 km2 (11,100 sq mi), it has a varied range of climatic, geological, hydrological and morphological conditions. Albania''s landscapes range from rugged snow-capped mountains in the Albanian Alps and the Korab, Skanderbeg, Pindus and Ceraunian Mountains, to fertile lowland plains extending from the Adriatic and Ionian seacoasts. Tirana is the capital and largest city in the country, followed by Durrës, Vlorë, and Shkodër.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/36/Flag_of_Albania.svg/330px-Flag_of_Albania.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Albania", "description": "Country in Southeast Europe"}', '2e1333d1-61d3-4ebb-bc8f-5ae6f03d8d5e', NULL, 'AL', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:43:59.220313+01', NULL, NULL, '{albania,al,europe,community,diaspora}', NULL, 'Europe', 'Southern Europe', NULL);
INSERT INTO public.spaces VALUES ('ed846b64-4539-43cd-85b8-42255f221a2a', NULL, '00000000-0000-0000-0000-000000000060', 'Algeria', 'algeria', 'Rooted in North Africa, sharing borders with Tunisia, and reaching across continents — this space bridges home and diaspora. Algiers is the capital; a population of 47 million calls it home. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "Algeria", "extract": "Algeria, officially the People''s Democratic Republic of Algeria, is a country in the Maghreb region of North Africa. Spanning over 2,381,741 square kilometres (919,595 sq mi), it is the largest country in Africa and the tenth largest in the world. It is bordered to the northeast by Tunisia; to the east by Libya; to the southeast by Niger; to the southwest by Mali, Mauritania, and Western Sahara; to the west by Morocco; and to the north by the Mediterranean Sea. With a population of over 47 million, Algeria is the tenth-most populous country in Africa. Its capital and largest city is Algiers.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/77/Flag_of_Algeria.svg/330px-Flag_of_Algeria.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Algeria", "description": "Country in North Africa"}', '2e768004-0d82-44b9-b7fa-6101bc4ac9b3', NULL, 'DZ', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:00.304661+01', NULL, NULL, '{algeria,dz,africa,community,diaspora}', NULL, 'Africa', 'Northern Africa', NULL);
INSERT INTO public.spaces VALUES ('3561e7ea-e7ee-4395-b1a0-14871196fdff', NULL, '00000000-0000-0000-0000-000000000060', 'Bangladesh', 'bangladesh', 'It is set in South Asia, sharing borders with India and Myanmar. Whether you''re still in South Asia or building a life elsewhere, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Bangladesh", "extract": "Bangladesh, officially the People''s Republic of Bangladesh, is a country in South Asia. It is the eighth-most populous country in the world and among the most densely populated with a population of almost 176 million within an area of 148,461 square kilometres (57,321 sq mi). Bangladesh shares land borders with India to the north, west, and east, and Myanmar to the southeast. It has a coastline along the Bay of Bengal to its south and is separated from Bhutan and Nepal by the Siliguri Corridor, and from China by the Indian state of Sikkim to its north. Dhaka, the capital and largest city, is the nation''s political, financial, and cultural centre. Chittagong is the second-largest city and the busiest port of the country.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/f9/Flag_of_Bangladesh.svg/330px-Flag_of_Bangladesh.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Bangladesh", "description": "Country in South Asia"}', '9ece018f-ea63-4cc3-ac3c-a3580337d2e5', NULL, 'BD', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:07.368992+01', NULL, NULL, '{bangladesh,bd,asia,community,diaspora}', NULL, 'Asia', 'Southern Asia', NULL);
INSERT INTO public.spaces VALUES ('e822aa47-9ae8-40dd-89a0-5885f8cf54e5', NULL, '00000000-0000-0000-0000-000000000060', 'Belgium', 'belgium', 'Every journey out of Northwestern Europe carries a story — of ambition, of longing, of roots that stretch but never break. Discover local businesses, share news from home, find events near you, and build a network that spans borders — all on JapaConnect.', '{"title": "Belgium", "extract": "Belgium, officially the Kingdom of Belgium, is a country in Northwestern Europe. Situated in a coastal lowland region known as the Low Countries, it is bordered by the Netherlands to the north, Germany to the east, Luxembourg to the southeast, France to the south, and the North Sea to the west. Belgium covers an area of 30,689 km2 (11,849 sq mi) and has a population of more than 11.8 million; its population density of 383/km2 (990/sq mi) ranks 22nd in the world and sixth in Europe. The capital and largest metropolitan region is Brussels; other major cities are Antwerp, Ghent, Charleroi, Liège, Bruges, Namur, and Leuven.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/65/Flag_of_Belgium.svg/330px-Flag_of_Belgium.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Belgium", "description": "Country in Northwestern Europe"}', '2af980c5-02f7-44c0-b112-a946cf39567a', NULL, 'BE', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:08.883889+01', NULL, 'EUR', '{belgium,be,europe,community,diaspora}', NULL, 'Europe', 'Western Europe', NULL);
INSERT INTO public.spaces VALUES ('24dd6cea-d011-48d5-a808-8069128f8416', NULL, '00000000-0000-0000-0000-000000000060', 'Burkina Faso', 'burkina-faso', 'It is set in West Africa, landlocked, sharing borders with Mali, Niger, Benin, and Togo, with Ouagadougou as its capital. From the streets of Ouagadougou to diaspora communities worldwide, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Burkina Faso", "extract": "Burkina Faso is a landlocked country in West Africa. It is bordered by Mali to the northwest, Niger to the northeast, Benin to the southeast, Togo and Ghana to the south, and Ivory Coast to the southwest. It covers an area of 274,223 km2 (105,878 sq mi). In 2024, the country had an estimated population of approximately 23,286,000. Its citizens are known as Burkinabes, and its capital and largest city is Ouagadougou.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/31/Flag_of_Burkina_Faso.svg/330px-Flag_of_Burkina_Faso.svg.png", "content_url": "https://en.wikipedia.org/wiki/Burkina_Faso", "description": "Country in West Africa"}', '4d3fc628-e7a3-4454-95fa-67ea165a1c0b', NULL, 'BF', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:15.948337+01', NULL, NULL, '{"burkina faso",burkina-faso,bf,africa,landlocked,community,diaspora}', NULL, 'Africa', 'Western Africa', NULL);
INSERT INTO public.spaces VALUES ('72173298-214b-43ff-9657-b9224de42da2', NULL, '00000000-0000-0000-0000-000000000060', 'Benin', 'benin', 'Your digital anchor in West Africa — from Porto-Novo to the farthest corners of the diaspora, everything flows through here. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "Benin", "extract": "Benin, officially the Republic of Benin, formerly known as Dahomey, is a country in West Africa. It is bordered by Togo to the west, Nigeria to the east, Burkina Faso to the northwest, and Niger to the northeast. The majority of its population lives on the southern coastline of the Bight of Benin, part of the Gulf of Guinea in the northernmost tropical portion of the Atlantic Ocean. The capital is Porto-Novo, and the seat of government is in Cotonou, the most populous city and economic capital. Benin covers an area of 112,622 km2 (43,484 sq mi), and its population in 2026 was estimated to be approximately 15 million. It is a tropical country with an economy heavily dependent on agriculture and the exports of palm oil and cotton.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/0a/Flag_of_Benin.svg/330px-Flag_of_Benin.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Benin", "description": "Country in West Africa"}', 'c22e3791-1444-4813-ae10-9676f9760962', NULL, 'BJ', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:09.890585+01', NULL, NULL, '{benin,bj,africa,community,diaspora}', NULL, 'Africa', 'Western Africa', NULL);
INSERT INTO public.spaces VALUES ('52515423-810f-4bab-ae44-354358b6c9b9', NULL, '00000000-0000-0000-0000-000000000060', 'Dominica', 'dominica', 'Every journey out of Caribbean carries a story — of ambition, of longing, of roots that stretch but never break. From the capital, Roseau, to the cities where the diaspora now lives, the connection to home runs deep. Discover local businesses, share news from home, find events near you, and build a network that spans borders — all on JapaConnect.', '{"title": "Dominica", "extract": "Dominica, officially the Commonwealth of Dominica, is an island country in the Caribbean. It is part of the Windward Islands chain in the Lesser Antilles archipelago in the Caribbean Sea. The capital, Roseau, is located on the western side of the island. Dominica''s closest neighbours are two constituent territories of the European Union, both overseas departments of France: Guadeloupe to the northwest and Martinique to the south-southeast. Dominica comprises a land area of 750 km2 (290 sq mi), and the highest point is Morne Diablotins, at 1,448 m (4,751 ft) in elevation. The population was 71,293 at the 2011 census.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/c4/Flag_of_Dominica.svg/330px-Flag_of_Dominica.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Dominica", "description": "Country in the Caribbean"}', '8d5ac65e-4d36-4574-92f7-6f9fa1d896eb', NULL, 'DM', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:29.063267+01', NULL, NULL, '{dominica,dm,caribbean,island,community,diaspora}', NULL, 'Americas', 'Caribbean', NULL);
INSERT INTO public.spaces VALUES ('26403135-8449-41f5-87ea-75cd6906d1b1', NULL, '00000000-0000-0000-0000-000000000060', 'Dominican Republic', 'dominican-republic', 'An island in Caribbean, but its diaspora spans the globe — this space is the bridge between here and everywhere. A population of after Haiti with approximately 11 calls it home. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "Dominican Republic", "extract": "The Dominican Republic is an island country on the eastern part of the Caribbean island of Hispaniola in the Greater Antilles of the Caribbean Sea in the North Atlantic Ocean. It shares a maritime border with Puerto Rico to the east and a land border with Haiti to the west, occupying the eastern five-eighths of Hispaniola which, along with Saint Martin, is one of only two islands in the Caribbean shared by two sovereign states. In the Antilles, the country is the second-largest country by area after Cuba at 48,671 square kilometers (18,792 sq mi) and the second most populous country after Haiti with approximately 11.4 million people in 2024, of whom 3.6 million reside in the metropolitan area of Santo Domingo, the capital city.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/9f/Flag_of_the_Dominican_Republic.svg/330px-Flag_of_the_Dominican_Republic.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Dominican_Republic", "description": "Island country in the Caribbean"}', '578b838a-4c83-4c88-bf95-06223c432f4a', NULL, 'DO', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:29.56675+01', NULL, NULL, '{"dominican republic",dominican-republic,do,caribbean,island,community,diaspora}', NULL, 'Americas', 'Caribbean', NULL);
INSERT INTO public.spaces VALUES ('8e5bbc94-2c09-429b-a15b-20730ef9b86a', NULL, '00000000-0000-0000-0000-000000000060', 'Iran', 'iran', 'Every journey out of West Asia carries a story — of ambition, of longing, of roots that stretch but never break. Discover local businesses, share news from home, find events near you, and build a network that spans borders — all on JapaConnect.', '{"title": "Iran", "extract": "Iran, officially the Islamic Republic of Iran, historically known as Persia, is a country in West Asia. It borders Iraq to the west, Turkey, Azerbaijan, and Armenia to the northwest, the Caspian Sea to the north, Turkmenistan to the northeast, Afghanistan to the east, Pakistan to the southeast, and the Gulf of Oman and the Persian Gulf to the south. With a population of over 92 million, Iran ranks 17th globally in both geographic size and population. It is divided into five regions with 31 provinces. Tehran is the nation''s capital and largest city and serves as its primary economic center.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/be/Flag_of_Iran_%28official%29.svg/330px-Flag_of_Iran_%28official%29.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Iran", "description": "Country in West Asia"}', '37ee419d-e4dc-44fd-a133-1be01cba4406', NULL, 'IR', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:49.730739+01', NULL, NULL, '{iran,ir,asia,community,diaspora}', NULL, 'Asia', 'Southern Asia', NULL);
INSERT INTO public.spaces VALUES ('0b72219b-4be6-4cf2-bd0d-d42b249a0ccc', NULL, '00000000-0000-0000-0000-000000000060', 'New Caledonia', 'new-caledonia', 'It is set in southwest Pacific Ocean. Whether you''re still in southwest Pacific Ocean or building a life elsewhere, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "New Caledonia", "extract": "New Caledonia is a French territory consisting of a group of islands in the southwest Pacific Ocean, 220 km (140 mi) southwest of Vanuatu and 1,210 km (750 mi) east of Australia. Located 16,100 km (10,000 mi) from Metropolitan France, it forms a sui generis collectivity of the French Republic, having a unique legal status enshrined in a dedicated chapter of the French Constitution.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/c1/New_Caledonia_in_France_%28zoomed%29.svg/330px-New_Caledonia_in_France_%28zoomed%29.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/New_Caledonia", "description": "French territory in the southwest Pacific Ocean"}', 'fdb76a18-cf72-4c68-8d3e-74540d5a8646', NULL, 'NC', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:15.958273+01', NULL, NULL, '{"new caledonia",new-caledonia,nc,pacific,island,community,diaspora}', NULL, 'Oceania', 'Melanesia', NULL);
INSERT INTO public.spaces VALUES ('4772734f-3aa9-4111-ace0-5b32d1d29815', NULL, '00000000-0000-0000-0000-000000000060', 'Kuwait', 'kuwait', 'Every journey out of West Asia carries a story — of ambition, of longing, of roots that stretch but never break. Discover local businesses, share news from home, find events near you, and build a network that spans borders — all on JapaConnect.', '{"title": "Kuwait", "extract": "Kuwait, officially the State of Kuwait, is a country in West Asia. With a coastline of approximately 500 km (311 mi), it is situated at the head of the Persian Gulf in the northeastern edge of the Arabian Peninsula, bordering Iraq to the north and Saudi Arabia to the south. Kuwait is geographically the second closest Gulf country to mainland Iran after Iraq. The country is a small city-state; most of the population reside in the urban agglomeration of Kuwait City, the capital and largest city. As of 2024, Kuwait has a population of 4.82 million, of which 1.53 million are Kuwaiti citizens while the remaining 3.29 million are foreign nationals from over 100 countries. In 2024, Kuwait had the world''s seventh largest number of foreign nationals as a percentage of the population, where its citizens make up fewer than 30% of the overall population.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/aa/Flag_of_Kuwait.svg/330px-Flag_of_Kuwait.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Kuwait", "description": "Country in West Asia"}', '26ec0fe7-ac41-4054-a3cc-298b4bbbc579', NULL, 'KW', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:56.79174+01', NULL, NULL, '{kuwait,kw,asia,community,diaspora}', NULL, 'Asia', 'Western Asia', NULL);
INSERT INTO public.spaces VALUES ('27db4ac3-c401-476e-9202-64de61de1de5', NULL, '00000000-0000-0000-0000-000000000060', 'Estonia', 'estonia', 'Rooted in Northern Europe, sharing borders with Finland, Sweden, Latvia, and Russia, and reaching across continents — this space bridges home and diaspora. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "Estonia", "extract": "Estonia, officially the Republic of Estonia, is a country in the Baltic region of Northern Europe. It is bordered to the north by the Gulf of Finland across from Finland, to the west by the Baltic Sea across from Sweden, to the south by Latvia, and to the east by Russia. The territory of Estonia consists of the mainland, the larger islands of Saaremaa and Hiiumaa, and over 2,300 other islands and islets on the east coast of the Baltic Sea. Its capital city of Tallinn, along with the city of Tartu, are the country''s two largest urban areas. The Estonian language, of the Finnic family, is the official language and the first language of the majority of nearly 1.4 million people. Estonia is one of the least populous member states of the European Union.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/8f/Flag_of_Estonia.svg/330px-Flag_of_Estonia.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Estonia", "description": "Country in Northern Europe"}', 'fdbbcfdd-f68d-41dd-b43e-d76601df406e', NULL, 'EE', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:32.593494+01', NULL, 'EUR', '{estonia,ee,europe,island,community,diaspora}', NULL, 'Europe', 'Northern Europe', NULL);
INSERT INTO public.spaces VALUES ('0180251b-d80f-46de-9e6b-31dfbbaaafb9', NULL, '00000000-0000-0000-0000-000000000060', 'Nepal', 'nepal', 'It is set in South Asia, landlocked, sharing borders with Tibet Autonomous Region, China, India, and Bangladesh. Whether you''re still in South Asia or building a life elsewhere, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Nepal", "extract": "Nepal, officially the Federal Democratic Republic of Nepal, is a landlocked country in South Asia. It is mainly situated in the Himalayas, but also includes parts of the Indo-Gangetic Plain. It borders the Tibet Autonomous Region of China to the north, and India to the south, east, and west, while it is narrowly separated from Bangladesh by the Siliguri Corridor, and from Bhutan by the Indian state of Sikkim. Nepal has a diverse geography, including fertile plains, subalpine forested hills, and eight of the world''s ten highest mountains, including Mount Everest, the highest point above mean sea level on Earth. Kathmandu is the nation''s capital and its largest city. Nepal is a multi-ethnic, multi-lingual, multi-religious, and multi-cultural sovereign state, with Nepali as the official language.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/23/Emblem_of_Nepal.svg/330px-Emblem_of_Nepal.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Nepal", "description": "Country in South Asia"}', '639100bb-6acf-4527-90e4-112cd4257080', NULL, 'NP', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:14.949024+01', NULL, NULL, '{nepal,np,asia,landlocked,community,diaspora}', NULL, 'Asia', 'Southern Asia', NULL);
INSERT INTO public.spaces VALUES ('c5ea7339-5f63-49ed-85cb-ba50ef6c927c', NULL, '00000000-0000-0000-0000-000000000060', 'San Marino', 'san-marino', 'Smallest country in the world in Southern Europe,. It is set in Southern Europe, landlocked. Whether you''re still in Southern Europe or building a life elsewhere, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "San Marino", "extract": "San Marino, officially the Republic of San Marino (RSM), is a landlocked country in Southern Europe, completely surrounded by Italy. Located on the northeastern slopes of the Apennine Mountains, it is the larger of two microstates within the Italian Peninsula, the other being Vatican City. San Marino is the fifth-smallest country in the world, with a land area of just over 61 square kilometres (24 sq mi) and a population of 34,042 as of 2025. Its capital, the City of San Marino, sits atop Monte Titano, while its largest settlement is Dogana, in the municipality of Serravalle.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/b1/Flag_of_San_Marino.svg/330px-Flag_of_San_Marino.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/San_Marino", "description": "Microstate in Southern Europe"}', 'f4ea412d-06d9-4214-a364-7d104d7be57d', NULL, 'SM', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:34.625425+01', NULL, 'EUR', '{"san marino",san-marino,sm,europe,landlocked,community,diaspora}', NULL, 'Europe', 'Southern Europe', NULL);
INSERT INTO public.spaces VALUES ('8563db64-657e-4aad-9005-2c8169c14cdc', NULL, '00000000-0000-0000-0000-000000000064', 'Hallym University', 'hallym-university', NULL, '{"name": "Hallym University", "country": "Q884", "founded": "+1982-00-00T00:00:00Z", "website": "http://www.hallym.ac.kr", "description": "university in Chuncheon, South Korea", "wikidata_id": "Q482724", "wikipedia_url": "https://en.wikipedia.org/wiki/Q482724"}', NULL, NULL, 'KR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.5184+01', '2026-08-27 06:03:32.944359+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('30543cc7-eca8-4f0f-8a83-63de3fb0e17f', NULL, '00000000-0000-0000-0000-000000000060', 'Turkey', 'turkey', 'Every journey out of Southeastern Europe and West Asia carries a story — of ambition, of longing, of roots that stretch but never break. Discover local businesses, share news from home, find events near you, and build a network that spans borders — all on JapaConnect.', '{"title": "Turkey", "extract": "Turkey, officially the Republic of Türkiye, is a country mainly located in Anatolia in West Asia, with a smaller part called East Thrace in Southeast Europe. It borders the Black Sea to the north; Georgia, Armenia, Azerbaijan, and Iran to the east; Iraq, Syria, and the Mediterranean Sea to the south; and the Aegean Sea, Greece, and Bulgaria to the west. Turkey is home to over 86 million people; most are ethnic Turks, while Kurds are the largest ethnic minority. Officially a secular state, Turkey has a Muslim-majority population. Ankara is Turkey''s capital and second-largest city. Istanbul is its largest city and economic center. Other major cities include İzmir, Bursa, and Antalya.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/b4/Flag_of_Turkey.svg/330px-Flag_of_Turkey.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Turkey", "description": "Country in Southeastern Europe and West Asia"}', '8046c61d-b141-49d9-add7-0256cf2f6324', NULL, 'TR', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:53.263466+01', NULL, NULL, '{turkey,tr,europe,community,diaspora}', NULL, 'Asia', 'Western Asia', NULL);
INSERT INTO public.spaces VALUES ('58d6191c-0845-446e-a84b-dd88bfbd065b', NULL, '00000000-0000-0000-0000-000000000060', 'Virgin Islands (US)', 'virgin-islands-us', 'Every journey out of Caribbean carries a story — of ambition, of longing, of roots that stretch but never break. Discover local businesses, share news from home, find events near you, and build a network that spans borders — all on JapaConnect.', '{"title": "United States Virgin Islands", "extract": "The United States Virgin Islands, officially the Virgin Islands of the United States, is a Caribbean unincorporated territory of the United States. The islands are geographically part of the Virgin Islands archipelago and are located in the Leeward Islands of the Lesser Antilles. The islands have a tropical climate.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/f8/Flag_of_the_United_States_Virgin_Islands.svg/330px-Flag_of_the_United_States_Virgin_Islands.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/United_States_Virgin_Islands", "description": "U.S. territory in the Caribbean"}', 'b3d740a1-4c3d-4699-a112-f0c5d8974d2a', NULL, 'VI', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:46:01.855842+01', NULL, 'USD', '{"virgin islands (us)",virgin-islands-us,vi,caribbean,island,community,diaspora}', NULL, 'Americas', 'Caribbean', NULL);
