INSERT INTO public.spaces VALUES ('b20a371e-57c6-4a4c-9dac-792db1dcaec2', NULL, '00000000-0000-0000-0000-000000000060', 'Yemen', 'yemen', 'From West Asia to cities and towns across the globe — this is the gathering point for a diaspora that never lost touch with home. It is set in West Asia, sharing borders with Saudi Arabia, Oman, and Aden. Share local news, discover events, trade on the marketplace, and tap into remittance rates, scholarship finds, and community resources — all in one place.', '{"title": "Yemen", "extract": "Yemen, officially the Republic of Yemen, is a country in West Asia. Located in southern Arabia, the country includes the Socotra Archipelago and borders Saudi Arabia to the north, Oman to the northeast, the Arabian Sea to the east, the Gulf of Aden to the south, and the Red Sea to the west. It also shares maritime borders with Djibouti, Eritrea, and Somalia across the Horn of Africa. Covering 455,503 square kilometres (175,871 sq mi), with a coastline of approximately 2,000 kilometres (1,200 mi), Yemen is the second-largest country on the Arabian Peninsula by area and the second-largest by population. Sanaa is its constitutional capital and largest city. Yemen''s population is estimated at 34.7 million, predominantly Arab Muslims.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/89/Flag_of_Yemen.svg/330px-Flag_of_Yemen.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Yemen", "description": "Country in West Asia"}', '6f6519bf-d3dd-4b4d-80bc-cdafdd03408e', NULL, 'YE', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:46:03.374211+01', NULL, NULL, '{yemen,ye,asia,community,diaspora}', NULL, 'Asia', 'Western Asia', NULL);
INSERT INTO public.spaces VALUES ('0091864e-50e0-4a7a-8b41-e04604c33b0a', NULL, '00000000-0000-0000-0000-000000000060', 'China', 'china', 'Rooted in East Asia, reaching across continents — this space bridges home and diaspora. A population of after India calls it home. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "China", "extract": "China, officially the People''s Republic of China (PRC), is a country in East Asia. It is divided into 33 province-level divisions, including two special administrative regions. Beijing is the capital, while Shanghai is the most populous city by urban area. Its geography features the Central Plain, major rivers such as the Yangtze and Yellow River, deserts, subtropical and temperate forests, plateaus, and mountain ranges such as the Himalayas. It is the world''s second-most populous country after India, with a population exceeding 1.4 billion, across an area of 9.6 million square kilometers (3,700,000 sq mi), making it the third-largest country by area.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/fa/Flag_of_the_People%27s_Republic_of_China.svg/330px-Flag_of_the_People%27s_Republic_of_China.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/China", "description": "Country in East Asia"}', 'd7480ab8-b1fd-47ce-bf7b-70887146204f', NULL, 'CN', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:20.98721+01', NULL, NULL, '{china,cn,asia,community,diaspora}', NULL, 'Asia', 'Eastern Asia', NULL);
INSERT INTO public.spaces VALUES ('2e61ed5d-f1a0-4752-b994-731c0d4a34dd', NULL, '00000000-0000-0000-0000-000000000060', 'Argentina', 'argentina', 'Second-largest country in South America after Brazil in South America,. It is set in South America, sharing borders with Bolivia, Paraguay, Brazil, and Uruguay. Whether you''re still in South America or building a life elsewhere, this is your space to connect, trade, and stay rooted.', '{"title": "Argentina", "extract": "Argentina, officially the Argentine Republic, is a country in the Southern Cone of South America. It covers an area of 2,780,085 km2 (1,073,397 mi2), making it the second-largest country in South America after Brazil, the fourth-largest country in the Americas, and the eighth-largest country in the world. Argentina shares the bulk of the Southern Cone with Chile to the west, and is also bordered by Bolivia and Paraguay to the north, Brazil to the northeast, Uruguay and the South Atlantic Ocean to the east, and the Drake Passage to the south. Argentina is a federal state subdivided into twenty-three provinces, and one autonomous city, which is the federal capital and largest city of the nation, Buenos Aires. The provinces and the capital have their own constitutions, but exist under a federal system. Argentina claims sovereignty over the Falkland Islands, South Georgia and the South Sandwich Islands, the Southern Patagonian Ice Field, and a part of Antarctica.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/1a/Flag_of_Argentina.svg/330px-Flag_of_Argentina.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Argentina", "description": "Country in South America"}', 'ccd8296b-c529-4be0-b091-2e2a89f18cb6', NULL, 'AR', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:03.83456+01', NULL, NULL, '{argentina,ar,"south america",island,community,diaspora}', NULL, 'Americas', 'South America', NULL);
INSERT INTO public.spaces VALUES ('9a5aa27e-8323-43e0-a092-6a1c6fc853c4', NULL, '00000000-0000-0000-0000-000000000060', 'Cape Verde', 'cape-verde', 'It is set in West Africa, an island nation. Whether you''re still in West Africa or building a life elsewhere, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Cape Verde", "extract": "Cape Verde, also referred to in English by its Portuguese name Cabo Verde, and known officially as the Republic of Cabo Verde, is an archipelagic country in the eastern Atlantic Ocean, off the coast of West Africa. It consists of ten volcanic islands with a combined land area of about 4,033 square kilometres (1,557 sq mi). These islands lie between 600 and 850 kilometres west of Cap-Vert, the westernmost point of continental Africa, after which they are named. Cape Verde forms part of the Macaronesia ecoregion, along with the Azores, the Canary Islands, Madeira and the Savage Islands. It is also the largest country off-continental Africa.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/7a/Flag_of_Cape_Verde_%283-2%29.svg/330px-Flag_of_Cape_Verde_%283-2%29.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Cape_Verde", "description": "Island country in West Africa"}', '09c2c03d-af75-43bf-a1dd-c29ba963bc9f', NULL, 'CV', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:18.469291+01', NULL, NULL, '{"cape verde",cape-verde,cv,africa,island,community,diaspora}', NULL, 'Africa', 'Western Africa', NULL);
INSERT INTO public.spaces VALUES ('566445ee-b4fa-48bb-b533-4e12bd43cf4d', NULL, '00000000-0000-0000-0000-000000000064', 'University of Puget Sound', 'university-of-puget-sound', NULL, '{"logo": "http://commons.wikimedia.org/wiki/Special:FilePath/Puget%20sound%20textlogo.png", "name": "University of Puget Sound", "image": "http://commons.wikimedia.org/wiki/Special:FilePath/UPS%20-%20Langdon%2C%20Harrington%2C%20&%20Schiff%20Halls%2001.jpg", "country": "Q30", "founded": "+1888-00-00T00:00:00Z", "website": "https://www.pugetsound.edu/", "students": "+2130", "description": "university in the US state of Washington", "wikidata_id": "Q956780", "wikipedia_url": "https://en.wikipedia.org/wiki/Q956780"}', 'f82c04d2-79e1-446c-a72a-60df9c479cdf', NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.262718+01', '2026-08-09 20:37:14.305192+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('51a3ef7e-df33-4cc8-b8a7-1b5e25493789', NULL, '00000000-0000-0000-0000-000000000060', 'France', 'france', 'It is set in Western Europe, sharing borders with Belgium, Luxembourg, Germany, and Switzerland. Whether you''re still in Western Europe or building a life elsewhere, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "France", "extract": "France, officially the French Republic, is a country primarily located in Western Europe. Its overseas regions and territories include French Guiana in South America, Saint Pierre and Miquelon in the North Atlantic, the French West Indies, and many islands in Oceania and the Indian Ocean. Metropolitan France shares borders with Belgium and Luxembourg to the north, Germany to the northeast, Switzerland to the east, Italy and Monaco to the southeast, Andorra and Spain to the south, and a maritime border with the United Kingdom to the northwest. Its metropolitan area extends from the Rhine to the Atlantic Ocean and from the Mediterranean Sea to the English Channel and the North Sea. Its 18 integral regions—five of which are overseas—span a combined area of 632,702 km2 (244,288 sq mi), with a total population estimated at over 69.1 million in 2026. Its capital, largest city and main cultural and economic centre is Paris, with a metropolitan population of over 13 million.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/c/c3/Flag_of_France.svg/330px-Flag_of_France.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/France", "description": "Country primarily in Western Europe"}', '1e74bf4d-1f56-4b04-a3c2-0e95c592962c', NULL, 'FR', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-07-08 23:07:05.600578+01', '2026-08-07 11:44:36.116534+01', NULL, 'EUR', '{france,fr,europe,island,community,diaspora}', NULL, 'Europe', 'Western Europe', NULL);
INSERT INTO public.spaces VALUES ('5a5ed8e1-ffe3-45c0-90a8-e576022d7d1b', NULL, '00000000-0000-0000-0000-000000000060', 'Japan', 'japan', 'An island nation in East Asia with a diaspora scattered across every continent — this space brings them all back to one table. It is set in East Asia, an island nation. Share local news, discover events, trade on the marketplace, and tap into remittance rates, scholarship finds, and community resources — all in one place.', '{"title": "Japan", "extract": "Japan is an island country in East Asia. Located in the Pacific Ocean off the northeast coast of the Asian mainland, it is bordered to the west by the Sea of Japan, the Sea of Okhotsk in the north, and the East China Sea in the south. The Japanese archipelago consists of four major islands alongside over 14,000 smaller islands. Japan is divided into 47 administrative prefectures and eight traditional regions, and around 75% of its terrain is mountainous and heavily forested, concentrating its agriculture and highly urbanized population along its eastern coastal plains. With a population of almost 123 million as of 2026, it is the world''s 11th most populous country. Tokyo is the country''s capital and largest city.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/9/9e/Flag_of_Japan.svg/330px-Flag_of_Japan.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Japan", "description": "Country in East Asia"}', '638bb44f-203f-4d5a-8d42-dae33e3c04da', NULL, 'JP', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:53.260627+01', NULL, NULL, '{japan,jp,asia,island,community,diaspora}', NULL, 'Asia', 'Eastern Asia', NULL);
INSERT INTO public.spaces VALUES ('5bd2b5c2-cd67-4a46-a9e9-f74924464759', NULL, '00000000-0000-0000-0000-000000000064', 'Hitec University', 'hitec-university', NULL, '{"name": "HITEC University", "country": "Q843", "founded": "+2007-00-00T00:00:00Z", "website": "https://www.hitecuni.edu.pk/", "description": "private university in Rawalpindi, Pakistan", "wikidata_id": "Q5629800", "wikipedia_url": "https://en.wikipedia.org/wiki/Q5629800"}', NULL, NULL, 'PK', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.573335+01', '2026-08-27 05:56:55.326124+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
