INSERT INTO public.spaces VALUES ('b827160e-4009-40dc-9287-b6f056712fed', NULL, '00000000-0000-0000-0000-000000000060', 'Kiribati', 'kiribati', 'An island nation in central Pacific with a diaspora scattered across every continent — this space brings them all back to one table. It is set in central Pacific, an island nation. Share local news, discover events, trade on the marketplace, and tap into remittance rates, scholarship finds, and community resources — all in one place.', '{"title": "Kiribati", "extract": "Kiribati, officially the Republic of Kiribati, is an archipelagic country spanning the Micronesia and Polynesia sub-regions of Oceania in the central Pacific Ocean. The state comprises 32 atolls and other islands and one remote raised coral island, Banaba. Its total land area is 811 km2 (313 sq mi) dispersed over 3,441,810 km2 (1,328,890 sq mi) of ocean. The spread of the country''s islands, from Banaba in the west to Kiritimati in the east straddles the equator and the 180th meridian. The International Date Line goes around Kiribati and swings far to the east, almost reaching 150°W. This brings Kiribati''s easternmost islands, the southern Line Islands south of Hawaii, into the same day as the Gilbert Islands and places them in the most advanced time zone on Earth: UTC+14.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d3/Flag_of_Kiribati.svg/330px-Flag_of_Kiribati.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Kiribati", "description": "Island country in the central Pacific"}', 'ef4dfe2e-2e5f-4e48-b2a9-6a4f045db24c', NULL, 'KI', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:55.784536+01', NULL, NULL, '{kiribati,ki,pacific,island,community,diaspora}', NULL, 'Oceania', 'Micronesia', NULL);
INSERT INTO public.spaces VALUES ('eef67a58-a5b2-4148-9197-ab435b411d8e', NULL, '00000000-0000-0000-0000-000000000060', 'Lesotho', 'lesotho', 'Every journey out of Southern Africa carries a story — of ambition, of longing, of roots that stretch but never break. From the capital, Maseru, to the cities where the diaspora now lives, the connection to home runs deep. Discover local businesses, share news from home, find events near you, and build a network that spans borders — all on JapaConnect.', '{"title": "Lesotho", "extract": "Lesotho, officially the Kingdom of Lesotho, is a landlocked country in Southern Africa. Surrounded by South Africa, it is the largest of the only three sovereign enclaves. Lesotho is located in the Maloti Mountains, with the highest peak in southern Africa. It has an area of over 30,000 km2 (11,600 mi2), with a population of about 2.3 million. Its capital and largest city is Maseru.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/4a/Flag_of_Lesotho.svg/330px-Flag_of_Lesotho.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Lesotho", "description": "Country in Southern Africa"}', '399c388e-073f-4992-87e7-a20d441e528e', NULL, 'LS', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:59.310594+01', NULL, NULL, '{lesotho,ls,africa,landlocked,community,diaspora}', NULL, 'Africa', 'Southern Africa', NULL);
INSERT INTO public.spaces VALUES ('3ed7feb3-31b6-471a-81f2-98794e1e63b7', NULL, '00000000-0000-0000-0000-000000000060', 'Macau S.A.R.', 'macau-sar', 'Your digital anchor — wherever the diaspora has settled, this is home base. Home to about 720 people, with communities spread far beyond its borders. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "Macau", "extract": "Macau or Macao is a special administrative region of China. It consists of the Macau Peninsula, the islands of Taipa and Coloane, the Cotai reclamation zone between Taipa and Coloane, and several smaller islets. It borders Zhuhai to the north and west, and it lies west of Hong Kong, separated by the Pearl River estuary. With a population of about 720,000 people and a land area of 32.9 square kilometres (12.7 sq mi), it is the most densely populated region in the world.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/63/Flag_of_Macau.svg/330px-Flag_of_Macau.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Macau", "description": "Special administrative region of China"}', '23f3e9f7-420e-4381-89b7-dc5de789b46c', NULL, 'MO', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:02.340359+01', NULL, NULL, '{"macau s.a.r.",macau-sar,mo,island,community,diaspora}', NULL, 'Asia', 'Eastern Asia', NULL);
INSERT INTO public.spaces VALUES ('ddc7a7ab-e1d1-4f95-a3ec-4ecbdf0c0cab', NULL, '00000000-0000-0000-0000-000000000060', 'Monaco', 'monaco', 'Landlocked in Western Europe but connected to the world — this is where the diaspora gathers, no matter how far they''ve traveled. It is set in Western Europe, landlocked, sharing borders with France. Share local news, discover events, trade on the marketplace, and tap into remittance rates, scholarship finds, and community resources — all in one place.', '{"title": "Monaco", "extract": "Monaco, officially the Principality of Monaco, is a sovereign city-state and microstate in Western Europe. Situated on the French Riviera, it is a semi-enclave bordered by France to the north, east, and west, with the Mediterranean Sea to the south; the Italian region of Liguria is about 15 km (9.3 mi) east. With a population of 38,423 living in an area of 2.08 km2 (0.80 sq mi), Monaco is the second smallest sovereign state in the world, after Vatican City, as well as the most densely populated. It also has the world''s shortest national coastline of any non-landlocked nation, at 3.83 km (2.38 mi). Fewer than 10,000 of its residents are Monégasque nationals. Although French is the official language of Monaco, Italian and Monégasque are also widely spoken and understood.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/ea/Flag_of_Monaco.svg/330px-Flag_of_Monaco.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Monaco", "description": "Microstate in Western Europe"}', '69884f19-4342-499b-b475-ce0414adfe60', NULL, 'MC', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:10.410898+01', NULL, 'EUR', '{monaco,mc,europe,landlocked,community,diaspora}', NULL, 'Europe', 'Western Europe', NULL);
INSERT INTO public.spaces VALUES ('8d8740bb-8773-400d-8eba-98c418ed4e04', NULL, '00000000-0000-0000-0000-000000000060', 'Morocco', 'morocco', 'Your digital anchor in North Africa — from Rabat to the farthest corners of the diaspora, everything flows through here. A land of the Sahara, shaped by geography and history into something uniquely its own. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "Morocco", "extract": "Morocco, officially the Kingdom of Morocco, is a country in the Maghreb region of North Africa. It has coastlines on the Mediterranean Sea to the north and the Atlantic Ocean to the west, and has land borders with Algeria to the east; the Spanish exclaves of Ceuta, Melilla and Peñón de Vélez de la Gomera along the north, which it claims together with several small Spanish-controlled islands; and the disputed territory of Western Sahara to the south, partly occupied by Morocco since 1975. Morocco also claims to share a border with Mauritania through the disputed territory of Western Sahara. It has a population of approximately 37 million. Its capital is Rabat, while its largest city is Casablanca.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/2c/Flag_of_Morocco.svg/330px-Flag_of_Morocco.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Morocco", "description": "Country in North Africa"}', '90933233-16b5-4b84-a785-da9e72428822', NULL, 'MA', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:12.428035+01', NULL, NULL, '{morocco,ma,africa,island,community,diaspora}', NULL, 'Africa', 'Northern Africa', NULL);
INSERT INTO public.spaces VALUES ('b956c8a6-43df-408e-be00-a074076a608d', NULL, '00000000-0000-0000-0000-000000000060', 'Oman', 'oman', 'From West Asia to cities and towns across the globe — this is the gathering point for a diaspora that never lost touch with home. It is set in West Asia, sharing borders with Saudi Arabia, United Arab Emirates, Yemen, and Iran, with Islam is the state religion as its capital.', '{"title": "Oman", "extract": "Oman, officially the Sultanate of Oman, is a country in the southeastern Arabian Peninsula in West Asia. It shares land borders with Saudi Arabia, the United Arab Emirates, and Yemen, while also sharing maritime borders with Iran and Pakistan. Oman''s coastline faces the Arabian Sea to the southeast and the Gulf of Oman on the northeast. The exclaves of Madha and Musandam are surrounded by the United Arab Emirates on their land borders, while Musandam''s coastal boundaries are formed by the strategic Strait of Hormuz and the Gulf of Oman. It has a population of approximately 5.46 million and an area of 315,331 km2, making it the third-largest country on the Arabian Peninsula. Muscat is the capital and largest city, Islam is the state religion, and Arabic is the official language.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/dd/Flag_of_Oman.svg/330px-Flag_of_Oman.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Oman", "description": "Country in West Asia"}', 'eb6c8f7a-8f43-45d7-96c9-749f6a71a2b0', NULL, 'OM', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:21.50504+01', NULL, NULL, '{oman,om,asia,community,diaspora}', NULL, 'Asia', 'Western Asia', NULL);
INSERT INTO public.spaces VALUES ('fc4d25b1-87d8-488d-abd1-e5be9366cb92', NULL, '00000000-0000-0000-0000-000000000060', 'Eritrea', 'eritrea', 'It is set in Horn of Africa, sharing borders with Ethiopia, Sudan, and Djibouti, with Asmara as its capital. From the streets of Asmara to diaspora communities worldwide, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Eritrea", "extract": "Eritrea, officially the State of Eritrea, is a country in the Horn of Africa region of East Africa. Its capital and largest city is Asmara. The country is bordered by Ethiopia to the south, Sudan to the west, and Djibouti to the southeast. The northeastern and eastern parts of Eritrea have an extensive coastline along the Red Sea. The country has a total area of approximately 117,600 km2 (45,406 sq mi), and includes the Dahlak Archipelago and several of the Hanish Islands.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/29/Flag_of_Eritrea.svg/330px-Flag_of_Eritrea.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Eritrea", "description": "Country in the Horn of Africa"}', '8c44779f-d38f-4534-8c61-f0d131d01ca9', NULL, 'ER', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:32.089143+01', NULL, NULL, '{eritrea,er,africa,island,community,diaspora}', NULL, 'Africa', 'Eastern Africa', NULL);
INSERT INTO public.spaces VALUES ('aab5bb74-5a31-445c-9d59-78a7aa46e2f9', NULL, '00000000-0000-0000-0000-000000000060', 'Sao Tome and Principe', 'sao-tome-and-principe', 'An island nation in Central Africa with a diaspora scattered across every continent — this space brings them all back to one table. It is set in Central Africa, an island nation. Share local news, discover events, trade on the marketplace, and tap into remittance rates, scholarship finds, and community resources — all in one place.', '{"title": "São Tomé and Príncipe", "extract": "São Tomé and Príncipe, officially the Democratic Republic of Sao Tome and Principe, is an island country in the Gulf of Guinea, off the western equatorial coast of Central Africa. It consists of two archipelagos around the two main islands of São Tomé and Príncipe, about 81 nautical miles apart and about 135 and 121 nautical miles off the northwestern coast of Gabon. With a population of 201,800, São Tomé and Príncipe is the second-smallest and second-least populous African sovereign state after Seychelles.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/0a/Flag_of_S%C3%A3o_Tom%C3%A9_and_Pr%C3%ADncipe.svg/330px-Flag_of_S%C3%A3o_Tom%C3%A9_and_Pr%C3%ADncipe.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/S%C3%A3o_Tom%C3%A9_and_Pr%C3%ADncipe", "description": "Island country in Central Africa"}', '2391b2d5-f8e6-46b7-b9ef-1390c888e5aa', NULL, 'ST', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:35.129858+01', NULL, NULL, '{"sao tome and principe",sao-tome-and-principe,st,africa,island,community,diaspora}', NULL, 'Africa', 'Middle Africa', NULL);
INSERT INTO public.spaces VALUES ('a1ed0d51-c40d-4a70-a864-9dd1fa36f518', NULL, '00000000-0000-0000-0000-000000000060', 'South Korea', 'south-korea', 'It is set in East Asia, sharing borders with Korea, Korean Demilitarized Zone, and Japan. Whether you''re still in East Asia or building a life elsewhere, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "South Korea", "extract": "South Korea, officially the Republic of Korea (ROK), is a country in East Asia. It constitutes the southern half of the Korean Peninsula and borders North Korea along the Korean Demilitarized Zone, with the Yellow Sea to the west and the Sea of Japan to the east. South Korea claims to be the sole legitimate government of the entire peninsula and adjacent islands. It has a population of about 52 million, of which half live in the Seoul metropolitan area, the ninth most populous metropolitan area in the world, with other major cities being Busan, Daegu, and Incheon.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/09/Flag_of_South_Korea.svg/330px-Flag_of_South_Korea.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/South_Korea", "description": "Country in East Asia"}', '3e25e642-731b-4e79-89c8-1fdcc71ee2b9', NULL, 'KR', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:42.185529+01', NULL, NULL, '{"south korea",south-korea,kr,asia,island,community,diaspora}', NULL, 'Asia', 'Eastern Asia', NULL);
INSERT INTO public.spaces VALUES ('c631bbe4-dd9e-45db-8364-8fcd09b32af9', NULL, '00000000-0000-0000-0000-000000000060', 'Suriname', 'suriname', 'Smallest country in South America by both population and territory in South America, shaped by rainforests and an equatorial location. It is set in South America, sharing borders with French Guiana, Brazil, and Guyana, with Paramaribo as its capital. From the streets of Paramaribo to diaspora communities worldwide, this is your space to connect, trade, and stay rooted.', '{"title": "Suriname", "extract": "Suriname, officially the Republic of Suriname, is a country in northern South America, also considered as part of the Caribbean and the West Indies. Situated slightly north of the equator, over 90% of its territory is covered by rainforest, the second-highest proportion of forest cover in the world. Suriname is bordered by the Atlantic Ocean to the north, French Guiana to the east, Brazil to the south, and Guyana to the west. It is the smallest country in South America by both population and territory, with around 612,985 inhabitants in 2021 in an area of approximately 165,940 square kilometres. The capital and largest city is Paramaribo, which is home to roughly half the population.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/60/Flag_of_Suriname.svg/330px-Flag_of_Suriname.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Suriname", "description": "Country in South America"}', '8b5b43b3-308e-4511-8012-773e41891bf8', NULL, 'SR', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:44.701421+01', NULL, NULL, '{suriname,sr,"south america",community,diaspora}', NULL, 'Americas', 'South America', NULL);
INSERT INTO public.spaces VALUES ('50e8c197-4fdb-425a-a135-6588e60972f4', NULL, '00000000-0000-0000-0000-000000000060', 'Tajikistan', 'tajikistan', 'Your digital anchor in Central Asia — wherever the diaspora has settled, this is home base. Home to 1 people, with communities spread far beyond its borders. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "Tajikistan", "extract": "Tajikistan, officially the Republic of Tajikistan, is a landlocked country located in Central Asia. Dushanbe is the capital and largest city of the country, with a population of over 1.2 million. Tajikistan borders Afghanistan to the south, Uzbekistan to the west, Kyrgyzstan to the north, and China to the east; it is narrowly separated from Pakistan by Afghanistan''s Wakhan Corridor. Its total population exceeds 11 million.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d0/Flag_of_Tajikistan.svg/330px-Flag_of_Tajikistan.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Tajikistan", "description": "Landlocked country in Central Asia"}', 'ad982edf-1313-4db5-b1d4-035fca8cefa8', NULL, 'TJ', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:47.723752+01', NULL, NULL, '{tajikistan,tj,asia,landlocked,community,diaspora}', NULL, 'Asia', 'Central Asia', NULL);
INSERT INTO public.spaces VALUES ('184796cf-0078-410b-9ffa-60936cda6b02', NULL, '00000000-0000-0000-0000-000000000060', 'American Samoa', 'american-samoa', 'Every journey out of Polynesia carries a story — of ambition, of longing, of roots that stretch but never break. From an equatorial location to the cities where the diaspora now lives, the connection to home runs deep. Discover local businesses, share news from home, find events near you, and build a network that spans borders — all on JapaConnect.', '{"title": "American Samoa", "extract": "American Samoa is a self-governing, unincorporated and unorganized territory of the United States located in the south Pacific Ocean, within the Polynesia subregion of Oceania. Centered on 14.3°S 170.7°W, it is 40 miles (64 km) southeast of the island country of Samoa, east of the International Date Line and the French territory of Wallis and Futuna, west of the Cook Islands, north of Tonga, and some 310 miles (500 km) south of Tokelau. American Samoa is the southernmost territory of the United States, situated 2,200 miles (3,500 km) southwest of the U.S. state of Hawaii, and one of two U.S. territories south of the Equator, along with the uninhabited Jarvis Island.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/87/Flag_of_American_Samoa.svg/330px-Flag_of_American_Samoa.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/American_Samoa", "description": "American territory in Polynesia"}', '2f0d013d-8ac0-40d4-accf-55b7f82d335a', NULL, 'AS', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:00.808637+01', NULL, 'USD', '{"american samoa",american-samoa,as,island,community,diaspora}', NULL, 'Oceania', 'Polynesia', NULL);
INSERT INTO public.spaces VALUES ('81292131-7c97-458a-9a52-f832f6feaf23', NULL, '00000000-0000-0000-0000-000000000060', 'Bosnia and Herzegovina', 'bosnia-and-herzegovina', 'Every journey out of Southeast Europe carries a story — of ambition, of longing, of roots that stretch but never break. From mountainous terrain to the cities where the diaspora now lives, the connection to home runs deep. Discover local businesses, share news from home, find events near you, and build a network that spans borders — all on JapaConnect.', '{"title": "Bosnia and Herzegovina", "extract": "Bosnia and Herzegovina, often referred to as Bosnia-Herzegovina or simply Bosnia, is a country in Southeast Europe. Situated on the Balkan Peninsula, it borders Serbia to the east, Montenegro to the southeast, and Croatia to the north and southwest, with a 20-kilometre-long (12-mile) coast on the Adriatic Sea in the south. Bosnia has a moderate continental climate with hot summers and cold, snowy winters. Its geography is largely mountainous, particularly in the central and eastern regions, which are dominated by the Dinaric Alps. Herzegovina, the smaller, southern region, has a Mediterranean climate and is mostly mountainous. Sarajevo is the capital and the largest city.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/bf/Flag_of_Bosnia_and_Herzegovina.svg/330px-Flag_of_Bosnia_and_Herzegovina.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Bosnia_and_Herzegovina", "description": "Country in Southeast Europe"}', '7ea6a721-e19c-4bcd-96a8-3b90f04ffb46', NULL, 'BA', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:12.415082+01', NULL, NULL, '{"bosnia and herzegovina",bosnia-and-herzegovina,ba,europe,community,diaspora}', NULL, 'Europe', 'Southern Europe', NULL);
INSERT INTO public.spaces VALUES ('8c006550-2bde-4387-b8c8-34f8c96b379e', NULL, '00000000-0000-0000-0000-000000000060', 'Chile', 'chile', 'From South America to cities and towns across the globe — this is the gathering point for a diaspora that never lost touch with home. It is set in South America, sharing borders with Peru, Bolivia, Argentina, and Drake Passage, with Santiago as its capital.', '{"title": "Chile", "extract": "Chile, officially the Republic of Chile, is a country in the Southern Cone of western South America. It is the southernmost country in the world and the closest to Antarctica, extending along a narrow strip of land between the Andes Mountains and the Pacific Ocean. According to the 2024 census, Chile had an enumerated population of 18.5 million. The country covers a territorial area of 756,102 square kilometers (291,933 sq mi), sharing borders with Peru to the north, Bolivia to the northeast, Argentina to the east, and the Drake Passage to the south. It also administers several Pacific islands, including Juan Fernández, Isla Salas y Gómez, Desventuradas, and Easter Island, and claims about 1,250,000 square kilometers (480,000 sq mi) of Antarctica as the Chilean Antarctic Territory. The capital and largest city is Santiago, and the official and national language is Spanish.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/78/Flag_of_Chile.svg/330px-Flag_of_Chile.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Chile", "description": "Country in South America"}', 'd5a5692d-897c-4746-8f9f-c083c7c36f0a', NULL, 'CL', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:20.482138+01', NULL, NULL, '{chile,cl,"south america",island,community,diaspora}', NULL, 'Americas', 'South America', NULL);
INSERT INTO public.spaces VALUES ('a8ac559d-0a97-43ca-9f11-e53c73d63f0f', NULL, '00000000-0000-0000-0000-000000000060', 'Cocos (Keeling) Islands', 'cocos-keeling-islands', 'Every journey carries a story — of ambition, of longing, of roots that stretch but never break. Discover local businesses, share news from home, find events near you, and build a network that spans borders — all on JapaConnect.', '{"title": "Cocos (Keeling) Islands", "extract": "The Cocos (Keeling) Islands, officially the Territory of Cocos (Keeling) Islands, are an Australian external territory located in the Indian Ocean, comprising a small archipelago approximately midway between Australia and Sri Lanka and relatively close to the Indonesian island of Sumatra. The territory''s dual name reflects that the islands have historically been known as either the Cocos Islands or the Keeling Islands, the latter of which is still a common short name.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/7/74/Flag_of_the_Cocos_%28Keeling%29_Islands.svg/330px-Flag_of_the_Cocos_%28Keeling%29_Islands.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Cocos_(Keeling)_Islands", "description": "External territory of Australia"}', 'eed5b549-3a51-43d0-9047-97d830295c3b', NULL, 'CC', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:21.992981+01', NULL, NULL, '{"cocos (keeling) islands",cocos-keeling-islands,cc,island,community,diaspora}', NULL, 'Oceania', 'Australia and New Zealand', NULL);
INSERT INTO public.spaces VALUES ('15a7cae5-dbcd-4b23-a6fd-8e8dcf96dbba', NULL, '00000000-0000-0000-0000-000000000064', 'Belarusian State Agrarian Technical University', 'belarusian-state-agrarian-technical-university', NULL, '{"logo": "http://commons.wikimedia.org/wiki/Special:FilePath/%D0%9B%D0%BE%D0%B3%D0%BE%D1%82%D0%B8%D0%BF%20%D0%91%D0%93%D0%90%D0%A2%D0%A3.jpg", "name": "Belarusian State Agrarian Technical University", "image": "http://commons.wikimedia.org/wiki/Special:FilePath/%D0%9C%D1%96%D0%BD%D1%81%D0%BA.%20%D0%91%D0%94%D0%90%D0%A2%D0%A3%20%2802%29.jpg", "country": "Q184", "founded": "+1954-00-00T00:00:00Z", "website": "https://www.bsatu.by/", "description": "public university in Minsk, Belarus", "wikidata_id": "Q4082743", "wikipedia_url": "https://en.wikipedia.org/wiki/Q4082743"}', '262745f5-3c26-4ff0-899f-1a165680196a', NULL, 'BY', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.296289+01', '2026-08-10 06:58:17.874606+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('3bf86afa-27e6-479e-91a1-ded874497071', NULL, '00000000-0000-0000-0000-000000000060', 'Equatorial Guinea', 'equatorial-guinea', 'From Central Africa to cities and towns across the globe — this is the gathering point for a diaspora that never lost touch with home. It is set in Central Africa. Share local news, discover events, trade on the marketplace, and tap into remittance rates, scholarship finds, and community resources — all in one place.', '{"title": "Equatorial Guinea", "extract": "Equatorial Guinea, officially the Republic of Equatorial Guinea, is a country on the west coast of Central Africa and the only Spanish-speaking country in Africa. It has an area of 28,000 square kilometres (11,000 sq mi). Formerly the colony of Spanish Guinea, its post-independence name refers to its location both near the Equator and in the African region of Guinea. As of 2025, the country has a population of 1,853,559, over 85% of whom are members of the Fang people, the country''s dominant ethnic group. The Bubi people, indigenous to Bioko Island, are the second largest group at approximately 6.5% of the population. The country''s new capital, since January 2026, is Ciudad de la Paz, and Malabo, the former capital, is the second largest city, after Bata.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/31/Flag_of_Equatorial_Guinea.svg/330px-Flag_of_Equatorial_Guinea.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Equatorial_Guinea", "description": "Country in Central Africa"}', '0b30b303-89a7-4dfb-9f6f-8641536d8fb0', NULL, 'GQ', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:31.584366+01', NULL, NULL, '{"equatorial guinea",equatorial-guinea,gq,africa,island,community,diaspora}', NULL, 'Africa', 'Middle Africa', NULL);
INSERT INTO public.spaces VALUES ('8ffdb9ff-dae1-4589-9e82-04f2cd39a0a2', NULL, '00000000-0000-0000-0000-000000000060', 'Falkland Islands', 'falkland-islands', 'Your digital anchor in South Atlantic — wherever the diaspora has settled, this is home base. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "Falkland Islands", "extract": "The Falkland Islands, commonly referred to as the Falklands, is an archipelago in the South Atlantic Ocean on the Patagonian Shelf. The principal islands are about 300 mi (500 km) east of South America''s southern Patagonian coast and 752 mi (1,210 km) from Cape Dubouzet at the northern tip of the Antarctic Peninsula, at a latitude of about 52°S. The archipelago, with an area of 4,700 sq mi (12,000 km2), comprises East Falkland, West Falkland, and 776 smaller islands. As a British Overseas Territory, the Falklands have internal self-governance, while the United Kingdom takes responsibility for their defence and foreign affairs. The capital and largest settlement is Stanley on East Falkland.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/83/Flag_of_the_Falkland_Islands.svg/330px-Flag_of_the_Falkland_Islands.svg.png", "content_url": "https://en.wikipedia.org/wiki/Falkland_Islands", "description": "Group of islands in the South Atlantic"}', 'b0e59ff5-212a-4a20-8185-9c925760b9a1', NULL, 'FK', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:34.104676+01', NULL, NULL, '{"falkland islands",falkland-islands,fk,island,community,diaspora}', NULL, 'Americas', 'South America', NULL);
INSERT INTO public.spaces VALUES ('a64cfaf1-a818-41d5-bcd2-b583a814f40f', NULL, '00000000-0000-0000-0000-000000000060', 'Heard Island and McDonald Islands', 'heard-island-and-mcdonald-islands', 'From here to the world — this is where the diaspora gathers, no matter how far they''ve traveled. Share local news, discover events, trade on the marketplace, and tap into remittance rates, scholarship finds, and community resources — all in one place.', '{"title": "Heard Island and McDonald Islands", "extract": "The Territory of Heard Island and McDonald Islands is an Australian external territory in the southern Indian Ocean. Discovered in the mid-19th century, the territory is a group of sub-Antarctic volcanic islands that lie on the Kerguelen Plateau. It is about 4000 kilometres (2500 mi) south-west of the Australian mainland and 1700 kilometres (1100 mi) north of Antarctica. The territory contains Australia''s only active volcanoes and is home to its highest point outside the Australian Antarctic Territory, Mawson Peak. The territory is uninhabited and has been described as one of the most remote places on Earth.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/38/Heard_Island_%28cropped%29.jpg/330px-Heard_Island_%28cropped%29.jpg", "content_url": "https://en.wikipedia.org/wiki/Heard_Island_and_McDonald_Islands", "description": "External territory of Australia"}', 'e7587469-e3c2-4953-b604-4bf6be830171', NULL, 'HM', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:46.201529+01', NULL, NULL, '{"heard island and mcdonald islands",heard-island-and-mcdonald-islands,hm,island,community,diaspora}', NULL, 'Global', 'Global', NULL);
INSERT INTO public.spaces VALUES ('f5f62bc1-a534-42ec-8b02-1c0176a14766', NULL, '00000000-0000-0000-0000-000000000060', 'Iraq', 'iraq', 'Your digital anchor in West Asia — wherever the diaspora has settled, this is home base. Home to 46 million people, with communities spread far beyond its borders. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "Iraq", "extract": "Iraq, officially the Republic of Iraq, is a country in West Asia. Located within the Middle East, it is bordered by Saudi Arabia to the south, Turkey to the north, Iran to the east, the Persian Gulf and Kuwait to the southeast, Jordan to the southwest, and Syria to the west. The country covers an area of 438,317 square kilometres (169,235 sq mi) and has a population of over 46 million, making it the 58th largest country by area and the 31st most populous in the world. Baghdad, home to over 8 million people, is the capital city and the largest in the country.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/f6/Flag_of_Iraq.svg/330px-Flag_of_Iraq.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Iraq", "description": "Country in West Asia"}', 'a41df45b-ef07-4c32-8ce1-700b80b6e19d', NULL, 'IQ', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:50.235233+01', NULL, NULL, '{iraq,iq,asia,community,diaspora}', NULL, 'Asia', 'Western Asia', NULL);
INSERT INTO public.spaces VALUES ('af5ff832-53c6-49e3-ad6e-9fe66d33022c', NULL, '00000000-0000-0000-0000-000000000060', 'Italy', 'italy', 'From Southern and Western Europe to cities and towns across the globe — this is the gathering point for a diaspora that never lost touch with home. It is set in Southern and Western Europe, sharing borders with France. Share local news, discover events, trade on the marketplace, and tap into remittance rates, scholarship finds, and community resources — all in one place.', '{"title": "Italy", "extract": "Italy, officially the Italian Republic, is a country in Southern and Western Europe. It consists of a peninsula that extends into the Mediterranean Sea, with the Alps on its northern land border, as well as nearly 800 islands, notably Sicily and Sardinia. Italy shares land borders with France to the west; Switzerland and Austria to the north; Slovenia to the east; and the two enclaves of Vatican City and San Marino. It is the tenth-largest country in Europe by area, covering 301,340 km2 (116,350 sq mi), and the third-most populous member state of the European Union, with nearly 59 million inhabitants. Rome is the capital of Italy; other major cities include Milan, Naples, Turin, Palermo, Bologna, Florence, Genoa, Bari, and Venice.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/0/03/Flag_of_Italy.svg/330px-Flag_of_Italy.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Italy", "description": "Country in Southern and Western Europe"}', 'c9ade3c0-4905-4336-bb9e-209ad51e717d', NULL, 'IT', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:51.749105+01', NULL, 'EUR', '{italy,it,europe,island,community,diaspora}', NULL, 'Europe', 'Southern Europe', NULL);
INSERT INTO public.spaces VALUES ('25cba591-4d9a-4611-a7d6-a4e4a29964c3', NULL, '00000000-0000-0000-0000-000000000060', 'Niger', 'niger', 'It is set in West Africa, landlocked, sharing borders with Libya, Chad, Nigeria, and Benin. Whether you''re still in West Africa or building a life elsewhere, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Niger", "extract": "Niger, officially the Republic of the Niger, is a landlocked country in West Africa. It is a unitary state bordered by Libya to the northeast, Chad to the east, Nigeria to the south, Benin and Burkina Faso to the southwest, Mali to the west, and Algeria to the northwest. It covers a land area of almost 1.27 million km2 (490,000 mi2), making it the sixth-largest country in Africa and the second-largest landlocked nation in Africa behind Chad. Over 80% of its land area lies in the Sahara. Its predominantly Muslim population of about 29 million lives mostly in clusters in the south and west of the country. The capital Niamey is located in the southwest corner along the namesake Niger River.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/88/Niger_%28orthographic_projection%29.svg/330px-Niger_%28orthographic_projection%29.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Niger", "description": "Landlocked country in West Africa"}', '87cb8c3a-7b0a-4693-b286-11003488526d', NULL, 'NE', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:17.473459+01', NULL, NULL, '{niger,ne,africa,landlocked,community,diaspora}', NULL, 'Africa', 'Western Africa', NULL);
INSERT INTO public.spaces VALUES ('b650294a-237f-4474-9fc2-726fa4e2c052', NULL, '00000000-0000-0000-0000-000000000060', 'Malaysia', 'malaysia', 'Your digital anchor in Southeast Asia — wherever the diaspora has settled, this is home base. Home to 34 million people, with communities spread far beyond its borders. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "Malaysia", "extract": "Malaysia is a country in Southeast Asia. A federal constitutional monarchy, it consists of 13 states and three federal territories, separated by the South China Sea into two regions: Peninsular Malaysia on Mainland Southeast Asia and East Malaysia on the island of Borneo. Peninsular Malaysia shares land and maritime borders with Thailand, as well as maritime borders with Singapore, Vietnam, and Indonesia; East Malaysia shares land borders with Brunei and Indonesia, and maritime borders with the Philippines and Vietnam. Kuala Lumpur is the country''s national capital, largest city, and the seat of the legislative branch of the federal government, while Putrajaya is the federal administrative capital, representing the seat of both the executive branch and the judicial branch of the federal government. With a population of over 34 million, it is the world''s 43rd-most populous country.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/66/Flag_of_Malaysia.svg/330px-Flag_of_Malaysia.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Malaysia", "description": "Country in Southeast Asia"}', '76acbc6f-25c7-4d39-8de0-3ae5f19cacbb', NULL, 'MY', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:03.851239+01', NULL, NULL, '{malaysia,my,asia,island,community,diaspora}', NULL, 'Asia', 'South-Eastern Asia', NULL);
INSERT INTO public.spaces VALUES ('6b04421c-6c5e-4693-947c-cf41fc12d2c5', NULL, '00000000-0000-0000-0000-000000000060', 'Mongolia', 'mongolia', 'Your digital anchor in East Asia — wherever the diaspora has settled, this is home base. A land of the Gobi Desert and grassy steppes, shaped by geography and history into something uniquely its own. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "Mongolia", "extract": "Mongolia is a landlocked country in East Asia. It is bordered by Russia to the north and China to the south and covers an area of 1,564,116 square kilometers, making it the 18th-largest country in the world and the second largest landlocked nation after Kazakhstan, as well as the largest landlocked country that does not border an inland sea. With a population of 3.5 million, Mongolia is the world''s most sparsely populated sovereign state, excluding partially unrecognized Western Sahara. The country constitutes a significant portion of the Mongolian Plateau, and its natural environment is characterized by grassy steppe, mountains to the north and west, and the Gobi Desert to the south. Ulaanbaatar, the capital and largest city, is home to roughly half of the country''s population.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/4c/Flag_of_Mongolia.svg/330px-Flag_of_Mongolia.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Mongolia", "description": "Country in East Asia"}', '380b0bb3-d53e-4931-babe-6ac65265f7e4', NULL, 'MN', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:10.915113+01', NULL, NULL, '{mongolia,mn,asia,landlocked,community,diaspora}', NULL, 'Asia', 'Eastern Asia', NULL);
INSERT INTO public.spaces VALUES ('9fd08055-7c2c-4ddd-b5e4-fc7169b508e6', NULL, '00000000-0000-0000-0000-000000000060', 'Namibia', 'namibia', 'Every journey out of Southern Africa carries a story — of ambition, of longing, of roots that stretch but never break. From the capital, Windhoek, to the cities where the diaspora now lives, the connection to home runs deep. Discover local businesses, share news from home, find events near you, and build a network that spans borders — all on JapaConnect.', '{"title": "Namibia", "extract": "Namibia, officially the Republic of Namibia, is a country in Southern Africa. It borders the Atlantic Ocean to the west, Angola and Zambia to the north, Botswana to the east, and South Africa to the south; in the northeast, approximating a quadripoint, Zimbabwe lies less than 200 metres (660 ft) away along the Zambezi river near Kazungula, Zambia. Namibia''s capital and largest city is Windhoek.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/00/Flag_of_Namibia.svg/330px-Flag_of_Namibia.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Namibia", "description": "Country in Southern Africa"}', '3178b458-878c-4d9d-a14e-3c7a9bd85044', NULL, 'NA', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:13.940343+01', NULL, NULL, '{namibia,na,africa,community,diaspora}', NULL, 'Africa', 'Southern Africa', NULL);
INSERT INTO public.spaces VALUES ('562ac081-df8f-41a2-b469-79ccb7a634ec', NULL, '00000000-0000-0000-0000-000000000064', 'Owensboro Community and Technical College', 'owensboro-community-and-technical-college', NULL, '{"name": "Owensboro Community and Technical College", "country": "Q30", "founded": "+1986-00-00T00:00:00Z", "website": "http://www.owensboro.kctcs.edu", "students": "+3901", "description": "public community college in Owensboro, Kentucky, United States", "wikidata_id": "Q7114753", "wikipedia_url": "https://en.wikipedia.org/wiki/Q7114753"}', NULL, NULL, 'US', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.702225+01', '2026-08-22 10:03:07.650602+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('27878fd4-1b78-4c37-80af-85e5c8372731', NULL, '00000000-0000-0000-0000-000000000060', 'New Zealand', 'new-zealand', 'Rooted here, reaching across continents — this space bridges home and diaspora. Wellington serves as the capital while Auckland leads in population; the landscape is defined by volcanic activity. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "New Zealand", "extract": "New Zealand is an island country in the southwestern Pacific Ocean. It comprises two main landmasses—the North Island and the South Island —and over 700 smaller islands. It is the sixth-largest island country by area and lies east of Australia across the Tasman Sea and south of the islands of New Caledonia, Fiji, and Tonga. The country''s varied topography and sharp mountain peaks, including the Southern Alps, owe much to tectonic uplift and volcanic eruptions. New Zealand''s capital city is Wellington, and its most populous city is Auckland.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/3e/Flag_of_New_Zealand.svg/330px-Flag_of_New_Zealand.svg.png", "content_url": "https://en.wikipedia.org/wiki/New_Zealand", "description": "Island country in the Pacific Ocean"}', 'da20f65a-ffdc-4985-b986-1d32dd63be96', NULL, 'NZ', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:16.463037+01', NULL, NULL, '{"new zealand",new-zealand,nz,pacific,island,community,diaspora}', NULL, 'Oceania', 'Australia and New Zealand', NULL);
INSERT INTO public.spaces VALUES ('69a8cbb2-c0c4-4761-a97f-5c59e70466ab', NULL, '00000000-0000-0000-0000-000000000064', 'University of Ioannina', 'university-of-ioannina', NULL, '{"name": "University of Ioannina", "image": "http://commons.wikimedia.org/wiki/Special:FilePath/Uoi%20main-entrance.jpg", "country": "Q41", "founded": "+1970-12-11T00:00:00Z", "website": "http://www.uoi.gr/", "students": "+25000", "description": "higher education institution based in Ioannina, Greece", "wikidata_id": "Q1229924", "wikipedia_url": "https://en.wikipedia.org/wiki/Q1229924"}', NULL, NULL, 'GR', 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 12:47:33.411195+01', '2026-08-27 06:02:29.679353+01', NULL, NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('eec38cc6-6aa4-4cae-be4a-2819cf3a757e', NULL, '00000000-0000-0000-0000-000000000060', 'Puerto Rico', 'puerto-rico', 'Rooted in Caribbean, reaching across continents — this space bridges home and diaspora. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "Puerto Rico", "extract": "Puerto Rico, officially the Commonwealth of Puerto Rico, is a self-governing Caribbean archipelago and island organized as an unincorporated territory of the United States under the designation of commonwealth. Located about 1,000 miles (1,600 km) southeast of Miami, Florida, between the Dominican Republic in the Greater Antilles and the U.S. Virgin Islands in the Lesser Antilles, it consists of the eponymous main island and numerous smaller islands, including Vieques, Culebra, and Mona. With approximately 3.2 million people, it is divided into 78 municipalities, of which the most populous is the capital municipality of San Juan, followed by those within the San Juan metropolitan area. Spanish and English are the official languages of the government, though Spanish predominates.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/28/Flag_of_Puerto_Rico.svg/330px-Flag_of_Puerto_Rico.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Puerto_Rico", "description": "U.S. territory in the Caribbean"}', '715a5b27-9976-478a-ada4-367d19e28874', NULL, 'PR', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:27.560838+01', NULL, 'USD', '{"puerto rico",puerto-rico,pr,caribbean,island,community,diaspora}', NULL, 'Americas', 'Caribbean', NULL);
INSERT INTO public.spaces VALUES ('a1f6b229-6f41-4d14-8773-71ef2972f1db', NULL, '00000000-0000-0000-0000-000000000060', 'Somalia', 'somalia', 'From East Africa to cities and towns across the globe — this is the gathering point for a diaspora that never lost touch with home. It is set in East Africa, sharing borders with Ethiopia, Djibouti, Kenya, and Aden, with Mogadishu as its capital.', '{"title": "Somalia", "extract": "Somalia, officially the Federal Republic of Somalia, is the easternmost country in continental Africa. Stretching across the Horn of Africa, it borders Ethiopia to the west, Djibouti to the northwest, Kenya to the southwest, the Gulf of Aden to the north, and the Indian Ocean to the east. Somalia has the longest coastline on Africa''s mainland. Somalia has an estimated population of more than 18 million, of which 2.7 million live in the capital and largest city, Mogadishu. As one of Africa''s most ethnically homogeneous countries, around 85% of its residents are ethnic Somalis. The official and national language of the country is Somali while Arabic is recognised as a second language. The overwhelming majority of the population are Sunni Muslims.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/a0/Flag_of_Somalia.svg/330px-Flag_of_Somalia.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Somalia", "description": "Country in East Africa"}', 'cd200a9e-5632-46f8-a3ec-861a031afa59', NULL, 'SO', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:40.675414+01', NULL, NULL, '{somalia,so,africa,community,diaspora}', NULL, 'Africa', 'Eastern Africa', NULL);
INSERT INTO public.spaces VALUES ('f9d2b449-ba20-4ce9-b73c-9f0ff51eb0c5', NULL, '00000000-0000-0000-0000-000000000060', 'South Sudan', 'south-sudan', 'Landlocked in East Africa but connected to the world — this is where the diaspora gathers, no matter how far they''ve traveled. It is set in East Africa, landlocked, sharing borders with Sudan, Ethiopia, Kenya, and Uganda. Share local news, discover events, trade on the marketplace, and tap into remittance rates, scholarship finds, and community resources — all in one place.', '{"title": "South Sudan", "extract": "South Sudan, officially the Republic of South Sudan, is a landlocked country in East Africa. It is bordered by Sudan to the north, Ethiopia to the east, Kenya to the southeast, Uganda to the south, the Democratic Republic of the Congo to the southwest, and the Central African Republic to the west. South Sudan''s diverse landscape includes vast plains and plateaus, dry and tropical savannahs, inland floodplains, and forested mountains. The Nile River system is the defining physical feature of the country, running south to north across its center, which is dominated by a large swamp known as the Sudd. South Sudan has an estimated population of just over 12.7 million in 2024. Juba is the capital and largest city.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/7a/Flag_of_South_Sudan.svg/330px-Flag_of_South_Sudan.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/South_Sudan", "description": "Country in East Africa"}', '4144e83f-276d-444a-bd17-71c99eb199b5', NULL, 'SS', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:42.688231+01', NULL, NULL, '{"south sudan",south-sudan,ss,africa,landlocked,community,diaspora}', NULL, 'Africa', 'Middle Africa', NULL);
INSERT INTO public.spaces VALUES ('a612cfcf-2086-4e44-a89d-8e748725d56a', NULL, '00000000-0000-0000-0000-000000000060', 'Sri Lanka', 'sri-lanka', 'It is set in South Asia, an island nation, with Colombo as its capital. From the streets of Colombo to diaspora communities worldwide, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Sri Lanka", "extract": "Sri Lanka, officially the Democratic Socialist Republic of Sri Lanka, formerly known as Ceylon, is an island country in South Asia. It is located in the Indian Ocean, southwest of the Bay of Bengal, and is separated from India by the Gulf of Mannar and the Palk Strait. Sri Lanka shares a maritime border with the Maldives to the southwest and India to the northwest, and lies across the Bay of Bengal from Bangladesh and Myanmar to the northeast and the Andaman and Nicobar Islands of India to the east. Its executive and judicial capital is Colombo, which is also its largest city and the political, financial and cultural centre of the country; neighboring Sri Jayawardenepura Kotte is the legislative capital. Sri Lanka''s population is 22 million. About 74% of the population are Sinhalese, who speak the Sinhala language, and about 15% are Tamils who speak the Tamil language. Other long-established ethnic groups include the Moors, Indian Tamils, Burghers, Malays, Chinese, and Vedda.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/11/Flag_of_Sri_Lanka.svg/330px-Flag_of_Sri_Lanka.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Sri_Lanka", "description": "Country in South Asia"}', '82d71dd2-75f2-401c-b361-9529df58beab', NULL, 'LK', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:43.695011+01', NULL, NULL, '{"sri lanka",sri-lanka,lk,asia,island,community,diaspora}', NULL, 'Asia', 'Southern Asia', NULL);
