INSERT INTO public.spaces VALUES ('15ce613b-ab38-4369-aba8-9580c319efe8', NULL, '00000000-0000-0000-0000-000000000060', 'Syria', 'syria', 'From West Asia to cities and towns across the globe — this is the gathering point for a diaspora that never lost touch with home. It is set in West Asia, sharing borders with Turkey, Iraq, Jordan, and Israel. Share local news, discover events, trade on the marketplace, and tap into remittance rates, scholarship finds, and community resources — all in one place.', '{"title": "Syria", "extract": "Syria, officially the Syrian Arab Republic, is a country in West Asia located in the Eastern Mediterranean and the Levant. It borders the Mediterranean Sea to the west, Turkey to the north and northwest, Iraq to the east and southeast, Jordan to the south, and Israel and Lebanon to the southwest. It is a republic under a provisional government and comprises 14 governorates. Damascus is Syria''s capital and largest city. With a population of 26 million across an area of 185,180 square kilometres (71,500 sq mi), it is the 56th-most populous and 87th-largest country.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/54/Flag_of_Syria_%282025-%29.svg/330px-Flag_of_Syria_%282025-%29.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Syria", "description": "Country in West Asia"}', 'e943b07b-d3bd-40a7-89de-fe3a2aae7e35', NULL, 'SY', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:46.715897+01', NULL, NULL, '{syria,sy,asia,community,diaspora}', NULL, 'Asia', 'Western Asia', NULL);
INSERT INTO public.spaces VALUES ('7dc18bd4-42f9-4d5c-8c8c-5ba0f34c5589', NULL, '00000000-0000-0000-0000-000000000060', 'Tonga', 'tonga', 'An island nation in Oceania with a diaspora scattered across every continent — this space brings them all back to one table. It is set in Oceania, an island nation. Share local news, discover events, trade on the marketplace, and tap into remittance rates, scholarship finds, and community resources — all in one place.', '{"title": "Tonga", "extract": "Tonga, officially known as the Kingdom of Tonga, is an island country in Polynesia, part of Oceania. The country has 171 islands, of which 45 are inhabited. Its total surface area is about 750 km2 (290 sq mi), scattered over 700,000 km2 (270,000 sq mi) in the southern Pacific Ocean. As of 2021, according to Johnson''s Tribune, Tonga has a population of 104,494, 70% of whom live on the main island, Tongatapu. The country stretches approximately 800 km north-south. It is surrounded by Fiji and Wallis and Futuna (France) to the northwest, Samoa to the northeast, New Caledonia (France) and Vanuatu to the west, Niue to the east and Kermadec to the southwest. Tonga is about 1,800 km from New Zealand''s North Island.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/9a/Flag_of_Tonga.svg/330px-Flag_of_Tonga.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Tonga", "description": "Country in Oceania"}', '42097db3-c57d-4c37-b0e5-a58c0212ff6e', NULL, 'TO', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:51.751093+01', NULL, NULL, '{tonga,to,oceania,island,community,diaspora}', NULL, 'Oceania', 'Polynesia', NULL);
