INSERT INTO public.spaces VALUES ('448a7d30-d9bd-4091-9c38-3ecbb625503c', NULL, '00000000-0000-0000-0000-000000000060', 'Tunisia', 'tunisia', 'Rooted in North Africa, sharing borders with Italy, Sicily, Sardinia, and Malta, and reaching across continents — this space bridges home and diaspora. A population of 12 calls it home; the landscape is defined by the Sahara. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "Tunisia", "extract": "Tunisia, officially the Republic of Tunisia, is a country in the Maghreb region of North Africa. It is bordered by Algeria to the west and southwest, Libya to the southeast, and the Mediterranean Sea to the north and east. Tunisia also shares maritime borders with Italy through the islands of Sicily and Sardinia to the north and Malta to the east. It features the archaeological sites of Carthage dating back to the 9th century BC, as well as the Great Mosque of Kairouan. Known for its ancient architecture, souks, and blue coasts, it covers 163,610 km2 (63,170 sq mi), and has a population of 12.1 million. It contains the eastern end of the Atlas Mountains and the northern reaches of the Sahara desert; much of its remaining territory is arable land. Its 1,300 km (810 mi) of coastline includes the African conjunction of the western and eastern parts of the Mediterranean Basin. Tunisia is home to Africa''s northernmost point, Cape Angela. Located on the northeastern coast, Tunis is the capital of the country, which is itself named after Tunis. The official language of Tunisia is Arabic. The vast majority of Tunisia''s population is Arab and Muslim. Vernacular Tunisian Arabic is the most spoken language, and French serves as an administrative and educational language in some contexts, but has no official status.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/ce/Flag_of_Tunisia.svg/330px-Flag_of_Tunisia.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Tunisia", "description": "Country in North Africa"}', 'f5bfb8f7-5f64-4a5f-9435-44e93ccf9823', NULL, 'TN', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:52.75942+01', NULL, NULL, '{tunisia,tn,africa,island,community,diaspora}', NULL, 'Africa', 'Northern Africa', NULL);
INSERT INTO public.spaces VALUES ('fc41be90-9354-451d-a496-ba5166f79e43', NULL, '00000000-0000-0000-0000-000000000060', 'Ukraine', 'ukraine', 'Every journey out of Eastern Europe carries a story — of ambition, of longing, of roots that stretch but never break. Discover local businesses, share news from home, find events near you, and build a network that spans borders — all on JapaConnect.', '{"title": "Ukraine", "extract": "Ukraine is a country in Eastern Europe. It is the second-largest country in Europe after Russia, which borders it to the east and northeast. Ukraine also borders Belarus to the north; Poland and Slovakia to the west; Hungary, Romania and Moldova to the southwest; and the Black Sea and the Sea of Azov to the south and southeast. Kyiv is Ukraine''s capital and largest city, followed by Kharkiv, Odesa, and Dnipro. The official language of the country is Ukrainian. Ukraine covers an area of 603,628 km2 (233,062 sq mi) with an estimated total population of 32.3 million in 2026.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/49/Flag_of_Ukraine.svg/330px-Flag_of_Ukraine.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Ukraine", "description": "Country in Eastern Europe"}', '7b9d49ea-3575-4b87-9a92-a1bd68a3059d', NULL, 'UA', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:45:55.781935+01', NULL, NULL, '{ukraine,ua,europe,community,diaspora}', NULL, 'Europe', 'Eastern Europe', NULL);
INSERT INTO public.spaces VALUES ('33282d36-e73b-40e9-8df4-92861020601b', NULL, '00000000-0000-0000-0000-000000000060', 'Venezuela', 'venezuela', 'Rooted in South America, reaching across continents — this space bridges home and diaspora. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "Venezuela", "extract": "Venezuela, officially the Bolivarian Republic of Venezuela, is a country on the northern coast of South America, consisting of a continental landmass and various islands and islets in the Caribbean Sea. It comprises an area of 912,050 km2 (352,140 sq mi), with a population estimated at 31.8 million in 2025. The capital and largest urban agglomeration is Caracas. The continental territory is bordered on the north by the Caribbean Sea and the Atlantic Ocean, on the west by Colombia, on the south by Brazil, on the east by Guyana, and on the northeast by Trinidad and Tobago. Venezuela consists of 23 states, the Capital District, and the Federal Dependencies covering Venezuela''s offshore islands. Venezuela is among the most urbanized countries in Latin America, with an estimated urbanization rate of 88.4% in 2022. The vast majority of Venezuelans live in urban areas in the north, including in the capital.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/06/Flag_of_Venezuela.svg/330px-Flag_of_Venezuela.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Venezuela", "description": "Country in South America"}', '1eb79620-9769-43c9-adba-e2608657b049', NULL, 'VE', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:46:00.328052+01', NULL, NULL, '{venezuela,ve,"south america",island,community,diaspora}', NULL, 'Americas', 'South America', NULL);
