INSERT INTO public.spaces VALUES ('fe1531dc-2ab1-48a0-9c2c-6e8cded93406', NULL, '00000000-0000-0000-0000-000000000060', 'Fiji Islands', 'fiji-islands', 'It is set in Oceania, an island nation. Whether you''re still in Oceania or building a life elsewhere, this is your space to connect, trade, and stay rooted. Join forums, browse the marketplace, track remittance rates, find scholarships, and connect with people who share your roots.', '{"title": "Fiji", "extract": "Fiji, officially the Republic of Fiji, is an archipelagic country in Melanesia, part of Oceania in the South Pacific Ocean. It lies about 1,100 nautical miles north-northeast of New Zealand. Fiji consists of an archipelago of more than 330 islands—of which about 110 are permanently inhabited—and more than 500 islets, amounting to a total land area of about 18,300 square kilometres (7,100 sq mi). The most outlying island group is Ono-i-Lau. About 87% of the total population live on the two major islands, Viti Levu and Vanua Levu. About three-quarters of Fijians live on Viti Levu''s coasts, either in the capital city of Suva, or in smaller urban centres such as Nadi or Lautoka. The interior of Viti Levu is sparsely inhabited because of its terrain.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/ba/Flag_of_Fiji.svg/330px-Flag_of_Fiji.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Fiji", "description": "Country in Oceania"}', 'f799167d-b15d-424a-9d35-4ee2cfdd884e', NULL, 'FJ', 'country', 0, 0, 1, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:35.109787+01', NULL, NULL, '{"fiji islands",fiji-islands,fj,oceania,island,community,diaspora}', NULL, 'Oceania', 'Melanesia', NULL);
INSERT INTO public.spaces VALUES ('d031acbb-5556-4730-8e54-82b46abf060d', NULL, '00000000-0000-0000-0000-000000000060', 'Australia', 'australia', 'Every journey out of Oceania carries a story — of ambition, of longing, of roots that stretch but never break. From tropical rainforests and megadiverse landscapes to the cities where the diaspora now lives, the connection to home runs deep. Discover local businesses, share news from home, find events near you, and build a network that spans borders — all on JapaConnect.', '{"title": "Australia", "extract": "Australia, officially the Commonwealth of Australia, is a country comprising the mainland of the Australian continent, the island of Tasmania and numerous smaller islands. It has a land area of 7,688,287 km2 (2,968,464 sq mi), making it the sixth-largest country in the world, and is the world''s flattest and driest inhabited continent. It is a megadiverse country, and its size gives it a wide variety of landscapes and climates, including deserts in the interior and tropical rainforests along the coast.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/88/Flag_of_Australia_%28converted%29.svg/330px-Flag_of_Australia_%28converted%29.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Australia", "description": "Country in Oceania"}', 'f6214f55-4cb8-4606-ad32-1862801cc276', NULL, 'AU', 'country', 0, 0, 1, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:05.348503+01', NULL, NULL, '{australia,au,oceania,island,community,diaspora}', NULL, 'Oceania', 'Australia and New Zealand', NULL);
