INSERT INTO public.spaces VALUES ('e5bc78fd-8e1c-469c-afc3-c2341d1530db', NULL, '00000000-0000-0000-0000-000000000060', 'United Kingdom', 'united-kingdom', 'Your digital anchor in northwestern Europe — wherever the diaspora has settled, this is home base. Home to 69 million in 2024 people, with communities spread far beyond its borders. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "United Kingdom", "extract": "The United Kingdom of Great Britain and Northern Ireland, commonly known as the United Kingdom (UK) or Britain, is a country in northwestern Europe, off the coast of the continental mainland. It comprises England, Scotland, Wales and Northern Ireland, with a population of over 69 million in 2024. The UK includes the island of Great Britain, the north-eastern part of the island of Ireland, and most of the smaller islands within the British Isles, covering 94,354 square miles (244,376 km2). It shares a land border with the Republic of Ireland and is surrounded by the Atlantic Ocean, the North Sea, the English Channel, the Celtic Sea and the Irish Sea, while maintaining sovereignty over the Crown Dependencies and the British Overseas Territories. The capital and largest city of England and the UK is London; Edinburgh, Cardiff and Belfast are the national capitals of Scotland, Wales and Northern Ireland, respectively.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/a5/Flag_of_the_United_Kingdom_%281-2%29.svg/330px-Flag_of_the_United_Kingdom_%281-2%29.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/United_Kingdom", "description": "Country in northwestern Europe"}', '942d29e6-f63f-46e1-b666-3f32b25a4842', NULL, 'GB', 'country', 1, 0, 1, 'public', 'members', 'members', 'members', 'open', 'active', '2026-06-28 22:21:17.142323+01', '2026-08-07 11:45:56.790556+01', NULL, 'GBP', '{"united kingdom",united-kingdom,gb,europe,island,community,diaspora}', NULL, 'Europe', 'Northern Europe', NULL);
