INSERT INTO public.spaces VALUES ('056e664d-0221-4a78-a907-5acdd9521d5e', NULL, '00000000-0000-0000-0000-000000000060', 'Ghana', 'ghana', 'Every journey out of West Africa carries a story — of ambition, of longing, of roots that stretch but never break. From tropical rainforests to the cities where the diaspora now lives, the connection to home runs deep. Discover local businesses, share news from home, find events near you, and build a network that spans borders — all on JapaConnect.', '{"title": "Ghana", "extract": "Ghana, officially the Republic of Ghana, is a country in West Africa. It is situated with the Gulf of Guinea and the Atlantic Ocean to the south, and shares borders with Ivory Coast to the west, Burkina Faso to the north, and Togo to the east. Ghana covers an area of 239,567 km2 (92,497 sq mi), spanning various ecologies, from coastal savannas to tropical rainforests. With over 35 million inhabitants, Ghana is ranked the thirteenth-most populous country in Africa, and the second-most populous country in West Africa. The capital and most populous city is Accra.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/19/Flag_of_Ghana.svg/330px-Flag_of_Ghana.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Ghana", "description": "Country in West Africa"}', '226f475e-43b8-442c-aa05-b1931413f3db', NULL, 'GH', 'country', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'active', '2026-07-08 23:07:05.600578+01', '2026-08-07 11:44:39.641664+01', NULL, 'GHS', '{ghana,gh,africa,community,diaspora}', NULL, 'Africa', 'West Africa', NULL);
