INSERT INTO public.spaces VALUES ('ff8b4b63-260c-4e2a-9e40-ec3dad7c2008', NULL, '00000000-0000-0000-0000-000000000060', 'Finland', 'finland', 'From northern Europe to cities and towns across the globe — this is the gathering point for a diaspora that never lost touch with home. It is set in northern Europe, sharing borders with Sweden, Norway, Russia, and Bothnia, with Helsinki as its capital.', '{"title": "Finland", "extract": "Finland, officially the Republic of Finland, is a Nordic country in Northern Europe. It borders Sweden to the northwest, Norway to the north, and Russia to the east, with the Gulf of Bothnia to the west and the Gulf of Finland to the south, opposite Estonia. Its capital and largest city is Helsinki. Finland has a population of 5.7 million. The official languages are Finnish and Swedish, the mother tongues of 83.5 percent and 5.0 percent of the population, respectively. Finland''s climate varies from humid continental in the south to boreal in the north. Its land is predominantly covered by boreal forest, with over 180,000 recorded lakes.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/bc/Flag_of_Finland.svg/330px-Flag_of_Finland.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Finland", "description": "Country in northern Europe"}', '48344aed-a3a3-47c1-9631-118d3556c1fb', NULL, 'FI', 'country', 1, 0, 1, 'public', 'members', 'members', 'members', 'open', 'active', '2026-08-07 07:51:38.715002+01', '2026-08-07 11:44:35.612906+01', NULL, 'EUR', '{finland,fi,europe,community,diaspora}', NULL, 'Europe', 'Northern Europe', NULL);
INSERT INTO public.spaces VALUES ('6d0736d5-5920-4a6a-8959-6e712a54d797', NULL, '00000000-0000-0000-0000-000000000060', 'wop_f544abea-a58b-400d-911d-a5229f943c8e', 'wop-fad7f3e2e1ac4c5592af7d2f515d02e4', NULL, NULL, NULL, NULL, NULL, 'custom', 0, 0, 0, 'public', 'members', 'members', 'members', 'open', 'deleted', '2026-09-25 01:26:56.558486+01', '2026-09-25 01:26:56.558486+01', '2026-09-25 08:15:00.50165+01', NULL, '{}', NULL, NULL, NULL, NULL);
INSERT INTO public.spaces VALUES ('ea5563ad-2319-4945-8829-11424872c28f', NULL, '00000000-0000-0000-0000-000000000060', 'Nigeria', 'nigeria', 'Rooted in West Africa, sharing borders with Niger, Chad, Cameroon, and Benin, and reaching across continents — this space bridges home and diaspora. Abuja serves as the capital while Lagos leads in population; a population of 242 million calls it home. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "Nigeria", "extract": "Nigeria, officially the Federal Republic of Nigeria, is a country in West Africa between the Sahel to the north and the Gulf of Guinea in the Atlantic Ocean to the south. It covers an area of 923,769 square kilometres (356,669 mi2). With a population of more than 242 million, it is the most populous country in Africa, and the world''s sixth-most populous country. Nigeria borders Niger in the north, Chad in the northeast, Cameroon in the east, and Benin in the west. Nigeria is a federal republic comprising 36 states and the Federal Capital Territory, where its capital, Abuja, is located. The largest city in Nigeria by population is Lagos, one of the largest metropolitan areas in the world and the second largest in Africa.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/79/Flag_of_Nigeria.svg/330px-Flag_of_Nigeria.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Nigeria", "description": "Country in West Africa"}', 'ddef9162-cbc8-47b0-b109-4c632cbebf25', NULL, 'NG', 'country', 1, 0, 1, 'public', 'members', 'members', 'members', 'open', 'active', '2026-06-28 22:21:17.134648+01', '2026-08-07 11:45:17.978277+01', NULL, 'NGN', '{nigeria,ng,africa,community,diaspora}', NULL, 'Africa', 'West Africa', NULL);
INSERT INTO public.spaces VALUES ('4f145397-6349-4d6a-9fa8-ffdca5c70d7d', NULL, '00000000-0000-0000-0000-000000000060', 'Canada', 'canada', 'Rooted in North America, reaching across continents — this space bridges home and diaspora. A population of 41 million calls it home. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "Canada", "extract": "Canada is a country in North America. Its ten provinces and three territories extend from the Atlantic Ocean to the Pacific Ocean and northward into the Arctic Ocean, making it the second-largest country by total area, with the longest coastline of any country. Its border with the United States is the longest international land border. The country is characterized by a wide range of both meteorologic and geological regions. With a population of over 41 million, it has widely varying population densities, with the majority residing in its urban areas and large areas being sparsely populated. Its capital is Ottawa and its three largest metropolitan areas are Toronto, Montreal, and Vancouver.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d9/Flag_of_Canada_%28Pantone%29.svg/330px-Flag_of_Canada_%28Pantone%29.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Canada", "description": "Country in North America"}', 'bcef312d-3489-4586-95b5-5706d3f26b03', 'a792639c-2c28-4faa-8d98-8d7fe0af4b27', 'CA', 'country', 0, 0, 3, 'public', 'members', 'members', 'members', 'open', 'active', '2026-06-28 22:21:17.15339+01', '2026-08-07 11:44:17.966521+01', NULL, 'CAD', '{canada,ca,"north america",community,diaspora}', NULL, 'Americas', 'Northern America', NULL);
