INSERT INTO public.spaces VALUES ('414c2f7e-bb0e-4162-a8a0-291c6a4aff8b', NULL, '00000000-0000-0000-0000-000000000060', 'United States', 'united-states', 'Your digital anchor in North America — wherever the diaspora has settled, this is home base. A land of megadiverse landscapes, shaped by geography and history into something uniquely its own. Trade on the marketplace, join discussions, find local services, and keep up with news from back home.', '{"title": "United States", "extract": "The United States of America (USA), also known as the United States (U.S.) or America, is a country primarily located in North America. It is a federal republic consisting of 50 states and a federal capital district, Washington, D.C. The 48 contiguous states border Canada to the north and Mexico to the south, with the semi-exclave of Alaska in the northwest and the archipelago of Hawaii in the Pacific Ocean. The United States also asserts sovereignty over five major island territories and various uninhabited islands in Oceania and the Caribbean. It is a megadiverse country, with the world''s third-largest land area and third-largest population, exceeding 341 million.", "thumbnail": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/96/Flag_of_the_United_States_%28DDD-F-416E_specifications%29.svg/330px-Flag_of_the_United_States_%28DDD-F-416E_specifications%29.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/United_States", "description": "Country primarily in North America"}', '50c17253-cfbd-4a0a-8bbe-a3e59d59003e', NULL, 'US', 'country', -1, 0, 3, 'public', 'members', 'members', 'members', 'open', 'active', '2026-06-28 22:21:17.147609+01', '2026-08-07 11:45:57.295349+01', NULL, 'USD', '{"united states",united-states,us,"north america",island,community,diaspora}', NULL, 'Americas', 'Northern America', NULL);
INSERT INTO public.spaces VALUES ('0a43279d-6e89-41ec-950b-31e1a20cf78d', NULL, '00000000-0000-0000-0000-000000000060', 'Germany', 'germany', 'Rooted in Europe, sharing borders with Denmark, and reaching across continents — this space bridges home and diaspora. A population of 83 million calls it home. Connect with fellow travelers, share visa tips, compare cost of living, find community events, and stay anchored to home.', '{"title": "Germany", "extract": "Germany, officially the Federal Republic of Germany, is a country in Western and Central Europe. It lies between the Baltic Sea and the North Sea to the north with the Alps to the south. Its 16 constituent states have a total population of over 83 million, making it the most populous member state of the European Union (EU). Germany borders Denmark to the north; Poland and the Czech Republic to the east; Austria and Switzerland to the south; and France, Luxembourg, Belgium, and the Netherlands to the west. The nation''s capital and most populous city is Berlin and its main financial centre is Frankfurt; the largest urban area is the Ruhr.", "thumbnail": "https://upload.wikimedia.org/wikipedia/en/thumb/b/ba/Flag_of_Germany.svg/330px-Flag_of_Germany.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "content_url": "https://en.wikipedia.org/wiki/Germany", "description": "Country in Europe"}', 'c5460f99-06db-4c24-b19b-778f4c1a1ced', NULL, 'DE', 'country', 0, 0, 2, 'public', 'members', 'members', 'members', 'open', 'active', '2026-07-08 23:07:05.600578+01', '2026-08-07 11:44:39.134591+01', NULL, 'EUR', '{germany,de,europe,community,diaspora}', NULL, 'Europe', 'Western Europe', NULL);
