INSERT INTO public.ai_tools VALUES ('80c497d2-070d-4381-a9db-ed52dc1cddcd', 'moderation.detect_spam', 'AI-powered semantic spam classification via the moderation gateway category. Catches scam pitches, social engineering, and promotional flooding that rule-based layers miss.', 'moderation', '{}', true, NULL, '2026-08-05 15:31:14.529284+01', '2026-08-05 15:31:14.529284+01');
INSERT INTO public.ai_tools VALUES ('3ee9a0b6-7d75-4983-bdf9-12a2d019dd04', 'content.search', 'Search site content by query. Returns matching content items with title, slug, status, and geo scope. When geo_space_id is provided, results are scoped to that space. Exempt content is filtered post-query.', 'agent_content', '{"handler": "ContentSearch", "is_blocked": false, "parameters": {"type": "object", "required": ["query"], "properties": {"limit": {"type": "integer", "description": "Max results (default 10, max 50)"}, "query": {"type": "string", "description": "Search query"}, "geo_space_id": {"type": "string", "description": "Optional geo scope (space UUID)"}}}, "description": "Search site content by query. Returns matching content items.", "function_name": "content.search", "requires_hitl": false, "reads_user_data": false, "writes_user_data": false}', true, NULL, '2026-08-11 21:11:11.755135+01', '2026-08-11 21:11:11.755135+01');
INSERT INTO public.ai_tools VALUES ('254d8377-24c3-430f-a655-9361a0fd5650', 'content.read', 'Read a single content record by ID, including its non-exempt custom field values. Content marked ai_exempt is blocked by the privacy gate.', 'agent_content', '{"handler": "ContentRead", "is_blocked": false, "parameters": {"type": "object", "required": ["content_id"], "properties": {"content_id": {"type": "string", "description": "Content UUID"}}}, "description": "Read a content record and its custom field values.", "function_name": "content.read", "requires_hitl": false, "reads_user_data": true, "writes_user_data": false}', true, NULL, '2026-08-11 21:11:11.755135+01', '2026-08-11 21:11:11.755135+01');
INSERT INTO public.ai_tools VALUES ('4c04b9fc-371e-4385-9f24-e1a9c29af6eb', 'content.update', 'Update an existing content record. Only the fields provided in the arguments are changed. Content marked ai_exempt is blocked.', 'agent_content', '{"handler": "ContentUpdate", "is_blocked": false, "parameters": {"type": "object", "required": ["content_id"], "properties": {"body": {"type": "string", "description": "New body"}, "slug": {"type": "string", "description": "New slug"}, "title": {"type": "string", "description": "New title"}, "status": {"type": "string", "description": "New status"}, "content_id": {"type": "string", "description": "Content UUID"}, "field_values": {"type": "object", "description": "Updated field values"}, "geo_space_id": {"type": "string", "description": "New geo scope"}}}, "description": "Update an existing content record.", "function_name": "content.update", "requires_hitl": true, "reads_user_data": true, "writes_user_data": true}', true, 'content.update', '2026-08-11 21:11:11.755135+01', '2026-08-11 21:11:11.755135+01');
INSERT INTO public.ai_tools VALUES ('0a8fd524-63c9-4093-86fe-a1cf64dea59d', 'custom_fields.list', 'List field definitions for a custom field group. Returns field key, label, type, and validation flags.', 'agent_fields', '{"handler": "CustomFieldsList", "is_blocked": false, "parameters": {"type": "object", "required": ["group_id"], "properties": {"group_id": {"type": "string", "description": "Custom field group UUID"}}}, "description": "List custom field definitions for a group.", "function_name": "custom_fields.list", "requires_hitl": false, "reads_user_data": false, "writes_user_data": false}', true, NULL, '2026-08-11 21:11:11.755135+01', '2026-08-11 21:11:11.755135+01');
INSERT INTO public.ai_tools VALUES ('d8fed0c6-ea2a-4937-bf24-daab29042e78', 'custom_field_values.read', 'Read custom field values for an entity. Values marked ai_exempt are filtered out.', 'agent_fields', '{"handler": "CFVRead", "is_blocked": false, "parameters": {"type": "object", "required": ["entity_type", "entity_id"], "properties": {"entity_id": {"type": "string", "description": "Entity UUID"}, "entity_type": {"type": "string", "description": "Entity type (content, user, organization)"}}}, "description": "Read custom field values for an entity (privacy-filtered).", "function_name": "custom_field_values.read", "requires_hitl": false, "reads_user_data": true, "writes_user_data": false}', true, NULL, '2026-08-11 21:11:11.755135+01', '2026-08-11 21:11:11.755135+01');
INSERT INTO public.ai_tools VALUES ('33604df8-9a45-4e94-bfa0-0eff211c4c91', 'custom_field_values.set', 'Set a single custom field value. The target entity is privacy-checked before the write.', 'agent_fields', '{"handler": "CFVSet", "is_blocked": false, "parameters": {"type": "object", "required": ["field_id", "entity_type", "entity_id"], "properties": {"field_id": {"type": "string", "description": "Field definition UUID"}, "entity_id": {"type": "string", "description": "Entity UUID"}, "value_bool": {"type": "boolean", "description": "Boolean value"}, "value_date": {"type": "string", "description": "Date value (RFC 3339)"}, "value_json": {"type": "object", "description": "JSON value"}, "value_text": {"type": "string", "description": "Text value"}, "entity_type": {"type": "string", "description": "Entity type"}, "value_number": {"type": "number", "description": "Numeric value (integer or decimal). Use for numeric fields such as salary_min, salary_max, or any custom field with field_type=number."}}}, "description": "Set a single custom field value. The target entity is privacy-checked before the write.", "function_name": "custom_field_values.set", "requires_hitl": false, "reads_user_data": true, "writes_user_data": true}', true, 'content.update', '2026-08-11 21:11:11.755135+01', '2026-08-11 21:11:11.755135+01');
INSERT INTO public.ai_tools VALUES ('aead6bab-4703-46e8-bd60-90cfe78bb054', 'rag.search', 'Search the knowledge base via vector retrieval. When geo_space_id is provided, results are geo-filtered. Exempt content is filtered post-retrieval.', 'agent_knowledge', '{"handler": "RAGSearch", "is_blocked": false, "parameters": {"type": "object", "required": ["query"], "properties": {"limit": {"type": "integer", "description": "Max results"}, "query": {"type": "string", "description": "Search query"}, "language": {"type": "string", "description": "Language code (default: en)"}, "geo_space_id": {"type": "string", "description": "Optional geo scope"}}}, "description": "Search the knowledge base (geo-filtered vector retrieval).", "function_name": "rag.search", "requires_hitl": false, "reads_user_data": false, "writes_user_data": false}', true, NULL, '2026-08-11 21:11:11.755135+01', '2026-08-11 21:11:11.755135+01');
INSERT INTO public.ai_tools VALUES ('a21ac4e8-f7ff-4950-b5b2-1a5c5a38d454', 'comparison.add_dimension', 'Add one or more dimensions to an existing comparison content row (Tier 2 — semi-structured). Use after comparison.types.list identifies a type that is missing requested dimensions.', 'agent_comparison', '{"handler": "ComparisonAddDimension", "is_blocked": false, "parameters": {"type": "object", "required": ["content_id", "dimensions"], "properties": {"content_id": {"type": "string", "description": "Comparison content UUID"}, "dimensions": {"type": "array", "items": {"type": "object", "required": ["label"], "properties": {"label": {"type": "string", "description": "Dimension label"}, "dimension_type": {"type": "string", "description": "Dimension type: text|rating|boolean|number|currency (default text)"}}}, "description": "Dimensions to add"}}}, "description": "Add dimensions to an existing comparison.", "function_name": "comparison.add_dimension", "requires_hitl": true, "reads_user_data": false, "writes_user_data": true}', true, 'comparison.dimension.manage', '2026-08-11 21:11:11.823732+01', '2026-08-11 21:11:11.823732+01');
INSERT INTO public.ai_tools VALUES ('54570c2e-6450-4d1f-9a28-b93848003396', 'comparison.read', 'Read a comparison with its full items x dimensions value matrix. Returns the parent content metadata, items, dimensions, and all cell values. Content marked ai_exempt is blocked by the privacy gate.', 'agent_comparison', '{"handler": "ComparisonRead", "is_blocked": false, "parameters": {"type": "object", "required": ["content_id"], "properties": {"content_id": {"type": "string", "description": "Comparison content UUID"}}}, "description": "Read a comparison with its full value matrix.", "function_name": "comparison.read", "requires_hitl": false, "reads_user_data": true, "writes_user_data": false}', true, NULL, '2026-08-11 21:11:11.823732+01', '2026-08-11 21:11:11.823732+01');
INSERT INTO public.ai_tools VALUES ('455c969d-1f67-42b8-b6f0-acd43bf9a27a', 'comparison.create', 'Create a new comparison content row with items and dimensions. When create_type is provided, a new comparison type definition is created first (Tier 3). When entity_type references an existing type slug, the comparison is linked to it (Tier 2). The status is always draft — the agent never publishes directly.', 'agent_comparison', '{"handler": "ComparisonCreate", "is_blocked": false, "parameters": {"type": "object", "required": ["title", "items"], "properties": {"body": {"type": "string", "description": "Comparison body (markdown, optional)"}, "depth": {"type": "string", "description": "JCE comparison depth: ''quick'' or ''detailed'' (optional; default ''quick'' when item_ref is present)"}, "items": {"type": "array", "items": {"type": "object", "required": ["name"], "properties": {"name": {"type": "string"}, "slug": {"type": "string"}, "item_ref": {"type": "object", "description": "Polymorphic JCE item reference, e.g. {\"type\":\"university\", \"id\":\"...\"}"}}}, "description": "Items to compare"}, "title": {"type": "string", "description": "Comparison title"}, "space_id": {"type": "string", "description": "Optional space UUID"}, "dimensions": {"type": "array", "items": {"type": "string"}, "description": "Dimension labels"}, "visibility": {"type": "string", "description": "Visibility (default members)"}, "create_type": {"type": "object", "required": ["name", "slug"], "properties": {"name": {"type": "string"}, "slug": {"type": "string"}, "item_label": {"type": "string"}, "description": {"type": "string"}}, "description": "Create a new comparison type definition (Tier 3)"}, "entity_type": {"type": "string", "description": "Slug of an existing comparison type to link (optional)"}}}, "description": "Create a new comparison with items and dimensions.", "function_name": "comparison.create", "requires_hitl": true, "reads_user_data": false, "writes_user_data": true}', true, 'comparison.create', '2026-08-11 21:11:11.823732+01', '2026-08-11 21:11:11.823732+01');
INSERT INTO public.ai_tools VALUES ('d81ff67e-53f1-49ab-afcb-b835d172890e', 'comparison.types.list', 'List comparison type definitions (e.g. universities, visa-types, banks). Use this to discover existing types before creating a new comparison.', 'agent_comparison', '{"handler": "ComparisonTypesList", "is_blocked": false, "parameters": {"type": "object", "required": [], "properties": {"limit": {"type": "integer", "description": "Max results (default 50, max 100)"}, "offset": {"type": "integer", "description": "Pagination offset (default 0)"}}}, "description": "List comparison type definitions.", "function_name": "comparison.types.list", "requires_hitl": false, "reads_user_data": false, "writes_user_data": false}', true, NULL, '2026-08-11 21:11:11.823732+01', '2026-09-25 10:59:40.038759+01');
