INSERT INTO public.ai_tools VALUES ('9dc65ef0-1d7c-4ee7-81f6-46e9dcfa37d8', 'external.search', 'Search the web via Tavily, Brave, or Perplexity (configurable via agent.external_search_provider). Results are cached for 30 minutes. Requires agent.external_search permission.', 'agent_knowledge', '{"handler": "ExternalSearch", "is_blocked": false, "parameters": {"type": "object", "required": ["query"], "properties": {"limit": {"type": "integer", "description": "Max results (default 5, max 20)"}, "query": {"type": "string", "description": "Web search query"}}}, "description": "Search the web when internal knowledge is insufficient. Provider is configurable via agent.external_search_provider (tavily, brave, or perplexity).", "function_name": "external.search", "requires_hitl": false, "reads_user_data": false, "writes_user_data": false}', true, 'agent.external_search', '2026-08-11 21:11:11.755135+01', '2026-08-17 18:20:31.096107+01');
