INSERT INTO public.ai_tools VALUES ('3af98626-36b8-4a40-b42e-a2698a16e583', 'tools.read', 'Read a tool details. DISABLED — the backing tools table does not exist yet (§78 discrepancy).', 'agent_tools', '{"handler": "ToolsRead", "is_blocked": false, "parameters": {"type": "object", "required": ["tool_id"], "properties": {"tool_id": {"type": "string", "description": "Tool UUID"}}}, "description": "Read a tool details.", "function_name": "tools.read", "requires_hitl": false, "reads_user_data": false, "writes_user_data": false}', false, NULL, '2026-08-11 21:11:11.90418+01', '2026-09-01 06:08:34.404074+01');
INSERT INTO public.ai_tools VALUES ('02882711-0e44-4a59-be63-0d911658f7f5', 'comparison.fill_values', 'Fill comparison values for items x dimensions. Each value records its source (custom_field, rag, external, or llm_knowledge), source_ref, confidence, and retrieved_at timestamp. When source is "external", set source_ref to the most relevant URL from the external.search result citations array.', 'agent_comparison', '{"handler": "ComparisonFillValues", "is_blocked": false, "parameters": {"type": "object", "required": ["content_id", "values"], "properties": {"values": {"type": "array", "items": {"type": "object", "required": ["dimension_id", "item_id", "source"], "properties": {"value": {"type": "string", "description": "Text value"}, "source": {"type": "string", "description": "Provenance source: custom_field|rag|external|llm_knowledge"}, "item_id": {"type": "string", "description": "Item UUID"}, "confidence": {"type": "string", "description": "Confidence level: high|medium|low"}, "source_ref": {"type": "string", "description": "Source reference: URL from external.search citations, content UUID for rag, or custom_field_values UUID"}, "dimension_id": {"type": "string", "description": "Dimension UUID"}, "value_rating": {"type": "number", "description": "Numeric rating value"}, "value_boolean": {"type": "boolean", "description": "Boolean value"}}}, "description": "Values to fill"}, "content_id": {"type": "string", "description": "Comparison content UUID"}}}, "description": "Fill comparison values with provenance metadata. When source is external, use the most relevant URL from the external.search result citations array as source_ref.", "function_name": "comparison.fill_values", "requires_hitl": false, "reads_user_data": false, "writes_user_data": true}', true, 'comparison.value.manage', '2026-08-11 21:11:11.823732+01', '2026-08-17 18:20:31.103354+01');
INSERT INTO public.ai_tools VALUES ('27935d66-d8b6-4502-ad92-e604f7c4bf39', 'source.crawl_now', 'Enqueue an immediate crawl for a single enabled intelligence source. The crawl runs asynchronously through the intel:fetch_source worker.', 'agent_intelligence', '{"handler": "SourceCrawlNow", "is_blocked": false, "parameters": {"type": "object", "required": ["source_id"], "properties": {"source_id": {"type": "string", "description": "UUID of the intel source to crawl"}}}, "description": "Enqueue an immediate crawl for a single enabled intelligence source.", "function_name": "source.crawl_now", "requires_hitl": false, "reads_user_data": false, "writes_user_data": false}', true, 'agent.source.crawl_now', '2026-08-19 11:12:33.527544+01', '2026-08-19 11:12:33.527544+01');
INSERT INTO public.ai_tools VALUES ('04c600ab-e85f-4ea3-9422-d752f0d87b2d', 'record.update_now', 'Resolve an intel record or source and enqueue the full intelligence fetch/change-detection/extraction/promotion chain. If record_id is provided, the source is read from the record; otherwise source_id is used directly.', 'agent_intelligence', '{"handler": "RecordUpdateNow", "is_blocked": false, "parameters": {"type": "object", "required": [], "properties": {"record_id": {"type": "string", "description": "Optional UUID of the intel record to refresh"}, "source_id": {"type": "string", "description": "Optional UUID of the source to crawl directly"}}}, "description": "Resolve an intel record or source and enqueue the full update chain.", "function_name": "record.update_now", "requires_hitl": false, "reads_user_data": false, "writes_user_data": false}', true, 'agent.record.update_now', '2026-08-19 11:12:33.527544+01', '2026-08-19 11:12:33.527544+01');
INSERT INTO public.ai_tools VALUES ('23fc5355-5352-460d-abca-26e4254c9d98', 'content.regenerate_from_source', 'Enqueue the content:regenerate_from_source worker to rewrite an existing contents row from a linked intelligence record extraction. Respects HITL, high-stakes, and manual-edit guards.', 'agent_intelligence', '{"handler": "ContentRegenerateFromSource", "is_blocked": false, "parameters": {"type": "object", "required": ["content_id", "intel_record_id"], "properties": {"content_id": {"type": "string", "description": "UUID of the contents row to regenerate"}, "intel_record_id": {"type": "string", "description": "UUID of the intelligence record whose extraction supplies the facts"}}}, "description": "Rewrite an existing contents row from a linked intelligence record extraction.", "function_name": "content.regenerate_from_source", "requires_hitl": false, "reads_user_data": false, "writes_user_data": true}', true, 'content.regenerate', '2026-08-19 11:12:33.527544+01', '2026-08-19 11:12:33.527544+01');
INSERT INTO public.ai_tools VALUES ('8a2c6bec-6905-4cfa-b000-08908e4aab3c', 'attestation_guide.create', 'Create a new Attestation Guides record.', 'agent_immigration', '{"handler": "attestation_guide.create", "parameters": {"type": "object", "properties": {"payload": {"type": "object", "description": "Tool record fields", "additionalProperties": true}}, "description": "Fields for the new Attestation Guides record", "additionalProperties": true}, "description": "Create a Attestation Guides record", "function_name": "attestation_guide.create", "requires_hitl": false, "writes_user_data": true}', true, 'attestation.manage', '2026-08-24 15:05:59.369738+01', '2026-08-24 15:05:59.369738+01');
INSERT INTO public.ai_tools VALUES ('0a68f896-058a-4081-8532-a899bc73abf7', 'scholarship.search', 'Search the scholarships projection table. Returns scholarship records with id, guide_id, intel_record_id, title, slug, country, level of study, award amount, deadline, application URL, and institution. Use this to find scholarships before refreshing their sources or regenerating content.', 'agent_intelligence', '{"handler": "ScholarshipSearch", "is_blocked": false, "parameters": {"type": "object", "required": [], "properties": {"level": {"type": "string", "description": "Filter by level of study (e.g. undergraduate, masters, phd)"}, "limit": {"type": "integer", "description": "Max results (default 20, max 50)"}, "country": {"type": "string", "description": "Filter by country code or name (e.g. NGA)"}, "funding_type": {"type": "string", "description": "Filter by funding type keywords"}, "deadline_after": {"type": "string", "description": "Only return scholarships with deadlines on or after this date (YYYY-MM-DD)"}, "eligible_countries": {"type": "string", "description": "Filter by additional eligible countries"}}}, "description": "Search the scholarships projection table for matching records.", "function_name": "scholarship.search", "requires_hitl": false, "reads_user_data": false, "writes_user_data": false}', true, 'agent.scholarship.search', '2026-08-19 11:27:33.949399+01', '2026-08-19 11:27:33.949399+01');
INSERT INTO public.ai_tools VALUES ('11ef3876-d4a2-46f7-94b5-5ba37f9656ac', 'source.discover', 'Search the web for candidate intelligence sources and create them with status=proposed, enabled=false for admin review. Optionally auto-enables high-trust sources when agent.auto_enable_discovered_sources is true.', 'agent_intelligence', '{"handler": "SourceDiscover", "is_blocked": false, "parameters": {"type": "object", "required": ["query"], "properties": {"limit": {"type": "integer", "description": "Max candidate results (default 5, max 20)"}, "query": {"type": "string", "description": "Search query describing the kind of source to find (e.g. \"scholarships in Nigeria 2026\")"}, "country": {"type": "string", "description": "Optional country filter for the search"}, "category": {"type": "string", "description": "Optional category for the discovered source (e.g. scholarship, job, guide)"}}}, "description": "Search the web for candidate intelligence sources and propose them for admin review.", "function_name": "source.discover", "requires_hitl": false, "reads_user_data": false, "writes_user_data": true}', true, 'agent.source.discover', '2026-08-19 11:51:31.129586+01', '2026-08-19 11:51:31.129586+01');
