INSERT INTO public.ai_tools VALUES ('a0d7838b-943a-4e92-a251-cc0c35db3e48', 'personas.create', 'Create one or more AI personas. Each persona receives a name, slug, tagline, voice prompt, and activity policy. Use when the campaign plan needs additional personas.', 'agent_persona', '{"handler": "PersonasCreate", "is_blocked": false, "parameters": {"type": "object", "required": ["personas"], "properties": {"personas": {"type": "array", "items": {"type": "object", "required": ["name", "slug", "tagline", "voice_prompt"], "properties": {"name": {"type": "string", "description": "Display name of the persona"}, "slug": {"type": "string", "description": "URL-safe unique slug"}, "tagline": {"type": "string", "description": "Short professional tagline"}, "role_focus": {"type": "string", "description": "Primary role focus (e.g. immigration_lawyer, travel_blogger)"}, "voice_prompt": {"type": "string", "description": "Voice and tone guidance for content generation"}}}, "description": "List of persona definitions to create"}}}, "description": "Create one or more AI personas with complete identities.", "function_name": "personas.create", "requires_hitl": false, "reads_user_data": false, "writes_user_data": true}', true, 'persona.manage', '2026-08-26 17:33:23.401775+01', '2026-08-26 17:33:23.401775+01');
INSERT INTO public.ai_tools VALUES ('092c0ab1-93af-4a8f-a4c0-fee1519dad03', 'content.campaign.create', 'Plan and optionally run a multi-piece content campaign. Expands the user brief into the requested number of unique content items, auto-provisions missing personas, assigns one distinct persona to each item, and dispatches them through the Studio review pipeline. Returns the campaign summary and status.', 'agent_content', '{"handler": "ContentCampaignCreate", "is_blocked": false, "parameters": {"type": "object", "required": ["prompt"], "properties": {"count": {"type": "integer", "description": "Number of content pieces to generate (1-50, default 1)"}, "prompt": {"type": "string", "description": "High-level campaign brief"}, "auto_assign": {"type": "boolean", "description": "Allow AI to assign personas (default true)"}, "persona_ids": {"type": "array", "items": {"type": "string"}, "description": "Optional list of persona UUIDs to use; omit for auto-assignment"}, "target_tags": {"type": "array", "items": {"type": "string"}, "description": "Optional tag names"}, "content_type": {"type": "string", "description": "Optional content type (blog, story, guide, discussion, reply); omit to let the planner infer mixed types"}, "run_immediately": {"type": "boolean", "description": "Run the campaign after planning (default false)"}, "target_space_id": {"type": "string", "description": "Optional target space UUID"}, "auto_provision_personas": {"type": "boolean", "description": "Create missing personas automatically (default true)"}}}, "description": "Create and optionally run a multi-piece content campaign with one persona per item.", "function_name": "content.campaign.create", "requires_hitl": false, "reads_user_data": false, "writes_user_data": true}', true, 'campaign.create', '2026-08-26 17:33:23.401775+01', '2026-08-26 17:33:23.401775+01');
INSERT INTO public.ai_tools VALUES ('08bdfc1d-2fbe-458f-9f09-5be43cdbf608', 'content.create', 'Create new content. The agent injects _ai_provenance metadata into field_values for transparency. Content is always created as draft — the agent never publishes directly. Set guide_category when content_type is "guide".', 'agent_content', '{"handler": "ContentCreate", "is_blocked": false, "parameters": {"type": "object", "required": ["title", "content_type"], "properties": {"body": {"type": "string", "description": "Content body (markdown)"}, "title": {"type": "string", "description": "Content title"}, "space_id": {"type": "string", "description": "Optional space"}, "author_id": {"type": "string", "description": "Author UUID (defaults to calling user)"}, "publish_at": {"type": "string", "description": "Optional RFC 3339 timestamp to schedule future publishing. For events this can represent the event start time."}, "content_type": {"type": "string", "description": "Content type (e.g. blog_post, guide, comparison, page, discussion, service_listing, story, achievement, job_listing, event). Call content_types.list to discover valid types and their custom field group entity classes."}, "field_values": {"type": "object", "description": "Free-form JSONB for the contents.field_values column (e.g. page builder blocks, _ai_provenance). NOT for structured custom field values — use custom_field_values.bulk_set after content creation."}, "geo_space_id": {"type": "string", "description": "Optional geo scope"}, "guide_category": {"type": "string", "description": "Guide category slug. Required when content_type is ''guide''. Call guide_categories.list to discover valid slugs and their custom field group IDs."}, "organization_id": {"type": "string", "description": "Optional organization UUID. Useful for job_listings and service_listings posted on behalf of an org (requires the author to be an owner/admin/editor of that org)."}}}, "description": "Create new content with AI provenance metadata. Content is always created as draft.", "function_name": "content.create", "requires_hitl": true, "reads_user_data": false, "writes_user_data": true}', true, 'content.create', '2026-08-11 21:11:11.755135+01', '2026-08-11 21:11:11.755135+01');
INSERT INTO public.ai_tools VALUES ('e1e1ee47-1815-44c7-8a29-ef36f0d6231d', 'content.list', 'List content by type (or across all types when content_type is empty). Exempt content is filtered post-query.', 'agent_content', '{"handler": "ContentList", "is_blocked": false, "parameters": {"type": "object", "properties": {"limit": {"type": "integer", "description": "Max results (default 20, max 50)"}, "content_type": {"type": "string", "description": "Content type filter (optional)"}}}, "description": "List content by type or across all types.", "function_name": "content.list", "requires_hitl": false, "reads_user_data": false, "writes_user_data": false}', true, NULL, '2026-08-11 21:11:11.90418+01', '2026-09-25 10:59:40.038759+01');
INSERT INTO public.ai_tools VALUES ('16429f8d-42c2-4112-9de2-b92f7b96a1ad', 'content.create_draft', 'Create a draft content row for admin review. Use this when pre-search found nothing and the user lacks content.create permission. The author is the AI persona (not the calling user); status is always draft. A HITL review is created. Set guide_category when content_type is "guide".', 'agent_content', '{"handler": "ContentCreateDraft", "is_blocked": false, "parameters": {"type": "object", "required": ["title", "content_type", "body"], "properties": {"body": {"type": "string", "description": "Content body (markdown), synthesized from external search results + RAG"}, "title": {"type": "string", "description": "Content title"}, "space_id": {"type": "string", "description": "Optional space"}, "author_id": {"type": "string", "description": "AI persona backing user UUID (resolved by the agent loop from agent.default_persona_id; the tool ignores any other value)"}, "publish_at": {"type": "string", "description": "Optional RFC 3339 timestamp to schedule future publishing. For events this can represent the event start time."}, "content_type": {"type": "string", "description": "Content type (e.g. blog_post, guide, comparison, page, discussion, service_listing, story, achievement, job_listing, event). Call content_types.list to discover valid types and their custom field group entity classes."}, "field_values": {"type": "object", "description": "Free-form JSONB for the contents.field_values column (e.g. page builder blocks, _ai_provenance). NOT for structured custom field values — use custom_field_values.bulk_set after content creation."}, "geo_space_id": {"type": "string", "description": "Optional geo scope"}, "ai_persona_id": {"type": "string", "description": "The AI persona UUID (from agent.default_persona_id). Pass this so the draft records which persona authored it."}, "guide_category": {"type": "string", "description": "Guide category slug. Required when content_type is ''guide''. Call guide_categories.list to discover valid slugs and their custom field group IDs."}, "organization_id": {"type": "string", "description": "Optional organization UUID. Useful for job_listings and service_listings posted on behalf of an org (requires the author to be an owner/admin/editor of that org)."}, "original_prompt": {"type": "string", "description": "The original user prompt that triggered this draft (for provenance)"}}}, "description": "Create a draft content row for admin review (agent.draft_request path). Author is the AI persona; status is forced to draft; a HITL review is created.", "function_name": "content.create_draft", "requires_hitl": true, "reads_user_data": false, "writes_user_data": true}', true, 'agent.draft_request', '2026-08-11 21:11:11.84557+01', '2026-08-11 21:11:11.84557+01');
INSERT INTO public.ai_tools VALUES ('13ba0969-eb33-42b6-9ec1-989eb1b4a500', 'custom_field_values.bulk_set', 'Set multiple custom field values for a single entity in one call. Per-field status is reported. Bulk operations are HITL-queued.', 'agent_fields', '{"handler": "CFVBulkSet", "is_blocked": false, "parameters": {"type": "object", "required": ["entity_type", "entity_id", "values"], "properties": {"values": {"type": "array", "items": {"type": "object", "required": ["field_id"], "properties": {"field_id": {"type": "string", "description": "Field definition UUID"}, "value_bool": {"type": "boolean"}, "value_date": {"type": "string"}, "value_json": {"type": "object"}, "value_text": {"type": "string"}, "value_number": {"type": "number", "description": "Numeric value (integer or decimal). Use for numeric fields such as salary_min, salary_max."}}}, "description": "Field value entries"}, "entity_id": {"type": "string", "description": "Entity UUID"}, "entity_type": {"type": "string", "description": "Entity type"}}}, "description": "Set multiple custom field values for an entity.", "function_name": "custom_field_values.bulk_set", "requires_hitl": true, "reads_user_data": true, "writes_user_data": true}', true, 'content.update', '2026-08-11 21:11:11.755135+01', '2026-08-11 21:11:11.755135+01');
INSERT INTO public.ai_tools VALUES ('4b3b5a5c-fe88-44d8-9889-80db225fb8c5', 'custom_field_groups.list', 'List custom field groups.', 'agent_custom_fields', '{"handler": "CustomFieldGroupsList", "is_blocked": false, "parameters": {"type": "object", "properties": {}}, "description": "List custom field groups.", "function_name": "custom_field_groups.list", "requires_hitl": false, "reads_user_data": false, "writes_user_data": false}', true, NULL, '2026-08-11 21:11:11.90418+01', '2026-09-25 10:59:40.038759+01');
INSERT INTO public.ai_tools VALUES ('61c22f53-a9e4-4ea1-b538-61b7643a2091', 'content_types.list', 'List valid content types. Returns content_type, label, has_category, category_list_tool, field_group_entity_class, field_group_id, and field_group_slug. Use this before creating any content.', 'agent_content', '{"handler": "ContentTypesList", "is_blocked": false, "parameters": {"type": "object", "properties": {}}, "description": "List valid content types and their custom field group hints.", "function_name": "content_types.list", "requires_hitl": false, "reads_user_data": false, "writes_user_data": false}', true, NULL, '2026-08-26 17:33:23.439858+01', '2026-09-25 10:59:40.038759+01');
INSERT INTO public.ai_tools VALUES ('269dc44c-ca02-49af-b0d0-45274ba88b15', 'guide_categories.list', 'List admin-configured guide categories and their custom field group IDs. Use before creating guide content so the correct guide_category and field group are known.', 'agent_content', '{"handler": "GuideCategoriesList", "is_blocked": false, "parameters": {"type": "object", "properties": {}}, "description": "List admin-configured guide categories. Returns slug, label, is_system, group_id, and group_slug. Use the group_id with custom_fields.list to discover the category''s field definitions.", "function_name": "guide_categories.list", "requires_hitl": false, "reads_user_data": false, "writes_user_data": false}', true, NULL, '2026-08-26 17:33:23.420054+01', '2026-09-25 10:59:40.038759+01');
INSERT INTO public.ai_tools VALUES ('0615d70c-3668-4ac7-aec0-5445d4caffa4', 'content.bulk_create', 'Create multiple content rows in one call. Each item supports author_id, organization_id, publish_at, guide_category, and field_values. HITL-queued as a bulk operation.', 'agent_content', '{"handler": "ContentBulkCreate", "is_blocked": false, "parameters": {"type": "object", "required": ["items"], "properties": {"items": {"type": "array", "items": {"type": "object", "required": ["title", "content_type"], "properties": {"body": {"type": "string", "description": "Content body"}, "title": {"type": "string", "description": "Content title"}, "space_id": {"type": "string", "description": "Space UUID"}, "author_id": {"type": "string", "description": "Author UUID (defaults to calling user; requires content.assign_author to override)"}, "publish_at": {"type": "string", "description": "Publish timestamp (RFC 3339)"}, "content_type": {"type": "string", "description": "Content type slug (e.g. blog_post, job_listing, guide)"}, "field_values": {"type": "object", "description": "Free-form JSONB for contents.field_values"}, "geo_space_id": {"type": "string", "description": "Geo space UUID"}, "guide_category": {"type": "string", "description": "Guide category slug (when content_type = guide)"}, "organization_id": {"type": "string", "description": "Organization UUID (author must be an org owner/admin/editor)"}}}, "description": "Content items to create"}}}, "description": "Create multiple content rows in one call.", "function_name": "content.bulk_create", "requires_hitl": true, "reads_user_data": false, "writes_user_data": true}', true, 'content.create', '2026-08-26 17:33:23.450112+01', '2026-08-26 17:33:23.450112+01');
INSERT INTO public.ai_tools VALUES ('23002fee-3739-4796-bd29-5e56e64b79ad', 'persona_voices.read', 'Read a single shared persona voice by id or slug, including the full voice_prompt used as tone guidance for content generation.', 'agent_persona', '{"handler": "PersonaVoicesRead", "is_blocked": false, "parameters": {"type": "object", "properties": {"id": {"type": "string", "description": "Voice UUID"}, "slug": {"type": "string", "description": "Voice slug (used when id is not provided)"}}}, "description": "Read a single shared persona voice including its voice_prompt.", "function_name": "persona_voices.read", "requires_hitl": false, "reads_user_data": false, "writes_user_data": false}', true, 'persona.view', '2026-09-23 23:32:25.226162+01', '2026-09-23 23:32:25.226162+01');
INSERT INTO public.ai_tools VALUES ('809bb7ee-cf6d-45bf-a006-6c1fa7fda6de', 'content.bulk_publish', 'Change the status of multiple content rows in one call. Defaults to "published". HITL-queued as a bulk operation.', 'agent_content', '{"handler": "ContentBulkPublish", "is_blocked": false, "parameters": {"type": "object", "required": ["content_ids"], "properties": {"status": {"type": "string", "description": "Target status (default published)"}, "content_ids": {"type": "array", "items": {"type": "string"}, "description": "Content UUIDs"}}}, "description": "Publish or transition the status of multiple content rows in one call.", "function_name": "content.bulk_publish", "requires_hitl": true, "reads_user_data": false, "writes_user_data": true}', true, 'content.publish', '2026-08-26 17:33:23.450112+01', '2026-08-26 17:33:23.450112+01');
INSERT INTO public.ai_tools VALUES ('a8a0d479-d3e1-4257-b330-799dc9adddcb', 'comparison.analyze', 'Analyze a comparison against the user profile and return a ranked, explained answer with next actions.', 'agent_comparison', '{"handler": "JCEAnalyze", "is_blocked": false, "parameters": {"type": "object", "required": ["content_id"], "properties": {"question": {"type": "string", "description": "User question, e.g. Which is best for me?"}, "content_id": {"type": "string", "description": "Comparison content UUID"}, "profile_id": {"type": "string", "description": "Optional comparison profile UUID"}}}, "description": "Analyze a comparison and profile, return scores/explanations and next actions.", "function_name": "comparison.analyze", "requires_hitl": false, "reads_user_data": true, "writes_user_data": false}', true, 'jce.ai_advisor.use', '2026-08-31 02:25:17.674821+01', '2026-08-31 02:25:17.674821+01');
INSERT INTO public.ai_tools VALUES ('a4072b6b-4d22-4153-a798-79f4adcd97b8', 'comparison.rank', 'Rank comparison items with reasoning and confidence.', 'agent_comparison', '{"handler": "JCERank", "is_blocked": false, "parameters": {"type": "object", "required": ["content_id"], "properties": {"content_id": {"type": "string"}, "profile_id": {"type": "string"}}}, "description": "Rank items in a comparison with reasoning.", "function_name": "comparison.rank", "requires_hitl": false, "reads_user_data": true, "writes_user_data": false}', true, 'jce.ai_advisor.use', '2026-08-31 02:25:17.674821+01', '2026-08-31 02:25:17.674821+01');
INSERT INTO public.ai_tools VALUES ('7ea5a709-0a9d-4383-83ac-df117869fc12', 'comparison.explain', 'Explain a single JapaScore factor or recommendation for an item.', 'agent_comparison', '{"handler": "JCEExplain", "is_blocked": false, "parameters": {"type": "object", "required": ["content_id", "item_id"], "properties": {"item_id": {"type": "string"}, "content_id": {"type": "string"}, "factor_key": {"type": "string"}}}, "description": "Explain a single score or recommendation.", "function_name": "comparison.explain", "requires_hitl": false, "reads_user_data": true, "writes_user_data": false}', true, 'jce.ai_advisor.use', '2026-08-31 02:25:17.674821+01', '2026-08-31 02:25:17.674821+01');
INSERT INTO public.ai_tools VALUES ('06149c0e-e0cb-4f46-b62c-fcbbb1ba6c70', 'comparison.recommend_next_step', 'Get the top next actions and recommendations for a comparison and profile.', 'agent_comparison', '{"handler": "JCERecommend", "is_blocked": false, "parameters": {"type": "object", "required": ["content_id"], "properties": {"content_id": {"type": "string"}, "profile_id": {"type": "string"}}}, "description": "Get the top next actions and recommendations for a comparison and profile.", "function_name": "comparison.recommend_next_step", "requires_hitl": false, "reads_user_data": true, "writes_user_data": false}', true, 'jce.ai_advisor.use', '2026-08-31 02:25:17.674821+01', '2026-08-31 02:25:17.674821+01');
INSERT INTO public.ai_tools VALUES ('19ec6734-f1ad-4a4e-8cab-7500bd97c7b2', 'comparison.refresh', 'Trigger a refresh of stale comparison values from data sources.', 'agent_comparison', '{"handler": "JCERefresh", "is_blocked": false, "parameters": {"type": "object", "required": ["content_id"], "properties": {"content_id": {"type": "string"}, "source_kind": {"type": "string", "description": "Optional filter: official|third_party|ai_estimate"}}}, "description": "Refresh stale comparison values from registered data sources.", "function_name": "comparison.refresh", "requires_hitl": false, "reads_user_data": true, "writes_user_data": true}', true, 'jce.refresh.trigger', '2026-08-31 02:25:17.674821+01', '2026-08-31 02:25:17.674821+01');
INSERT INTO public.ai_tools VALUES ('f904eb5c-f7c2-4bac-811e-7e0e2880e7f8', 'spaces.create', 'Create a new space. Requires spaces.create permission. HITL-queued — a human reviewer approves before the space goes live.', 'agent_spaces', '{"handler": "SpacesCreate", "is_blocked": false, "parameters": {"type": "object", "required": ["name", "slug", "level"], "properties": {"name": {"type": "string", "description": "Space name"}, "slug": {"type": "string", "description": "URL slug"}, "level": {"type": "string", "description": "Level (country, state, city, community, university)"}, "status": {"type": "string", "description": "Status (active, dormant) — default active"}, "geo_code": {"type": "string", "description": "Country geo code (optional)"}, "parent_id": {"type": "string", "description": "Parent space UUID (optional)"}, "visibility": {"type": "string", "description": "Visibility (public, private) — default public"}, "description": {"type": "string", "description": "Description (optional)"}, "joining_perm": {"type": "string", "description": "Joining permission (open, approval, invite) — default open"}, "posting_perm": {"type": "string", "description": "Posting permission (members, mods, admins) — default members"}, "replying_perm": {"type": "string", "description": "Replying permission — default members"}, "space_type_id": {"type": "string", "description": "Space type UUID (optional)"}, "commenting_perm": {"type": "string", "description": "Commenting permission — default members"}}}, "description": "Create a new space.", "function_name": "spaces.create", "requires_hitl": true, "reads_user_data": false, "writes_user_data": false}', true, 'spaces.create', '2026-08-11 21:11:11.90418+01', '2026-09-01 06:08:34.404074+01');
INSERT INTO public.ai_tools VALUES ('00819db2-ecea-4ff1-8d3a-618aa80ed72b', 'spaces.update', 'Update an existing space. Requires spaces.edit permission. HITL-queued.', 'agent_spaces', '{"handler": "SpacesUpdate", "is_blocked": false, "parameters": {"type": "object", "required": ["space_id", "name"], "properties": {"name": {"type": "string", "description": "New name"}, "status": {"type": "string", "description": "New status (optional)"}, "geo_code": {"type": "string", "description": "New geo code (optional)"}, "space_id": {"type": "string", "description": "Space UUID to update"}, "visibility": {"type": "string", "description": "New visibility (optional)"}, "description": {"type": "string", "description": "New description (optional)"}, "joining_perm": {"type": "string", "description": "New joining permission (optional)"}, "posting_perm": {"type": "string", "description": "New posting permission (optional)"}, "replying_perm": {"type": "string", "description": "New replying permission (optional)"}, "commenting_perm": {"type": "string", "description": "New commenting permission (optional)"}}}, "description": "Update an existing space.", "function_name": "spaces.update", "requires_hitl": true, "reads_user_data": false, "writes_user_data": false}', true, 'spaces.edit', '2026-08-11 21:11:11.90418+01', '2026-09-01 06:08:34.404074+01');
INSERT INTO public.ai_tools VALUES ('cacff553-b27e-4f4c-b111-18c972c88e68', 'personas.read', 'Read a single AI persona by id, including the resolved voice_prompt (persona override wins over the shared voice) and activity_policy.', 'agent_persona', '{"handler": "PersonasRead", "is_blocked": false, "parameters": {"type": "object", "required": ["id"], "properties": {"id": {"type": "string", "description": "Persona UUID"}}}, "description": "Read a single AI persona including resolved voice_prompt and activity_policy.", "function_name": "personas.read", "requires_hitl": false, "reads_user_data": false, "writes_user_data": false}', true, 'persona.view', '2026-09-23 23:32:25.226162+01', '2026-09-23 23:32:25.226162+01');
INSERT INTO public.ai_tools VALUES ('8dec5144-7117-431a-8669-b8c0ddaa2d28', 'learn.tracks.create', 'Create a learning track. Requires learning.admin.manage. HITL-queued.', 'agent_learning', '{"handler": "LearnTracksCreate", "is_blocked": false, "parameters": {"type": "object", "required": ["title", "slug"], "properties": {"slug": {"type": "string", "description": "URL slug"}, "title": {"type": "string", "description": "Track title"}, "category": {"type": "string", "description": "Category (optional)"}, "difficulty": {"type": "string", "description": "Difficulty (beginner, intermediate, advanced) — default beginner"}, "sort_order": {"type": "integer", "description": "Sort order — default 0"}, "description": {"type": "string", "description": "Description (optional)"}, "is_published": {"type": "boolean", "description": "Published state — default false"}, "cover_media_id": {"type": "string", "description": "Cover media UUID (optional)"}, "subscription_eligible": {"type": "boolean", "description": "Subscription eligibility — default false"}}}, "description": "Create a learning track.", "function_name": "learn.tracks.create", "requires_hitl": true, "reads_user_data": false, "writes_user_data": false}', true, 'learning.admin.manage', '2026-08-11 21:11:11.90418+01', '2026-09-01 06:08:34.404074+01');
INSERT INTO public.ai_tools VALUES ('0fbe5701-e8aa-442d-90d7-6af0ce9d422a', 'learn.tracks.update', 'Update a learning track. Requires learning.admin.manage. HITL-queued.', 'agent_learning', '{"handler": "LearnTracksUpdate", "is_blocked": false, "parameters": {"type": "object", "required": ["track_id", "title"], "properties": {"title": {"type": "string", "description": "New title"}, "category": {"type": "string", "description": "New category (optional)"}, "track_id": {"type": "string", "description": "Track UUID"}, "difficulty": {"type": "string", "description": "New difficulty (optional)"}, "sort_order": {"type": "integer", "description": "New sort order (optional)"}, "description": {"type": "string", "description": "New description (optional)"}, "is_published": {"type": "boolean", "description": "New published state (optional)"}, "cover_media_id": {"type": "string", "description": "New cover media UUID (optional)"}, "subscription_eligible": {"type": "boolean", "description": "New subscription eligibility (optional)"}}}, "description": "Update a learning track.", "function_name": "learn.tracks.update", "requires_hitl": true, "reads_user_data": false, "writes_user_data": false}', true, 'learning.admin.manage', '2026-08-11 21:11:11.90418+01', '2026-09-01 06:08:34.404074+01');
INSERT INTO public.ai_tools VALUES ('af52c04c-262c-4e01-aab3-7446be0dc96b', 'learn.lessons.create', 'Create a lesson in a module. Requires learning.admin.manage. HITL-queued. module_id is required — lessons attach to modules.', 'agent_learning', '{"handler": "LearnLessonsCreate", "is_blocked": false, "parameters": {"type": "object", "required": ["module_id", "title", "slug"], "properties": {"slug": {"type": "string", "description": "URL slug"}, "title": {"type": "string", "description": "Lesson title"}, "content": {"type": "string", "description": "Lesson content (optional)"}, "media_id": {"type": "string", "description": "Media UUID (optional)"}, "module_id": {"type": "string", "description": "Module UUID (required — lessons attach to modules)"}, "is_preview": {"type": "boolean", "description": "Preview (free) state — default false"}, "sort_order": {"type": "integer", "description": "Sort order — default 0"}, "lesson_type": {"type": "string", "description": "Lesson type (text, video, quiz) — default text"}, "is_published": {"type": "boolean", "description": "Published state — default false"}, "duration_minutes": {"type": "integer", "description": "Duration in minutes (optional)"}}}, "description": "Create a lesson in a module.", "function_name": "learn.lessons.create", "requires_hitl": true, "reads_user_data": false, "writes_user_data": false}', true, 'learning.admin.manage', '2026-08-11 21:11:11.90418+01', '2026-09-01 06:08:34.404074+01');
INSERT INTO public.ai_tools VALUES ('7117bb30-1348-4175-8e41-c2bba691307e', 'learn.lessons.update', 'Update a lesson. Requires learning.admin.manage. HITL-queued.', 'agent_learning', '{"handler": "LearnLessonsUpdate", "is_blocked": false, "parameters": {"type": "object", "required": ["lesson_id", "title"], "properties": {"title": {"type": "string", "description": "New title"}, "content": {"type": "string", "description": "New content (optional)"}, "media_id": {"type": "string", "description": "New media UUID (optional)"}, "lesson_id": {"type": "string", "description": "Lesson UUID"}, "is_preview": {"type": "boolean", "description": "New preview state (optional)"}, "sort_order": {"type": "integer", "description": "New sort order (optional)"}, "lesson_type": {"type": "string", "description": "New lesson type (optional)"}, "is_published": {"type": "boolean", "description": "New published state (optional)"}, "duration_minutes": {"type": "integer", "description": "New duration (optional)"}}}, "description": "Update a lesson.", "function_name": "learn.lessons.update", "requires_hitl": true, "reads_user_data": false, "writes_user_data": false}', true, 'learning.admin.manage', '2026-08-11 21:11:11.90418+01', '2026-09-01 06:08:34.404074+01');
INSERT INTO public.ai_tools VALUES ('83ed9708-7769-4d4e-b7b7-eea6481c2d9a', 'learn.lessons.reorder', 'Reorder lessons by updating their sort_order values in bulk. Requires learning.admin.manage.', 'agent_learning', '{"handler": "LearnLessonsReorder", "is_blocked": false, "parameters": {"type": "object", "required": ["entries"], "properties": {"entries": {"type": "array", "items": {"type": "object", "required": ["lesson_id", "sort_order"], "properties": {"lesson_id": {"type": "string", "description": "Lesson UUID"}, "sort_order": {"type": "integer", "description": "New sort order"}}}, "description": "Reorder entries"}}}, "description": "Reorder lessons in bulk.", "function_name": "learn.lessons.reorder", "requires_hitl": false, "reads_user_data": false, "writes_user_data": false}', true, 'learning.admin.manage', '2026-08-11 21:11:11.90418+01', '2026-09-01 06:08:34.404074+01');
INSERT INTO public.ai_tools VALUES ('3a21d9b8-23d7-416c-b7e7-4bc2841873bc', 'docs.create', 'Create a documentation page. Requires docs.admin. HITL-queued. The agent never publishes directly — review_status defaults to draft.', 'agent_docs', '{"handler": "DocsCreate", "is_blocked": false, "parameters": {"type": "object", "required": ["title", "slug", "audience"], "properties": {"slug": {"type": "string", "description": "URL slug"}, "title": {"type": "string", "description": "Page title"}, "content": {"type": "string", "description": "Page content (JSON)"}, "audience": {"type": "string", "description": "Audience (public, premium, organizations, moderators, admin, superadmin)"}, "position": {"type": "integer", "description": "Nav position — default 0"}, "parent_id": {"type": "string", "description": "Parent page UUID (optional)"}, "review_status": {"type": "string", "description": "Review status (draft, in_review, approved) — default draft. Cannot be published."}}}, "description": "Create a documentation page.", "function_name": "docs.create", "requires_hitl": true, "reads_user_data": false, "writes_user_data": false}', true, 'docs.admin', '2026-08-11 21:11:11.90418+01', '2026-09-01 06:08:34.404074+01');
INSERT INTO public.ai_tools VALUES ('5fa8969e-c817-48f9-83cd-a54190e2f4f5', 'docs.update', 'Update a documentation page. Requires docs.admin. The agent cannot publish directly — review_status published is rejected.', 'agent_docs', '{"handler": "DocsUpdate", "is_blocked": false, "parameters": {"type": "object", "required": ["doc_id"], "properties": {"title": {"type": "string", "description": "New title (optional)"}, "doc_id": {"type": "string", "description": "Doc page UUID"}, "content": {"type": "string", "description": "New content (optional)"}, "review_status": {"type": "string", "description": "New review status (draft, in_review, approved) — cannot be published"}}}, "description": "Update a documentation page.", "function_name": "docs.update", "requires_hitl": false, "reads_user_data": false, "writes_user_data": false}', true, 'docs.admin', '2026-08-11 21:11:11.90418+01', '2026-09-01 06:08:34.404074+01');
INSERT INTO public.ai_tools VALUES ('fd3783ac-406d-4539-8c90-4639603a8c1c', 'docs.organize', 'Reorganize doc pages in the nav tree by updating parent_id and position. Requires docs.admin. DISABLED — the docs service does not expose a parent_id/position update query (no UpdateDocPageParent/UpdateDocPagePosition SQL query exists). The handler is registered as a gracefully-degrading stub; when the backing query is added, flip is_enabled to true.', 'agent_docs', '{"handler": "DocsOrganize", "is_blocked": false, "parameters": {"type": "object", "required": ["entries"], "properties": {"entries": {"type": "array", "items": {"type": "object", "required": ["doc_id", "position"], "properties": {"doc_id": {"type": "string", "description": "Doc page UUID"}, "position": {"type": "integer", "description": "New nav position"}, "parent_id": {"type": "string", "description": "New parent UUID (optional, null = top level)"}}}, "description": "Organize entries"}}}, "description": "Reorganize doc pages in the nav tree.", "function_name": "docs.organize", "requires_hitl": false, "reads_user_data": false, "writes_user_data": false}', false, 'docs.admin', '2026-08-11 21:11:11.90418+01', '2026-09-01 06:08:34.404074+01');
INSERT INTO public.ai_tools VALUES ('bfa9140f-99d0-429f-b0a9-02ed24cc3b66', 'tools.list', 'List available tools/features. DISABLED — the backing tools table does not exist yet (§78 discrepancy).', 'agent_tools', '{"handler": "ToolsList", "is_blocked": false, "parameters": {"type": "object", "properties": {}}, "description": "List available tools/features.", "function_name": "tools.list", "requires_hitl": false, "reads_user_data": false, "writes_user_data": false}', false, NULL, '2026-08-11 21:11:11.90418+01', '2026-09-01 06:08:34.404074+01');
INSERT INTO public.ai_tools VALUES ('2e5e8757-22c6-4235-a9c1-d5545b602918', 'tools.create', 'Create a new tool page. DISABLED — the backing tools table does not exist yet (§78 discrepancy).', 'agent_tools', '{"handler": "ToolsCreate", "is_blocked": false, "parameters": {"type": "object", "required": ["name", "slug"], "properties": {"name": {"type": "string", "description": "Tool name"}, "slug": {"type": "string", "description": "URL slug"}, "category": {"type": "string", "description": "Category (optional)"}, "description": {"type": "string", "description": "Description (optional)"}}}, "description": "Create a new tool page.", "function_name": "tools.create", "requires_hitl": true, "reads_user_data": false, "writes_user_data": false}', false, NULL, '2026-08-11 21:11:11.90418+01', '2026-09-01 06:08:34.404074+01');
INSERT INTO public.ai_tools VALUES ('0370f355-c767-48db-a642-040e895a44ac', 'tools.update', 'Update a tool. DISABLED — the backing tools table does not exist yet (§78 discrepancy).', 'agent_tools', '{"handler": "ToolsUpdate", "is_blocked": false, "parameters": {"type": "object", "required": ["tool_id"], "properties": {"name": {"type": "string", "description": "New name (optional)"}, "tool_id": {"type": "string", "description": "Tool UUID"}, "description": {"type": "string", "description": "New description (optional)"}}}, "description": "Update a tool.", "function_name": "tools.update", "requires_hitl": true, "reads_user_data": false, "writes_user_data": false}', false, NULL, '2026-08-11 21:11:11.90418+01', '2026-09-01 06:08:34.404074+01');
INSERT INTO public.ai_tools VALUES ('85fb25c5-8ef0-4e71-809b-2afffa19064b', 'tools.assign_geo', 'Geo-scope a tool to a country/region. DISABLED — the backing tools table does not exist yet (§78 discrepancy).', 'agent_tools', '{"handler": "ToolsAssignGeo", "is_blocked": false, "parameters": {"type": "object", "required": ["tool_id", "geo_code"], "properties": {"tool_id": {"type": "string", "description": "Tool UUID"}, "geo_code": {"type": "string", "description": "Country geo code"}}}, "description": "Geo-scope a tool to a country/region.", "function_name": "tools.assign_geo", "requires_hitl": true, "reads_user_data": false, "writes_user_data": false}', false, NULL, '2026-08-11 21:11:11.90418+01', '2026-09-01 06:08:34.404074+01');
INSERT INTO public.ai_tools VALUES ('2fc7d938-7a46-46bf-af46-f6215f5e8e15', 'menu.list', 'List menus with optional placement/status filters. Returns menus with item counts.', 'agent_menus', '{"handler": "MenuList", "is_blocked": false, "parameters": {"type": "object", "properties": {"q": {"type": "string", "description": "Search query (optional)"}, "limit": {"type": "integer", "description": "Max results (default 20, max 100)"}, "offset": {"type": "integer", "description": "Pagination offset (default 0)"}, "status": {"type": "string", "description": "Filter by status (optional)"}, "placement": {"type": "string", "description": "Filter by placement (optional)"}}}, "description": "List menus with optional filters.", "function_name": "menu.list", "requires_hitl": false, "reads_user_data": false, "writes_user_data": false}', true, NULL, '2026-08-11 21:11:11.90418+01', '2026-09-01 06:08:34.404074+01');
INSERT INTO public.ai_tools VALUES ('f83222d2-46af-4977-a0e6-d488ac8cd299', 'destination.brief', 'Get the aggregate destination brief for a space slug: visa routes, processing timelines, universities, scholarships, and scam alerts composed into one document. Omit include to get all sections.', 'agent_data', '{"handler": "DestinationBrief", "is_blocked": false, "parameters": {"type": "object", "required": ["slug"], "properties": {"slug": {"type": "string", "description": "Destination space slug"}, "include": {"type": "array", "items": {"enum": ["visa", "timelines", "universities", "scholarships", "scam_alerts"], "type": "string"}, "description": "Sections to include (default: all)"}}}, "description": "Get the aggregate destination brief for a space slug.", "function_name": "destination.brief", "requires_hitl": false, "reads_user_data": false, "writes_user_data": false}', true, NULL, '2026-09-23 20:02:48.635188+01', '2026-09-23 20:02:48.635188+01');
INSERT INTO public.ai_tools VALUES ('4a0ad09d-598e-43e2-b732-4cf7fae0eb76', 'menu.create', 'Create a menu item. Requires menus.manage. HITL-queued.', 'agent_menus', '{"handler": "MenuCreate", "is_blocked": false, "parameters": {"type": "object", "required": ["menu_id", "label"], "properties": {"url": {"type": "string", "description": "Item URL"}, "icon": {"type": "string", "description": "Icon name (optional)"}, "label": {"type": "string", "description": "Item label"}, "target": {"type": "string", "description": "Link target (_self, _blank) — default _self"}, "menu_id": {"type": "string", "description": "Menu UUID to add the item to"}, "parent_id": {"type": "string", "description": "Parent item UUID (optional)"}, "is_ad_slot": {"type": "boolean", "description": "Is this an ad slot — default false"}, "sort_order": {"type": "integer", "description": "Sort order — default 0"}, "visibility": {"type": "string", "description": "Visibility (all, authenticated, anonymous) — default all"}, "ad_slot_config": {"type": "object", "description": "Ad slot config (optional)"}, "permission_node": {"type": "string", "description": "Required permission node (optional)"}, "required_group_ids": {"type": "array", "items": {"type": "string"}, "description": "Required group UUIDs (optional)"}}}, "description": "Create a menu item.", "function_name": "menu.create", "requires_hitl": true, "reads_user_data": false, "writes_user_data": false}', true, 'menus.manage', '2026-08-11 21:11:11.90418+01', '2026-09-01 06:08:34.404074+01');
INSERT INTO public.ai_tools VALUES ('42b5a23f-248e-4704-89de-abf95b2c4455', 'menu.update', 'Update a menu item. Requires menus.manage. HITL-queued.', 'agent_menus', '{"handler": "MenuUpdate", "is_blocked": false, "parameters": {"type": "object", "required": ["item_id", "label"], "properties": {"url": {"type": "string", "description": "New URL (optional)"}, "icon": {"type": "string", "description": "New icon (optional)"}, "label": {"type": "string", "description": "New label"}, "status": {"type": "string", "description": "New status (active, inactive) — default active"}, "target": {"type": "string", "description": "New target (optional)"}, "item_id": {"type": "string", "description": "Menu item UUID"}, "parent_id": {"type": "string", "description": "New parent UUID (optional)"}, "is_ad_slot": {"type": "boolean", "description": "New ad slot flag (optional)"}, "sort_order": {"type": "integer", "description": "New sort order (optional)"}, "visibility": {"type": "string", "description": "New visibility (optional)"}, "ad_slot_config": {"type": "object", "description": "New ad slot config (optional)"}, "permission_node": {"type": "string", "description": "New permission node (optional)"}, "required_group_ids": {"type": "array", "items": {"type": "string"}, "description": "New required group UUIDs (optional)"}}}, "description": "Update a menu item.", "function_name": "menu.update", "requires_hitl": true, "reads_user_data": false, "writes_user_data": false}', true, 'menus.manage', '2026-08-11 21:11:11.90418+01', '2026-09-01 06:08:34.404074+01');
INSERT INTO public.ai_tools VALUES ('729cd726-15d8-4c78-8679-ad8c7d13078b', 'menu.delete', 'Delete a menu item. Requires menus.manage. HITL-queued.', 'agent_menus', '{"handler": "MenuDelete", "is_blocked": false, "parameters": {"type": "object", "required": ["item_id"], "properties": {"item_id": {"type": "string", "description": "Menu item UUID"}}}, "description": "Delete a menu item.", "function_name": "menu.delete", "requires_hitl": true, "reads_user_data": false, "writes_user_data": false}', true, 'menus.manage', '2026-08-11 21:11:11.90418+01', '2026-09-01 06:08:34.404074+01');
INSERT INTO public.ai_tools VALUES ('faa3b3a6-01a1-4882-9ade-4549bf5c9c4e', 'user.read_profile', 'Read a user public profile (no PII — email, last_login, groups omitted). Privacy-gated: blocked when the target user is ai_exempt.', 'agent_user', '{"handler": "UserReadProfile", "is_blocked": false, "parameters": {"type": "object", "required": ["user_id"], "properties": {"user_id": {"type": "string", "description": "User UUID"}}}, "description": "Read a user public profile.", "function_name": "user.read_profile", "requires_hitl": false, "reads_user_data": true, "writes_user_data": false}', true, NULL, '2026-08-11 21:11:11.90418+01', '2026-09-01 06:08:34.404074+01');
INSERT INTO public.ai_tools VALUES ('8ad16c0f-c77b-4d5f-add0-4cdb25fcc052', 'user.update_profile', 'Update the calling user own profile fields. Self-only — user_id must match the calling user. No permission node required (self-service).', 'agent_user', '{"handler": "UserUpdateProfile", "is_blocked": false, "parameters": {"type": "object", "required": ["user_id"], "properties": {"bio": {"type": "string", "description": "New bio (optional)"}, "user_id": {"type": "string", "description": "User UUID (must be the calling user)"}, "timezone": {"type": "string", "description": "New timezone (optional)"}, "avatar_url": {"type": "string", "description": "New avatar URL (optional)"}, "display_name": {"type": "string", "description": "New display name (optional)"}, "origin_country": {"type": "string", "description": "New origin country (optional)"}, "destination_country": {"type": "string", "description": "New destination country (optional)"}}}, "description": "Update own profile fields.", "function_name": "user.update_profile", "requires_hitl": false, "reads_user_data": true, "writes_user_data": true}', true, NULL, '2026-08-11 21:11:11.90418+01', '2026-09-01 06:08:34.404074+01');
INSERT INTO public.ai_tools VALUES ('2108cb7b-0ddd-4a5e-bebf-5127910a8493', 'user.read_own_fields', 'Read the calling user own custom field values (including private/ai_exempt fields). Self-only — user_id must match the calling user.', 'agent_user', '{"handler": "UserReadOwnFields", "is_blocked": false, "parameters": {"type": "object", "required": ["user_id"], "properties": {"user_id": {"type": "string", "description": "User UUID (must be the calling user)"}}}, "description": "Read own custom field values (including private fields).", "function_name": "user.read_own_fields", "requires_hitl": false, "reads_user_data": true, "writes_user_data": false}', true, NULL, '2026-08-11 21:11:11.90418+01', '2026-09-01 06:08:34.404074+01');
INSERT INTO public.ai_tools VALUES ('d1f4ce94-db50-47b2-8cdd-b4caefa240b7', 'custom_fields.create', 'Create a custom field definition. Requires custom_fields.field.create. HITL-queued.', 'agent_custom_fields', '{"handler": "CustomFieldsCreate", "is_blocked": false, "parameters": {"type": "object", "required": ["group_id", "label", "key", "field_type"], "properties": {"key": {"type": "string", "description": "Field key (machine name)"}, "label": {"type": "string", "description": "Field label"}, "options": {"type": "object", "description": "Field options (JSON, optional)"}, "group_id": {"type": "string", "description": "Field group UUID"}, "position": {"type": "integer", "description": "Position — default 0"}, "sortable": {"type": "boolean", "description": "Sortable — default false"}, "is_system": {"type": "boolean", "description": "System field — default false"}, "field_type": {"type": "string", "description": "Field type (text, textarea, number, boolean, date, select, json)"}, "filterable": {"type": "boolean", "description": "Filterable — default false"}, "searchable": {"type": "boolean", "description": "Searchable — default false"}, "is_required": {"type": "boolean", "description": "Required — default false"}, "placeholder": {"type": "string", "description": "Placeholder (optional)"}, "default_value": {"type": "string", "description": "Default value (optional)"}, "embed_platforms": {"type": "array", "items": {"type": "string"}, "description": "Embed platforms (optional)"}, "show_in_frontend": {"type": "boolean", "description": "Show in frontend — default false"}}}, "description": "Create a custom field definition.", "function_name": "custom_fields.create", "requires_hitl": true, "reads_user_data": false, "writes_user_data": false}', true, 'custom_fields.field.create', '2026-08-11 21:11:11.90418+01', '2026-09-01 06:08:34.404074+01');
INSERT INTO public.ai_tools VALUES ('d1648b29-1d65-4f48-9137-be2f56ce0ad8', 'personas.list', 'List AI personas with their status, linked voice, and activity stats. Use the returned id as ai_persona_id when calling content.create_draft.', 'agent_persona', '{"handler": "PersonasList", "is_blocked": false, "parameters": {"type": "object", "properties": {"q": {"type": "string", "description": "Search by display name or backing username"}, "dir": {"type": "string", "description": "Sort direction: asc|desc (default desc)"}, "sort": {"type": "string", "description": "Sort key: name|created_at|total_actions (default created_at)"}, "limit": {"type": "integer", "description": "Max results (default 50, max 100)"}, "offset": {"type": "integer", "description": "Pagination offset (default 0)"}, "status": {"type": "string", "description": "Filter by status (active|paused|retired); empty = all"}}}, "description": "List AI personas with voice and activity info.", "function_name": "personas.list", "requires_hitl": false, "reads_user_data": false, "writes_user_data": false}', true, 'persona.view', '2026-09-23 23:32:25.226162+01', '2026-09-23 23:32:25.226162+01');
INSERT INTO public.ai_tools VALUES ('14bcd75d-3da8-41ef-b31d-9b08e301f511', 'custom_fields.update', 'Update a custom field definition. Requires custom_fields.field.edit. HITL-queued.', 'agent_custom_fields', '{"handler": "CustomFieldsUpdate", "is_blocked": false, "parameters": {"type": "object", "required": ["field_id", "label"], "properties": {"label": {"type": "string", "description": "New label"}, "options": {"type": "object", "description": "New options (optional)"}, "field_id": {"type": "string", "description": "Field UUID"}, "position": {"type": "integer", "description": "New position (optional)"}, "sortable": {"type": "boolean", "description": "New sortable flag (optional)"}, "field_type": {"type": "string", "description": "New field type (optional)"}, "filterable": {"type": "boolean", "description": "New filterable flag (optional)"}, "searchable": {"type": "boolean", "description": "New searchable flag (optional)"}, "is_required": {"type": "boolean", "description": "New required flag (optional)"}, "placeholder": {"type": "string", "description": "New placeholder (optional)"}, "default_value": {"type": "string", "description": "New default value (optional)"}, "embed_platforms": {"type": "array", "items": {"type": "string"}, "description": "New embed platforms (optional)"}, "show_in_frontend": {"type": "boolean", "description": "New frontend flag (optional)"}}}, "description": "Update a custom field definition.", "function_name": "custom_fields.update", "requires_hitl": true, "reads_user_data": false, "writes_user_data": false}', true, 'custom_fields.field.edit', '2026-08-11 21:11:11.90418+01', '2026-09-01 06:08:34.404074+01');
INSERT INTO public.ai_tools VALUES ('a4028a0a-034b-4d0f-9643-48eed3643a01', 'custom_field_groups.create', 'Create a custom field group. Requires custom_fields.group.create. HITL-queued.', 'agent_custom_fields', '{"handler": "CustomFieldGroupsCreate", "is_blocked": false, "parameters": {"type": "object", "required": ["name", "slug"], "properties": {"name": {"type": "string", "description": "Group name"}, "slug": {"type": "string", "description": "URL slug"}, "is_system": {"type": "boolean", "description": "System group — default false"}, "description": {"type": "string", "description": "Description (optional)"}}}, "description": "Create a custom field group.", "function_name": "custom_field_groups.create", "requires_hitl": true, "reads_user_data": false, "writes_user_data": false}', true, 'custom_fields.group.create', '2026-08-11 21:11:11.90418+01', '2026-09-01 06:08:34.404074+01');
INSERT INTO public.ai_tools VALUES ('ceef7458-2946-4cf9-b136-d95afd7d2e54', 'content.delete', 'Soft-delete a content row. Requires content.delete. HITL-queued. Privacy-gated: blocked when the content is ai_exempt.', 'agent_content', '{"handler": "ContentDelete", "is_blocked": false, "parameters": {"type": "object", "required": ["content_id"], "properties": {"content_id": {"type": "string", "description": "Content UUID"}}}, "description": "Soft-delete a content row.", "function_name": "content.delete", "requires_hitl": true, "reads_user_data": false, "writes_user_data": true}', true, 'content.delete', '2026-08-11 21:11:11.90418+01', '2026-09-01 06:08:34.404074+01');
INSERT INTO public.ai_tools VALUES ('a6710c06-c105-4468-9e59-9f3244831a0f', 'content.publish', 'Change a content row status (default published). Requires content.publish. HITL-queued. Privacy-gated: blocked when the content is ai_exempt.', 'agent_content', '{"handler": "ContentPublish", "is_blocked": false, "parameters": {"type": "object", "required": ["content_id"], "properties": {"status": {"type": "string", "description": "New status (published, draft, scheduled, archived) — default published"}, "content_id": {"type": "string", "description": "Content UUID"}}}, "description": "Change content status (default published).", "function_name": "content.publish", "requires_hitl": true, "reads_user_data": false, "writes_user_data": true}', true, 'content.publish', '2026-08-11 21:11:11.90418+01', '2026-09-01 06:08:34.404074+01');
INSERT INTO public.ai_tools VALUES ('cfe32ef1-8bb4-49c3-8a70-e0d525d18eb1', 'visa.search', 'Search visa and immigration routes. Optionally filter by destination space, profession, education, and years of experience. Returns matching routes with total count.', 'agent_data', '{"handler": "VisaSearch", "is_blocked": false, "parameters": {"type": "object", "properties": {"page": {"type": "integer", "description": "Page number (default 1)"}, "limit": {"type": "integer", "description": "Max results (default 20, max 50)"}, "education": {"type": "string", "description": "Education level filter"}, "profession": {"type": "string", "description": "Profession filter"}, "experience_years": {"type": "integer", "description": "Years of experience filter"}, "destination_space_id": {"type": "string", "description": "Destination space UUID to filter routes"}}}, "description": "Search visa and immigration routes.", "function_name": "visa.search", "requires_hitl": false, "reads_user_data": false, "writes_user_data": false}', true, NULL, '2026-09-23 20:02:48.635188+01', '2026-09-23 20:02:48.635188+01');
INSERT INTO public.ai_tools VALUES ('314485cd-7e3b-4601-a557-ef461b8a1c0d', 'visa.get', 'Read a single visa route record by ID.', 'agent_data', '{"handler": "VisaGet", "is_blocked": false, "parameters": {"type": "object", "required": ["route_id"], "properties": {"route_id": {"type": "string", "description": "Visa route UUID"}}}, "description": "Read a single visa route record by ID.", "function_name": "visa.get", "requires_hitl": false, "reads_user_data": false, "writes_user_data": false}', true, NULL, '2026-09-23 20:02:48.635188+01', '2026-09-23 20:02:48.635188+01');
INSERT INTO public.ai_tools VALUES ('63006f63-4549-49a6-a869-7b5450efd091', 'visa.compare', 'Compare up to 5 visa routes side by side by their IDs.', 'agent_data', '{"handler": "VisaCompare", "is_blocked": false, "parameters": {"type": "object", "required": ["route_ids"], "properties": {"route_ids": {"type": "array", "items": {"type": "string"}, "maxItems": 5, "minItems": 1, "description": "Visa route UUIDs to compare (1-5)"}}}, "description": "Compare up to 5 visa routes side by side.", "function_name": "visa.compare", "requires_hitl": false, "reads_user_data": false, "writes_user_data": false}', true, NULL, '2026-09-23 20:02:48.635188+01', '2026-09-23 20:02:48.635188+01');
INSERT INTO public.ai_tools VALUES ('48d12aca-266f-45bb-9501-2c010307d3ee', 'university.get', 'Read a single university record by its space slug.', 'agent_data', '{"handler": "UniversityGet", "is_blocked": false, "parameters": {"type": "object", "required": ["slug"], "properties": {"slug": {"type": "string", "description": "University space slug"}}}, "description": "Read a single university record by slug.", "function_name": "university.get", "requires_hitl": false, "reads_user_data": false, "writes_user_data": false}', true, NULL, '2026-09-23 20:02:48.635188+01', '2026-09-23 20:02:48.635188+01');
INSERT INTO public.ai_tools VALUES ('93bfea42-61d9-4061-b9ec-603894b941b6', 'learn.tracks.list', 'List all learning tracks (admin view, including drafts).', 'agent_learning', '{"handler": "LearnTracksList", "is_blocked": false, "parameters": {"type": "object", "properties": {}}, "description": "List all learning tracks.", "function_name": "learn.tracks.list", "requires_hitl": false, "reads_user_data": false, "writes_user_data": false}', true, NULL, '2026-08-11 21:11:11.90418+01', '2026-09-25 10:59:40.038759+01');
INSERT INTO public.ai_tools VALUES ('d2e69456-cdee-4e70-b8ce-ee74aaa56936', 'persona_voices.list', 'List the shared persona voices (tone catalog). Returns id, name, slug, description and is_system for each voice; pass include_prompts=true to also return each voice_prompt. Use persona_voices.read to fetch a single voice.', 'agent_persona', '{"handler": "PersonaVoicesList", "is_blocked": false, "parameters": {"type": "object", "properties": {"limit": {"type": "integer", "description": "Max results (default 50, max 200)"}, "offset": {"type": "integer", "description": "Pagination offset (default 0)"}, "include_prompts": {"type": "boolean", "description": "Include each voice''s full voice_prompt in the result (default false)"}}}, "description": "List the shared persona voices (tone catalog).", "function_name": "persona_voices.list", "requires_hitl": false, "reads_user_data": false, "writes_user_data": false}', true, 'persona.view', '2026-09-23 23:32:25.226162+01', '2026-09-23 23:32:25.226162+01');
INSERT INTO public.ai_tools VALUES ('c42f79e8-e287-44ce-8910-5cdf90bc7465', 'feeds.explore', 'Browse the public explore feeds. Optionally scope to a tag (tag) or a space (space_slug); otherwise returns the named explore feed (popular, latest, or rising — default popular). sort overrides the name mapping when valid (latest, top, rising, relevant).', 'agent_data', '{"handler": "FeedsExplore", "is_blocked": false, "parameters": {"type": "object", "properties": {"tag": {"type": "string", "description": "Tag slug — when set, returns the tag feed instead"}, "name": {"enum": ["popular", "latest", "rising"], "type": "string", "description": "Explore feed name (default popular)"}, "sort": {"enum": ["latest", "top", "rising", "relevant"], "type": "string", "description": "Sort override"}, "limit": {"type": "integer", "description": "Max results (default 20, max 50)"}, "cursor": {"type": "string", "description": "Opaque next_cursor for tag-feed pagination"}, "offset": {"type": "integer", "description": "Offset for explore/space feed pagination (default 0)"}, "space_slug": {"type": "string", "description": "Space slug — when set, returns that space feed instead"}}}, "description": "Browse the public explore feeds (popular, latest, rising), a tag feed, or a space feed.", "function_name": "feeds.explore", "requires_hitl": false, "reads_user_data": false, "writes_user_data": false}', true, NULL, '2026-09-24 09:38:09.445523+01', '2026-09-24 09:38:09.445523+01');
INSERT INTO public.ai_tools VALUES ('457bb043-ee7f-4c6c-8493-ae07b217b7cc', 'feeds.for_you', 'Read the calling user''s ranked for-you feed — the same personalized feed as GET /public/me/feed, resolved against the session user or API-key owner.', 'agent_data', '{"handler": "FeedsForYou", "is_blocked": false, "parameters": {"type": "object", "properties": {"sort": {"enum": ["latest", "top", "rising", "relevant"], "type": "string", "description": "Sort mode"}, "limit": {"type": "integer", "description": "Max results (default 20, max 50)"}, "offset": {"type": "integer", "description": "Offset for pagination (default 0)"}}}, "description": "Read the calling user''s ranked for-you feed.", "function_name": "feeds.for_you", "requires_hitl": false, "reads_user_data": true, "writes_user_data": false}', true, NULL, '2026-09-24 09:38:09.445523+01', '2026-09-24 09:38:09.445523+01');
INSERT INTO public.ai_tools VALUES ('b0f55060-4627-4865-b325-9b36fbccc1bf', 'scam.list', 'List confirmed scam alerts. Optionally filter by destination space or scam type. Returns matching reports with total count.', 'agent_data', '{"handler": "ScamList", "is_blocked": false, "parameters": {"type": "object", "properties": {"limit": {"type": "integer", "description": "Max results (default 20, max 50)"}, "offset": {"type": "integer", "description": "Offset for pagination (default 0)"}, "scam_type": {"type": "string", "description": "Scam type filter (see scam-alerts schema endpoint for options)"}, "destination_space_id": {"type": "string", "description": "Destination space UUID to filter reports"}}}, "description": "List confirmed scam alerts.", "function_name": "scam.list", "requires_hitl": false, "reads_user_data": false, "writes_user_data": false}', true, NULL, '2026-09-24 09:38:09.445523+01', '2026-09-24 09:38:09.445523+01');
INSERT INTO public.ai_tools VALUES ('08b18eac-c344-4bf5-ad21-12bea77d54a7', 'scam.get', 'Read a single confirmed scam alert by ID.', 'agent_data', '{"handler": "ScamGet", "is_blocked": false, "parameters": {"type": "object", "required": ["id"], "properties": {"id": {"type": "string", "description": "Scam alert UUID"}}}, "description": "Read a single confirmed scam alert by ID.", "function_name": "scam.get", "requires_hitl": false, "reads_user_data": false, "writes_user_data": false}', true, NULL, '2026-09-24 09:38:09.445523+01', '2026-09-24 09:38:09.445523+01');
INSERT INTO public.ai_tools VALUES ('7e54753a-1cd0-465b-a445-15ce142e7a24', 'search.semantic', 'Semantic (vector) search over indexed spaces and content. Premium — requires a pro subscription. Optionally constrain by language and space.', 'agent_data', '{"handler": "SemanticSearch", "is_blocked": false, "parameters": {"type": "object", "required": ["query"], "properties": {"lang": {"type": "string", "description": "Language code to bias retrieval (e.g. en, fr)"}, "limit": {"type": "integer", "description": "Max hits (server default applies when omitted)"}, "query": {"type": "string", "description": "Natural-language search query"}, "space": {"type": "string", "description": "Space slug to constrain results"}}}, "description": "Semantic (vector) search over indexed spaces and content. Premium tool.", "function_name": "search.semantic", "requires_hitl": false, "reads_user_data": false, "writes_user_data": false}', true, NULL, '2026-09-24 09:38:09.445523+01', '2026-09-24 09:38:09.445523+01');
