INSERT INTO public.comparison_type_definitions VALUES ('c4bf6df7-49d5-445b-85b1-e19c58d5e066', 'Cost of Living', 'cost_of_living', 'City-to-city cost of living comparison with Lagos baseline', NULL, '00000000-0000-0000-0000-000000000044', 'City', true, '2026-08-04 07:56:51.011871+01', '{"weights": {"gym_monthly": 0.05, "avg_net_salary": 0.10, "internet_monthly": 0.05, "rent_1br_outside": 0.15, "groceries_monthly": 0.15, "transport_monthly": 0.10, "utilities_monthly": 0.10, "rent_1br_city_centre": 0.25, "restaurant_meal_cheap": 0.05}, "scope_chain": ["country", "state", "city"], "smart_modes": {"cost": {"factor_multipliers": {"cost": 2.0}}, "pathway": {"factor_multipliers": {"speed": 1.5, "pr_path": 1.5}}, "eligibility": {"filter_ineligible": true, "factor_multipliers": {"eligibility": 2.0}}}, "sort_options": ["title", "title_desc", "members", "newest"], "allowed_goals": [{"key": "pr_fast", "label": "Get permanent residency fast", "description": "Prioritise routes with a clear, short PR pathway", "default_weight": 0.25}, {"key": "low_cost", "label": "Low cost of living", "description": "Minimise tuition, rent, and daily expenses", "default_weight": 0.25}, {"key": "high_income", "label": "High earning potential", "description": "Maximise post-study or post-move salary", "default_weight": 0.20}, {"key": "family_friendly", "label": "Family friendly", "description": "Favour schooling, healthcare, and family visa options", "default_weight": 0.15}, {"key": "scholarships", "label": "Scholarship opportunities", "description": "Favour funding and bursaries", "default_weight": 0.10}, {"key": "language_ease", "label": "Language ease", "description": "Favour destinations that match my language skills", "default_weight": 0.05}], "item_ref_types": ["col_city", "comparison"], "default_weights": {"cost": 0.20, "speed": 0.10, "income": 0.15, "pr_path": 0.10, "eligibility": 0.25, "language_match": 0.10, "location_match": 0.10}, "goal_factor_map": {"pr_fast": ["pr_path", "speed"], "low