INSERT INTO public.cv_standards VALUES ('7bcf5f9e-1862-4d20-8e07-3412b3dcc333', '4f145397-6349-4d6a-9fa8-ffdca5c70d7d', '1-2 pages', 'prohibited', 'MM/DD/YYYY', '{"Contact Information","Professional Summary","Work Experience",Education,Skills,Certifications,"Optional: Volunteer Experience"}', 'Concise and achievement-oriented. Use action verbs and quantifiable results. Tailor to the job description. Avoid first-person pronouns.', 'Including a photo (ATS systems reject it), using subjective statements without evidence, exceeding 2 pages, including personal details (age, marital status, SSN), using fancy formatting that breaks ATS parsing.', '2026-08-15 11:55:15.491535+01', '2026-08-15 11:55:15.491535+01');
INSERT INTO public.cv_standards VALUES ('24a5e731-611d-4b46-a4f2-0df125e5ceb8', '414c2f7e-bb0e-4162-a8a0-291c6a4aff8b', '1-2 pages', 'prohibited', 'MM/DD/YYYY', '{"Contact Information","Professional Summary","Work Experience",Education,Skills,Certifications,"Optional: Volunteer Experience"}', 'Concise and achievement-oriented. Use action verbs and quantifiable results. Tailor to the job description. Avoid first-person pronouns.', 'Including a photo (ATS systems reject it), using subjective statements without evidence, exceeding 2 pages, including personal details (age, marital status, SSN), using fancy formatting that breaks ATS parsing.', '2026-08-15 11:55:15.491535+01', '2026-08-15 11:55:15.491535+01');
INSERT INTO public.cv_standards VALUES ('b95392e2-c487-4b33-9366-d45e6c44f1dc', 'e5bc78fd-8e1c-469c-afc3-c2341d1530db', '1-2 pages', 'not_recommended', 'DD/MM/YYYY', '{"Personal Details","Personal Profile","Work Experience",Education,Skills,Achievements,"Optional: Hobbies & Interests"}', 'Professional and evidence-based. Use reverse-chronological order. Keep to two pages unless senior-level. Include a strong personal profile statement.', 'Exceeding 2 pages for non-senior roles, including a photo, using American spelling, listing references on the CV, including age or marital status.', '2026-08-15 11:55:15.491535+01', '2026-08-15 11:55:15.491535+01');
