INSERT INTO public.translations VALUES ('248e4cac-c34e-44af-bcbe-d377a59f09fc', 'fr', 'about.mission_heading', 'Notre mission', NULL, '2026-07-15 15:09:37.623689+01', '2026-07-15 15:09:37.623689+01');
INSERT INTO public.translations VALUES ('13fc44d9-50f3-4724-a7b6-6e8a3d09dc1b', 'fr', 'about.mission_text', 'JapaConnect a été conçu pour servir la diaspora nigériane et les Nigérians préparant leur expatriation. Nous offrons une communauté, des ressources et des conseils d''experts pour faciliter votre parcours.', NULL, '2026-07-15 15:09:37.623689+01', '2026-07-15 15:09:37.623689+01');
INSERT INTO public.translations VALUES ('5ff4c250-2505-4c63-9138-03420c45a0a7', 'fr', 'about.mission_text_1', 'JapaConnect est une plateforme communautaire créée pour la diaspora nigériane et les Nigérians préparant leur expatriation. Nous fournissons des outils pour partager des expériences, trouver des ressources et créer des connexions significatives à travers les frontières.', NULL, '2026-07-15 15:09:37.623689+01', '2026-07-15 15:09:37.623689+01');
INSERT INTO public.translations VALUES ('a0c9c782-fd7a-4a6e-b2fb-aafba3d96c08', 'fr', 'about.mission_text_2', 'Notre mission est de rendre le parcours d''expatriation moins isolant en connectant les personnes ayant des expériences partagées, des informations fiables et des communautés de soutien.', NULL, '2026-07-15 15:09:37.623689+01', '2026-07-15 15:09:37.623689+01');
INSERT INTO public.translations VALUES ('f9c041c5-11a4-4f06-8fc0-6cceb78de044', 'fr', 'about.mission_title', 'Notre mission', NULL, '2026-07-15 15:09:37.623689+01', '2026-07-15 15:09:37.623689+01');
INSERT INTO public.translations VALUES ('144ece09-7188-417d-889b-fed50a39633e', 'fr', 'about.offer_1', 'Des espaces communautaires organisés par pays, profession et intérêt', NULL, '2026-07-15 15:09:37.623689+01', '2026-07-15 15:09:37.623689+01');
INSERT INTO public.translations VALUES ('f4b51af9-e238-46d8-a0d6-fd1e8ffe53a3', 'fr', 'about.offer_2', 'Un éditeur de contenu riche pour partager des guides, des histoires et des ressources', NULL, '2026-07-15 15:09:37.623689+01', '2026-07-15 15:09:37.623689+01');
INSERT INTO public.translations VALUES ('8afb0115-2c8b-40fd-8c78-bbb2f6c59fa8', 'fr', 'about.offer_3', 'Des outils de découverte et de comparaison d''universités', NULL, '2026-07-15 15:09:37.623689+01', '2026-07-15 15:09:37.623689+01');
INSERT INTO public.translations VALUES ('8625240b-86f2-4ab6-a758-100b2c12d2c1', 'fr', 'about.offer_4', 'Des notifications et des messageries en temps réel', NULL, '2026-07-15 15:09:37.623689+01', '2026-07-15 15:09:37.623689+01');
INSERT INTO public.translations VALUES ('240eb791-b981-486e-9da9-152d819329f1', 'fr', 'about.offer_5', 'Des informations d''immigration et d''expatriation sélectionnées', NULL, '2026-07-15 15:09:37.623689+01', '2026-07-15 15:09:37.623689+01');
