INSERT INTO public.translations VALUES ('2c9b55d6-12f7-4327-a336-4aa08ff31bb3', 'en', 'about.mission_heading', 'Our Mission', NULL, '2026-07-01 16:58:35.463967+01', '2026-07-13 07:13:32.372955+01');
INSERT INTO public.translations VALUES ('bc261cac-fbf5-43a1-8a72-d7b867e73d63', 'en', 'about.mission_text', 'JapaConnect is built to serve the Nigerian diaspora and Nigerians planning to relocate abroad. We provide community, resources, and expert guidance to make your journey smoother.', NULL, '2026-07-01 16:58:35.463967+01', '2026-07-13 07:13:32.372955+01');
INSERT INTO public.translations VALUES ('0f21814a-5920-425a-b2b8-6f0018f17164', 'en', 'about.mission_text_1', 'JapaConnect is a community platform built for the Nigerian diaspora and Nigerians planning to relocate abroad. We provide tools for sharing experiences, finding resources, and building meaningful connections across borders.', NULL, '2026-07-01 16:58:35.463967+01', '2026-07-13 07:13:32.372955+01');
INSERT INTO public.translations VALUES ('eb1101c9-095b-4882-8262-0a5437397ee7', 'en', 'about.mission_text_2', 'Our mission is to make the relocation journey less isolating by connecting people with shared experiences, reliable information, and supportive communities.', NULL, '2026-07-01 16:58:35.463967+01', '2026-07-13 07:13:32.372955+01');
INSERT INTO public.translations VALUES ('ea204166-24ea-4c4c-8dfd-a42446e5fbb0', 'en', 'about.offer_1', 'Community spaces organized by country, profession, and interest', NULL, '2026-07-01 16:58:35.463967+01', '2026-07-13 07:13:32.372955+01');
