INSERT INTO public.translations VALUES ('65e5cfce-48fd-4080-a614-c1fb7d744e3e', 'es', 'about.mission_heading', 'Our Mission', NULL, '2026-07-17 03:50:03.538196+01', '2026-07-17 03:50:03.538196+01');
INSERT INTO public.translations VALUES ('16b45f5e-5777-4363-9c63-c510e5d8cd84', 'es', 'about.mission_text', 'JapaConnect is built to serve the Nigerian diaspora and Nigerians planning to relocate abroad. We provide community, resources, and expert guidance to make your journey smoother.', NULL, '2026-07-17 03:50:03.544624+01', '2026-07-17 03:50:03.544624+01');
INSERT INTO public.translations VALUES ('9b658df7-354b-4cbd-bbd6-860bf68ad905', 'es', 'ads.sections.campaign', 'Campaign', NULL, '2026-07-17 03:50:03.692195+01', '2026-07-17 03:50:03.692195+01');
INSERT INTO public.translations VALUES ('d7c21efc-9afa-49f4-bb55-ad175c47577d', 'es', 'ads.sections.creative', 'Creative', NULL, '2026-07-17 03:50:03.69362+01', '2026-07-17 03:50:03.69362+01');
INSERT INTO public.translations VALUES ('ada1ab8f-7e21-4244-b8f0-90bdd4a62b69', 'es', 'about.mission_text_1', 'JapaConnect is a community platform built for the Nigerian diaspora and Nigerians planning to relocate abroad. We provide tools for sharing experiences, finding resources, and building meaningful connections across borders.', NULL, '2026-07-17 03:50:03.547381+01', '2026-07-17 03:50:03.547381+01');
INSERT INTO public.translations VALUES ('046f7cc6-c197-4af7-9dd7-91a51efadadf', 'es', 'about.mission_text_2', 'Our mission is to make the relocation journey less isolating by connecting people with shared experiences, reliable information, and supportive communities.', NULL, '2026-07-17 03:50:03.550445+01', '2026-07-17 03:50:03.550445+01');
INSERT INTO public.translations VALUES ('1ceb9d13-e3c1-4865-bcde-a0a818d62750', 'es', 'about.mission_title', 'Our Mission', NULL, '2026-07-17 03:50:03.553212+01', '2026-07-17 03:50:03.553212+01');
